/** caller-keyed canonical JSON cache 的公开存储边界。 */
import { createHash, randomUUID } from "node:crypto";
import { promises as fs } from "node:fs";
import { isAbsolute, join } from "node:path";

import {
  canonicalizeJsonObject,
  canonicalJsonBytes,
  type CanonicalJsonObject
} from "../data-boundary/canonical-data.ts";
import { hasExactPlainRecordKeys, snapshotClosedRecord } from "../data-boundary/closed-values.ts";

const CACHE_API_VERSION = "caller-keyed-json-v1";
const CACHE_ENVELOPE_KEYS = ["cacheFormatVersion", "identityDigest", "payload"] as const;

/**
 * `cacheJsonByKey` 的 caller-owned identity、payload parser 与 computation。
 *
 * `key` 必须覆盖所有会改变 computation 结果的输入、实现、options、toolchain 与声明的外部状态；
 * 不能放入 secret 或低熵敏感值。`directory` 是调用方信任、可自行删除的本地状态空间。
 */
type NonThenable<T extends object> = T & Readonly<{ readonly then?: undefined }>;

/** Caller-keyed JSON cache 的 options。 */
export interface CacheJsonByKeyOptions<T extends object> {
  readonly compute: () => unknown;
  readonly directory: string;
  readonly key: string;
  readonly namespace: string;
  readonly parse: (value: unknown) => NonThenable<T>;
  readonly version: string;
}

/** `cacheJsonByKey` 返回的闭合 cache observation 与本次 parser value。 */
export type CacheJsonByKeyResult<T extends object> =
  | Readonly<{
      readonly read: "hit";
      readonly source: "cache";
      readonly value: T;
      readonly write: "not-attempted";
    }>
  | Readonly<{
      readonly read: "failed" | "invalid" | "miss";
      readonly source: "computed";
      readonly value: T;
      readonly write: "failed" | "stored";
    }>;

/**
 * 按 caller 提供的完整 semantic key 复用本地 canonical JSON object。
 *
 * cache hit 不会跳过或重放 Check settlement、Records、messages、duration 或 side effects。读取或写入失败
 * 只通过返回的 observation 可见；只要 `compute` 与 `parse` 成功，就仍返回本次 computation 的 value。
 * 不提供依赖发现、默认目录、lock/single-flight、TTL/LRU、cleanup、remote cache 或 tamper protection。
 */
export async function cacheJsonByKey<T extends object>(
  authoredOptions: CacheJsonByKeyOptions<T>
): Promise<CacheJsonByKeyResult<T>> {
  const options = parseOptions(authoredOptions);
  const identityDigest = cacheIdentityDigest(options);
  const targetPath = join(options.directory, `${identityDigest}.json`);
  const cached = await readCacheEntry({ identityDigest, parse: options.parse, targetPath });
  if (cached.hit) {
    return Object.freeze({
      read: "hit",
      source: "cache",
      value: cached.value,
      write: "not-attempted"
    });
  }

  const payload = canonicalizeJsonObject(await options.compute());
  if (payload === undefined) {
    throw new TypeError("cacheJsonByKey compute must return a canonical JSON object");
  }
  const value = parseSynchronously(options.parse, payload, "computed value");
  const stored = await publishCacheEntry({
    directory: options.directory,
    identityDigest,
    parse: options.parse,
    payload,
    targetPath
  });
  return Object.freeze({
    read: cached.read,
    source: "computed",
    value,
    write: stored ? "stored" : "failed"
  });
}

type ParsedOptions<T extends object> = Readonly<{
  readonly compute: () => unknown;
  readonly directory: string;
  readonly key: string;
  readonly namespace: string;
  readonly parse: (value: unknown) => T;
  readonly version: string;
}>;

function parseOptions<T extends object>(value: CacheJsonByKeyOptions<T>): ParsedOptions<T> {
  const record = snapshotClosedRecord(value);
  if (
    record === undefined ||
    !hasExactPlainRecordKeys(record, [
      "compute",
      "directory",
      "key",
      "namespace",
      "parse",
      "version"
    ])
  ) {
    throw new TypeError("cacheJsonByKey options must be a closed object");
  }
  const { compute, directory, key, namespace, parse, version } = record;
  if (typeof compute !== "function" || typeof parse !== "function") {
    throw new TypeError("cacheJsonByKey compute and parse must be functions");
  }
  if (
    typeof directory !== "string" ||
    directory.length === 0 ||
    directory.includes("\0") ||
    !isAbsolute(directory)
  ) {
    throw new TypeError(
      "cacheJsonByKey directory must be a non-empty absolute path without U+0000"
    );
  }
  if (typeof namespace !== "string" || namespace.length === 0) {
    throw new TypeError("cacheJsonByKey namespace must be a non-empty string");
  }
  if (typeof version !== "string" || version.length === 0) {
    throw new TypeError("cacheJsonByKey version must be a non-empty string");
  }
  if (typeof key !== "string" || key.length === 0) {
    throw new TypeError("cacheJsonByKey key must be a non-empty string");
  }
  const typedOptions: ParsedOptions<T> = {
    compute: value.compute,
    directory: value.directory,
    key: value.key,
    namespace: value.namespace,
    parse: value.parse,
    version: value.version
  };
  if (
    typedOptions.compute !== compute ||
    typedOptions.directory !== directory ||
    typedOptions.key !== key ||
    typedOptions.namespace !== namespace ||
    typedOptions.parse !== parse ||
    typedOptions.version !== version
  ) {
    throw new TypeError("cacheJsonByKey options changed during validation");
  }
  return Object.freeze(typedOptions);
}

function cacheIdentityDigest(options: ParsedOptions<object>): string {
  return createHash("sha256")
    .update(
      canonicalJsonBytes({
        cacheApiVersion: CACHE_API_VERSION,
        key: options.key,
        namespace: options.namespace,
        payloadVersion: options.version
      })
    )
    .digest("hex");
}

type CacheRead<T extends object> =
  | Readonly<{ readonly hit: true; readonly value: T }>
  | Readonly<{ readonly hit: false; readonly read: "failed" | "invalid" | "miss" }>;

async function readCacheEntry<T extends object>(
  input: Readonly<{
    readonly identityDigest: string;
    readonly parse: (value: unknown) => T;
    readonly targetPath: string;
  }>
): Promise<CacheRead<T>> {
  let source: string;
  try {
    source = await fs.readFile(input.targetPath, "utf8");
  } catch (error: unknown) {
    return isMissingPath(error)
      ? Object.freeze({ hit: false, read: "miss" })
      : Object.freeze({ hit: false, read: "failed" });
  }
  try {
    const envelope = parseEnvelope(JSON.parse(source), input.identityDigest);
    if (envelope === undefined) return Object.freeze({ hit: false, read: "invalid" });
    return Object.freeze({
      hit: true,
      value: parseSynchronously(input.parse, envelope.payload, "cached payload")
    });
  } catch {
    return Object.freeze({ hit: false, read: "invalid" });
  }
}

function parseEnvelope(
  value: unknown,
  identityDigest: string
): Readonly<{ readonly payload: CanonicalJsonObject }> | undefined {
  const record = snapshotClosedRecord(value);
  if (record === undefined || !hasExactPlainRecordKeys(record, CACHE_ENVELOPE_KEYS))
    return undefined;
  if (record.cacheFormatVersion !== CACHE_API_VERSION || record.identityDigest !== identityDigest) {
    return undefined;
  }
  const payload = canonicalizeJsonObject(record.payload);
  return payload === undefined ? undefined : Object.freeze({ payload });
}

function parseSynchronously<T extends object>(
  parse: (value: unknown) => T,
  payload: CanonicalJsonObject,
  subject: string
): T {
  const value = parse(payload);
  if (isThenable(value))
    throw new TypeError(`cacheJsonByKey parse must synchronously return ${subject}`);
  return value;
}

function isThenable(value: unknown): boolean {
  return (
    ((typeof value === "object" && value !== null) || typeof value === "function") &&
    typeof (value as { then?: unknown }).then === "function"
  );
}

async function publishCacheEntry<T extends object>(
  input: Readonly<{
    readonly directory: string;
    readonly identityDigest: string;
    readonly parse: (value: unknown) => T;
    readonly payload: CanonicalJsonObject;
    readonly targetPath: string;
  }>
): Promise<boolean> {
  const temporaryPath = join(input.directory, `.vibe-check-cache-${randomUUID()}.tmp`);
  try {
    await fs.mkdir(input.directory, { recursive: true });
    await fs.writeFile(
      temporaryPath,
      JSON.stringify({
        cacheFormatVersion: CACHE_API_VERSION,
        identityDigest: input.identityDigest,
        payload: input.payload
      }),
      { encoding: "utf8", flag: "wx" }
    );
  } catch {
    await fs.rm(temporaryPath, { force: true }).catch(() => undefined);
    return false;
  }

  try {
    await fs.rename(temporaryPath, input.targetPath);
    return true;
  } catch (error: unknown) {
    if (!isConcurrentTargetConflict(error)) return false;
    const concurrent = await readCacheEntry({
      identityDigest: input.identityDigest,
      parse: input.parse,
      targetPath: input.targetPath
    });
    return concurrent.hit;
  } finally {
    await fs.rm(temporaryPath, { force: true }).catch(() => undefined);
  }
}

function isConcurrentTargetConflict(error: unknown): boolean {
  return (
    typeof error === "object" && error !== null && (error as { code?: unknown }).code === "EEXIST"
  );
}

function isMissingPath(error: unknown): boolean {
  return (
    typeof error === "object" && error !== null && (error as { code?: unknown }).code === "ENOENT"
  );
}

import { canonicalizeJsonObject } from "../data-boundary/canonical-data.ts";
import type { CheckOutcome } from "../check/check.ts";
import { validateCheckDescriptor } from "../check/descriptor-validation.ts";
import type { CoreCheck, CoreRecord, CoreSnapshot } from "./facts.ts";
import {
  hasExactPlainRecordKeys,
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedArray,
  snapshotClosedRecord
} from "../data-boundary/closed-values.ts";
import { isClosedCheckReason } from "./reason-shape.ts";

export interface ValidationIssue {
  readonly path: string;
  readonly code:
    | "duplicate"
    | "identity-mismatch"
    | "invalid-value"
    | "missing-field"
    | "unknown-field";
  readonly message: string;
}

export type ValidationResult<T> = Readonly<
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly issues: readonly [ValidationIssue, ...ValidationIssue[]] }
>;

export function validateCoreSnapshot(value: unknown): ValidationResult<CoreSnapshot> {
  const snapshot = snapshotClosedRecord(value);
  if (snapshot === undefined || !hasExactPlainRecordKeys(snapshot, ["checks", "records"])) {
    return invalid("$", "Core snapshot must contain only checks and records");
  }
  const checksInput = snapshotClosedArray(snapshot.checks);
  const recordsInput = snapshotClosedArray(snapshot.records);
  if (checksInput === undefined || recordsInput === undefined) {
    return invalid("$", "Core snapshot entities must be dense arrays");
  }
  const checks = validateChecks(checksInput);
  if (!checks.ok) return checks;
  const reasonReferences = validateReasonReferences(checks.value);
  if (!reasonReferences.ok) return reasonReferences;
  const records = validateRecords(recordsInput, checks.value);
  if (!records.ok) return records;
  return accepted(Object.freeze({ checks: checks.value, records: records.value }));
}

function validateReasonReferences(checks: readonly CoreCheck[]): ValidationResult<void> {
  const knownCheckIds = new Set(checks.map((check) => check.checkId));
  for (const [index, check] of checks.entries()) {
    if (check.outcome.status !== "unavailable" || check.outcome.reason.checkIds === undefined)
      continue;
    const seen = new Set<string>();
    for (const checkId of check.outcome.reason.checkIds) {
      if (!knownCheckIds.has(checkId) || seen.has(checkId))
        return invalid(
          `$.checks[${index}].outcome.reason.checkIds`,
          "Unavailable reason references are invalid"
        );
      seen.add(checkId);
    }
  }
  return accepted(undefined);
}

function validateChecks(values: readonly unknown[]): ValidationResult<readonly CoreCheck[]> {
  const checks: CoreCheck[] = [];
  const checkIds = new Set<string>();
  let previousCheckId: string | undefined;
  for (const [index, value] of values.entries()) {
    const check = snapshotClosedRecord(value);
    if (
      check === undefined ||
      !hasExactPlainRecordKeys(check, ["checkId", "displayName", "outcome"])
    ) {
      return invalid(`$.checks[${index}]`, "Core Check must be closed");
    }
    const definition = validateCheckDescriptor({
      checkId: check.checkId,
      displayName: check.displayName
    });
    if (!definition.ok) return definition;
    if (checkIds.has(definition.value.checkId)) {
      return invalid(`$.checks[${index}].checkId`, "Duplicate Core Check checkId", "duplicate");
    }
    if (
      previousCheckId !== undefined &&
      compareText(previousCheckId, definition.value.checkId) >= 0
    ) {
      return invalid(`$.checks[${index}].checkId`, "Core Checks must be sorted by checkId");
    }
    const outcome = validateOutcome(check.outcome, `$.checks[${index}].outcome`);
    if (!outcome.ok) return outcome;
    checks.push(Object.freeze({ ...definition.value, outcome: outcome.value }));
    checkIds.add(definition.value.checkId);
    previousCheckId = definition.value.checkId;
  }
  return accepted(Object.freeze(checks));
}

function validateRecords(
  values: readonly unknown[],
  checks: readonly CoreCheck[]
): ValidationResult<readonly CoreRecord[]> {
  const ownerIds = new Set(checks.map((check) => check.checkId));
  const recordIdsByCheckId = new Map<string, Set<string>>();
  const records: CoreRecord[] = [];
  let previous: Readonly<{ readonly checkId: string; readonly id: string }> | undefined;
  for (const [index, value] of values.entries()) {
    const record = validateRecordRow(value, index, ownerIds);
    if (!record.ok) return record;
    const current = record.value;
    const ids = recordIdsByCheckId.get(current.checkId) ?? new Set<string>();
    if (ids.has(current.id)) {
      return invalid(`$.records[${index}].id`, "Duplicate Check-local Record id", "duplicate");
    }
    if (
      previous !== undefined &&
      (compareText(previous.checkId, current.checkId) > 0 ||
        (previous.checkId === current.checkId && compareText(previous.id, current.id) >= 0))
    ) {
      return invalid(`$.records[${index}]`, "Core Records must be sorted by checkId then id");
    }
    ids.add(current.id);
    recordIdsByCheckId.set(current.checkId, ids);
    records.push(current);
    previous = { checkId: current.checkId, id: current.id };
  }
  return accepted(Object.freeze(records));
}

function validateRecordRow(
  value: unknown,
  index: number,
  ownerIds: ReadonlySet<string>
): ValidationResult<CoreRecord> {
  const record = snapshotClosedRecord(value);
  if (record === undefined || !hasExactPlainRecordKeys(record, ["checkId", "id", "data"]))
    return invalid(`$.records[${index}]`, "Core Record must be closed");
  if (
    typeof record.checkId !== "string" ||
    !ownerIds.has(record.checkId) ||
    typeof record.id !== "string" ||
    record.id.length === 0
  ) {
    return invalid(`$.records[${index}]`, "Core Record identity is invalid", "identity-mismatch");
  }
  const data = canonicalizeJsonObject(record.data);
  return data === undefined
    ? invalid(`$.records[${index}].data`, "Core Record data is invalid")
    : accepted(Object.freeze({ checkId: record.checkId, id: record.id, data }));
}

function validateOutcome(value: unknown, path: string): ValidationResult<CheckOutcome> {
  const outcome = snapshotClosedRecord(value);
  if (outcome === undefined || typeof outcome.status !== "string") {
    return invalid(path, "Check outcome is invalid");
  }
  if (outcome.status === "passed" || outcome.status === "failed")
    return validateFinalOutcome(outcome, path);
  if (outcome.status === "not-applicable") return validateNotApplicableOutcome(outcome, path);
  if (outcome.status === "unavailable") return validateUnavailableOutcome(outcome, path);
  return invalid(`${path}.status`, "Unknown Check outcome status");
}

function validateFinalOutcome(
  outcome: Readonly<Record<string, unknown>>,
  path: string
): ValidationResult<CheckOutcome> {
  if (outcome.status === "passed" || outcome.status === "failed") {
    if (!hasExactPlainRecordKeys(outcome, ["status", "data"]))
      return invalid(path, "Final outcome is not closed");
    const data = canonicalizeJsonObject(outcome.data);
    return data === undefined
      ? invalid(`${path}.data`, "Final data is invalid")
      : accepted(Object.freeze({ status: outcome.status, data }));
  }
  return invalid(`${path}.status`, "Unknown Check outcome status");
}

function validateNotApplicableOutcome(
  outcome: Readonly<Record<string, unknown>>,
  path: string
): ValidationResult<CheckOutcome> {
  if (
    !hasRequiredAndOptionalRecordKeys(outcome, {
      optional: ["reason"],
      required: ["status"]
    })
  )
    return invalid(path, "Not-applicable outcome is not closed");
  const reason = validateReason(outcome.reason, false);
  return reason === null
    ? invalid(`${path}.reason`, "Not-applicable reason is invalid")
    : accepted(
        Object.freeze(
          reason === undefined ? { status: "not-applicable" } : { status: "not-applicable", reason }
        )
      );
}

function validateUnavailableOutcome(
  outcome: Readonly<Record<string, unknown>>,
  path: string
): ValidationResult<CheckOutcome> {
  if (!hasExactPlainRecordKeys(outcome, ["status", "reason"]))
    return invalid(path, "Unavailable outcome is not closed");
  const reason = validateReason(outcome.reason, true);
  return reason === null || reason === undefined
    ? invalid(`${path}.reason`, "Unavailable reason is invalid")
    : accepted(Object.freeze({ status: "unavailable", reason }));
}

function validateReason(
  value: unknown,
  allowCheckIds: boolean
): Readonly<{ readonly code: string; readonly checkIds?: readonly string[] }> | null | undefined {
  if (value === undefined) return undefined;
  const reason = snapshotClosedRecord(value);
  if (!isClosedCheckReason(reason, allowCheckIds)) return null;
  if (
    !hasRequiredAndOptionalRecordKeys(reason, {
      optional: allowCheckIds ? ["checkIds"] : [],
      required: ["code"]
    })
  )
    return null;
  if (!Object.hasOwn(reason, "checkIds")) return Object.freeze({ code: reason.code });
  const normalizedCheckIds = normalizedReasonCheckIds(reason.checkIds, allowCheckIds);
  if (normalizedCheckIds === undefined) return null;
  return Object.freeze({ code: reason.code, checkIds: Object.freeze(normalizedCheckIds) });
}

function normalizedReasonCheckIds(
  value: unknown,
  allowCheckIds: boolean
): readonly string[] | undefined {
  const checkIds = snapshotClosedArray(value);
  if (
    !allowCheckIds ||
    checkIds === undefined ||
    checkIds.length === 0 ||
    checkIds.some((checkId) => typeof checkId !== "string" || !isSettlementCheckReference(checkId))
  )
    return undefined;
  const normalizedCheckIds: string[] = [];
  for (const checkId of checkIds) {
    if (typeof checkId !== "string") return undefined;
    normalizedCheckIds.push(checkId);
  }
  return Object.freeze(normalizedCheckIds);
}

function accepted<T>(value: T): ValidationResult<T> {
  return Object.freeze({ ok: true, value });
}

function invalid(
  path: string,
  message: string,
  code: ValidationIssue["code"] = "invalid-value"
): ValidationResult<never> {
  const issue = Object.freeze({ path, code, message }) satisfies ValidationIssue;
  const issues: readonly [ValidationIssue, ...ValidationIssue[]] = [issue];
  return Object.freeze({
    ok: false,
    issues: Object.freeze(issues)
  });
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

function isSettlementCheckReference(value: string): boolean {
  return value.length > 0;
}

import type { CheckDescriptor } from "../check/descriptor.ts";
import type { CheckOutcome } from "../check/check.ts";

export type {
  CanonicalJsonObject,
  CanonicalJsonPrimitive,
  CanonicalJsonValue
} from "../data-boundary/canonical-data.ts";
export type { CheckDescriptor, CheckOutcome };

/** A Core Check has exactly one terminal outcome and no execution bookkeeping. */
export interface CoreCheck extends CheckDescriptor {
  readonly outcome: CheckOutcome;
}

/** A supplemental Record is owned by its structural `{ checkId, id }` identity. */
export interface CoreRecord {
  readonly checkId: string;
  readonly id: string;
  readonly data: import("../data-boundary/canonical-data.ts").CanonicalJsonObject;
}

/** The complete Product entity projection. Invocation metadata belongs to Run, not Core. */
export interface CoreSnapshot {
  readonly checks: readonly CoreCheck[];
  readonly records: readonly CoreRecord[];
}

import type { CheckOutcome } from "../check/check.ts";
import { canonicalizeJsonObject } from "../data-boundary/canonical-data.ts";
import {
  hasExactPlainRecordKeys,
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedArray,
  snapshotClosedRecord
} from "../data-boundary/closed-values.ts";
import { isClosedCheckReason } from "./reason-shape.ts";

interface OutcomeNormalizationInput {
  readonly knownCheckIds: ReadonlySet<string>;
  readonly productOutcome: boolean;
  readonly value: unknown;
}

/** Normalizes one live Check terminal value before the settlement session commits it. */
export function normalizeCheckOutcome(input: OutcomeNormalizationInput): CheckOutcome | undefined {
  const outcome = snapshotClosedRecord(input.value);
  if (outcome === undefined || typeof outcome.status !== "string") return undefined;
  if (outcome.status === "passed" || outcome.status === "failed") {
    return normalizeFinalOutcome(outcome);
  }
  if (outcome.status === "not-applicable") {
    return normalizeNotApplicableOutcome(outcome, input.knownCheckIds);
  }
  if (outcome.status === "unavailable") {
    return normalizeUnavailableOutcome(outcome, input.productOutcome, input.knownCheckIds);
  }
  return undefined;
}

function normalizeFinalOutcome(
  outcome: Readonly<Record<string, unknown>>
): CheckOutcome | undefined {
  if (outcome.status !== "passed" && outcome.status !== "failed") return undefined;
  if (!hasExactPlainRecordKeys(outcome, ["status", "data"])) return undefined;
  const data = canonicalizeJsonObject(outcome.data);
  return data === undefined ? undefined : Object.freeze({ status: outcome.status, data });
}

function normalizeNotApplicableOutcome(
  outcome: Readonly<Record<string, unknown>>,
  knownCheckIds: ReadonlySet<string>
): CheckOutcome | undefined {
  if (
    !hasRequiredAndOptionalRecordKeys(outcome, {
      optional: ["reason"],
      required: ["status"]
    })
  )
    return undefined;
  if (outcome.reason === undefined) return Object.freeze({ status: "not-applicable" });
  const reason = normalizeReason(outcome.reason, false, knownCheckIds);
  return reason === undefined ? undefined : Object.freeze({ status: "not-applicable", reason });
}

function normalizeUnavailableOutcome(
  outcome: Readonly<Record<string, unknown>>,
  productOutcome: boolean,
  knownCheckIds: ReadonlySet<string>
): CheckOutcome | undefined {
  if (!hasExactPlainRecordKeys(outcome, ["status", "reason"])) return undefined;
  const reason = normalizeReason(outcome.reason, productOutcome, knownCheckIds);
  return reason === undefined ? undefined : Object.freeze({ status: "unavailable", reason });
}

function normalizeReason(
  value: unknown,
  allowCheckIds: boolean,
  knownCheckIds: ReadonlySet<string>
): Readonly<{ readonly code: string; readonly checkIds?: readonly string[] }> | undefined {
  const reason = snapshotClosedRecord(value);
  if (!isClosedCheckReason(reason, allowCheckIds)) return undefined;
  if (!Object.hasOwn(reason, "checkIds")) return Object.freeze({ code: reason.code });
  const checkIds = normalizedSessionReasonCheckIds(reason.checkIds, allowCheckIds, knownCheckIds);
  return checkIds === undefined ? undefined : Object.freeze({ code: reason.code, checkIds });
}

function normalizedSessionReasonCheckIds(
  value: unknown,
  allowCheckIds: boolean,
  knownCheckIds: ReadonlySet<string>
): readonly string[] | undefined {
  const rawCheckIds = snapshotClosedArray(value);
  if (!allowCheckIds || rawCheckIds === undefined || rawCheckIds.length === 0) return undefined;
  const checkIds: string[] = [];
  for (const checkId of rawCheckIds) {
    if (
      typeof checkId !== "string" ||
      checkId.length === 0 ||
      !knownCheckIds.has(checkId) ||
      checkIds.includes(checkId)
    ) {
      return undefined;
    }
    checkIds.push(checkId);
  }
  return Object.freeze(checkIds);
}

import { hasRequiredAndOptionalRecordKeys } from "../data-boundary/closed-values.ts";

export type ClosedCheckReason = Readonly<Record<string, unknown>> &
  Readonly<{ readonly code: string }>;

/** Recognizes the shared closed reason shape before owner-specific ID validation. */
export function isClosedCheckReason(
  value: Readonly<Record<string, unknown>> | undefined,
  allowCheckIds: boolean
): value is ClosedCheckReason {
  return (
    value !== undefined &&
    typeof value.code === "string" &&
    value.code.length > 0 &&
    hasRequiredAndOptionalRecordKeys(value, {
      optional: allowCheckIds ? ["checkIds"] : [],
      required: ["code"]
    })
  );
}

import { canonicalizeJsonObject } from "../data-boundary/canonical-data.ts";
import type { CoreRecord } from "./facts.ts";
import { snapshotClosedRecord } from "../data-boundary/closed-values.ts";

export type RecordSubmissionResult = "committed" | "rejected";
export type RecordDiagnostic = "record-conflict" | "record-invalid";

export interface CoreRecordSlot {
  readonly checkId: string;
  readonly diagnostics: Set<RecordDiagnostic>;
  readonly recordIds: Set<string>;
}

/** Holds one Check's minimal Records without inventing a composite string identity. */
export class CoreRecordStore {
  readonly #recordsByCheckId = new Map<string, Map<string, CoreRecord>>();

  public report(
    slot: CoreRecordSlot,
    rawIdentity: unknown,
    rawData: unknown
  ): RecordSubmissionResult {
    const id = recordId(rawIdentity);
    const data = canonicalizeJsonObject(rawData);
    if (id === undefined || data === undefined) return this.#reject(slot, "record-invalid");
    if (slot.recordIds.has(id)) return this.#reject(slot, "record-conflict");

    const record: CoreRecord = Object.freeze({ checkId: slot.checkId, id, data });
    let records = this.#recordsByCheckId.get(slot.checkId);
    if (records === undefined) {
      records = new Map<string, CoreRecord>();
      this.#recordsByCheckId.set(slot.checkId, records);
    }
    records.set(id, record);
    slot.recordIds.add(id);
    return "committed";
  }

  public recordsInCanonicalOrder(): readonly CoreRecord[] {
    const records: CoreRecord[] = [];
    for (const checkId of [...this.#recordsByCheckId.keys()].sort(compareText)) {
      const byId = this.#recordsByCheckId.get(checkId);
      if (byId === undefined) continue;
      for (const id of [...byId.keys()].sort(compareText)) {
        const record = byId.get(id);
        if (record !== undefined) records.push(record);
      }
    }
    return Object.freeze(records);
  }

  #reject(slot: CoreRecordSlot, diagnostic: RecordDiagnostic): "rejected" {
    slot.diagnostics.add(diagnostic);
    return "rejected";
  }
}

function recordId(value: unknown): string | undefined {
  const identity = snapshotClosedRecord(value);
  return identity !== undefined &&
    Object.keys(identity).length === 1 &&
    Object.hasOwn(identity, "id") &&
    typeof identity.id === "string" &&
    identity.id.length > 0
    ? identity.id
    : undefined;
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import type { CheckDescriptor } from "../check/descriptor.ts";
import type { CheckOutcome } from "../check/check.ts";
import {
  CoreRecordStore,
  type CoreRecordSlot,
  type RecordDiagnostic,
  type RecordSubmissionResult
} from "./record-store.ts";
import type { CoreCheck, CoreSnapshot } from "./facts.ts";
import { validateCheckDescriptor } from "../check/descriptor-validation.ts";
import { normalizeCheckOutcome } from "./outcome-normalization.ts";

export type { RecordSubmissionResult } from "./record-store.ts";

export interface CoreCheckRegistration {
  readonly definition: CheckDescriptor;
}

/** Internal Record port bound to one currently executing Check. */
export interface RecordSink {
  report(identity: unknown, data: unknown): RecordSubmissionResult;
}

/** Only the Product Task adapter receives this Core lifecycle capability. */
export interface TrustedCheckScope {
  readonly records: RecordSink;
  /** Core is the only author-result validation/canonicalization boundary. */
  readonly settle: (outcome: unknown) => AuthorCheckSettlement;
  /** Private Product lifecycle outcomes may include contained prerequisite IDs. */
  readonly settleProduct: (outcome: CheckOutcome) => CheckOutcome;
}

/** Core's private marker for an author result that survived every settlement guard. */
export interface AuthorCheckSettlement {
  readonly authorResultAccepted: boolean;
  readonly outcome: CheckOutcome;
}

export interface CoreCheckSession {
  openCheckScope(checkId: string): TrustedCheckScope;
  readSettledCheckOutcome(checkId: string): CheckOutcome;
  closeUnresolvedAsCancelled(): readonly CancelledCheckClosure[];
  freeze(): CoreSnapshot;
}

/** Product-private cancellation facts emitted at the exact Core closure boundary. */
export interface CancelledCheckClosure {
  readonly checkId: string;
  readonly outcome: CheckOutcome;
}

/** A trusted integration bug is fatal to the invocation, not a Check outcome. */
export class CoreInvariantFailure extends Error {
  public constructor(message: string) {
    super(message);
    this.name = "CoreInvariantFailure";
  }
}

type CoreSlotLifecycle = Readonly<
  | { readonly kind: "registered" }
  | { readonly kind: "open" }
  | { readonly kind: "settled"; readonly outcome: CheckOutcome }
>;

interface CoreSlot extends CoreRecordSlot {
  readonly definition: CheckDescriptor;
  lifecycle: CoreSlotLifecycle;
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

function coreInvariant(message: string): never {
  throw new CoreInvariantFailure(message);
}

function createSlots(registrations: readonly CoreCheckRegistration[]): CoreSlot[] {
  const slots: CoreSlot[] = [];
  const checkIds = new Set<string>();
  for (const registration of registrations) {
    if (registration === null || typeof registration !== "object") {
      coreInvariant("Core Check registration is invalid");
    }
    const definition = validateCheckDescriptor(registration.definition);
    if (!definition.ok) coreInvariant("Core Check registration definition is invalid");
    if (checkIds.has(definition.value.checkId)) {
      coreInvariant("Core Check registration has a duplicate checkId");
    }
    checkIds.add(definition.value.checkId);
    slots.push({
      checkId: definition.value.checkId,
      definition: definition.value,
      diagnostics: new Set(),
      lifecycle: { kind: "registered" },
      recordIds: new Set()
    });
  }
  return slots.sort((left, right) =>
    compareText(left.definition.checkId, right.definition.checkId)
  );
}

class CoreCheckSessionImpl implements CoreCheckSession {
  readonly #slots: CoreSlot[];
  readonly #recordStore = new CoreRecordStore();
  #snapshot: CoreSnapshot | undefined;

  public constructor(registrations: readonly CoreCheckRegistration[]) {
    this.#slots = createSlots(registrations);
  }

  public openCheckScope(checkId: string): TrustedCheckScope {
    const slot = this.#slotFor(checkId);
    if (this.#snapshot !== undefined || slot.lifecycle.kind !== "registered") {
      coreInvariant("Core Check scope is not available");
    }
    slot.lifecycle = Object.freeze({ kind: "open" });
    return Object.freeze({
      records: Object.freeze({
        report: (identity: unknown, data: unknown): RecordSubmissionResult => {
          if (this.#snapshot !== undefined || slot.lifecycle.kind !== "open") return "rejected";
          return this.#recordStore.report(slot, identity, data);
        }
      }),
      settle: (outcome: unknown): AuthorCheckSettlement => this.#settleAuthorSlot(slot, outcome),
      settleProduct: (outcome: CheckOutcome): CheckOutcome => this.#settleSlot(slot, outcome, true)
    });
  }

  public readSettledCheckOutcome(checkId: string): CheckOutcome {
    const slot = this.#slotFor(checkId);
    if (slot.lifecycle.kind !== "settled") {
      coreInvariant("Core settled Check is not available");
    }
    return slot.lifecycle.outcome;
  }

  public closeUnresolvedAsCancelled(): readonly CancelledCheckClosure[] {
    if (this.#snapshot !== undefined) {
      coreInvariant("Cancelled closure cannot mutate a frozen Core snapshot");
    }
    const closures: CancelledCheckClosure[] = [];
    for (const slot of this.#slots) {
      if (slot.lifecycle.kind !== "settled") {
        const outcome = this.#commitTerminal(
          slot,
          Object.freeze({ status: "unavailable", reason: { code: "execution-cancelled" } }),
          true
        );
        closures.push(Object.freeze({ checkId: slot.checkId, outcome }));
      }
    }
    return Object.freeze(closures);
  }

  public freeze(): CoreSnapshot {
    if (this.#snapshot !== undefined) return this.#snapshot;
    const checks: CoreCheck[] = [];
    for (const slot of this.#slots) {
      if (slot.lifecycle.kind !== "settled") {
        return coreInvariant("Core snapshot cannot freeze before every Check slot closes");
      }
      checks.push(coreCheckFor(slot));
    }
    this.#snapshot = Object.freeze({
      checks: Object.freeze(checks),
      records: this.#recordStore.recordsInCanonicalOrder()
    });
    return this.#snapshot;
  }

  #slotFor(checkId: string): CoreSlot {
    if (typeof checkId !== "string") coreInvariant("Core Check scope requires a checkId");
    const slot = this.#slots.find((candidate) => candidate.definition.checkId === checkId);
    return slot ?? coreInvariant("Core Check scope does not own this checkId");
  }

  #checkIds(): ReadonlySet<string> {
    return new Set(this.#slots.map((candidate) => candidate.checkId));
  }

  #settleSlot(slot: CoreSlot, outcome: unknown, productOutcome: boolean): CheckOutcome {
    if (this.#snapshot !== undefined || slot.lifecycle.kind !== "open") {
      return coreInvariant("Trusted Core Check settlement is duplicate, late, or out of scope");
    }
    return this.#commitTerminal(slot, outcome, productOutcome);
  }

  #settleAuthorSlot(slot: CoreSlot, terminal: unknown): AuthorCheckSettlement {
    if (this.#snapshot !== undefined || slot.lifecycle.kind !== "open") {
      return coreInvariant("Trusted Core Check settlement is duplicate, late, or out of scope");
    }
    const diagnostic = terminalDiagnostic(slot);
    const normalized =
      diagnostic === undefined
        ? normalizeCheckOutcome({
            knownCheckIds: this.#checkIds(),
            productOutcome: false,
            value: terminal
          })
        : undefined;
    const outcome = normalized ?? unavailable(diagnostic ?? "invalid-execution-result");
    slot.lifecycle = Object.freeze({ kind: "settled", outcome });
    return Object.freeze({
      authorResultAccepted: diagnostic === undefined && normalized !== undefined,
      outcome
    });
  }

  #commitTerminal(slot: CoreSlot, terminal: unknown, productOutcome = false): CheckOutcome {
    if (slot.lifecycle.kind === "settled") {
      coreInvariant("Core Check terminal closure is duplicate");
    }
    const diagnostic = terminalDiagnostic(slot);
    const outcome =
      diagnostic === undefined
        ? (normalizeCheckOutcome({
            knownCheckIds: this.#checkIds(),
            productOutcome,
            value: terminal
          }) ?? unavailable("invalid-execution-result"))
        : unavailable(diagnostic);
    slot.lifecycle = Object.freeze({ kind: "settled", outcome });
    return outcome;
  }
}

function terminalDiagnostic(slot: CoreSlot): RecordDiagnostic | undefined {
  if (slot.diagnostics.has("record-conflict")) return "record-conflict";
  if (slot.diagnostics.has("record-invalid")) return "record-invalid";
  return undefined;
}

function coreCheckFor(slot: CoreSlot): CoreCheck {
  if (slot.lifecycle.kind !== "settled") {
    coreInvariant("Core Check fact requires a settled slot");
  }
  return Object.freeze({
    checkId: slot.definition.checkId,
    displayName: slot.definition.displayName,
    outcome: slot.lifecycle.outcome
  });
}

function unavailable(code: string): CheckOutcome {
  return Object.freeze({ status: "unavailable", reason: Object.freeze({ code }) });
}

export function createCoreCheckSession(
  registrations: readonly CoreCheckRegistration[]
): CoreCheckSession {
  return new CoreCheckSessionImpl(registrations);
}

import type { CanonicalJsonObject, CanonicalJsonValue } from "../data-boundary/canonical-json.ts";
import type { InheritableCheckCollection } from "./inherited-collection.ts";

export {
  inherit,
  isInheritedCheckCollection,
  snapshotInheritedCheckCollection
} from "./inherited-collection.ts";
export type {
  InheritCheckCollectionInput,
  InheritableCheckCollection,
  InheritedCheckCollection
} from "./inherited-collection.ts";

/** Check 无法给出 final data 时返回的受控 reason code。 */
export type CheckReason = Readonly<{
  /** 由 owning Check 定义、供调用方诊断的稳定 code。 */
  readonly code: string;
}>;

/** `not-applicable` Check result 的可选 reason。 */
export type CheckNotApplicableReason = CheckReason;
/** author callback 明确返回 `unavailable` 时必须提供的 reason。 */
export type CheckDeclaredUnavailableReason = CheckReason;

/** `unavailable` Check outcome 的 reason；可列出导致当前 Check 不可用的上游 Check。 */
export type CheckUnavailableReason = Readonly<{
  /** 由当前 Check 或 Product 边界给出的受控原因。 */
  readonly code: string;
  /** 仅在上游关系有助于定位时给出的相关 Check IDs。 */
  readonly checkIds?: readonly string[];
}>;

/** 终端 Check message 的 presentation severity。 */
export type CheckMessageLevel = "info" | "warning" | "error";

/** 由 Check author 附加到 terminal result 的补充消息。 */
export interface CheckMessage {
  /** 人读 presentation 使用的 severity。 */
  readonly level: CheckMessageLevel;
  /** owning Check namespace 内的稳定 message code。 */
  readonly code: string;
  /** 非空消息正文；Product 保留 author 提供的字符串。 */
  readonly message: string;
}

/** 可附加到每个 {@link CheckResult} branch 的有序 terminal messages。 */
export interface CheckResultMessages {
  /** 省略、`undefined` 或空数组都表示没有 supplemental messages。 */
  readonly messages?: readonly CheckMessage[];
}

/** 已结算 Check 在人读 progress 中的可见性。 */
export type CheckVisibility = "always" | "attention";

/** 多 flag Check 启用条件使用的集合 predicate。 */
export type CheckFlagEnablementMode = "all" | "any" | "none" | "not-all";

/** executable Check 的声明式多 flag 启用条件。 */
export interface CheckFlagEnablement {
  /** 非空 flag token 集合；Definition 会去重并稳定排序。 */
  readonly flags: readonly [string, ...string[]];
  /** 对声明 token 与本次 Run flags 执行的 presence predicate。 */
  readonly mode: CheckFlagEnablementMode;
}

/**
 * Check callback 的 terminal result。
 *
 * @typeParam FinalData - `passed` 或 `failed` 时保留为 canonical final data 的业务对象。
 * @remarks `not-applicable` 与 `unavailable` 不携带 final data；普通 callback、Record 或取消失败由
 * Product 转换为 `unavailable`，而不是抛出为 Run 的成功结果。
 */
export type CheckResult<FinalData extends object = object> = Readonly<
  (
    | {
        /** Check 已产生通过的 final data。 */
        readonly status: "passed";
        /** 此 Check 的主要终态事实。 */
        readonly data: FinalData;
      }
    | {
        /** Check 已产生失败的 final data。 */
        readonly status: "failed";
        /** 此 Check 的主要终态事实。 */
        readonly data: FinalData;
      }
    | {
        /** Check 在当前 invocation 中不适用。 */
        readonly status: "not-applicable";
        /** 不适用的可选受控原因。 */
        readonly reason?: CheckNotApplicableReason;
      }
    | {
        /** Check 不能提供 terminal data。 */
        readonly status: "unavailable";
        /** 不可用的受控原因。 */
        readonly reason: CheckDeclaredUnavailableReason;
      }
  ) &
    CheckResultMessages
>;

/** 已 materialize 到 Core snapshot 的 Check terminal outcome。 */
export type CheckOutcome = Readonly<
  | {
      /** 已 materialize 的通过 outcome。 */
      readonly status: "passed";
      /** 已 canonicalize 的 primary final fact。 */
      readonly data: CanonicalJsonObject;
    }
  | {
      /** 已 materialize 的失败 outcome。 */
      readonly status: "failed";
      /** 已 canonicalize 的 primary final fact。 */
      readonly data: CanonicalJsonObject;
    }
  | {
      /** 已 materialize 的不适用 outcome。 */
      readonly status: "not-applicable";
      /** 不适用的可选受控原因。 */
      readonly reason?: CheckNotApplicableReason;
    }
  | {
      /** 已 materialize 的不可用 outcome。 */
      readonly status: "unavailable";
      /** 包含相关 upstream Check IDs 的受控原因。 */
      readonly reason: CheckUnavailableReason;
    }
>;

/** 将 callback options 转为不可变观察值的递归 utility type。 */
export type DeepReadonly<T> = T extends string | number | boolean | null
  ? T
  : T extends readonly (infer Item)[]
    ? readonly DeepReadonly<Item>[]
    : T extends object
      ? { readonly [Key in keyof T]: DeepReadonly<T[Key]> }
      : never;

/** callback 写入 supplemental Record 时的 Check-local identity。 */
interface RecordIdentityInput {
  /** 在当前 Check 内唯一的 Record ID。 */
  readonly id: string;
}

/** callback 写入 supplemental Records 的 Product-owned reporter。 */
interface CheckRecordReporter {
  /** 记录一个补充事实；它不决定 Check 的 terminal status。 */
  report(identity: RecordIdentityInput, data: object): void;
}

/** 读取已声明 direct relation final data 时的失败原因。 */
export type DependencyReadError = Readonly<
  | {
      /** 当前 Check 未声明所请求的 direct relation ID。 */
      readonly code: "dependency-not-declared";
      /** 被拒绝的 direct relation ID。 */
      readonly checkId: string;
    }
  | {
      /** 已声明 upstream 没有可读取的 final data。 */
      readonly code: "upstream-data-unavailable";
      /** 没有 final data 的 direct relation ID。 */
      readonly checkId: string;
      /** 阻止 readback 的 upstream terminal status。 */
      readonly status: "not-applicable" | "unavailable";
    }
>;

/** {@link CheckDependencies.get} 的受控 readback 结果。 */
export type DependencyReadResult = Readonly<
  | {
      /** 成功读取 direct relation final data。 */
      readonly ok: true;
      /** 被读取的 direct relation ID。 */
      readonly checkId: string;
      /** upstream 已结算为 `passed` 或 `failed` 的 status。 */
      readonly status: "passed" | "failed";
      /** 已与原对象脱离的上游依赖终态数据。 */
      readonly data: CanonicalJsonObject;
    }
  | {
      /** direct relation data 不可读取。 */
      readonly ok: false;
      /** 失败的授权或 upstream-data reason。 */
      readonly error: DependencyReadError;
    }
>;

/** 当前 Check 的一个已规范化直接 relation 及其完整终态事实。 */
export type DependencyObservation = Readonly<{
  /** 已规范化、稳定排序的 direct relation ID。 */
  readonly checkId: string;
  /** Core 已结算并冻结的四态 outcome。 */
  readonly outcome: CheckOutcome;
}>;

/** 当前 Check 的已规范化直接 relation outcomes 的 data reader。 */
export interface CheckDependencies {
  /**
   * 读取一个直接 relation 的 canonical final data。
   *
   * @returns 已声明的 `dependsOn` 或 `observes` relation 且为 `passed`/`failed` 的 Check 返回其 data；
   * 未声明或没有 final data 时返回 `ok: false`，不会授权 transitive Check。
   */
  get(checkId: string): DependencyReadResult;

  /**
   * 枚举当前 Check 的全部已规范化 direct relation outcomes。
   *
   * @returns 按有效 direct relation ID 稳定排序、深度冻结的 `{ checkId, outcome }` observations；只含当前
   * Check 显式或继承得到的 `dependsOn` / `observes` relation，不暴露 scheduler 历史、transitive 或未声明
   * Check。
   */
  list(): readonly DependencyObservation[];
}

/** callback 可读取的、由 Product 规范化的项目上下文。 */
export interface CheckProjectContext {
  /** 本次 Run 使用的绝对项目根目录。 */
  readonly root: string;
  /** 已去重、排序的 caller-supplied flags。 */
  readonly flags: readonly string[];
}

/**
 * Check callback 收到的 Product-owned execution context。
 *
 * @typeParam Options - 此 Check preflight 后传给 execution 的 options shape。
 */
export interface CheckExecutionContext<Options extends object> {
  /** 读取当前 Check 的已声明 direct relations。 */
  readonly dependencies: CheckDependencies;
  /** 深度只读、canonical 的 invocation-local prepared Check options。 */
  readonly options: DeepReadonly<Options>;
  /** 已规范化的项目根与 flags。 */
  readonly project: CheckProjectContext;
  /** 写入 supplemental Records 的 reporter。 */
  readonly records: CheckRecordReporter;
  /** 本次 invocation 的 cancellation signal。 */
  readonly signal: AbortSignal;
}

/**
 * 一个 Check 的 callback signature。
 *
 * @typeParam Options - callback 从 context 读取的 prepared options shape。
 * @returns terminal Check result 或其 Promise。
 */
export type CheckExecution<Options extends object = object> = (
  this: void,
  context: CheckExecutionContext<Options>
) => CheckResult | Promise<CheckResult>;

/**
 * 在 Check execution 前，可选地为本次 invocation 准备 options。
 *
 * @remarks `signal` 与同一次 callback execution 使用同一个 cancellation signal；实现应在可等待工作中
 * 协作退出，而不是留下悬挂 work。bivariant callback 保持具体 options Check 可进入普通递归 Check
 * collection；Product 仍只会用该 Check 自己的 authored options 调用它。精确结果见
 * {@link CheckPreflightResult}。
 */
export type CheckPreflight<
  AuthoredOptions extends object = object,
  PreparedOptions extends object = AuthoredOptions
> = {
  bivarianceHack(
    this: void,
    options: DeepReadonly<AuthoredOptions>,
    signal: AbortSignal
  ): CheckPreflightResult<PreparedOptions> | Promise<CheckPreflightResult<PreparedOptions>>;
}["bivarianceHack"];

/**
 * Check-owned preflight 的判别结果。
 *
 * `failure/block` 不允许 fallback，直接以 owning reason 结算为 unavailable；`failure/continue` 必须给出
 * fallback 并继续 execution。两种进入 execution 的值都只属于本次 invocation，Product canonicalize/freeze
 * 后传递，不会改写 Definition 中 authored options。两个 failure 分支都必须给出 reason；continue reason
 * 是 Check-owned diagnostic identity，当前不会单独 materialize 为 outcome，调用方通过 messages 与后续
 * outcome 观察结果；block 物理上不含 fallback 字段。
 */
export type CheckPreflightResult<PreparedOptions extends object = object> = Readonly<
  | {
      readonly status: "success";
      readonly preparedOptions: PreparedOptions;
      readonly messages?: readonly CheckMessage[];
    }
  | {
      readonly status: "failure";
      readonly action: "block";
      readonly reason: CheckDeclaredUnavailableReason;
      readonly messages?: readonly CheckMessage[];
    }
  | {
      readonly status: "failure";
      readonly action: "continue";
      readonly fallback: PreparedOptions;
      readonly reason: CheckReason;
      readonly messages?: readonly CheckMessage[];
    }
>;

/**
 * 普通递归 Check authoring value 的共享字段。
 *
 * @typeParam AuthoredOptions - Definition 中的 declarative options shape。
 * @typeParam PreparedOptions - preflight 后 callback 接收的 invocation-local options shape。
 * @remarks 该值可以同时有 `execution` 和 `checks`；只有 executable node 产生 final Check fact。
 */
interface CheckBase<AuthoredOptions extends object, PreparedOptions extends object> {
  /** 在 Definition 内唯一的 stable Check ID。 */
  readonly checkId: string;
  /** 人读 progress 与 output 使用的非空名称。 */
  readonly displayName: string;
  /** Check-owned declarative options；默认 Check 的嵌套 branch 以普通对象组合替换。 */
  readonly options?: AuthoredOptions;
  /** 仅当多 flag presence predicate 匹配时启用 executable Check；省略时始终启用。 */
  readonly enabledByFlags?: CheckFlagEnablement;
  /** 可执行节点的 callback；省略时此节点只承载递归 children。 */
  execution?(
    this: void,
    context: CheckExecutionContext<PreparedOptions>
  ): CheckResult | Promise<CheckResult>;
  /** 继承 scheduling context 的 child Checks，不会单独形成 container result。 */
  readonly checks?: readonly Check[];
  /** 必须全部 `passed` 才能开始当前 Check author work 的直接 prerequisite Check IDs。 */
  readonly dependsOn?: InheritableCheckCollection<string>;
  /** 等待任意 terminal outcome 并授权当前 Check readback 的直接 observation Check IDs。 */
  readonly observes?: InheritableCheckCollection<string>;
  /** 此 Check 及其 descendants 的最大并行预算。 */
  readonly maxParallel?: number;
  /** 同一 ready admission 层级中的静态优先级；省略时继承并最终规范化为 `0`。 */
  readonly admissionPriority?: number;
  /** 共享资源名称，或对父 mutex collection 的显式 edit。 */
  readonly mutex?: InheritableCheckCollection<string>;
  /** 已结算 Check 的人读可见性；可执行节点默认 `always`。 */
  readonly visibility?: CheckVisibility;
}

/**
 * 判断两个 options shape 是否互相可赋值；互相可赋值时 execution 不需要 preparation 转换。
 */
type HasSameOptionsShape<AuthoredOptions extends object, PreparedOptions extends object> = [
  AuthoredOptions
] extends [PreparedOptions]
  ? [PreparedOptions] extends [AuthoredOptions]
    ? true
    : false
  : false;

/** Prepared shape 不同时，preflight 是建立安全转换的必填边界。 */
type CheckPreflightField<AuthoredOptions extends object, PreparedOptions extends object> =
  HasSameOptionsShape<AuthoredOptions, PreparedOptions> extends true
    ? Readonly<{ readonly preflight?: CheckPreflight<AuthoredOptions, PreparedOptions> }>
    : Readonly<{ readonly preflight: CheckPreflight<AuthoredOptions, PreparedOptions> }>;

/**
 * Project Definition 中的普通递归 Check authoring value。
 *
 * @typeParam AuthoredOptions - Definition 中的 declarative options shape。
 * @typeParam PreparedOptions - preflight 后 callback 接收的 invocation-local options shape。
 * @remarks Definition 只闭合 authored JSON options；每个 admitted Check 先在自身 Task lifecycle 内执行
 * preflight，随后才执行 callback。`PreparedOptions` 与 `AuthoredOptions` 不同时必须提供 preflight；同形时可以
 * 省略。它不进入 declarative fingerprint 或 machine output。
 */
export type Check<
  AuthoredOptions extends object = object,
  PreparedOptions extends object = AuthoredOptions
> = CheckBase<AuthoredOptions, PreparedOptions> &
  CheckPreflightField<AuthoredOptions, PreparedOptions>;

export type EmptyCheckOptions = Readonly<Record<never, never>>;

/**
 * 防止宽泛的 parser 标注擦除 `PromiseLike`。canonical `then` field 可以保存 JSON data，
 * 但不能保存使该值成为 thenable 的 callable。
 */
type NonThenableData = Readonly<{ readonly then?: CanonicalJsonValue }>;

/**
 * 将 canonical direct-relation data 还原为 provider final-data shape 的同步 parser。
 *
 * @typeParam FinalData - provider 在 `passed`/`failed` result 中声明的 final-data shape。
 * @remarks Product 不调用此 parser；provider 负责不受信任或跨版本 data 的业务验证。
 */
export type CheckDataParser<FinalData extends object = object> = (
  this: void,
  data: CanonicalJsonObject
) => FinalData & NonThenableData;

type CheckAuthoringBase<
  Id extends string,
  AuthoredOptions extends object,
  PreparedOptions extends object
> = Omit<CheckBase<AuthoredOptions, PreparedOptions>, "checkId" | "execution" | "options"> &
  CheckPreflightField<AuthoredOptions, PreparedOptions> &
  Readonly<{ readonly checkId: Id }>;

interface OrdinaryCheckFields<PreparedOptions extends object> {
  execution?(
    this: void,
    context: CheckExecutionContext<PreparedOptions>
  ): CheckResult | Promise<CheckResult>;
  readonly parseData?: never;
}

export type CheckWithOptions<
  Id extends string,
  AuthoredOptions extends object,
  PreparedOptions extends object = AuthoredOptions
> = CheckAuthoringBase<Id, AuthoredOptions, PreparedOptions> &
  OrdinaryCheckFields<PreparedOptions> &
  Readonly<{
    readonly options: AuthoredOptions;
  }>;

export type CheckWithoutOptions<Id extends string> = CheckAuthoringBase<
  Id,
  EmptyCheckOptions,
  EmptyCheckOptions
> &
  OrdinaryCheckFields<EmptyCheckOptions> &
  Readonly<{
    readonly options?: never;
  }>;

interface TypedCheckFields<PreparedOptions extends object, Parser extends CheckDataParser> {
  /**
   * 将 canonical runtime data 还原为 provider data。
   *
   * 启发式边界：同版本且受信任的 provider 若由测试保证 data shape，可仅将它实现为
   * identity/type anchor。这不验证 JavaScript 或基于 cast 的 producer、历史或跨版本 artifact，
   * 也不验证不受信任输入。
   */
  readonly parseData: Parser;

  execution(
    this: void,
    context: CheckExecutionContext<PreparedOptions>
  ): CheckResult<NoInfer<ReturnType<Parser>>> | Promise<CheckResult<NoInfer<ReturnType<Parser>>>>;
}

export type TypedCheckWithOptions<
  Id extends string,
  AuthoredOptions extends object,
  Parser extends CheckDataParser,
  PreparedOptions extends object = AuthoredOptions
> = CheckAuthoringBase<Id, AuthoredOptions, PreparedOptions> &
  TypedCheckFields<PreparedOptions, Parser> &
  Readonly<{
    readonly options: AuthoredOptions;
  }>;

export type TypedCheckWithoutOptions<
  Id extends string,
  Parser extends CheckDataParser
> = CheckAuthoringBase<Id, EmptyCheckOptions, EmptyCheckOptions> &
  TypedCheckFields<EmptyCheckOptions, Parser> &
  Readonly<{
    readonly options?: never;
  }>;

/**
 * 定义一个 Check，同时保留 literal `checkId`、options 与 typed-provider parser 的 inference。
 *
 * @remarks 此函数负责 authoring inference；{@link run} 负责 Project Definition validation。
 * @example 定义带 options、Records 与 messages 的自定义 Check
 * ```ts
 * function hasValidLicensePolicyOptions(options: object): boolean {
 *   const denied: unknown = Reflect.get(options, "denied");
 *   return (
 *     Object.keys(options).length === 1 &&
 *     Object.hasOwn(options, "denied") &&
 *     Array.isArray(denied) &&
 *     denied.every((license) => typeof license === "string")
 *   );
 * }
 *
 * const licensePolicy = defineCheck({
 *   checkId: "license-policy",
 *   displayName: "License policy",
 *   options: { denied: ["GPL-3.0-only"] },
 *   preflight(options) {
 *     return hasValidLicensePolicyOptions(options)
 *       ? { status: "success", preparedOptions: options }
 *       : { status: "failure", action: "block", reason: { code: "invalid-options" } };
 *   },
 *   visibility: "attention",
 *   execution({ options, records, signal }) {
 *     if (signal.aborted) return { status: "unavailable", reason: { code: "cancelled" } };
 *
 *     const deniedCount = options.denied.length;
 *     if (deniedCount > 0) {
 *       records.report({ id: "denied-license" }, { count: deniedCount });
 *       return {
 *         status: "failed",
 *         data: { deniedCount },
 *         messages: [{ level: "warning", code: "denied-license", message: "Denied licenses found." }]
 *       };
 *     }
 *     return { status: "passed", data: { deniedCount: 0 } };
 *   }
 * });
 * ```
 */
export function defineCheck<
  const Id extends string,
  AuthoredOptions extends object,
  PreparedOptions extends object = AuthoredOptions
>(
  value: CheckWithOptions<Id, AuthoredOptions, PreparedOptions>
): CheckWithOptions<Id, AuthoredOptions, PreparedOptions>;
export function defineCheck<const Id extends string>(
  value: CheckWithoutOptions<Id>
): CheckWithoutOptions<Id>;
export function defineCheck<
  const Id extends string,
  AuthoredOptions extends object,
  const Parser extends CheckDataParser,
  PreparedOptions extends object = AuthoredOptions
>(
  value: TypedCheckWithOptions<Id, AuthoredOptions, Parser, PreparedOptions>
): TypedCheckWithOptions<Id, AuthoredOptions, Parser, PreparedOptions>;
export function defineCheck<const Id extends string, const Parser extends CheckDataParser>(
  value: TypedCheckWithoutOptions<Id, Parser>
): TypedCheckWithoutOptions<Id, Parser>;
export function defineCheck(value: Check): Check {
  return value;
}

import { snapshotClosedRecord } from "../data-boundary/closed-values.ts";
import type { CheckDescriptor } from "./descriptor.ts";

export interface CheckDescriptorValidationIssue {
  readonly path: string;
  readonly code: "invalid-value";
  readonly message: string;
}

export type CheckDescriptorValidationResult = Readonly<
  | { readonly ok: true; readonly value: CheckDescriptor }
  | {
      readonly ok: false;
      readonly issues: readonly [
        CheckDescriptorValidationIssue,
        ...CheckDescriptorValidationIssue[]
      ];
    }
>;

/** Validates the minimal Check identity shared by Definition authoring and final facts. */
export function validateCheckDescriptor(value: unknown): CheckDescriptorValidationResult {
  const definition = snapshotClosedRecord(value);
  if (definition === undefined) return invalid("$", "Check definition must be a closed object");
  if (!hasExactKeys(definition, ["checkId", "displayName"])) {
    return invalid("$", "Check definition has unsupported fields");
  }
  if (
    typeof definition.checkId !== "string" ||
    definition.checkId.length === 0 ||
    typeof definition.displayName !== "string"
  ) {
    return invalid("$", "Check definition identity is invalid");
  }
  if (definition.displayName.length === 0) {
    return invalid("$.displayName", "Check displayName is empty");
  }
  return Object.freeze({
    ok: true,
    value: Object.freeze({ checkId: definition.checkId, displayName: definition.displayName })
  });
}

function hasExactKeys(value: Readonly<Record<string, unknown>>, keys: readonly string[]): boolean {
  return (
    Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key))
  );
}

function invalid(path: string, message: string): CheckDescriptorValidationResult {
  const issue = Object.freeze({
    path,
    code: "invalid-value",
    message
  }) satisfies CheckDescriptorValidationIssue;
  const issues: readonly [CheckDescriptorValidationIssue, ...CheckDescriptorValidationIssue[]] = [
    issue
  ];
  return Object.freeze({ ok: false, issues: Object.freeze(issues) });
}

/** The declaration identity retained for one executable Check. */
export interface CheckDescriptor {
  readonly checkId: string;
  readonly displayName: string;
}

import type { CheckMessage, CheckResult } from "./check.ts";

/**
 * 将 Check-owned Finding 投影为有界 terminal messages 所需的超限上下文。
 * 完整 Finding facts 与深入查看位置继续由调用方拥有。
 */
export interface FindingOverflowContext<Finding> {
  readonly omittedFindings: readonly Finding[];
  readonly omittedCount: number;
  readonly presentedCount: number;
  readonly totalCount: number;
}

/**
 * 将调用方已经稳定排序的 Finding 投影为有界 Check messages。
 *
 * `limit`、安全字段和超限后的深入查看说明都由 producing Check 决定。Product 不读取 Finding
 * shape，也不猜测完整明细位于 Records、artifact、transcript 或其它位置。
 */
export function presentCheckFindings<Finding>(input: {
  readonly findings: readonly Finding[];
  readonly limit: number;
  readonly message: (finding: Finding, index: number) => CheckMessage;
  readonly omittedMessage: (context: FindingOverflowContext<Finding>) => CheckMessage;
}): readonly CheckMessage[] {
  assertFindingLimit(input.limit);
  if (input.findings.length === 0) return Object.freeze([]);

  const presentedFindings = input.findings.slice(0, input.limit);
  const messages = presentedFindings.map((finding, index) =>
    Object.freeze({ ...input.message(finding, index) })
  );
  const omittedFindings = Object.freeze(input.findings.slice(input.limit));
  if (omittedFindings.length > 0) {
    messages.push(
      Object.freeze({
        ...input.omittedMessage(
          Object.freeze({
            omittedFindings,
            omittedCount: omittedFindings.length,
            presentedCount: presentedFindings.length,
            totalCount: input.findings.length
          })
        )
      })
    );
  }
  return Object.freeze(messages);
}

/** Appends presentation-only messages without changing the owning terminal result. */
export function appendCheckMessages<Data extends object>(
  result: CheckResult<Data>,
  messages: readonly CheckMessage[]
): CheckResult<Data> {
  if (messages.length === 0) return result;
  return Object.freeze({
    ...result,
    messages: Object.freeze([...(result.messages ?? []), ...messages])
  });
}

function assertFindingLimit(limit: number): void {
  if (!Number.isSafeInteger(limit) || limit < 0) {
    throw new TypeError("Finding presentation limit must be a non-negative safe integer");
  }
}

const INHERITED_CHECK_COLLECTION: unique symbol = Symbol("vibe-check.inherited-check-collection");

/** 使用 {@link inherit} 对父 Check 的 string collection 做显式增删的输入。 */
export type InheritCheckCollectionInput<T> = Readonly<
  | { readonly add: readonly T[]; readonly remove?: readonly T[] }
  | { readonly add?: readonly T[]; readonly remove: readonly T[] }
>;

/**
 * 由 {@link inherit} 创建、带有不可伪造 marker 的 collection edit。
 *
 * @remarks Definition validation 不接受看起来相同的 plain object。
 */
export type InheritedCheckCollection<T> = InheritCheckCollectionInput<T> &
  Readonly<{
    readonly [INHERITED_CHECK_COLLECTION]: true;
  }>;

/**
 * 可以直接替换父 collection 的数组，或由 {@link inherit} 表示的显式 edit。
 *
 * @typeParam T - collection item 类型。
 */
export type InheritableCheckCollection<T> = readonly T[] | InheritedCheckCollection<T>;

const inheritedCollections = new WeakSet();

type InheritedCollectionEntry = "data" | "invalid" | "marker";

/**
 * 创建可用于 `dependsOn`、`observes` 或 `mutex` 的受信任继承编辑。
 *
 * @typeParam T - 要添加或移除的 collection item 类型。
 * @param value - 至少提供 `add` 或 `remove` 的 edit；空数组可显式表示不添加或不移除。
 * @returns 只有此函数创建的值会被 Definition validation 识别为 inherited collection。
 */
export function inherit<T>(value: InheritCheckCollectionInput<T>): InheritedCheckCollection<T> {
  const result = { ...value, [INHERITED_CHECK_COLLECTION]: true as const };
  Object.defineProperty(result, INHERITED_CHECK_COLLECTION, { enumerable: false });
  inheritedCollections.add(result);
  return result;
}

export function isInheritedCheckCollection(
  value: unknown
): value is InheritedCheckCollection<unknown> {
  return typeof value === "object" && value !== null && inheritedCollections.has(value);
}

/** Copies the trusted marker while preserving the authoring data's closed shape. */
export function snapshotInheritedCheckCollection(
  value: InheritedCheckCollection<unknown>
): Readonly<Record<string, unknown>> | undefined {
  try {
    if (!hasPlainObjectPrototype(value)) return undefined;
    const snapshot: Record<string, unknown> = {};
    let hasMarker = false;
    for (const key of Reflect.ownKeys(value)) {
      const entry = snapshotInheritedCollectionEntry(
        snapshot,
        key,
        Object.getOwnPropertyDescriptor(value, key)
      );
      if (entry === "invalid") return undefined;
      if (entry === "marker") hasMarker = true;
    }
    return hasMarker ? Object.freeze(snapshot) : undefined;
  } catch {
    return undefined;
  }
}

function hasPlainObjectPrototype(value: object): boolean {
  const prototype: unknown = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function snapshotInheritedCollectionEntry(
  snapshot: Record<string, unknown>,
  key: PropertyKey,
  descriptor: PropertyDescriptor | undefined
): InheritedCollectionEntry {
  if (!isDataDescriptor(descriptor)) return "invalid";
  if (key === INHERITED_CHECK_COLLECTION) {
    return descriptor.enumerable || descriptor.value !== true ? "invalid" : "marker";
  }
  if (typeof key !== "string" || descriptor.enumerable !== true) return "invalid";
  Object.defineProperty(snapshot, key, {
    configurable: true,
    enumerable: true,
    value: descriptor.value,
    writable: true
  });
  return "data";
}

function isDataDescriptor(
  descriptor: PropertyDescriptor | undefined
): descriptor is PropertyDescriptor {
  return descriptor !== undefined && descriptor.get === undefined && descriptor.set === undefined;
}

import { snapshotClosedArray, snapshotClosedRecord } from "../data-boundary/closed-values.ts";

type JsonSnapshot = object | readonly unknown[] | string | number | boolean | null;

/** Copies a closed JSON object without retaining untyped authoring input. */
export function snapshotJsonObject(value: unknown): object | undefined {
  const snapshot = snapshotJson(value, new Set<object>());
  return isJsonObject(snapshot) ? snapshot : undefined;
}

function isJsonObject(value: JsonSnapshot | undefined): value is object {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function snapshotJson(value: unknown, ancestors: Set<object>): JsonSnapshot | undefined {
  const primitive = snapshotJsonPrimitive(value);
  if (primitive !== undefined || value === null) return primitive;
  if (typeof value !== "object") return undefined;
  if (ancestors.has(value)) return undefined;

  const items = snapshotClosedArray(value);
  if (items !== undefined) return snapshotJsonArray(value, items, ancestors);

  const data = snapshotClosedRecord(value);
  if (data === undefined) return undefined;
  return snapshotJsonRecord(value, data, ancestors);
}

function snapshotJsonPrimitive(value: unknown): string | number | boolean | null | undefined {
  if (value === null) return null;
  if (typeof value === "string" || typeof value === "boolean") return value;
  if (typeof value !== "number" || !Number.isFinite(value)) return undefined;
  return value;
}

function snapshotJsonArray(
  value: object,
  items: readonly unknown[],
  ancestors: Set<object>
): readonly JsonSnapshot[] | undefined {
  ancestors.add(value);
  try {
    const snapshot: JsonSnapshot[] = [];
    for (const item of items) {
      const parsed = snapshotJson(item, ancestors);
      if (parsed === undefined) return undefined;
      snapshot.push(parsed);
    }
    return Object.freeze(snapshot);
  } finally {
    ancestors.delete(value);
  }
}

function snapshotJsonRecord(
  value: object,
  data: Readonly<Record<string, unknown>>,
  ancestors: Set<object>
): object | undefined {
  ancestors.add(value);
  try {
    // Assignment to an ordinary object treats an own `__proto__` JSON key as
    // a prototype mutation. Define the data property so every closed JSON key
    // remains data and the detached snapshot retains its ordinary prototype.
    const snapshot: Record<string, unknown> = {};
    for (const [key, item] of Object.entries(data)) {
      const parsed = snapshotJson(item, ancestors);
      if (parsed === undefined) return undefined;
      Object.defineProperty(snapshot, key, {
        configurable: true,
        enumerable: true,
        value: parsed,
        writable: true
      });
    }
    return Object.freeze(snapshot);
  } finally {
    ancestors.delete(value);
  }
}

import type { CanonicalJsonObject, CanonicalJsonValue } from "./canonical-json.ts";

export type {
  CanonicalJsonObject,
  CanonicalJsonPrimitive,
  CanonicalJsonValue
} from "./canonical-json.ts";

const encoder = new TextEncoder();

/**
 * Materializes arbitrary author data without property reads or JSON hooks.
 * The returned graph is detached, prototype-safe, and deeply frozen before it
 * becomes a Core fact. Canonical text order is applied explicitly at serialization.
 */
export function canonicalizeJsonObject(value: unknown): CanonicalJsonObject | undefined {
  const canonical = canonicalize(value, new Set<object>());
  return canonical !== undefined && isCanonicalJsonObject(canonical) ? canonical : undefined;
}

export function canonicalizeJsonValue(value: unknown): CanonicalJsonValue | undefined {
  return canonicalize(value, new Set<object>());
}

/** Serializes detached canonical JSON with explicit lexical object-key ordering. */
export function canonicalJsonText(value: unknown): string {
  const canonical = canonicalizeJsonValue(value);
  if (canonical === undefined) {
    throw new TypeError("Canonical JSON could not safely materialize the input");
  }
  return canonicalText(canonical);
}

/** Emits canonical UTF-8 JSON without invoking author getters or `toJSON`. */
export function canonicalJsonBytes(value: unknown): Uint8Array {
  return encoder.encode(canonicalJsonText(value));
}

function canonicalize(value: unknown, ancestors: Set<object>): CanonicalJsonValue | undefined {
  if (value === null) return null;
  const primitive = canonicalPrimitive(value);
  if (primitive !== undefined) return primitive;
  if (typeof value !== "object") return undefined;
  if (!admitCanonicalObject(value, ancestors)) return undefined;

  try {
    return Array.isArray(value)
      ? canonicalizeArray(value, ancestors)
      : canonicalizeObject(value, ancestors);
  } catch {
    return undefined;
  } finally {
    ancestors.delete(value);
  }
}

function canonicalPrimitive(value: unknown): CanonicalJsonValue | undefined {
  if (typeof value === "boolean" || typeof value === "string") return value;
  if (typeof value !== "number" || !Number.isFinite(value)) return undefined;
  return Object.is(value, -0) ? 0 : value;
}

function admitCanonicalObject(value: object, ancestors: Set<object>): boolean {
  if (ancestors.has(value)) return false;
  ancestors.add(value);
  return true;
}

function canonicalizeArray(
  value: readonly unknown[],
  ancestors: Set<object>
): readonly CanonicalJsonValue[] | undefined {
  const length = denseCanonicalArrayLength(value);
  if (length === undefined) return undefined;
  return canonicalArrayElements(value, length, ancestors);
}

function denseCanonicalArrayLength(value: readonly unknown[]): number | undefined {
  if (Object.getPrototypeOf(value) !== Array.prototype) return undefined;
  const keys = Reflect.ownKeys(value);
  const lengthDescriptor = Object.getOwnPropertyDescriptor(value, "length");
  if (!isDataDescriptor(lengthDescriptor) || lengthDescriptor.enumerable) return undefined;
  const length = lengthDescriptor.value;
  if (
    typeof length !== "number" ||
    !Number.isSafeInteger(length) ||
    length < 0 ||
    keys.length !== length + 1
  )
    return undefined;
  if (!keys.includes("length")) return undefined;
  return length;
}

function canonicalArrayElements(
  value: readonly unknown[],
  length: number,
  ancestors: Set<object>
): readonly CanonicalJsonValue[] | undefined {
  const values: CanonicalJsonValue[] = [];
  for (let index = 0; index < length; index += 1) {
    const key = String(index);
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!isEnumerableDataDescriptor(descriptor)) return undefined;
    const item = canonicalize(descriptor.value, ancestors);
    if (item === undefined) return undefined;
    values.push(item);
  }
  return Object.freeze(values);
}

function canonicalizeObject(
  value: object,
  ancestors: Set<object>
): CanonicalJsonObject | undefined {
  const prototype: unknown = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) return undefined;
  const keys: string[] = [];
  for (const key of Reflect.ownKeys(value)) {
    if (typeof key !== "string") return undefined;
    keys.push(key);
  }

  const snapshot: Record<string, CanonicalJsonValue> = {};
  Object.setPrototypeOf(snapshot, null);
  for (const key of keys.sort(compareText)) {
    const descriptor = Object.getOwnPropertyDescriptor(value, key);
    if (!isEnumerableDataDescriptor(descriptor)) return undefined;
    const item = canonicalize(descriptor.value, ancestors);
    if (item === undefined) return undefined;
    Object.defineProperty(snapshot, key, {
      configurable: false,
      enumerable: true,
      value: item,
      writable: false
    });
  }
  return Object.freeze(snapshot);
}

type DataDescriptor = Omit<PropertyDescriptor, "get" | "set" | "value"> &
  Readonly<{
    get?: undefined;
    set?: undefined;
    value: unknown;
  }>;

function isDataDescriptor(
  descriptor: PropertyDescriptor | undefined
): descriptor is DataDescriptor {
  return (
    descriptor !== undefined &&
    descriptor.get === undefined &&
    descriptor.set === undefined &&
    Object.hasOwn(descriptor, "value")
  );
}

function isEnumerableDataDescriptor(
  descriptor: PropertyDescriptor | undefined
): descriptor is DataDescriptor {
  return isDataDescriptor(descriptor) && descriptor.enumerable === true;
}

function isCanonicalJsonObject(value: CanonicalJsonValue): value is CanonicalJsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function canonicalText(value: CanonicalJsonValue): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (isCanonicalJsonArray(value)) {
    return `[${value.map((entry) => canonicalText(entry)).join(",")}]`;
  }
  return `{${Object.keys(value)
    .sort(compareText)
    .map((key) => `${JSON.stringify(key)}:${canonicalText(value[key])}`)
    .join(",")}}`;
}

function isCanonicalJsonArray(value: CanonicalJsonValue): value is readonly CanonicalJsonValue[] {
  return Array.isArray(value);
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

/** Package-private static shape for Product's detached canonical JSON facts. */
export type CanonicalJsonPrimitive = boolean | null | number | string;

export type CanonicalJsonValue =
  | CanonicalJsonPrimitive
  | readonly CanonicalJsonValue[]
  | CanonicalJsonObject;

export interface CanonicalJsonObject {
  readonly [key: string]: CanonicalJsonValue;
}

interface OwnDataShape {
  readonly descriptors: Readonly<Record<string, PropertyDescriptor>>;
  readonly keys: readonly string[];
}

function ownDataShape(value: object): OwnDataShape | undefined {
  const descriptors: Readonly<Record<string, PropertyDescriptor>> =
    Object.getOwnPropertyDescriptors(value);
  const ownKeys = Reflect.ownKeys(descriptors);
  const keys: string[] = [];
  for (const key of ownKeys) {
    if (typeof key !== "string") return undefined;
    keys.push(key);
  }
  if (
    keys.some((key) => {
      const descriptor = descriptors[key];
      return descriptor.get !== undefined || descriptor.set !== undefined;
    })
  )
    return undefined;
  return { descriptors, keys };
}

export function snapshotPlainRecord(value: unknown): Readonly<Record<string, unknown>> | undefined {
  try {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      return undefined;
    }
    const prototype: unknown = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) {
      return undefined;
    }
    const descriptors: Readonly<Record<string, PropertyDescriptor>> =
      Object.getOwnPropertyDescriptors(value);
    if (
      Object.values(descriptors).some(
        (descriptor) => descriptor.get !== undefined || descriptor.set !== undefined
      )
    ) {
      return undefined;
    }
    return Object.fromEntries(
      Object.entries(descriptors)
        .filter(([, descriptor]) => descriptor.enumerable === true)
        .map(([key, descriptor]) => [key, descriptor.value as unknown])
    );
  } catch {
    return undefined;
  }
}

export function snapshotClosedRecord(
  value: unknown
): Readonly<Record<string, unknown>> | undefined {
  try {
    if (value === null || typeof value !== "object" || Array.isArray(value)) return undefined;
    const prototype: unknown = Object.getPrototypeOf(value);
    if (prototype !== Object.prototype && prototype !== null) return undefined;
    const shape = ownDataShape(value);
    if (
      shape === undefined ||
      shape.keys.some((key) => shape.descriptors[key].enumerable !== true)
    ) {
      return undefined;
    }
    return Object.freeze(
      Object.fromEntries(shape.keys.map((key) => [key, shape.descriptors[key].value as unknown]))
    );
  } catch {
    return undefined;
  }
}

/** Snapshots a closed plain record only when it has exactly the declared own keys. */
export function snapshotExactClosedRecord(
  value: unknown,
  keys: readonly string[]
): Readonly<Record<string, unknown>> | undefined {
  const record = snapshotClosedRecord(value);
  return record !== undefined && hasExactPlainRecordKeys(record, keys) ? record : undefined;
}

function closedArrayLength(shape: OwnDataShape): number | undefined {
  const descriptor = shape.descriptors.length;
  if (typeof descriptor?.value !== "number" || descriptor.enumerable !== false) return undefined;
  const length = descriptor.value;
  return Number.isSafeInteger(length) && length >= 0 && shape.keys.length === length + 1
    ? length
    : undefined;
}

function closedArrayItems(shape: OwnDataShape, length: number): readonly unknown[] | undefined {
  const items: unknown[] = [];
  for (let index = 0; index < length; index += 1) {
    const descriptor = shape.descriptors[String(index)];
    if (descriptor === undefined || descriptor.enumerable !== true) return undefined;
    items.push(descriptor.value as unknown);
  }
  return Object.freeze(items);
}

export function snapshotClosedArray(value: unknown): readonly unknown[] | undefined {
  try {
    if (!Array.isArray(value) || Object.getPrototypeOf(value) !== Array.prototype) return undefined;
    const shape = ownDataShape(value);
    if (shape === undefined) return undefined;
    const length = closedArrayLength(shape);
    return length === undefined ? undefined : closedArrayItems(shape, length);
  } catch {
    return undefined;
  }
}

export function hasExactPlainRecordKeys(
  value: Readonly<Record<string, unknown>>,
  keys: readonly string[]
): boolean {
  const actualKeys = Object.keys(value);
  return actualKeys.length === keys.length && actualKeys.every((key) => keys.includes(key));
}

export function hasRequiredAndOptionalRecordKeys(
  value: Readonly<Record<string, unknown>>,
  keys: Readonly<{
    readonly optional: readonly string[];
    readonly required: readonly string[];
  }>
): boolean {
  const supportedKeys = new Set([...keys.required, ...keys.optional]);
  return (
    keys.required.every((key) => Object.hasOwn(value, key)) &&
    Object.keys(value).every((key) => supportedKeys.has(key))
  );
}

export interface ClosedPolicyRecordKeys {
  readonly optional?: readonly string[];
  readonly required?: readonly string[];
}

/** Snapshots an authoring record whose keys are limited to one required/optional policy. */
export function snapshotClosedPolicyRecord(
  value: unknown,
  keys: ClosedPolicyRecordKeys
): Readonly<Record<string, unknown>> | undefined {
  const record = snapshotClosedRecord(value);
  return record !== undefined &&
    hasRequiredAndOptionalRecordKeys(record, {
      optional: keys.optional ?? [],
      required: keys.required ?? []
    })
    ? record
    : undefined;
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

export function isNonArrayRecord(value: unknown): value is Record<string, unknown> {
  return isRecord(value) && !Array.isArray(value);
}

export function isUnknownArray(value: unknown): value is unknown[] {
  return Array.isArray(value);
}

export function isStringArray(value: unknown): value is string[] {
  return isUnknownArray(value) && value.every((item) => typeof item === "string");
}

export function isNonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

export function isPositiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

export function isNonNegativeSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

import {
  canonicalizeJsonValue,
  canonicalJsonText,
  type CanonicalJsonObject,
  type CanonicalJsonValue
} from "../data-boundary/canonical-data.ts";

/** 由采用方声明、用于匹配一个 finding 的语义身份与豁免理由。 */
export interface FindingWaiver<Identity> {
  /** 调用方定义的稳定 finding 身份；匹配时按 canonical JSON 结构比较。 */
  readonly identity: Identity;
  /** 解释该 finding 在当前范围内可被豁免的非空理由。 */
  readonly reason: string;
}

/** helper 安全 materialize 后保留的 waiver evidence；identity 是 detached canonical JSON。 */
export interface MaterializedFindingWaiver {
  /** 从 authored identity materialize 的 detached、deep-frozen canonical JSON。 */
  readonly identity: CanonicalJsonValue;
  /** 从 authored reason materialize 的非空理由。 */
  readonly reason: string;
}

/** 一项 finding waiver 的配置与匹配次数审计。 */
export interface FindingWaiverAudit {
  /** 被审计的 materialized authored waiver evidence，而非调用方可变输入引用。 */
  readonly waiver: MaterializedFindingWaiver;
  /** 该 waiver identity 在完整 finding 集合中匹配到的数量。 */
  readonly matchCount: number;
  /** 未使用、正常应用，或因过宽而没有应用。 */
  readonly status: "unused" | "applied" | "overmatched";
}

/** reconciliation 后单个 finding 的可执行处置；只有 `waived` branch 携带 matched waiver。 */
export type ReconciledFinding<Finding> = Readonly<
  | {
      /** 原始 finding；helper 不解释或改写它的领域字段。 */
      readonly finding: Finding;
      /** 没有匹配 waiver 的正常待处理 finding。 */
      readonly disposition: "actionable";
    }
  | {
      /** 原始 finding；helper 不解释或改写它的领域字段。 */
      readonly finding: Finding;
      /** 恰好匹配一项 waiver 的 finding。 */
      readonly disposition: "waived";
      /** applied waiver 的身份和理由。 */
      readonly waiver: MaterializedFindingWaiver;
    }
  | {
      /** 原始 finding；helper 不解释或改写它的领域字段。 */
      readonly finding: Finding;
      /** `overmatched` 保持为待处理，避免宽泛 waiver 静默覆盖多个 finding。 */
      readonly disposition: "overmatched";
    }
>;

/** 调用方提供完整候选集、身份识别器和 waiver 配置的输入。 */
export interface ReconcileFindingWaiversOptions<Finding, Identity> {
  /** 必须是完整 finding 候选集合，helper 才能审计每项 waiver 的匹配次数。 */
  readonly findings: readonly Finding[];
  /** 从完整 finding 提取调用方选择的稳定语义身份。 */
  readonly identify: (finding: Finding) => Identity;
  /** 要与识别器输出进行 canonical structural matching 的 waiver。 */
  readonly waivers: readonly FindingWaiver<Identity>[];
}

/** 独立 waiver reconciliation 的完整输出，保留 finding 处置和每项配置审计。 */
export interface FindingWaiverReconciliation<Finding> {
  /** 与 input finding 顺序相同的 reconciliation 结果。 */
  readonly findings: readonly ReconciledFinding<Finding>[];
  /** 与 input waiver 顺序相同的完整配置审计。 */
  readonly waiverAudits: readonly FindingWaiverAudit[];
}

/**
 * 按调用方定义的语义身份对完整 finding 集合和 waiver 配置做 canonical structural reconciliation。
 *
 * 每项 waiver 必须有唯一、可 canonicalize 的 identity 和非空 reason。匹配零项时产生 `unused` 审计；
 * 匹配一项时该 finding 为 `waived`；匹配多项时产生 `overmatched` 审计，相关 finding 保持待处理。
 */
export function reconcileFindingWaivers<Finding, Identity>(
  options: ReconcileFindingWaiversOptions<Finding, Identity>
): FindingWaiverReconciliation<Finding> {
  const waivers = materializeWaivers(options.waivers);
  const matchCounts = new Array<number>(waivers.length).fill(0);
  const waiverIndexesByIdentity = new Map<string, number>();
  for (const [index, waiver] of waivers.entries()) {
    const identity = canonicalIdentity(waiver.identity, "waiver identity");
    if (waiverIndexesByIdentity.has(identity)) {
      throw new TypeError("Finding waivers must not declare duplicate canonical identities");
    }
    waiverIndexesByIdentity.set(identity, index);
  }

  const matchedWaiverIndexes = options.findings.map((finding) => {
    const identity = canonicalIdentity(options.identify(finding), "finding identity");
    const waiverIndex = waiverIndexesByIdentity.get(identity);
    if (waiverIndex !== undefined) matchCounts[waiverIndex] += 1;
    return waiverIndex;
  });
  const waiverAudits = Object.freeze(
    waivers.map((waiver, index) =>
      Object.freeze({
        matchCount: matchCounts[index] ?? 0,
        status: waiverAuditStatus(matchCounts[index] ?? 0),
        waiver
      })
    )
  );
  const findings = Object.freeze(
    options.findings.map((finding, index) => {
      const waiverIndex = matchedWaiverIndexes[index];
      const audit = waiverIndex === undefined ? undefined : waiverAudits[waiverIndex];
      return reconciledFinding(finding, audit);
    })
  );
  return Object.freeze({ findings, waiverAudits });
}

function materializeWaivers<Identity>(
  waivers: readonly FindingWaiver<Identity>[]
): readonly MaterializedFindingWaiver[] {
  const canonicalWaivers = canonicalizeJsonValue(waivers);
  if (canonicalWaivers === undefined || !isCanonicalArray(canonicalWaivers)) {
    throw new TypeError("Finding waivers must be canonical JSON arrays");
  }
  return Object.freeze(canonicalWaivers.map(materializeWaiver));
}

function materializeWaiver(value: CanonicalJsonValue): MaterializedFindingWaiver {
  if (
    !isCanonicalObject(value) ||
    !Object.hasOwn(value, "identity") ||
    !Object.hasOwn(value, "reason")
  ) {
    throw new TypeError("Finding waivers must declare canonical identity and reason fields");
  }
  const reason = value.reason;
  if (typeof reason !== "string" || reason.length === 0) {
    throw new TypeError("Finding waiver reasons must be non-empty strings");
  }
  return Object.freeze({ identity: value.identity, reason });
}

function isCanonicalObject(value: CanonicalJsonValue): value is CanonicalJsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isCanonicalArray(value: CanonicalJsonValue): value is readonly CanonicalJsonValue[] {
  return Array.isArray(value);
}

function canonicalIdentity(identity: unknown, kind: string): string {
  try {
    return canonicalJsonText(identity);
  } catch {
    throw new TypeError(`Finding ${kind} must be canonical JSON`);
  }
}

function waiverAuditStatus(matchCount: number): FindingWaiverAudit["status"] {
  if (matchCount === 0) return "unused";
  return matchCount === 1 ? "applied" : "overmatched";
}

function reconciledFinding<Finding>(
  finding: Finding,
  audit: FindingWaiverAudit | undefined
): ReconciledFinding<Finding> {
  if (audit === undefined) return Object.freeze({ disposition: "actionable", finding });
  if (audit.status === "applied") {
    return Object.freeze({ disposition: "waived", finding, waiver: audit.waiver });
  }
  return Object.freeze({ disposition: "overmatched", finding });
}

