export interface MachinePublicationV4 {
  readonly records: readonly MachineRecordV4[];
  readonly run: MachineRunV4;
}

export function projectMachinePublicationV4(
  model: TrustedPublicationModelV4
): MachinePublicationV4 {
  const records = Object.freeze(
    model.snapshot.records.map((record): MachineRecordV4 =>
      freezePublicationValue({
        checkId: record.checkId,
        data: record.data,
        id: record.id,
        schemaVersion: MACHINE_RECORD_V4_IDENTITY
      })
    )
  );
  const run: MachineRunV4 = {
    checks: model.snapshot.checks.map((check): MachineRunV4["checks"][number] => ({
      checkId: check.checkId,
      displayName: check.displayName,
      outcome: check.outcome
    })),
    invocation: { ...model.invocation },
    recordsFingerprint: createRecordsFingerprintV4(records),
    schemaVersion: MACHINE_RUN_V4_IDENTITY
  };
  return Object.freeze({ records, run: freezePublicationValue(run) });
}

import { validateCoreSnapshot } from "../../check-settlement/fact-validation.ts";
import { createRecordsFingerprintV4 } from "./records-fingerprint.ts";
import type { MachineRecordV4, MachineRunV4 } from "./schema.ts";
import { setInvariantFailure, type ValidationFailure } from "./validation-result.ts";

export function validatePublicationInvariants(
  run: MachineRunV4,
  records: readonly MachineRecordV4[]
): ValidationFailure | null {
  const checkOrder = validateCheckOrder(run);
  if (checkOrder !== null) return checkOrder;
  const recordOrder = validateRecordOrder(records);
  if (recordOrder !== null) return recordOrder;
  const ownership = validateRecordOwnership(run, records);
  if (ownership !== null) return ownership;
  const core = validateProjectedCore(run, records);
  if (core !== null) return core;
  return createRecordsFingerprintV4(records) === run.recordsFingerprint
    ? null
    : setInvariantFailure(
        "records-fingerprint",
        "records.ndjson",
        "Records fingerprint must match the complete canonical Record row set."
      );
}

function validateCheckOrder(run: MachineRunV4): ValidationFailure | null {
  let previous: string | undefined;
  for (const check of run.checks) {
    if (previous !== undefined && previous >= check.checkId) {
      return setInvariantFailure(
        "check-canonical-order",
        "run.json",
        "Checks must be uniquely sorted by checkId."
      );
    }
    previous = check.checkId;
  }
  return null;
}

function validateRecordOrder(records: readonly MachineRecordV4[]): ValidationFailure | null {
  let previous: readonly [string, string] | undefined;
  for (const [index, record] of records.entries()) {
    const current = [record.checkId, record.id] as const;
    if (
      previous !== undefined &&
      (previous[0] > current[0] || (previous[0] === current[0] && previous[1] >= current[1]))
    ) {
      return setInvariantFailure(
        "record-canonical-order",
        "records.ndjson",
        "Records must be uniquely sorted by the composite { checkId, id } identity.",
        index
      );
    }
    previous = current;
  }
  return null;
}

function validateRecordOwnership(
  run: MachineRunV4,
  records: readonly MachineRecordV4[]
): ValidationFailure | null {
  const knownChecks = new Set(run.checks.map((check) => check.checkId));
  const unknownIndex = records.findIndex((record) => !knownChecks.has(record.checkId));
  return unknownIndex === -1
    ? null
    : setInvariantFailure(
        "record-check-ownership",
        "records.ndjson",
        "Every Record must name a published owning Check.",
        unknownIndex
      );
}

function validateProjectedCore(
  run: MachineRunV4,
  records: readonly MachineRecordV4[]
): ValidationFailure | null {
  const snapshot = validateCoreSnapshot({
    checks: run.checks,
    records: records.map(({ schemaVersion: _schemaVersion, ...record }) => record)
  });
  return snapshot.ok
    ? null
    : setInvariantFailure("core-snapshot", "run.json", "Published Core facts are invalid.");
}

import type { CoreSnapshot } from "../../check-settlement/facts.ts";
import { MACHINE_V4_TIMESTAMP_PATTERN } from "./schema-identities.ts";

const machineV4TimestampPattern = new RegExp(MACHINE_V4_TIMESTAMP_PATTERN);

export interface PublicationInvocationV4 {
  readonly invocationId: string;
  readonly projectRoot: ".";
  readonly timestamp: string;
}

/** Trusted Core facts and validated invocation metadata for v4 candidate projection. */
export interface TrustedPublicationModelV4 {
  readonly invocation: PublicationInvocationV4;
  readonly snapshot: CoreSnapshot;
}

export function createPublicationModelV4(
  input: Readonly<{ invocation: PublicationInvocationV4; snapshot: CoreSnapshot }>
): TrustedPublicationModelV4 {
  validateInvocation(input.invocation);
  return Object.freeze({
    invocation: Object.freeze({ ...input.invocation }),
    snapshot: input.snapshot
  });
}

function validateInvocation(invocation: PublicationInvocationV4): void {
  if (
    typeof invocation.invocationId !== "string" ||
    invocation.invocationId.length === 0 ||
    invocation.projectRoot !== "." ||
    typeof invocation.timestamp !== "string" ||
    !machineV4TimestampPattern.test(invocation.timestamp)
  ) {
    throw new TypeError("Publication invocation metadata is invalid");
  }
}

import { projectMachinePublicationV4 } from "./projection.ts";
