import type { MachinePublicationV4 } from "./projection.ts";

export type MachinePublicationValidationCategory =
  | "decoding"
  | "framing"
  | "schema"
  | "set-invariant"
  | "syntax";

export type MachinePublicationSetRelationship =
  | "check-canonical-order"
  | "core-snapshot"
  | "record-canonical-order"
  | "record-check-ownership"
  | "records-fingerprint";

export interface MachinePublicationValidationDiagnostic {
  readonly category: MachinePublicationValidationCategory;
  readonly index?: number;
  readonly line?: number;
  readonly logicalArtifact: "records.ndjson" | "run.json";
  readonly message: string;
  readonly pointer?: string;
  readonly relationship?: MachinePublicationSetRelationship;
}

export type MachinePublicationValidationResult = Readonly<
  ValidationFailure | { ok: true; value: MachinePublicationV4 }
>;

export interface ValidationFailure {
  readonly ok: false;
  readonly diagnostic: MachinePublicationValidationDiagnostic;
}

export function validationSuccess<Value>(value: Value): { ok: true; value: Value } {
  return { ok: true, value };
}

export function validationFailure(
  diagnostic: MachinePublicationValidationDiagnostic
): ValidationFailure {
  return { ok: false, diagnostic };
}

export function setInvariantFailure(
  relationship: MachinePublicationSetRelationship,
  logicalArtifact: MachinePublicationValidationDiagnostic["logicalArtifact"],
  message: string,
  index?: number
): ValidationFailure {
  return validationFailure({
    category: "set-invariant",
    ...(index === undefined ? {} : { index, line: index + 1 }),
    logicalArtifact,
    message,
    relationship
  });
}

import Value from "typebox/value";

import type { MachinePublicationV4 } from "./projection.ts";
import { freezePublicationValue } from "./freeze-publication-value.ts";
import { validatePublicationInvariants } from "./publication-invariants.ts";
import {
  MACHINE_RECORD_V4_SCHEMA,
  MACHINE_RUN_V4_SCHEMA,
  type MachineRecordV4,
  type MachineRunV4
} from "./schema.ts";
import {
  validationFailure,
  validationSuccess,
  type MachinePublicationValidationDiagnostic,
  type MachinePublicationValidationResult
} from "./validation-result.ts";

export type {
  MachinePublicationSetRelationship,
  MachinePublicationValidationCategory,
  MachinePublicationValidationDiagnostic,
  MachinePublicationValidationResult
} from "./validation-result.ts";

type Parsed<Value> = Readonly<
  { ok: false; diagnostic: MachinePublicationValidationDiagnostic } | { ok: true; value: Value }
>;

export function validateMachinePublicationSetV4(
  input: Readonly<{
    recordsNdjson: Uint8Array;
    runJson: Uint8Array;
  }>
): MachinePublicationValidationResult {
  const runResult = parseRun(input.runJson);
  if (!runResult.ok) return runResult;
  const recordsResult = parseRecords(input.recordsNdjson);
  if (!recordsResult.ok) return recordsResult;
  const invariant = validatePublicationInvariants(runResult.value, recordsResult.value);
  return (
    invariant ??
    validationSuccess(
      Object.freeze({
        run: freezePublicationValue(runResult.value),
        records: freezePublicationValue(recordsResult.value)
      }) satisfies MachinePublicationV4
    )
  );
}

function parseRun(bytes: Uint8Array): Parsed<MachineRunV4> {
  const decoded = decode(bytes, "run.json");
  if (!decoded.ok) return decoded;
  const parsed = parseJson(decoded.value, {
    logicalArtifact: "run.json",
    message: "Run artifact must contain exactly one JSON value."
  });
  if (!parsed.ok) return parsed;
  if (!Value.Check(MACHINE_RUN_V4_SCHEMA, parsed.value)) {
    const error = Value.Errors(MACHINE_RUN_V4_SCHEMA, parsed.value)[0];
    return validationFailure({
      category: "schema",
      logicalArtifact: "run.json",
      message: "Run artifact does not match the machine run v4 schema.",
      pointer: error?.instancePath ?? ""
    });
  }
  return validationSuccess(parsed.value);
}

function parseRecords(bytes: Uint8Array): Parsed<MachineRecordV4[]> {
  if (bytes.byteLength === 0) return validationSuccess([]);
  if (bytes[bytes.byteLength - 1] !== 0x0a) {
    return validationFailure({
      category: "framing",
      line: countLf(bytes) + 1,
      logicalArtifact: "records.ndjson",
      message: "Non-empty record stream must end with exactly one LF."
    });
  }
  const decoded = decode(bytes, "records.ndjson");
  if (!decoded.ok) return decoded;
  return parseRecordSegments(decoded.value.slice(0, -1).split("\n"));
}

function parseRecordSegments(segments: readonly string[]): Parsed<MachineRecordV4[]> {
  const records: MachineRecordV4[] = [];
  for (const [index, segment] of segments.entries()) {
    const framingFailure = validateRecordSegment(segment, index);
    if (framingFailure !== null) return framingFailure;
    const parsed = parseJson(segment, {
      index,
      line: index + 1,
      logicalArtifact: "records.ndjson",
      message: "Record segment must contain exactly one JSON value."
    });
    if (!parsed.ok) return parsed;
    if (!Value.Check(MACHINE_RECORD_V4_SCHEMA, parsed.value)) {
      const error = Value.Errors(MACHINE_RECORD_V4_SCHEMA, parsed.value)[0];
      return validationFailure({
        category: "schema",
        index,
        line: index + 1,
        logicalArtifact: "records.ndjson",
        message: "Record does not match the machine record v4 schema.",
        pointer: error?.instancePath ?? ""
      });
    }
    records.push(parsed.value);
  }
  return validationSuccess(records);
}

function validateRecordSegment(
  segment: string,
  index: number
): Extract<Parsed<never>, { ok: false }> | null {
  if (segment.length > 0 && !/^[\t\r ]+$/.test(segment)) return null;
  return validationFailure({
    category: "framing",
    index,
    line: index + 1,
    logicalArtifact: "records.ndjson",
    message: "Record segment must not be empty or whitespace-only."
  });
}

function parseJson(
  text: string,
  diagnostic: Omit<MachinePublicationValidationDiagnostic, "category">
): Parsed<unknown> {
  try {
    return validationSuccess(JSON.parse(text) as unknown);
  } catch {
    return validationFailure({ category: "syntax", ...diagnostic });
  }
}

function decode(
  bytes: Uint8Array,
  logicalArtifact: MachinePublicationValidationDiagnostic["logicalArtifact"]
): Parsed<string> {
  if (bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) {
    return validationFailure({
      category: "decoding",
      logicalArtifact,
      message: "Leading UTF-8 BOM is not allowed."
    });
  }
  try {
    return validationSuccess(new TextDecoder("utf-8", { fatal: true }).decode(bytes));
  } catch {
    return validationFailure({
      category: "decoding",
      logicalArtifact,
      message: "Input is not valid UTF-8."
    });
  }
}

function countLf(bytes: Uint8Array): number {
  let count = 0;
  for (const byte of bytes) if (byte === 0x0a) count += 1;
  return count;
}

import { canonicalJsonText } from "../../data-boundary/canonical-data.ts";
import {
  snapshotClosedArray,
  snapshotClosedPolicyRecord
} from "../../data-boundary/closed-values.ts";
import { isNonEmptyString } from "../../data-boundary/value-shapes.ts";
import type { FindingWaiver } from "../../finding-waivers/reconciliation.ts";

/**
 * Snapshots the shared closed waiver envelope while leaving identity grammar to the producing Check.
 */
export function resolveFindingWaiverAuthoring<Identity>(
  value: unknown,
  resolveIdentity: (value: unknown) => Identity | undefined
): readonly FindingWaiver<Identity>[] | undefined {
  if (value === undefined) return Object.freeze([]);
  const candidates = snapshotClosedArray(value);
  if (candidates === undefined) return undefined;

  const waivers: FindingWaiver<Identity>[] = [];
  const seenIdentities = new Set<string>();
  for (const candidate of candidates) {
    const authored = snapshotClosedPolicyRecord(candidate, { required: ["identity", "reason"] });
    if (authored === undefined || !isNonEmptyString(authored.reason)) return undefined;
    const identity = resolveIdentity(authored.identity);
    if (identity === undefined) return undefined;
    let identityKey: string;
    try {
      identityKey = canonicalJsonText(identity);
    } catch {
      return undefined;
    }
    if (seenIdentities.has(identityKey)) return undefined;
    seenIdentities.add(identityKey);
    waivers.push(Object.freeze({ identity, reason: authored.reason }));
  }
  return Object.freeze(waivers);
}

/** Validates the complete resolved waiver list through the same authoring boundary. */
export function validResolvedFindingWaivers<Identity>(
  value: unknown,
  resolveIdentity: (value: unknown) => Identity | undefined
): value is readonly FindingWaiver<Identity>[] {
  return value !== undefined && resolveFindingWaiverAuthoring(value, resolveIdentity) !== undefined;
}

import { createHash } from "node:crypto";

import type { CheckExecutionContext } from "../../check/check.ts";
import { canonicalJsonBytes } from "../../data-boundary/canonical-data.ts";
import type {
  FindingWaiverAudit,
  FindingWaiverReconciliation
} from "../../finding-waivers/reconciliation.ts";

interface CodeQualityFindingCandidate {
  readonly data: Readonly<{ readonly blocking: boolean }>;
  readonly id: string;
}

type FindingRecordContext = Pick<CheckExecutionContext<object>, "records">;

const FINDING_WAIVER_AUDIT_RECORD_ID_PREFIX = "/finding-waiver-audit/";

export type FindingWaiverRecordAudit = Readonly<
  Omit<FindingWaiverAudit, "status"> & {
    readonly status: "overmatched" | "unused";
  }
>;

export type FindingWaiverAuditRecordData<Identity> = Readonly<{
  readonly identity: Identity;
  readonly kind: "finding-waiver-audit";
  readonly matchCount: number;
  readonly reason: string;
  readonly status: "overmatched" | "unused";
}>;

/** Builds the common immutable data shared by Check-owned waiver audit Records. */
export function buildFindingWaiverAuditRecordData<Identity>(
  identity: Identity,
  audit: FindingWaiverRecordAudit
): FindingWaiverAuditRecordData<Identity> {
  return Object.freeze({
    identity,
    kind: "finding-waiver-audit",
    matchCount: audit.matchCount,
    reason: audit.waiver.reason,
    status: audit.status
  });
}

/** Builds the shared hash-addressed audit Record used by structured identities. */
export function buildHashedFindingWaiverAuditRecord<Identity>(
  identity: Identity,
  audit: FindingWaiverRecordAudit
): Readonly<{ readonly data: FindingWaiverAuditRecordData<Identity>; readonly id: string }> {
  const digest = createHash("sha256").update(canonicalJsonBytes(identity)).digest("hex");
  return Object.freeze({
    data: buildFindingWaiverAuditRecordData(identity, audit),
    id: `${FINDING_WAIVER_AUDIT_RECORD_ID_PREFIX}sha256:${digest}`
  });
}

/** Publishes every reconciled metric Finding while preserving applied waiver evidence. */
export function reportReconciledCodeQualityFindingRecords<
  Finding extends CodeQualityFindingCandidate
>(context: FindingRecordContext, reconciliation: FindingWaiverReconciliation<Finding>): void {
  for (const finding of reconciliation.findings) {
    const data =
      finding.disposition === "waived"
        ? Object.freeze({
            ...finding.finding.data,
            blocking: false,
            waiver: Object.freeze({ reason: finding.waiver.reason })
          })
        : finding.finding.data;
    context.records.report({ id: finding.finding.id }, data);
  }
}

/** Publishes only unused/overmatched audit rows built by the identity-owning Check. */
export function reportFindingWaiverAudits<Finding, AuditData extends object>(
  context: FindingRecordContext,
  reconciliation: FindingWaiverReconciliation<Finding>,
  buildRecord: (
    audit: FindingWaiverRecordAudit
  ) => Readonly<{ readonly data: AuditData; readonly id: string }>
): void {
  for (const audit of reconciliation.waiverAudits) {
    if (audit.status === "applied") continue;
    const record = buildRecord(
      Object.freeze({
        matchCount: audit.matchCount,
        status: audit.status,
        waiver: audit.waiver
      })
    );
    context.records.report({ id: record.id }, record.data);
  }
}

import type { CheckMessage, CheckResult } from "../../check/check.ts";
import { snapshotClosedRecord } from "../../data-boundary/closed-values.ts";
import { isNonEmptyString } from "../../data-boundary/value-shapes.ts";

export const FINDING_POLICIES = Object.freeze(["blocking", "non-blocking"] as const);

/** package-provided Check 用于结算 normal finding 的阻断策略。 */
export type FindingPolicy = (typeof FINDING_POLICIES)[number];

export const DEFAULT_FINDING_POLICY: FindingPolicy = "non-blocking";

/** 三个代码质量 Check 正常完成时返回的精确 finding 计数。 */
export interface FindingSummary {
  readonly blockingFindingCount: number;
  readonly findingCount: number;
}

/** 一项 finding 在 Check 自己结算前的领域中性处置。 */
export interface FindingSettlement {
  /** 该 finding 是否仍需要进入该 Check 的正常 finding 结算。 */
  readonly actionable: boolean;
  readonly blocking: boolean;
}

export function resolveFindingPolicy(
  value: unknown,
  fallback: FindingPolicy = DEFAULT_FINDING_POLICY
): FindingPolicy | undefined {
  if (value === undefined) return fallback;
  return FINDING_POLICIES.find((policy) => policy === value);
}

export function validFindingPolicy(value: unknown): value is FindingPolicy {
  return FINDING_POLICIES.some((policy) => policy === value);
}

/** Resolves the closed, non-empty named area map shared by code-quality Checks. */
export function resolveCodeAreaPolicyMap<Area>(
  value: unknown,
  defaultArea: () => Area,
  resolveArea: (candidate: unknown) => Area | undefined
): Readonly<Record<string, Area>> | undefined {
  if (value === undefined) return Object.freeze({ project: defaultArea() });
  const areas = snapshotClosedRecord(value);
  if (areas === undefined || Object.keys(areas).length === 0) return undefined;
  const resolvedEntries: Array<readonly [string, Area]> = [];
  for (const [areaId, candidate] of Object.entries(areas)) {
    if (!isNonEmptyString(areaId)) return undefined;
    const area = resolveArea(candidate);
    if (area === undefined) return undefined;
    resolvedEntries.push([areaId, area]);
  }
  return Object.freeze(Object.fromEntries(resolvedEntries));
}

export function isBlockingFinding(policies: readonly FindingPolicy[]): boolean {
  return policies.some((policy) => policy === "blocking");
}

export function settleFindings(
  findings: readonly FindingSettlement[]
): CheckResult<FindingSummary> {
  const blockingFindingCount = findings.filter(
    (finding) => finding.actionable && finding.blocking
  ).length;
  const findingCount = findings.length;
  const actionableNonBlockingFindingCount = findings.filter(
    (finding) => finding.actionable && !finding.blocking
  ).length;
  const messages = findingMessages({ actionableNonBlockingFindingCount, blockingFindingCount });
  return Object.freeze({
    status: blockingFindingCount > 0 ? "failed" : "passed",
    data: Object.freeze({
      blockingFindingCount,
      findingCount
    }),
    ...(messages.length === 0 ? {} : { messages })
  });
}

function findingMessages(
  summary: Readonly<{
    readonly actionableNonBlockingFindingCount: number;
    readonly blockingFindingCount: number;
  }>
): readonly CheckMessage[] {
  if (summary.blockingFindingCount > 0) {
    return Object.freeze([
      Object.freeze({
        code: "blocking-findings",
        level: "error",
        message: `${summary.blockingFindingCount} blocking finding(s) require attention; inspect this Check's Records for affected paths and measurements, then update the code or policy.`
      })
    ]);
  }
  if (summary.actionableNonBlockingFindingCount > 0) {
    return Object.freeze([
      Object.freeze({
        code: "non-blocking-findings",
        level: "warning",
        message: `${summary.actionableNonBlockingFindingCount} non-blocking finding(s) were recorded; inspect this Check's Records for affected paths and measurements, then update the code or policy.`
      })
    ]);
  }
  return Object.freeze([]);
}

import type {
  DuplicateCodeFragment,
  DuplicateCodeLocation,
  DuplicateDetectionAreaInput
} from "./measurement-model.ts";
import { isValidDuplicateFragment } from "./records.ts";

type PathPolicy = Readonly<{
  codeArea: string;
  minimumLines: number;
  minimumTokens: number;
}>;

type FragmentAnnotation =
  | Readonly<{
      fragment: DuplicateCodeFragment;
      kind: "comparable";
      requiredMinimumLines: number;
      requiredMinimumTokens: number;
    }>
  | Readonly<{ kind: "outside-common-area" }>;

/** Retains fragments whose locations share an area and applies its strictest policy. */
export function applyDuplicateAreaPolicy(
  fragments: readonly DuplicateCodeFragment[],
  areas: readonly DuplicateDetectionAreaInput[]
): readonly DuplicateCodeFragment[] | undefined {
  const policiesByPath = buildPathPolicies(areas);
  const accepted: DuplicateCodeFragment[] = [];
  for (const fragment of fragments) {
    if (!isValidDuplicateFragment(fragment)) return undefined;
    const annotated = annotateFragment(fragment, policiesByPath);
    if (annotated === undefined) return undefined;
    if (annotated.kind === "outside-common-area") continue;
    if (
      annotated.fragment.lineCount >= annotated.requiredMinimumLines &&
      annotated.fragment.tokenCount >= annotated.requiredMinimumTokens
    ) {
      accepted.push(annotated.fragment);
    }
  }
  return Object.freeze(accepted);
}

function buildPathPolicies(
  areas: readonly DuplicateDetectionAreaInput[]
): ReadonlyMap<string, readonly PathPolicy[]> {
  const mutablePolicies = new Map<string, PathPolicy[]>();
  for (const area of areas) {
    for (const path of area.approvedExactPaths) {
      const policies = mutablePolicies.get(path) ?? [];
      policies.push(
        Object.freeze({
          codeArea: area.codeArea,
          minimumLines: area.minimumLines,
          minimumTokens: area.minimumTokens
        })
      );
      mutablePolicies.set(path, policies);
    }
  }
  return new Map(
    Array.from(mutablePolicies, ([path, policies]) => [path, Object.freeze(policies)] as const)
  );
}

function annotateFragment(
  fragment: DuplicateCodeFragment,
  policiesByPath: ReadonlyMap<string, readonly PathPolicy[]>
): FragmentAnnotation | undefined {
  const locations: DuplicateCodeLocation[] = [];
  let commonPolicies: readonly PathPolicy[] | undefined;
  for (const location of fragment.locations) {
    const pathPolicies = policiesByPath.get(location.path);
    if (pathPolicies === undefined || pathPolicies.length === 0) return undefined;
    locations.push(
      Object.freeze({
        endLine: location.endLine,
        path: location.path,
        startLine: location.startLine
      })
    );
    commonPolicies =
      commonPolicies === undefined
        ? pathPolicies
        : commonPolicies.filter((policy) =>
            pathPolicies.some((candidate) => candidate.codeArea === policy.codeArea)
          );
  }
  if (commonPolicies === undefined) return undefined;
  if (commonPolicies.length === 0) return Object.freeze({ kind: "outside-common-area" });

  const annotatedFragment = Object.freeze({
    ...fragment,
    codeAreas: Object.freeze(uniqueSorted(commonPolicies.map((policy) => policy.codeArea))),
    locations: Object.freeze(locations)
  });
  return Object.freeze({
    fragment: annotatedFragment,
    kind: "comparable",
    requiredMinimumLines: Math.max(...commonPolicies.map((policy) => policy.minimumLines)),
    requiredMinimumTokens: Math.max(...commonPolicies.map((policy) => policy.minimumTokens))
  });
}

function uniqueSorted(values: readonly string[]): string[] {
  return [...new Set(values)].sort(compareText);
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

