} from "./cache-contract.ts";

const RAW_SCAN_CONFIGURATION_VERSION = "4";

interface DuplicateScanCacheIdentityInput {
  readonly dependency: ResolvedDuplicateDetectionScannerOptions;
  readonly exactInput: DuplicateDetectionExactInputSet;
  readonly minimumLines: number;
  readonly minimumTokens: number;
  readonly toolVersion: string;
}

export function createDuplicateScanCacheIdentity(
  input: DuplicateScanCacheIdentityInput
): DuplicateCodeCacheIdentity {
  return Object.freeze({
    toolName: "jscpd",
    toolVersion: input.toolVersion,
    scannerConfiguration: jscpdCacheConfiguration({
      dependency: input.dependency,
      minimumLines: input.minimumLines,
      minimumTokens: input.minimumTokens
    }),
    configVersion: RAW_SCAN_CONFIGURATION_VERSION,
    commitSha: input.exactInput.commitSha,
    inputFingerprint: {
      fileCount: input.exactInput.inputFingerprint.fileCount,
      fileList: [...input.exactInput.inputFingerprint.fileList],
      fingerprint: input.exactInput.inputFingerprint.fingerprint
    }
  });
}

export function jscpdCacheConfiguration(input: {
  readonly dependency: ResolvedDuplicateDetectionScannerOptions;
  readonly minimumLines: number;
  readonly minimumTokens: number;
}): DuplicateScannerCacheConfiguration {
  const backend: DuplicateScannerCacheConfiguration["backend"] = isPackageJscpdCommand(
    input.dependency.command
  )
    ? Object.freeze({ kind: "package" })
    : Object.freeze({
        executable: input.dependency.command.executable,
        kind: "custom"
      });
  return Object.freeze({
    backend,
    minimumLines: input.minimumLines,
    minimumTokens: input.minimumTokens,
    reportedPathMode: "absolute",
    reporter: "json",
    workerPolicy: "tool-default"
  });
}

import { createHash } from "node:crypto";
import { join } from "node:path";

import { isNonArrayRecord } from "../../../data-boundary/value-shapes.ts";
import { SCAN_CACHE_VERSION, type DuplicateCodeCacheIdentity } from "./cache-contract.ts";

export function buildScanCacheKey(identity: DuplicateCodeCacheIdentity): string {
  const keyInput = {
    scan_cache_version: SCAN_CACHE_VERSION,
    tool_name: identity.toolName,
    tool_version: identity.toolVersion,
    scanner_configuration: identity.scannerConfiguration,
    config_version: identity.configVersion,
    commit_sha: identity.commitSha,
    input_fingerprint: identity.inputFingerprint
  };

  return hashStable(keyInput);
}

export function getScanCachePath(rootDir: string, cacheKey: string): string {
  return join(getQualityCacheRoot(rootDir), `${cacheKey}.json`);
}

function getQualityCacheRoot(rootDir: string): string {
  return join(rootDir, SCAN_CACHE_VERSION);
}

function hashStable(value: unknown): string {
  return createHash("sha256").update(stableStringify(value)).digest("hex");
}

export function stableStringify(value: unknown): string {
  if (Array.isArray(value)) {
    return `[${value.map((item) => stableStringify(item)).join(",")}]`;
  }

  if (isNonArrayRecord(value)) {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableStringify(value[key])}`)
      .join(",")}}`;
  }

  return JSON.stringify(value);
}

import { isNonArrayRecord } from "../../../data-boundary/value-shapes.ts";
import type { DuplicateCodeFragment, DuplicateCodeLocation } from "../measurement-model.ts";
import { stableStringify } from "./key.ts";
import {
  SCAN_CACHE_VERSION,
  type DuplicateCodeCacheIdentity,
  type ScanCachePayload
} from "./cache-contract.ts";

export function isMatchingPayload(
  payload: unknown,
  identity: DuplicateCodeCacheIdentity,
  cacheKey: string
): payload is ScanCachePayload {
  if (!isNonArrayRecord(payload)) return false;

  return (
    cacheIdentityFieldsMatch(payload, identity, cacheKey) &&
    cacheStructuredFieldsMatch(payload, identity)
  );
}

export function isMetricArray(value: unknown): value is readonly DuplicateCodeFragment[] {
  if (!Array.isArray(value)) return false;
  return value.every(isDuplicateCodeFragment);
}

function cacheIdentityFieldsMatch(
  payload: Record<string, unknown>,
  identity: DuplicateCodeCacheIdentity,
  cacheKey: string
): boolean {
  return (
    payload.scanCacheVersion === SCAN_CACHE_VERSION &&
    payload.cacheKey === cacheKey &&
    payload.toolName === identity.toolName &&
    payload.toolVersion === identity.toolVersion &&
    payload.configVersion === identity.configVersion &&
    payload.commitSha === identity.commitSha
  );
}

function cacheStructuredFieldsMatch(
  payload: Record<string, unknown>,
  identity: DuplicateCodeCacheIdentity
): boolean {
  return (
    stableStringify(payload.scannerConfiguration) ===
      stableStringify(identity.scannerConfiguration) &&
    stableStringify(payload.inputFingerprint) === stableStringify(identity.inputFingerprint)
  );
}

function isDuplicateCodeFragment(value: unknown): value is DuplicateCodeFragment {
  return (
    isNonArrayRecord(value) &&
    isFiniteNumber(value.id) &&
    isFiniteNumber(value.tokenCount) &&
    isFiniteNumber(value.lineCount) &&
    Array.isArray(value.codeAreas) &&
    value.codeAreas.every((area) => typeof area === "string") &&
    Array.isArray(value.locations) &&
    value.locations.every(isDuplicateCodeLocation)
  );
}

function isDuplicateCodeLocation(value: unknown): value is DuplicateCodeLocation {
  return (
    isNonArrayRecord(value) &&
    typeof value.path === "string" &&
    isFiniteNumber(value.startLine) &&
    isFiniteNumber(value.endLine)
  );
}

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

/** 读取和写入 duplicate-code raw-scan cache entries。 */

import { readJsonFile, writeJsonFile } from "../../host-environment/filesystem.ts";
import type { DuplicateCodeFragment } from "../measurement-model.ts";
import { buildScanCacheKey, getScanCachePath } from "./key.ts";
import { isMatchingPayload, isMetricArray } from "./payload.ts";
import {
  SCAN_CACHE_VERSION,
  type DuplicateCodeCacheHit,
  type DuplicateCodeCacheIdentity,
  type DuplicateCodeCacheMiss,
  type ScanCachePayload
} from "./cache-contract.ts";

export { buildScanCacheKey, getScanCachePath } from "./key.ts";
export { SCAN_CACHE_VERSION } from "./cache-contract.ts";
export type {
  DuplicateCodeCacheHit,
  DuplicateCodeCacheIdentity,
  DuplicateCodeCacheMiss
} from "./cache-contract.ts";

export function loadScanCacheEntry({
  rootDir,
  identity
}: {
  identity: DuplicateCodeCacheIdentity;
  rootDir: string;
}): DuplicateCodeCacheHit | DuplicateCodeCacheMiss {
  const cacheKey = buildScanCacheKey(identity);
  const cachePath = getScanCachePath(rootDir, cacheKey);

  let payload: unknown;
  try {
    payload = readJsonFile(cachePath);
  } catch {
    return { hit: false, reason: "cache-miss", cacheKey, cachePath };
  }

  if (!isMatchingPayload(payload, identity, cacheKey)) {
    return { hit: false, reason: "cache-payload-mismatch", cacheKey, cachePath };
  }

  if (!isMetricArray(payload.metrics)) {
    return { hit: false, reason: "cache-payload-invalid", cacheKey, cachePath };
  }

  return { hit: true, metrics: payload.metrics, cacheKey, cachePath };
}

export function writeScanCacheEntry({
  rootDir,
  identity,
  metrics
}: {
  identity: DuplicateCodeCacheIdentity;
  metrics: readonly DuplicateCodeFragment[];
  rootDir: string;
}): { cacheKey: string; cachePath: string } {
  const cacheKey = buildScanCacheKey(identity);
  const cachePath = getScanCachePath(rootDir, cacheKey);
  const payload: ScanCachePayload = {
    scanCacheVersion: SCAN_CACHE_VERSION,
    cacheKey,
    toolName: identity.toolName,
    toolVersion: identity.toolVersion,
    scannerConfiguration: identity.scannerConfiguration,
    configVersion: identity.configVersion,
    commitSha: identity.commitSha,
    inputFingerprint: identity.inputFingerprint,
    metrics,
    createdAt: new Date().toISOString()
  };

  writeJsonFile({ filePath: cachePath, value: payload });
  return { cacheKey, cachePath };
}

import { defineCheck, type TypedCheckWithOptions } from "../../check/check.ts";
import { DUPLICATE_DETECTION_CHECK_DEFINITION, executeDuplicateDetection } from "./execution.ts";
import { parseDuplicateDetectionData } from "./final-data.ts";
import type { DuplicateDetectionOptions, ResolvedDuplicateDetectionOptions } from "./options.ts";
import { resolveDuplicateDetectionOptions } from "./options-resolution.ts";
import { validResolvedDuplicateDetectionOptions } from "./options-validation.ts";

/**
 * 使用可省略的区域、cache 与 scanner policy 构造一个完整 duplicate-detection Check。
 *
 * @param options - 省略字段由 package 补齐；显式 files 数组作为对应字段的完整替换值。
 * @returns 固定 `duplicate-detection` identity、完整冻结 options、preflight 与 execution。
 * @throws {TypeError} input 含未知字段、空 area、非法阈值、非法 cache 或 scanner policy 时抛出。
 */
export function duplicateDetection(
  options: DuplicateDetectionOptions = {}
): TypedCheckWithOptions<
  "duplicate-detection",
  ResolvedDuplicateDetectionOptions,
  typeof parseDuplicateDetectionData
> {
  const resolvedOptions = resolveDuplicateDetectionOptions(options);
  if (resolvedOptions === undefined) {
    throw new TypeError(
      "duplicateDetection options are invalid; use the documented closed constructor policy including exact finding waivers"
    );
  }
  return defineCheck({
    ...DUPLICATE_DETECTION_CHECK_DEFINITION,
    execution: executeDuplicateDetection,
    parseData: parseDuplicateDetectionData,
    preflight: (preparedOptions) =>
      validResolvedDuplicateDetectionOptions(preparedOptions)
        ? { status: "success", preparedOptions }
        : {
            status: "failure",
            action: "block",
            reason: { code: "invalid-options" },
            messages: [
              {
                code: "invalid-options",
                level: "error",
                message:
                  "duplicateDetection options are invalid; recreate the Check with duplicateDetection(options) or restore its complete resolved options."
              }
            ]
          },
    options: resolvedOptions
  });
}

import { resolve } from "node:path";

import type { CheckExecutionContext, CheckResult } from "../../check/check.ts";
import {
  reconcileFindingWaivers,
  type FindingWaiverReconciliation
} from "../../finding-waivers/reconciliation.ts";
import { collectProjectFileSets, requireProjectFileSet } from "../project-files/collection.ts";
import { fingerprintProjectFiles } from "../project-files/file-fingerprint.ts";
import { settleFindings } from "../code-quality-findings/policy.ts";
import {
  reportFindingWaiverAudits,
  reportReconciledCodeQualityFindingRecords
} from "../code-quality-findings/finding-waiver-evidence.ts";
import { appendCheckMessages } from "../../check/finding-presentation.ts";
import { duplicateFindingMessages, duplicateWaiverMessages } from "./finding-messages.ts";
import { getGitSha } from "./project-revision.ts";
import { measureDuplicateDetection, type DuplicateMeasurementResult } from "./measurement.ts";
import type {
  DuplicateDetectionAreaInput,
  DuplicateDetectionExactInputSet
} from "./measurement-model.ts";
import type {
  DuplicateDetectionFindingWaiver,
  ResolvedDuplicateDetectionOptions
} from "./options.ts";
import { validResolvedDuplicateDetectionOptions } from "./options-validation.ts";
import {
  buildDuplicateRecordCandidates,
  duplicateDetectionFindingIdentity,
  duplicateDetectionWaiverAuditRecord,
  type DuplicateRecordCandidate
} from "./records.ts";
import type { DuplicateDetectionFinalData } from "./final-data.ts";

export const DUPLICATE_DETECTION_CHECK_DEFINITION = {
  checkId: "duplicate-detection",
  displayName: "Duplicate detection"
} as const;

/** `duplicate-detection` whole-Check unavailable outcome 的稳定 reason code。 */
export type DuplicateDetectionUnavailableReasonCode =
  | "cache-write-failed"
  | "external-dependency-unavailable"
  | "external-execution-failed"
  | "external-result-invalid"
  | "invalid-options"
  | "source-unavailable";

/** Default Check callback；scanner configuration 由其完整 options 拥有。 */
export async function executeDuplicateDetection(
  context: CheckExecutionContext<ResolvedDuplicateDetectionOptions>
): Promise<CheckResult<DuplicateDetectionFinalData>> {
  if (!validResolvedDuplicateDetectionOptions(context.options))
    return unavailable("invalid-options");

  let exactInput: DuplicateDetectionExactInputSet;
  try {
    exactInput = prepareExactInputSet(context.project.root, context.options);
  } catch {
    return unavailable("source-unavailable");
  }
  if (exactInput.approvedExactPaths.length < 2) {
    return noEligibleDuplicateInputResult(context);
  }
  const measurement = await measureDuplicateDetection({
    cache: context.options.cache,
    dependency: context.options.scanner,
    exactInput
  });
  if (measurement.kind !== "complete") return directMeasurementFailure(measurement);
  const candidates = buildDuplicateRecordCandidates(
    measurement.fragments,
    context.options.codeAreas
  );
  if (candidates === undefined) return unavailable("external-result-invalid");
  const reconciliation = reconcileDuplicateFindingWaivers(
    candidates,
    context.options.findingWaivers
  );
  reportReconciledCodeQualityFindingRecords(context, reconciliation);
  reportFindingWaiverAudits(context, reconciliation, duplicateDetectionWaiverAuditRecord);
  return settleDuplicateFindings(reconciliation);
}

function noEligibleDuplicateInputResult(
  context: CheckExecutionContext<ResolvedDuplicateDetectionOptions>
): CheckResult<DuplicateDetectionFinalData> {
  const reconciliation = reconcileDuplicateFindingWaivers([], context.options.findingWaivers);
  reportFindingWaiverAudits(context, reconciliation, duplicateDetectionWaiverAuditRecord);
  return appendCheckMessages(
    Object.freeze({ status: "not-applicable", reason: { code: "no-eligible-input" } }),
    duplicateWaiverMessages(reconciliation)
  );
}

function reconcileDuplicateFindingWaivers(
  candidates: readonly DuplicateRecordCandidate[],
  waivers: readonly DuplicateDetectionFindingWaiver[]
): FindingWaiverReconciliation<DuplicateRecordCandidate> {
  return reconcileFindingWaivers({
    findings: candidates,
    identify: duplicateDetectionFindingIdentity,
    waivers
  });
}

function settleDuplicateFindings(
  reconciliation: FindingWaiverReconciliation<DuplicateRecordCandidate>
): CheckResult<DuplicateDetectionFinalData> {
  const settlement = settleFindings(
    reconciliation.findings.map((finding) => ({
      actionable: finding.disposition !== "waived",
      blocking: finding.finding.data.blocking
    }))
  );
  const actionableCandidates = reconciliation.findings
    .filter(({ disposition }) => disposition !== "waived")
    .map(({ finding }) => finding);
  return appendCheckMessages(
    appendCheckMessages(settlement, duplicateFindingMessages(actionableCandidates)),
    duplicateWaiverMessages(reconciliation)
  );
}

function prepareExactInputSet(
  rootDir: string,
  options: ResolvedDuplicateDetectionOptions
): DuplicateDetectionExactInputSet {
  const areas = collectAreaInputs(rootDir, options.codeAreas);
  const approvedExactPaths = uniqueSorted(areas.flatMap((area) => area.approvedExactPaths));
  const inputFingerprint = fingerprintProjectFiles(rootDir, approvedExactPaths);
  return Object.freeze({
    approvedExactPaths: Object.freeze(approvedExactPaths),
    areas,
    cacheRootDir: resolve(rootDir, options.cache.directory),
    commitSha: getGitSha(rootDir),
    inputFingerprint: Object.freeze({
      ...inputFingerprint,
      fileList: Object.freeze([...inputFingerprint.fileList])
    }),
    rootDir
  });
}

function collectAreaInputs(
  rootDir: string,
  codeAreas: ResolvedDuplicateDetectionOptions["codeAreas"]
): readonly DuplicateDetectionAreaInput[] {
  const orderedPolicies = Object.entries(codeAreas).sort(([left], [right]) =>
    compareText(left, right)
  );
  const filesByArea = collectProjectFileSets(
    rootDir,
    Object.fromEntries(orderedPolicies.map(([areaId, policy]) => [areaId, policy.files]))
  );
  return Object.freeze(
    orderedPolicies.flatMap(([codeArea, policy]) => {
      const approvedExactPaths = requireProjectFileSet(filesByArea, codeArea);
      return approvedExactPaths.length === 0
        ? []
        : [
            Object.freeze({
              approvedExactPaths: Object.freeze(approvedExactPaths),
              codeArea,
              minimumLines: policy.minimumLines,
              minimumTokens: policy.minimumTokens
            })
          ];
    })
  );
}

function uniqueSorted(values: readonly string[]): string[] {
  return [...new Set(values)].sort(compareText);
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

function directMeasurementFailure(
  measurement: Exclude<DuplicateMeasurementResult, { kind: "complete" }>
): CheckResult<DuplicateDetectionFinalData> {
  switch (measurement.kind) {
    case "cache-write-failed":
      return unavailable("cache-write-failed");
    case "execution-failed":
      return unavailable("external-execution-failed");
    case "invalid-result":
      return unavailable("external-result-invalid");
    case "unavailable":
      return unavailable("external-dependency-unavailable");
  }
  const exhaustiveMeasurement: never = measurement;
  return exhaustiveMeasurement;
}

function unavailable(
  code: DuplicateDetectionUnavailableReasonCode
): CheckResult<DuplicateDetectionFinalData> {
  return Object.freeze({
    status: "unavailable",
    reason: { code },
    messages: Object.freeze([
      Object.freeze({ code, level: "error" as const, message: unavailableMessage(code) })
    ])
  });
}

function unavailableMessage(code: DuplicateDetectionUnavailableReasonCode): string {
  switch (code) {
    case "invalid-options":
      return "duplicateDetection options are invalid; recreate the Check with duplicateDetection(options) or restore its complete resolved options.";
    case "source-unavailable":
      return "Duplicate detection could not collect its configured project files; check the project root, file permissions, and selected file source.";
    case "external-dependency-unavailable":
      return "The configured jscpd command is unavailable or incompatible; restore the package dependency or configure a compatible executable.";
    case "external-execution-failed":
      return "jscpd did not complete successfully; run the configured command directly and inspect its environment.";
    case "external-result-invalid":
      return "jscpd output could not form a trusted complete result; check command and report compatibility.";
    case "cache-write-failed":
      return "Duplicate detection completed scanning but could not write its cache; check the configured cache directory permissions.";
  }
}

import type { FindingSummary } from "../code-quality-findings/policy.ts";
import { parseFindingSummaryData } from "../final-data-parsing.ts";

/** `duplicate-detection` 在 passed/failed outcome 中发布的主数据。 */
export type DuplicateDetectionFinalData = FindingSummary;

/** 验证并脱离一份 `duplicate-detection` canonical final-data object。 */
export function parseDuplicateDetectionData(data: unknown): DuplicateDetectionFinalData {
  return parseFindingSummaryData(data, "duplicateDetection");
}

import type { CheckMessage } from "../../check/check.ts";
import { presentCheckFindings } from "../../check/finding-presentation.ts";
import type {
  FindingWaiverAudit,
  FindingWaiverReconciliation
} from "../../finding-waivers/reconciliation.ts";
import type { DuplicateDetectionFindingLocation } from "./options.ts";
import { duplicateDetectionWaiverIdentity, type DuplicateRecordCandidate } from "./records.ts";

const PRESENTED_FINDING_LIMIT = 10;

/** Projects duplicate Records into bounded, project-relative terminal summaries. */
export function duplicateFindingMessages(
  candidates: readonly DuplicateRecordCandidate[]
): readonly CheckMessage[] {
  return presentCheckFindings({
    findings: candidates,
    limit: PRESENTED_FINDING_LIMIT,
    message: ({ data }) =>
      Object.freeze({
        code: "finding-detail",
        level: data.blocking ? ("error" as const) : ("warning" as const),
        message: `Duplicate fragment contains ${data.tokenCount} tokens across ${data.lineCount} lines at ${duplicateLocationSummary(data.locations)}.`
      }),
    omittedMessage: ({ omittedCount, omittedFindings }) =>
      Object.freeze({
        code: "findings-omitted",
        level: omittedFindings.some(({ data }) => data.blocking)
          ? ("error" as const)
          : ("warning" as const),
        message: `${omittedCount} additional duplicate finding(s) were not shown; inspect this Check's Records for the complete set.`
      })
  });
}

/** 将每项 duplicate-detection waiver audit 投影为可行动的 terminal message。 */
export function duplicateWaiverMessages(
  reconciliation: FindingWaiverReconciliation<DuplicateRecordCandidate>
): readonly CheckMessage[] {
  return Object.freeze(reconciliation.waiverAudits.map(duplicateWaiverMessage));
}

function duplicateWaiverMessage(audit: FindingWaiverAudit): CheckMessage {
  const identity = duplicateDetectionWaiverIdentity(audit.waiver);
  const subject = duplicateLocationSummary(identity.locations);
  switch (audit.status) {
    case "applied":
      return Object.freeze({
        code: "finding-waived",
        level: "info",
        message: `Duplicate finding at ${subject} was waived: ${audit.waiver.reason}`
      });
    case "unused":
      return Object.freeze({
        code: "unused-finding-waiver",
        level: "warning",
        message: `Configured duplicate-detection finding waiver at ${subject} matched no finding; remove it or update its identity. Reason: ${audit.waiver.reason}`
      });
    case "overmatched":
      return Object.freeze({
        code: "overmatched-finding-waiver",
        level: "warning",
        message: `Configured duplicate-detection finding waiver at ${subject} matched ${audit.matchCount} findings and was not applied; narrow its identity. Reason: ${audit.waiver.reason}`
      });
  }
}

function duplicateLocationSummary(locations: readonly DuplicateDetectionFindingLocation[]): string {
  const presented = locations
    .slice(0, 2)
    .map(({ endLine, path, startLine }) => `${path}:${startLine}-${endLine}`)
    .join(", ");
  const omitted = locations.length - 2;
  return omitted > 0 ? `${presented}, and ${omitted} more location(s)` : presented;
}

import {
  snapshotClosedArray,
  snapshotClosedPolicyRecord
} from "../../data-boundary/closed-values.ts";
import { isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import { isNormalizedProjectRelativePath } from "../host-environment/path.ts";
import type {
  DuplicateDetectionFindingIdentity,
  DuplicateDetectionFindingLocation
} from "./options.ts";

export function resolveDuplicateDetectionFindingIdentity(
  value: unknown
): DuplicateDetectionFindingIdentity | undefined {
  const identity = snapshotClosedPolicyRecord(value, { required: ["locations", "metric"] });
  if (identity === undefined || identity.metric !== "duplicate-tokens") return undefined;
  const candidates = snapshotClosedArray(identity.locations);
  if (candidates === undefined || candidates.length < 2) return undefined;
  const locations: DuplicateDetectionFindingLocation[] = [];
  for (const candidate of candidates) {
    const resolved = resolveDuplicateFindingLocation(candidate);
    if (resolved === undefined) return undefined;
    const previous = locations.at(-1);
    if (previous !== undefined && compareDuplicateFindingLocations(previous, resolved) >= 0) {
      return undefined;
    }
    locations.push(resolved);
  }
  return Object.freeze({ locations: Object.freeze(locations), metric: "duplicate-tokens" });
}

function resolveDuplicateFindingLocation(
  value: unknown
): DuplicateDetectionFindingLocation | undefined {
  const location = snapshotClosedPolicyRecord(value, {
    required: ["endLine", "path", "startLine"]
  });
  if (
    location === undefined ||
    !isNormalizedProjectRelativePath(location.path) ||
    !isPositiveSafeInteger(location.startLine) ||
    !isPositiveSafeInteger(location.endLine) ||
    location.endLine < location.startLine
  ) {
    return undefined;
  }
  return Object.freeze({
    endLine: location.endLine,
    path: location.path,
    startLine: location.startLine
  });
}

export function compareDuplicateFindingLocations(
  left: DuplicateDetectionFindingLocation,
  right: DuplicateDetectionFindingLocation
): number {
  const pathOrder = compareText(left.path, right.path);
  if (pathOrder !== 0) return pathOrder;
  const startLineOrder = left.startLine - right.startLine;
  return startLineOrder === 0 ? left.endLine - right.endLine : startLineOrder;
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import { runProcess } from "../../host-environment/process/command.ts";
import type { ResolvedDuplicateDetectionScannerOptions } from "../options.ts";
import { isMissingExplicitCommand } from "./command-path.ts";
import { isPackageJscpdCommand, resolveJscpdCommand } from "./command-resolution.ts";
import { parseJscpdVersionOutput } from "./scanner.ts";

type JscpdAvailability = Readonly<
  | {
      available: true;
      error: null;
      name: "jscpd";
      reason: null;
      source: JscpdSource;
      version: string;
    }
  | {
      available: false;
      error: string;
      name: "jscpd";
      reason: "execution-error" | "tool-unavailable";
      source: JscpdSource;
      version: null;
    }
>;

type JscpdSource = "custom command" | "package dependency";

type ToolCommandResult = Awaited<ReturnType<typeof runProcess>>;

export async function checkJscpd(
  rootDir: string,
  dependency: ResolvedDuplicateDetectionScannerOptions
): Promise<JscpdAvailability> {
  const resolved = resolveJscpdCommand(dependency.command);
  if (resolved.kind === "unavailable") {
    return unavailableJscpd(resolved.error, "tool-unavailable", dependency);
  }
  if (isMissingExplicitCommand(resolved.command.executable)) {
    return unavailableJscpd("jscpd dependency binary unavailable", "tool-unavailable", dependency);
  }

  try {
    const result = await runProcess({
      args: [...resolved.command.versionArguments],
      command: resolved.command.executable,
      cwd: rootDir
    });
    return availabilityFromVersionResult(result, dependency);
  } catch (error: unknown) {
    return error instanceof Error
      ? processErrorAvailability(error, dependency)
      : unavailableJscpd("unknown error", "execution-error", dependency);
  }
}

function availabilityFromVersionResult(
  result: ToolCommandResult,
  dependency: ResolvedDuplicateDetectionScannerOptions
): JscpdAvailability {
  if (result.error) return processErrorAvailability(result.error, dependency);
  const output = commandOutput(result);
  if (result.status !== 0) return failedVersionAvailability(result, output, dependency);
  const version = parseJscpdVersionOutput(output);
  if (version === null) return unrecognizedVersionAvailability(dependency);
  return {
    name: "jscpd",
    available: true,
    version,
    error: null,
    source: jscpdSource(dependency),
    reason: null
  };
}

function failedVersionAvailability(
  result: ToolCommandResult,
  output: string,
  dependency: ResolvedDuplicateDetectionScannerOptions
): JscpdAvailability {
  const detail = output ? `: ${output}` : "";
  return unavailableJscpd(
    `jscpd --version failed, ${processTermination(result)}${detail}`,
    "execution-error",
    dependency
  );
}

function unrecognizedVersionAvailability(
  dependency: ResolvedDuplicateDetectionScannerOptions
): JscpdAvailability {
  return unavailableJscpd(
    "jscpd --version returned unrecognized output",
    "execution-error",
    dependency
  );
}

function processErrorAvailability(
  error: Error,
  dependency: ResolvedDuplicateDetectionScannerOptions
): JscpdAvailability {
  const isMissingTool = (error as NodeJS.ErrnoException).code === "ENOENT";
  return unavailableJscpd(
    isMissingTool ? "jscpd dependency binary unavailable" : `jscpd version error: ${error.message}`,
    isMissingTool ? "tool-unavailable" : "execution-error",
    dependency
  );
}

function unavailableJscpd(
  error: string,
  reason: Exclude<JscpdAvailability["reason"], null>,
  dependency: ResolvedDuplicateDetectionScannerOptions
): JscpdAvailability {
  return {
    name: "jscpd",
    available: false,
    version: null,
    error,
    source: jscpdSource(dependency),
    reason
  };
}

function jscpdSource(dependency: ResolvedDuplicateDetectionScannerOptions): JscpdSource {
  return isPackageJscpdCommand(dependency.command) ? "package dependency" : "custom command";
}

function commandOutput(result: ToolCommandResult): string {
  return (result.stdout || "").trim() || (result.stderr || "").trim();
}

function processTermination(result: ToolCommandResult): string {
  return typeof result.status === "number"
    ? `exit ${result.status}`
    : `signal ${result.signal || "unknown"}`;
}

import { existsSync } from "node:fs";
import { isAbsolute } from "node:path";

export function isMissingExplicitCommand(command: string): boolean {
  return (
    (isAbsolute(command) || command.includes("/") || command.includes("\\")) && !existsSync(command)
  );
}

import { existsSync, readFileSync } from "node:fs";
import { dirname, isAbsolute, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { isNonArrayRecord } from "../../../data-boundary/value-shapes.ts";
import type { DuplicateDetectionScannerCommand } from "../options.ts";

const JSCPD_BIN_NAME = "jscpd";
const JSCPD_PACKAGE_NAME = "jscpd";

export interface JscpdCommand {
  readonly executable: string;
  readonly scanPrefixArguments: readonly string[];
  readonly versionArguments: readonly string[];
}

export type ResolvedJscpdCommand =
  | Readonly<{ command: JscpdCommand; kind: "resolved" }>
  | Readonly<{ error: string; kind: "unavailable" }>;

/**
 * package-provided scanner 的可移植 marker。真实 executable 只由私有 jscpd adapter 解析，避免公共
 * Definition 与 fingerprint 保存 consumer-specific Bun 或 package path。
 */
export const DEFAULT_JSCPD_COMMAND: DuplicateDetectionScannerCommand = Object.freeze({
  kind: "package"
});

export function isPackageJscpdCommand(
  command: DuplicateDetectionScannerCommand
): command is Extract<DuplicateDetectionScannerCommand, { readonly kind: "package" }> {
  return command.kind === "package";
}

export function resolveJscpdCommand(
  command: DuplicateDetectionScannerCommand
): ResolvedJscpdCommand {
  if (command.kind === "custom") {
    return Object.freeze({
      command: Object.freeze({
        executable: command.executable,
        scanPrefixArguments: Object.freeze([]),
        versionArguments: Object.freeze(["--version"])
      }),
      kind: "resolved"
    });
  }

  const binTarget = installedJscpdBinTarget();
  if (binTarget === null) {
    return Object.freeze({
      error: "candidate jscpd package manifest or declared bin target is unavailable",
      kind: "unavailable"
    });
  }

  return Object.freeze({
    command: Object.freeze({
      executable: process.execPath,
      scanPrefixArguments: Object.freeze([binTarget]),
      versionArguments: Object.freeze([binTarget, "--version"])
    }),
    kind: "resolved"
  });
}

export function readJscpdBinTarget(packageManifestPath: string): string | null {
  let manifest: unknown;
  try {
    manifest = JSON.parse(readFileSync(packageManifestPath, "utf8"));
  } catch {
    return null;
  }

  const binTarget = declaredJscpdBinTarget(manifest);
  if (binTarget === null || isAbsolute(binTarget)) return null;

  const packageDirectory = dirname(packageManifestPath);
  const resolvedTarget = resolve(packageDirectory, binTarget);
  const targetRelativePath = relative(packageDirectory, resolvedTarget);
  if (
    targetRelativePath === "" ||
    targetRelativePath === ".." ||
    targetRelativePath.startsWith("../") ||
    targetRelativePath.startsWith("..\\") ||
    !existsSync(resolvedTarget)
  ) {
    return null;
  }

  return resolvedTarget;
}

function installedJscpdBinTarget(): string | null {
  try {
    const packageManifestPath = fileURLToPath(
      import.meta.resolve(`${JSCPD_PACKAGE_NAME}/package.json`)
    );
    return readJscpdBinTarget(packageManifestPath);
  } catch {
    return null;
  }
}

function declaredJscpdBinTarget(manifest: unknown): string | null {
  if (!isNonArrayRecord(manifest)) return null;
  const bin = manifest.bin;
  if (typeof bin === "string") return bin;
  if (!isNonArrayRecord(bin)) return null;
  const target = bin[JSCPD_BIN_NAME];
  return typeof target === "string" ? target : null;
}

import { isNonArrayRecord } from "../../../data-boundary/value-shapes.ts";
import { errorMessage } from "../../host-environment/error-message.ts";
import type { ExactInputMeasurement } from "../../project-files/exact-input-measurement.ts";
import { normalizeScannerReportedPath } from "../../project-files/reported-path.ts";
import type { DuplicateCodeFragment, DuplicateCodeLocation } from "../measurement-model.ts";
import { toScopedJscpdMeasurement } from "./scoped-fragments.ts";
import type { JscpdScanResult } from "./scanner-contract.ts";

type JscpdFileLocation = Readonly<{
  readonly end?: unknown;
  readonly endLoc?: unknown;
  readonly name?: unknown;
  readonly start?: unknown;
  readonly startLoc?: unknown;
}>;

export function parseJscpdJsonReport(json: string, cwd: string): JscpdScanResult {
  try {
    const parsed = JSON.parse(json) as unknown;
    if (!isNonArrayRecord(parsed)) {
      throw new Error("jscpd JSON report must be an object");
    }

    const duplicates = parsed.duplicates;
    if (!Array.isArray(duplicates)) {
      throw new Error("jscpd JSON report must include duplicates array");
    }

    return { ok: true, measurements: parseJscpdMeasurements(duplicates, cwd) };
  } catch (error: unknown) {
    return {
      ok: false,
      error: `Failed to parse jscpd JSON: ${errorMessage(error)}`,
      reason: "jscpd-parse-failure"
    };
  }
}

function parseJscpdMeasurements(
  duplicates: readonly unknown[],
  cwd: string
): ExactInputMeasurement<DuplicateCodeFragment>[] {
  const measurements: ExactInputMeasurement<DuplicateCodeFragment>[] = [];

  for (const [index, duplication] of duplicates.entries()) {
    if (!isNonArrayRecord(duplication)) {
      throw new Error(`jscpd duplicate #${index + 1} must be an object`);
    }
    const fragment = parseJscpdFragment(duplication, cwd, index + 1);
    measurements.push(toScopedJscpdMeasurement(fragment));
  }

  return measurements.sort((a, b) => b.payload.tokenCount - a.payload.tokenCount);
}

function parseJscpdFragment(
  duplication: Record<string, unknown>,
  cwd: string,
  id: number
): DuplicateCodeFragment {
  const lineCount = integerField(duplication, "lines");
  const tokenCount = integerField(duplication, "tokens");
  const locations = parseJscpdLocations(
    duplication,
    cwd,
    lineCount,
    optionalStringField(duplication, "format")
  );

  return {
    id,
    tokenCount,
    lineCount,
    locations,
    codeAreas: []
  };
}

function parseJscpdLocations(
  duplication: Record<string, unknown>,
  cwd: string,
  lineCount: number,
  format: string | null
): DuplicateCodeLocation[] {
  return [
    parseJscpdLocationObject(duplication.firstFile, "firstFile"),
    parseJscpdLocationObject(duplication.secondFile, "secondFile")
  ].map((location) => parseJscpdLocation(location, cwd, lineCount, format));
}

function parseJscpdLocationObject(value: unknown, name: string): JscpdFileLocation {
  if (!isNonArrayRecord(value)) {
    throw new Error(`jscpd duplicate must include ${name} location object`);
  }
  return value;
}

function parseJscpdLocation(
  location: JscpdFileLocation,
  cwd: string,
  lineCount: number,
  format: string | null
): DuplicateCodeLocation {
  const filePath = stringField(location, "name");
  const startLine =
    nestedIntegerField(location, "startLoc", "line") ?? integerField(location, "start");
  const endLine = nestedIntegerField(location, "endLoc", "line") ?? integerField(location, "end");

  return {
    path: normalizeScannerReportedPath(stripJscpdFormatSuffix(filePath, format), cwd),
    startLine,
    endLine: endLine || startLine + Math.max(0, lineCount - 1)
  };
}

function stripJscpdFormatSuffix(filePath: string, format: string | null): string {
  const suffix = format === null ? null : `:${format}`;
  return suffix !== null && filePath.endsWith(suffix)
    ? filePath.slice(0, -suffix.length)
    : filePath;
}

function optionalStringField(record: Record<string, unknown>, name: string): string | null {
  const value = record[name];
  return typeof value === "string" && value.length > 0 ? value : null;
}

function integerField(record: Record<string, unknown>, name: string): number {
  const value = record[name];
  if (typeof value !== "number" || !Number.isSafeInteger(value)) {
    throw new Error(`jscpd field "${name}" must be a safe integer`);
  }
  return value;
}

function nestedIntegerField(
  record: Record<string, unknown>,
  parent: string,
  child: string
): number | null {
  const parentValue = record[parent];
  if (!isNonArrayRecord(parentValue)) return null;
  const value = parentValue[child];
  if (typeof value !== "number" || !Number.isSafeInteger(value)) {
    throw new Error(`jscpd field "${parent}.${child}" must be a safe integer`);
  }
  return value;
}

function stringField(record: Record<string, unknown>, name: string): string {
  const value = record[name];
  if (typeof value !== "string" || value.length === 0) {
    throw new Error(`jscpd field "${name}" must be a non-empty string`);
  }
  return value;
}

import type { DuplicateCodeFragment } from "../measurement-model.ts";
import type { ExactInputMeasurement } from "../../project-files/exact-input-measurement.ts";

export type JscpdScanFailureReason =
  | "jscpd-execution-error"
  | "jscpd-report-failure"
  | "jscpd-parse-failure";

export type JscpdScanResult =
  | {
      readonly measurements: readonly ExactInputMeasurement<DuplicateCodeFragment>[];
      readonly ok: true;
    }
  | {
      readonly error: string;
      readonly ok: false;
      readonly reason: JscpdScanFailureReason;
    };

/**
 * jscpd duplicate-code detection wrapper.
 *
 * Runs the Check-owned jscpd CLI, writes a temporary config for the
 * approved exact-scope file list, and normalizes the JSON report behind the
 * repository-owned DuplicateCodeFragment model.
 */

import { mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

import { errorMessage } from "../../host-environment/error-message.ts";
import {
  runProcess,
  runProcessSync,
  type ProcessResult
} from "../../host-environment/process/command.ts";
import type { ResolvedDuplicateDetectionScannerOptions } from "../options.ts";
import { resolveJscpdCommand, type JscpdCommand } from "./command-resolution.ts";
import { parseJscpdJsonReport } from "./json-report.ts";
import type { JscpdScanResult } from "./scanner-contract.ts";

export type { JscpdScanResult } from "./scanner-contract.ts";
export { parseJscpdJsonReport } from "./json-report.ts";

const JSCPD_REPORT_FILE = "jscpd-report.json";
const JSCPD_PROCESS_MAX_BUFFER = 1024 * 1024 * 64;
const JSCPD_PROCESS_TIMEOUT_MS = 600_000;

export function parseJscpdVersionOutput(output: string): string | null {
  const match = output.trim().match(/(?:jscpd|cpd)\s+([^\s]+)/i);
  return match?.[1] ?? null;
}

interface ScanWithJscpdOptions {
  readonly cwd: string;
  readonly dependency: ResolvedDuplicateDetectionScannerOptions;
  readonly files: readonly string[];
  readonly minimumLines: number;
  readonly minimumTokens: number;
}

type PreparedJscpdInvocation = Readonly<{
  readonly argv: readonly string[];
  readonly configPath: string;
  readonly outputDir: string;
  readonly tempDir: string;
}>;

type PreparedJscpdScan =
  | Readonly<{
      readonly cwd: string;
      readonly dependency: JscpdCommand;
      readonly invocation: PreparedJscpdInvocation;
      readonly ok: true;
    }>
  | Readonly<{ readonly ok: false; readonly result: JscpdScanResult }>;

export function scanWithJscpd(options: ScanWithJscpdOptions): JscpdScanResult {
  try {
    const scan = prepareJscpdScan(options);
    if (!scan.ok) return scan.result;

    try {
      const child = runProcessSync({
        args: scan.invocation.argv,
        command: scan.dependency.executable,
        cwd: scan.cwd,
        encoding: "utf8",
        windowsHide: true,
        maxBuffer: JSCPD_PROCESS_MAX_BUFFER,
        timeout: JSCPD_PROCESS_TIMEOUT_MS
      });

      return handleJscpdProcessResult({ child, cwd: scan.cwd, invocation: scan.invocation });
    } finally {
      cleanupTempDir(scan.invocation.tempDir);
    }
  } catch (error: unknown) {
    return jscpdAdapterError(error);
  }
}

export async function scanWithJscpdAsync(options: ScanWithJscpdOptions): Promise<JscpdScanResult> {
  try {
    const scan = prepareJscpdScan(options);
    if (!scan.ok) return scan.result;

    try {
      const child = await runProcess({
        args: scan.invocation.argv,
        command: scan.dependency.executable,
        cwd: scan.cwd,
        label: "jscpd",
        maxBuffer: JSCPD_PROCESS_MAX_BUFFER,
        timeout: JSCPD_PROCESS_TIMEOUT_MS,
        windowsHide: true
      });

      return handleJscpdProcessResult({ child, cwd: scan.cwd, invocation: scan.invocation });
    } finally {
      cleanupTempDir(scan.invocation.tempDir);
    }
  } catch (error: unknown) {
    return jscpdAdapterError(error);
  }
}

function prepareJscpdScan(options: ScanWithJscpdOptions): PreparedJscpdScan {
  const { files, cwd, dependency, minimumLines, minimumTokens } = options;

  if (files.length < 2) {
    return { ok: false, result: { ok: true, measurements: [] } };
  }

  const resolved = resolveJscpdCommand(dependency.command);
  if (resolved.kind === "unavailable") {
    return {
      ok: false,
      result: {
        error: resolved.error,
        ok: false,
        reason: "jscpd-execution-error"
      }
    };
  }

  return {
    ok: true,
    cwd,
    dependency: resolved.command,
    invocation: prepareJscpdInvocation({
      cwd,
      scanPrefixArguments: resolved.command.scanPrefixArguments,
      files,
      minimumLines,
      minimumTokens
    })
  };
}

function prepareJscpdInvocation({
  cwd,
  scanPrefixArguments,
  files,
  minimumLines,
  minimumTokens
}: {
  readonly cwd: string;
  readonly scanPrefixArguments: readonly string[];
  readonly files: readonly string[];
  readonly minimumLines: number;
  readonly minimumTokens: number;
}): PreparedJscpdInvocation {
  const tempDir = mkdtempSync(join(tmpdir(), "quality-jscpd-"));
  const outputDir = join(tempDir, "report");
  const configPath = join(tempDir, ".jscpd.json");
  const config = {
    path: files.map((path) => resolve(cwd, path)),
    reporters: ["json"],
    minTokens: minimumTokens,
    minLines: minimumLines,
    absolute: true,
    silent: true,
    noTips: true
  };

  writeFileSync(configPath, `${JSON.stringify(config, null, 2)}\n`, "utf8");
  return {
    tempDir,
    outputDir,
    configPath,
    argv: [...scanPrefixArguments, "--config", configPath, "--output", outputDir]
  };
}

function handleJscpdProcessResult({
  child,
  cwd,
  invocation
}: {
  readonly child: ProcessResult;
  readonly cwd: string;
  readonly invocation: PreparedJscpdInvocation;
}): JscpdScanResult {
  if (child.error) {
    return jscpdProcessError(child.error);
  }

  if (child.status !== 0) {
    return jscpdExecutionFailure(
      child.status,
      child.signal,
      trimmedProcessOutput(child.stderr, child.stdout)
    );
  }

  return parseJscpdReportFile(join(invocation.outputDir, JSCPD_REPORT_FILE), cwd);
}

function parseJscpdReportFile(reportPath: string, cwd: string): JscpdScanResult {
  let json: string;
  try {
    json = readFileSync(reportPath, "utf8");
  } catch (error: unknown) {
    return {
      ok: false,
      error: `jscpd JSON report missing: ${errorMessage(error)}`,
      reason: "jscpd-report-failure"
    };
  }

  if (!json.trim()) {
    return {
      ok: false,
      error: "jscpd JSON report is empty",
      reason: "jscpd-report-failure"
    };
  }

  return parseJscpdJsonReport(json, cwd);
}

function jscpdProcessError(error: Error): JscpdScanResult {
  return {
    ok: false,
    error: `jscpd process error: ${error.message}`,
    reason: "jscpd-execution-error"
  };
}

function jscpdAdapterError(error: unknown): JscpdScanResult {
  return {
    ok: false,
    error: `jscpd adapter error: ${errorMessage(error)}`,
    reason: "jscpd-execution-error"
  };
}

function jscpdExecutionFailure(
  status: number | null,
  signal: NodeJS.Signals | null,
  output: string
): JscpdScanResult {
  const termination = status === null ? `signal ${signal ?? "unknown"}` : `exit ${status}`;
  return {
    ok: false,
    error: `jscpd ${termination}: ${output}`,
    reason: "jscpd-execution-error"
  };
}

function trimmedProcessOutput(stderr: string, stdout: string): string {
  return stderr.trim() || stdout.trim() || "no output";
}

function cleanupTempDir(path: string): void {
  rmSync(path, { recursive: true, force: true });
}

import type { DuplicateCodeFragment } from "../measurement-model.ts";
