export async function measureDuplicateDetection(
  options: DuplicateMeasurementInput
): Promise<DuplicateMeasurementResult> {
  const { dependency, exactInput } = options;
  if (!validMeasurementInput(exactInput)) {
    return Object.freeze({ kind: "invalid-result" });
  }
  const availability = await checkJscpd(exactInput.rootDir, dependency);
  if (!availability.available) {
    return Object.freeze({ kind: "unavailable" });
  }

  const minimumLines = Math.min(...exactInput.areas.map((area) => area.minimumLines));
  const minimumTokens = Math.min(...exactInput.areas.map((area) => area.minimumTokens));
  const rawMeasurement = await measureRawScope({
    cache: options.cache,
    dependency,
    exactInput,
    minimumLines,
    minimumTokens,
    toolVersion: availability.version
  });
  if (rawMeasurement.kind !== "complete") return rawMeasurement;

  const fragments = applyDuplicateAreaPolicy(rawMeasurement.fragments, exactInput.areas);
  return fragments === undefined
    ? Object.freeze({ kind: "invalid-result" })
    : Object.freeze({ fragments, kind: "complete" });
}

function validMeasurementInput(exactInput: DuplicateDetectionExactInputSet): boolean {
  const approvedExactPaths = exactInput.approvedExactPaths;
  if (!hasValidScopeIdentity(exactInput) || !hasValidApprovedPaths(exactInput)) return false;

  const approvedPathSet = new Set(approvedExactPaths);
  const coveredPathSet = new Set<string>();
  const codeAreaSet = new Set<string>();
  for (const area of exactInput.areas) {
    if (!isValidAreaInput(area) || codeAreaSet.has(area.codeArea)) return false;
    codeAreaSet.add(area.codeArea);
    for (const path of area.approvedExactPaths) {
      if (!approvedPathSet.has(path)) return false;
      coveredPathSet.add(path);
    }
  }
  return coveredPathSet.size === approvedPathSet.size;
}

function hasValidScopeIdentity(exactInput: DuplicateDetectionExactInputSet): boolean {
  return (
    exactInput.approvedExactPaths.length >= 2 &&
    nonEmptyString(exactInput.rootDir) &&
    nonEmptyString(exactInput.cacheRootDir) &&
    nonEmptyString(exactInput.commitSha)
  );
}

function hasValidApprovedPaths(exactInput: DuplicateDetectionExactInputSet): boolean {
  const paths = exactInput.approvedExactPaths;
  return (
    paths.every(nonEmptyString) &&
    sameStrings(paths, uniqueSorted(paths)) &&
    validFingerprintForPaths(exactInput.inputFingerprint, paths)
  );
}

function isValidAreaInput(area: DuplicateDetectionAreaInput): boolean {
  return (
    nonEmptyString(area.codeArea) &&
    positiveSafeInteger(area.minimumLines) &&
    positiveSafeInteger(area.minimumTokens) &&
    area.approvedExactPaths.length > 0 &&
    area.approvedExactPaths.every(nonEmptyString) &&
    sameStrings(area.approvedExactPaths, uniqueSorted(area.approvedExactPaths))
  );
}

function validFingerprintForPaths(
  fingerprint: DuplicateDetectionExactInputSet["inputFingerprint"],
  approvedExactPaths: readonly string[]
): boolean {
  const expectedFileList = approvedExactPaths.slice(0, 200);
  return (
    fingerprint.fileCount === approvedExactPaths.length &&
    sameStrings(fingerprint.fileList, expectedFileList) &&
    nonEmptyString(fingerprint.fingerprint)
  );
}

async function measureRawScope(input: RawScopeMeasurementInput): Promise<RawMeasurementResult> {
  const identity = createDuplicateScanCacheIdentity(input);
  const exactPaths = input.exactInput.approvedExactPaths;
  if (input.cache.enabled) {
    const cachedFragments = loadValidCachedFragments(
      input.exactInput.cacheRootDir,
      identity,
      exactPaths
    );
    if (cachedFragments !== null) {
      return Object.freeze({ fragments: cachedFragments, kind: "complete" });
    }
  }
  return scanAndCacheScope(input, identity, exactPaths);
}

function loadValidCachedFragments(
  cacheRootDir: string,
  identity: DuplicateCodeCacheIdentity,
  exactPaths: readonly string[]
): readonly DuplicateCodeFragment[] | null {
  const cached = loadScanCacheEntry({ rootDir: cacheRootDir, identity });
  if (!cached.hit) return null;
  const accepted = acceptExactInputMeasurements(
    toScopedJscpdMeasurements(cached.metrics),
    exactPaths
  );
  return accepted.ok && accepted.payloads.every(isValidDuplicateFragment)
    ? Object.freeze(accepted.payloads)
    : null;
}

async function scanAndCacheScope(
  input: RawScopeMeasurementInput,
  identity: DuplicateCodeCacheIdentity,
  exactPaths: readonly string[]
): Promise<RawMeasurementResult> {
  const result = await scanWithJscpdAsync({
    cwd: input.exactInput.rootDir,
    dependency: input.dependency,
    files: exactPaths,
    minimumLines: input.minimumLines,
    minimumTokens: input.minimumTokens
  });
  if (!result.ok) {
    return Object.freeze({
      kind: result.reason === "jscpd-execution-error" ? "execution-failed" : "invalid-result"
    });
  }

  const accepted = acceptExactInputMeasurements(result.measurements, exactPaths);
  if (!accepted.ok || !accepted.payloads.every(isValidDuplicateFragment)) {
    return Object.freeze({ kind: "invalid-result" });
  }
  const fragments = Object.freeze(accepted.payloads);
  if (input.cache.enabled) {
    try {
      writeScanCacheEntry({
        rootDir: input.exactInput.cacheRootDir,
        identity,
        metrics: [...fragments]
      });
    } catch {
      return Object.freeze({ kind: "cache-write-failed" });
    }
  }
  return Object.freeze({ fragments, kind: "complete" });
}

function positiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

function nonEmptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function uniqueSorted(values: readonly string[]): string[] {
  return [...new Set(values)].sort(compareText);
}

function sameStrings(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((value, index) => value === right[index]);
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import {
  snapshotClosedPolicyRecord,
  snapshotClosedRecord
} from "../../data-boundary/closed-values.ts";
import { isNonEmptyString, isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import {
  resolveProjectFileSelection,
  snapshotDefaultProjectFileSelection
} from "../project-files/configuration.ts";
import {
  DEFAULT_FINDING_POLICY,
  resolveCodeAreaPolicyMap,
  resolveFindingPolicy,
  type FindingPolicy
} from "../code-quality-findings/policy.ts";
import { resolveFindingWaiverAuthoring } from "../code-quality-findings/finding-waiver-authoring.ts";
import { DEFAULT_JSCPD_COMMAND } from "./jscpd/command-resolution.ts";
import { resolveDuplicateDetectionFindingIdentity } from "./finding-waiver-identity.ts";
import type {
  DuplicateDetectionScannerCommand,
  ResolvedDuplicateDetectionCodeAreaOptions,
  ResolvedDuplicateDetectionOptions,
  ResolvedDuplicateDetectionScannerOptions
} from "./options.ts";
import { validResolvedDuplicateDetectionOptions } from "./options-validation.ts";

const DEFAULT_CACHE_DIRECTORY = ".cache/vibe-check";
const DEFAULT_MINIMUM_LINES = 4;
const DEFAULT_MINIMUM_TOKENS = 100;

/** 校验 constructor input，并将所有可省略 policy 物化为完整、冻结的 Check options。 */
export function resolveDuplicateDetectionOptions(
  value: unknown
): ResolvedDuplicateDetectionOptions | undefined {
  const input = snapshotClosedPolicyRecord(value, {
    optional: ["cache", "codeAreas", "findingPolicy", "findingWaivers", "scanner"]
  });
  if (input === undefined) return undefined;

  const cache = resolveCache(input.cache);
  const findingPolicy = resolveFindingPolicy(input.findingPolicy, DEFAULT_FINDING_POLICY);
  if (findingPolicy === undefined) return undefined;
  const codeAreas = resolveCodeAreas(input.codeAreas, findingPolicy);
  const findingWaivers = resolveFindingWaiverAuthoring(
    input.findingWaivers,
    resolveDuplicateDetectionFindingIdentity
  );
  const scanner = resolveScanner(input.scanner);
  if (
    cache === undefined ||
    codeAreas === undefined ||
    findingWaivers === undefined ||
    scanner === undefined
  )
    return undefined;

  const options = Object.freeze({ cache, codeAreas, findingWaivers, scanner });
  return validResolvedDuplicateDetectionOptions(options) ? options : undefined;
}

function resolveCache(value: unknown): ResolvedDuplicateDetectionOptions["cache"] | undefined {
  if (value === undefined) {
    return Object.freeze({ directory: DEFAULT_CACHE_DIRECTORY, enabled: true });
  }
  const cache = snapshotClosedPolicyRecord(value, { optional: ["directory", "enabled"] });
  if (cache === undefined) return undefined;
  const directory = cache.directory ?? DEFAULT_CACHE_DIRECTORY;
  const enabled = cache.enabled ?? true;
  if (!isNonEmptyString(directory) || typeof enabled !== "boolean") return undefined;
  return Object.freeze({ directory, enabled });
}

function resolveCodeAreas(
  value: unknown,
  defaultFindingPolicy: FindingPolicy
): ResolvedDuplicateDetectionOptions["codeAreas"] | undefined {
  return resolveCodeAreaPolicyMap(
    value,
    () => defaultCodeArea(defaultFindingPolicy),
    (candidate) => resolveCodeArea(candidate, defaultFindingPolicy)
  );
}

function defaultCodeArea(findingPolicy: FindingPolicy): ResolvedDuplicateDetectionCodeAreaOptions {
  return Object.freeze({
    files: snapshotDefaultProjectFileSelection(),
    findingPolicy,
    minimumLines: DEFAULT_MINIMUM_LINES,
    minimumTokens: DEFAULT_MINIMUM_TOKENS
  });
}

function resolveCodeArea(
  value: unknown,
  defaultFindingPolicy: FindingPolicy
): ResolvedDuplicateDetectionCodeAreaOptions | undefined {
  const area = snapshotClosedPolicyRecord(value, {
    optional: ["findingPolicy", "minimumLines", "minimumTokens"],
    required: ["files"]
  });
  if (area === undefined) return undefined;
  const files = resolveProjectFileSelection(area.files);
  const findingPolicy = resolveFindingPolicy(area.findingPolicy, defaultFindingPolicy);
  const minimumLines = area.minimumLines ?? DEFAULT_MINIMUM_LINES;
  const minimumTokens = area.minimumTokens ?? DEFAULT_MINIMUM_TOKENS;
  if (
    files === undefined ||
    findingPolicy === undefined ||
    !isPositiveSafeInteger(minimumLines) ||
    !isPositiveSafeInteger(minimumTokens)
  ) {
    return undefined;
  }
  return Object.freeze({ files, findingPolicy, minimumLines, minimumTokens });
}

function resolveScanner(value: unknown): ResolvedDuplicateDetectionScannerOptions | undefined {
  if (value === undefined) return Object.freeze({ command: DEFAULT_JSCPD_COMMAND });
  const scanner = snapshotClosedPolicyRecord(value, { optional: ["command"] });
  if (scanner === undefined) return undefined;
  const command = resolveScannerCommand(scanner.command);
  return command === undefined ? undefined : Object.freeze({ command });
}

function resolveScannerCommand(value: unknown): DuplicateDetectionScannerCommand | undefined {
  if (value === undefined) return DEFAULT_JSCPD_COMMAND;
  const command = snapshotClosedRecord(value);
  if (command?.kind === "package") {
    return Object.keys(command).length === 1 ? DEFAULT_JSCPD_COMMAND : undefined;
  }
  if (command?.kind !== "custom") return undefined;
  const custom = snapshotClosedPolicyRecord(command, { required: ["executable", "kind"] });
  if (custom === undefined || custom.kind !== "custom" || !isNonEmptyString(custom.executable)) {
    return undefined;
  }
  return Object.freeze({ executable: custom.executable, kind: "custom" });
}

import {
  snapshotClosedRecord,
  snapshotExactClosedRecord
} from "../../data-boundary/closed-values.ts";
import { isNonEmptyString, isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import { validProjectFileSelection } from "../project-files/configuration.ts";
import { validFindingPolicy } from "../code-quality-findings/policy.ts";
import { validResolvedFindingWaivers } from "../code-quality-findings/finding-waiver-authoring.ts";
import { resolveDuplicateDetectionFindingIdentity } from "./finding-waiver-identity.ts";

export function validResolvedDuplicateDetectionOptions(value: object): boolean {
  const options = snapshotExactClosedRecord(value, [
    "cache",
    "codeAreas",
    "findingWaivers",
    "scanner"
  ]);
  return (
    options !== undefined &&
    validDuplicateCache(options.cache) &&
    validDuplicateCodeAreas(options.codeAreas) &&
    validResolvedFindingWaivers(options.findingWaivers, resolveDuplicateDetectionFindingIdentity) &&
    validDuplicateDetectionScanner(options.scanner)
  );
}

function validDuplicateCodeAreas(value: unknown): boolean {
  const areas = snapshotClosedRecord(value);
  if (areas === undefined || Object.keys(areas).length === 0) return false;
  return Object.entries(areas).every(([areaId, candidate]) => {
    const area = snapshotExactClosedRecord(candidate, [
      "files",
      "findingPolicy",
      "minimumLines",
      "minimumTokens"
    ]);
    return (
      isNonEmptyString(areaId) &&
      area !== undefined &&
      validProjectFileSelection(area.files) &&
      validFindingPolicy(area.findingPolicy) &&
      isPositiveSafeInteger(area.minimumLines) &&
      isPositiveSafeInteger(area.minimumTokens)
    );
  });
}

function validDuplicateDetectionScanner(value: unknown): boolean {
  const scanner = snapshotExactClosedRecord(value, ["command"]);
  return scanner !== undefined && validJscpdCommand(scanner.command);
}

function validJscpdCommand(value: unknown): boolean {
  const record = snapshotClosedRecord(value);
  if (record?.kind === "package") {
    return Object.keys(record).length === 1;
  }
  const command = snapshotExactClosedRecord(value, ["executable", "kind"]);
  return command?.kind === "custom" && isNonEmptyString(command.executable);
}

function validDuplicateCache(value: unknown): boolean {
  const cache = snapshotExactClosedRecord(value, ["directory", "enabled"]);
  return (
    cache !== undefined && isNonEmptyString(cache.directory) && typeof cache.enabled === "boolean"
  );
}

