export const FILE_METRICS_CHECK_DEFINITION = {
  checkId: "file-metrics",
  displayName: "File metrics"
} as const;

/** `file-metrics` whole-Check unavailable outcome 的稳定 reason code。 */
export type FileMetricsUnavailableReasonCode =
  | "external-dependency-unavailable"
  | "external-execution-failed"
  | "external-result-invalid"
  | "invalid-options"
  | "source-unavailable";

interface CollectedFileMetricsScope extends FileMetricsExactInputSet {
  readonly areaIdsByPath: ReadonlyMap<string, readonly string[]>;
}

/** 使用 resolved area policy 和 scanner selection 执行一次完整的 file-metrics measurement。 */
export async function executeFileMetrics(
  context: CheckExecutionContext<ResolvedFileMetricsOptions>
): Promise<CheckResult<FileMetricsFinalData>> {
  if (!isValidResolvedFileMetricsOptions(context.options)) return unavailable("invalid-options");

  let collectedScope: CollectedFileMetricsScope;
  try {
    collectedScope = collectAreaScope(context.project.root, context.options.codeAreas);
  } catch {
    return unavailable("source-unavailable");
  }
  if (collectedScope.approvedExactPaths.length === 0) {
    return noEligibleInputResult(context);
  }
  const measurement = await measureFileMetrics(collectedScope, context.options.scanner);
  if (measurement.kind !== "complete") return measurementFailureResult(measurement);
  const candidates = buildFileRecordCandidates(measurement.metrics, {
    areaIdsByPath: collectedScope.areaIdsByPath,
    codeAreas: context.options.codeAreas
  });
  if (candidates === undefined) return unavailable("external-result-invalid");
  const reconciliation = reconcileFileMetricWaivers(candidates, context.options.findingWaivers);
  reportReconciledCodeQualityFindingRecords(context, reconciliation);
  reportWaiverAuditRecords(context, reconciliation);
  const settlement = settleFindings(
    reconciliation.findings.map(({ disposition, finding }) => ({
      actionable: disposition !== "waived",
      blocking: finding.data.blocking
    }))
  );
  const actionableFindings = reconciliation.findings
    .filter(({ disposition }) => disposition !== "waived")
    .map(({ finding }) => finding);
  return appendWaiverMessages(
    appendCheckMessages(settlement, fileMetricFindingMessages(actionableFindings)),
    reconciliation
  );
}

function noEligibleInputResult(
  context: CheckExecutionContext<ResolvedFileMetricsOptions>
): CheckResult<FileMetricsFinalData> {
  const reconciliation = reconcileFileMetricWaivers([], context.options.findingWaivers);
  reportWaiverAuditRecords(context, reconciliation);
  return appendWaiverMessages(
    Object.freeze({ status: "not-applicable", reason: { code: "no-eligible-input" } }),
    reconciliation
  );
}

function reconcileFileMetricWaivers(
  candidates: readonly FileRecordCandidate[],
  waivers: readonly FileMetricsFindingWaiver[]
): FindingWaiverReconciliation<FileRecordCandidate> {
  return reconcileFindingWaivers({
    findings: candidates,
    identify: ({ data }) => ({ metric: data.metric, path: data.path }),
    waivers
  });
}

function reportWaiverAuditRecords(
  context: CheckExecutionContext<ResolvedFileMetricsOptions>,
  reconciliation: FindingWaiverReconciliation<FileRecordCandidate>
): void {
  reportFindingWaiverAudits(context, reconciliation, fileMetricsWaiverAuditRecord);
}

function appendWaiverMessages(
  settlement: CheckResult<FileMetricsFinalData>,
  reconciliation: FindingWaiverReconciliation<FileRecordCandidate>
): CheckResult<FileMetricsFinalData> {
  const waiverMessages: CheckMessage[] = [];
  for (const audit of reconciliation.waiverAudits) {
    const identity = fileMetricsWaiverIdentity(audit.waiver);
    switch (audit.status) {
      case "applied":
        waiverMessages.push(
          Object.freeze({
            code: "finding-waived",
            level: "info",
            message: `File metric finding for ${identity.path} was waived: ${audit.waiver.reason}`
          })
        );
        break;
      case "unused":
        waiverMessages.push(
          Object.freeze({
            code: "unused-finding-waiver",
            level: "warning",
            message: `Configured file-metrics finding waiver for ${identity.path} matched no finding; remove it or update its identity. Reason: ${audit.waiver.reason}`
          })
        );
        break;
      case "overmatched":
        waiverMessages.push(
          Object.freeze({
            code: "overmatched-finding-waiver",
            level: "warning",
            message: `Configured file-metrics finding waiver for ${identity.path} matched ${audit.matchCount} findings and was not applied; narrow its identity. Reason: ${audit.waiver.reason}`
          })
        );
        break;
    }
  }
  if (waiverMessages.length === 0) return settlement;
  return Object.freeze({
    ...settlement,
    messages: Object.freeze([...(settlement.messages ?? []), ...waiverMessages])
  });
}

function collectAreaScope(
  rootDir: string,
  codeAreas: Readonly<Record<string, ResolvedFileMetricsCodeAreaOptions>>
): CollectedFileMetricsScope {
  const areaIdsByPath = new Map<string, string[]>();
  const filesByArea = collectProjectFileSets(
    rootDir,
    Object.fromEntries(Object.entries(codeAreas).map(([areaId, area]) => [areaId, area.files]))
  );
  for (const [areaId] of Object.entries(codeAreas)) {
    for (const path of requireProjectFileSet(filesByArea, areaId)) {
      const areaIds = areaIdsByPath.get(path);
      if (areaIds === undefined) areaIdsByPath.set(path, [areaId]);
      else areaIds.push(areaId);
    }
  }

  const normalizedMembership = new Map<string, readonly string[]>();
  for (const [path, areaIds] of areaIdsByPath) {
    normalizedMembership.set(path, Object.freeze(areaIds.sort(compareText)));
  }
  return Object.freeze({
    approvedExactPaths: Object.freeze([...normalizedMembership.keys()].sort(compareText)),
    areaIdsByPath: normalizedMembership,
    rootDir
  });
}

function measurementFailureResult(
  measurement: Exclude<FileMeasurementResult, { kind: "complete" }>
): CheckResult<FileMetricsFinalData> {
  switch (measurement.kind) {
    case "execution-failed":
      return unavailable("external-execution-failed");
    case "invalid-result":
      return unavailable("external-result-invalid");
    case "unavailable":
      return unavailable("external-dependency-unavailable");
  }
  const exhaustiveMeasurement: never = measurement;
  return exhaustiveMeasurement;
}

function unavailable(code: FileMetricsUnavailableReasonCode): CheckResult<FileMetricsFinalData> {
  return Object.freeze({
    status: "unavailable",
    reason: { code },
    messages: Object.freeze([
      Object.freeze({ code, level: "error" as const, message: unavailableMessage(code) })
    ])
  });
}

function unavailableMessage(code: FileMetricsUnavailableReasonCode): string {
  switch (code) {
    case "invalid-options":
      return "fileMetrics options are invalid; recreate the Check with fileMetrics(options) or restore its complete resolved options.";
    case "source-unavailable":
      return "File metrics could not collect its configured project files; check the project root, file permissions, and selected file source.";
    case "external-dependency-unavailable":
      return "The configured SCC command is unavailable or incompatible; install SCC 4.0.0 or configure a compatible executable.";
    case "external-execution-failed":
      return "SCC did not complete successfully; run the configured command directly and inspect its environment.";
    case "external-result-invalid":
      return "SCC output could not form a trusted complete result; check the executable version and CSV compatibility.";
  }
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import type { FindingSummary } from "../code-quality-findings/policy.ts";
import { parseFindingSummaryData } from "../final-data-parsing.ts";

/** `file-metrics` 在 passed/failed outcome 中发布的主数据。 */
export type FileMetricsFinalData = FindingSummary;

/** 验证并脱离一份 `file-metrics` canonical final-data object。 */
export function parseFileMetricsData(data: unknown): FileMetricsFinalData {
  return parseFindingSummaryData(data, "fileMetrics");
}

import type { CheckMessage } from "../../check/check.ts";
import { presentCheckFindings } from "../../check/finding-presentation.ts";
import type { FileRecordCandidate } from "./records.ts";

const PRESENTED_FINDING_LIMIT = 10;

/** Projects actionable file-metric Records into bounded terminal summaries. */
export function fileMetricFindingMessages(
  findings: readonly FileRecordCandidate[]
): readonly CheckMessage[] {
  return presentCheckFindings({
    findings,
    limit: PRESENTED_FINDING_LIMIT,
    message: ({ data }) =>
      Object.freeze({
        code: "finding-detail",
        level: data.blocking ? ("error" as const) : ("warning" as const),
        message: `${data.path}: ${data.codeLines} code lines exceeds the ${data.limit} line limit (areas: ${data.codeAreas.join(", ")}).`
      }),
    omittedMessage: ({ omittedCount, omittedFindings }) =>
      Object.freeze({
        code: "findings-omitted",
        level: omittedFindings.some(({ data }) => data.blocking)
          ? ("error" as const)
          : ("warning" as const),
        message: `${omittedCount} additional file metric finding(s) were not shown; inspect this Check's Records for the complete set.`
      })
  });
}

export interface FileMetric {
  readonly codeLines: number;
  readonly decisionTokens: Readonly<{ readonly source: "scc"; readonly value: number | null }>;
  readonly path: string;
}

export interface FileMetricsExactInputSet {
  readonly approvedExactPaths: readonly string[];
  readonly rootDir: string;
}

import { acceptExactInputMeasurements } from "../project-files/exact-input-measurement.ts";
import type { FileMetric, FileMetricsExactInputSet } from "./measurement-model.ts";
import type { ResolvedFileMetricsScannerOptions } from "./options.ts";
import { checkScc } from "./scc/availability.ts";
import { scanWithScc } from "./scc/scanner.ts";

export type FileMeasurementResult = Readonly<
  | { kind: "complete"; metrics: readonly FileMetric[] }
  | { kind: "execution-failed" }
  | { kind: "invalid-result" }
  | { kind: "unavailable" }
>;

export async function measureFileMetrics(
  exactInputs: FileMetricsExactInputSet,
  scanner: ResolvedFileMetricsScannerOptions
): Promise<FileMeasurementResult> {
  if (exactInputs.approvedExactPaths.length === 0) {
    return Object.freeze({ kind: "complete", metrics: Object.freeze([]) });
  }
  const scannerAvailability = await checkScc(exactInputs.rootDir, scanner);
  if (!scannerAvailability.available) {
    return Object.freeze({ kind: "unavailable" });
  }
  return runFileScanner(exactInputs, scanner);
}

function runFileScanner(
  exactInputs: FileMetricsExactInputSet,
  scanner: ResolvedFileMetricsScannerOptions
): FileMeasurementResult {
  const scanResult = scanWithScc({
    cwd: exactInputs.rootDir,
    scanner,
    includePaths: exactInputs.approvedExactPaths
  });
  if (!scanResult.ok) {
    return Object.freeze({
      kind: scanResult.reason === "execution" ? "execution-failed" : "invalid-result"
    });
  }
  const acceptedMeasurements = acceptExactInputMeasurements(
    scanResult.measurements,
    exactInputs.approvedExactPaths
  );
  return acceptedMeasurements.ok
    ? Object.freeze({
        kind: "complete",
        metrics: Object.freeze([...acceptedMeasurements.payloads])
      })
    : Object.freeze({ kind: "invalid-result" });
}

import {
  snapshotClosedArray,
  snapshotClosedPolicyRecord
} from "../../data-boundary/closed-values.ts";
import {
  isNonEmptyString,
  isNonNegativeSafeInteger,
  isPositiveSafeInteger
} from "../../data-boundary/value-shapes.ts";
import {
  resolveProjectFileSelection,
  snapshotDefaultProjectFileSelection
} from "../project-files/configuration.ts";
import {
  DEFAULT_FINDING_POLICY,
  resolveCodeAreaPolicyMap,
  resolveFindingPolicy,
  type FindingPolicy
} from "../code-quality-findings/policy.ts";
import { isNormalizedProjectRelativePath } from "../host-environment/path.ts";
import type {
  FileMetricsFindingIdentity,
  FileMetricsFindingWaiver,
  ResolvedFileMetricsCodeAreaOptions,
  ResolvedFileMetricsOptions
} from "./options.ts";
import { isValidResolvedFileMetricsOptions } from "./options-validation.ts";

const DEFAULT_EXECUTABLE = "scc";
const DEFAULT_MAXIMUM_CODE_LINES = 360;
const DEFAULT_ALLOWANCE_MAXIMUM_CODE_LINES = 600;
const DEFAULT_ALLOWANCE_MAXIMUM_DECISION_TOKENS = 12;

/** 校验 constructor input，并将所有可省略 policy 物化为完整、冻结的 Check options。 */
export function resolveFileMetricsOptions(
  authoredOptions: unknown
): ResolvedFileMetricsOptions | undefined {
  const input = snapshotClosedPolicyRecord(authoredOptions, {
    optional: ["codeAreas", "findingPolicy", "findingWaivers", "scanner"]
  });
  if (input === undefined) return undefined;

  const findingPolicy = resolveFindingPolicy(input.findingPolicy, DEFAULT_FINDING_POLICY);
  if (findingPolicy === undefined) return undefined;
  const codeAreas = resolveCodeAreas(input.codeAreas, findingPolicy);
  const findingWaivers = resolveFindingWaivers(input.findingWaivers);
  const scanner = resolveScanner(input.scanner);
  if (codeAreas === undefined || findingWaivers === undefined || scanner === undefined)
    return undefined;

  const options = Object.freeze({ codeAreas, findingWaivers, scanner });
  return isValidResolvedFileMetricsOptions(options) ? options : undefined;
}

function resolveFindingWaivers(value: unknown): readonly FileMetricsFindingWaiver[] | undefined {
  if (value === undefined) return Object.freeze([]);
  const candidates = snapshotClosedArray(value);
  if (candidates === undefined) return undefined;
  const waivers: FileMetricsFindingWaiver[] = [];
  const seenIdentities = new Set<string>();
  for (const candidate of candidates) {
    const waiver = resolveFindingWaiver(candidate);
    if (waiver === undefined) return undefined;
    const identityKey = `${waiver.identity.metric}\u0000${waiver.identity.path}`;
    if (seenIdentities.has(identityKey)) return undefined;
    seenIdentities.add(identityKey);
    waivers.push(waiver);
  }
  return Object.freeze(waivers);
}

function resolveFindingWaiver(value: unknown): FileMetricsFindingWaiver | undefined {
  const waiver = snapshotClosedPolicyRecord(value, { required: ["identity", "reason"] });
  if (waiver === undefined || !isNonEmptyString(waiver.reason)) return undefined;
  const identity = resolveFindingIdentity(waiver.identity);
  return identity === undefined ? undefined : Object.freeze({ identity, reason: waiver.reason });
}

function resolveFindingIdentity(value: unknown): FileMetricsFindingIdentity | undefined {
  const identity = snapshotClosedPolicyRecord(value, { required: ["metric", "path"] });
  return identity === undefined ||
    identity.metric !== "code-lines" ||
    !isNormalizedProjectRelativePath(identity.path)
    ? undefined
    : Object.freeze({ metric: "code-lines", path: identity.path });
}

function resolveCodeAreas(
  value: unknown,
  defaultFindingPolicy: FindingPolicy
): ResolvedFileMetricsOptions["codeAreas"] | undefined {
  return resolveCodeAreaPolicyMap(
    value,
    () => defaultCodeArea(defaultFindingPolicy),
    (candidate) => resolveCodeArea(candidate, defaultFindingPolicy)
  );
}

function defaultCodeArea(findingPolicy: FindingPolicy): ResolvedFileMetricsCodeAreaOptions {
  return Object.freeze({
    codeLines: defaultCodeLines(),
    files: snapshotDefaultProjectFileSelection(),
    findingPolicy
  });
}

function resolveCodeArea(
  value: unknown,
  defaultFindingPolicy: FindingPolicy
): ResolvedFileMetricsCodeAreaOptions | undefined {
  const area = snapshotClosedPolicyRecord(value, {
    optional: ["codeLines", "findingPolicy"],
    required: ["files"]
  });
  if (area === undefined) return undefined;
  const files = resolveProjectFileSelection(area.files);
  const findingPolicy = resolveFindingPolicy(area.findingPolicy, defaultFindingPolicy);
  const codeLines = resolveCodeLines(area.codeLines);
  return files === undefined || findingPolicy === undefined || codeLines === undefined
    ? undefined
    : Object.freeze({ codeLines, files, findingPolicy });
}

function resolveCodeLines(
  value: unknown
): ResolvedFileMetricsCodeAreaOptions["codeLines"] | undefined {
  if (value === undefined) return defaultCodeLines();
  const codeLines = snapshotClosedPolicyRecord(value, {
    optional: ["lowDecisionTokenAllowance", "maximum"]
  });
  if (codeLines === undefined) return undefined;
  const maximum = codeLines.maximum ?? DEFAULT_MAXIMUM_CODE_LINES;
  const lowDecisionTokenAllowance = resolveAllowance(codeLines.lowDecisionTokenAllowance);
  if (
    !isPositiveSafeInteger(maximum) ||
    lowDecisionTokenAllowance === undefined ||
    lowDecisionTokenAllowance.maximumCodeLines <= maximum
  ) {
    return undefined;
  }
  return Object.freeze({ lowDecisionTokenAllowance, maximum });
}

function defaultCodeLines(): ResolvedFileMetricsCodeAreaOptions["codeLines"] {
  return Object.freeze({
    lowDecisionTokenAllowance: Object.freeze({
      maximumCodeLines: DEFAULT_ALLOWANCE_MAXIMUM_CODE_LINES,
      maximumDecisionTokens: DEFAULT_ALLOWANCE_MAXIMUM_DECISION_TOKENS
    }),
    maximum: DEFAULT_MAXIMUM_CODE_LINES
  });
}

function resolveAllowance(
  value: unknown
): ResolvedFileMetricsCodeAreaOptions["codeLines"]["lowDecisionTokenAllowance"] | undefined {
  if (value === undefined) return defaultCodeLines().lowDecisionTokenAllowance;
  const allowance = snapshotClosedPolicyRecord(value, {
    optional: ["maximumCodeLines", "maximumDecisionTokens"]
  });
  if (allowance === undefined) return undefined;
  const maximumCodeLines = allowance.maximumCodeLines ?? DEFAULT_ALLOWANCE_MAXIMUM_CODE_LINES;
  const maximumDecisionTokens =
    allowance.maximumDecisionTokens ?? DEFAULT_ALLOWANCE_MAXIMUM_DECISION_TOKENS;
  if (
    !isPositiveSafeInteger(maximumCodeLines) ||
    !isNonNegativeSafeInteger(maximumDecisionTokens)
  ) {
    return undefined;
  }
  return Object.freeze({ maximumCodeLines, maximumDecisionTokens });
}

function resolveScanner(value: unknown): ResolvedFileMetricsOptions["scanner"] | undefined {
  if (value === undefined) return Object.freeze({ executable: DEFAULT_EXECUTABLE });
  const scanner = snapshotClosedPolicyRecord(value, { optional: ["executable"] });
  if (scanner === undefined) return undefined;
  const executable = scanner.executable ?? DEFAULT_EXECUTABLE;
  return isNonEmptyString(executable) ? Object.freeze({ executable }) : undefined;
}

import {
  snapshotClosedArray,
  snapshotClosedRecord,
  snapshotExactClosedRecord
} from "../../data-boundary/closed-values.ts";
import {
  isNonEmptyString,
  isNonNegativeSafeInteger,
  isPositiveSafeInteger
} from "../../data-boundary/value-shapes.ts";
import { validProjectFileSelection } from "../project-files/configuration.ts";
import { validFindingPolicy } from "../code-quality-findings/policy.ts";
import { isNormalizedProjectRelativePath } from "../host-environment/path.ts";
import type { ResolvedFileMetricsOptions } from "./options.ts";

/** 验证 constructor 产物或普通对象组合形成的完整 file-metrics options。 */
export function isValidResolvedFileMetricsOptions(
  resolvedOptions: unknown
): resolvedOptions is ResolvedFileMetricsOptions {
  const options = snapshotExactClosedRecord(resolvedOptions, [
    "codeAreas",
    "findingWaivers",
    "scanner"
  ]);
  return (
    options !== undefined &&
    isValidCodeAreas(options.codeAreas) &&
    isValidFindingWaivers(options.findingWaivers) &&
    isValidScanner(options.scanner)
  );
}

function isValidFindingWaivers(value: unknown): boolean {
  const waivers = snapshotClosedArray(value);
  if (waivers === undefined) return false;
  const identities = new Set<string>();
  for (const candidate of waivers) {
    const waiver = snapshotExactClosedRecord(candidate, ["identity", "reason"]);
    const identity =
      waiver === undefined
        ? undefined
        : snapshotExactClosedRecord(waiver.identity, ["metric", "path"]);
    if (
      waiver === undefined ||
      identity === undefined ||
      identity.metric !== "code-lines" ||
      !isNormalizedProjectRelativePath(identity.path) ||
      !isNonEmptyString(waiver.reason)
    ) {
      return false;
    }
    const identityKey = `${identity.metric}\u0000${identity.path}`;
    if (identities.has(identityKey)) return false;
    identities.add(identityKey);
  }
  return true;
}

function isValidCodeAreas(value: unknown): boolean {
  const codeAreas = snapshotClosedRecord(value);
  if (codeAreas === undefined || Object.keys(codeAreas).length === 0) return false;
  return Object.entries(codeAreas).every(
    ([areaId, candidate]) => areaId.length > 0 && isValidCodeArea(candidate)
  );
}

function isValidCodeArea(value: unknown): boolean {
  const area = snapshotExactClosedRecord(value, ["codeLines", "files", "findingPolicy"]);
  return (
    area !== undefined &&
    validProjectFileSelection(area.files) &&
    validFindingPolicy(area.findingPolicy) &&
    isValidCodeLinePolicy(area.codeLines)
  );
}

function isValidCodeLinePolicy(value: unknown): boolean {
  const policy = snapshotExactClosedRecord(value, ["lowDecisionTokenAllowance", "maximum"]);
  if (policy === undefined || !isPositiveSafeInteger(policy.maximum)) return false;
  const allowance = snapshotExactClosedRecord(policy.lowDecisionTokenAllowance, [
    "maximumCodeLines",
    "maximumDecisionTokens"
  ]);
  return (
    allowance !== undefined &&
    isPositiveSafeInteger(allowance.maximumCodeLines) &&
    allowance.maximumCodeLines > policy.maximum &&
    isNonNegativeSafeInteger(allowance.maximumDecisionTokens)
  );
}

function isValidScanner(value: unknown): boolean {
  const scanner = snapshotExactClosedRecord(value, ["executable"]);
  return scanner !== undefined && isNonEmptyString(scanner.executable);
}

import type {
  ProjectFileSelection,
  ProjectFileSelectionOptions
} from "../project-files/configuration.ts";
import type { FindingPolicy } from "../code-quality-findings/policy.ts";
import type { FindingWaiver } from "../../finding-waivers/reconciliation.ts";

/** `fileMetrics` 构造函数可省略的 SCC 可执行文件策略。 */
export interface FileMetricsScannerOptions {
  /** 省略时直接执行 `scc`；显式命令必须直接接受 adapter 拥有的 SCC 参数。 */
  readonly executable?: string;
}

/** file-metrics 区域可省略并由构造函数补齐的文件策略。 */
export type FileMetricsFileOptions = ProjectFileSelectionOptions;

/** SCC decision-token 数较低的文件可使用的代码行宽限策略。 */
export interface FileMetricsLowDecisionTokenAllowanceOptions {
  /** 省略时为 `600`；必须严格大于同一区域的普通代码行上限。 */
  readonly maximumCodeLines?: number;
  /** 省略时为 `12`；decision-token measurement 不大于此值时应用宽限上限。 */
  readonly maximumDecisionTokens?: number;
}

/** 一个区域可省略的文件代码行策略。 */
export interface FileMetricsCodeLineOptions {
  /** 省略时为 `360`；只有严格超过此值才产生 finding。 */
  readonly maximum?: number;
  /** 省略时使用完整默认宽限策略。 */
  readonly lowDecisionTokenAllowance?: FileMetricsLowDecisionTokenAllowanceOptions;
}

/** 可独立选择文件并定义代码行与 finding policy 的 file-metrics 区域。 */
export interface FileMetricsCodeAreaOptions {
  /** 显式区域必须声明本字段；其中各子字段可省略并使用 package 默认值。 */
  readonly files: FileMetricsFileOptions;
  /** 省略时继承顶层 `findingPolicy`。 */
  readonly findingPolicy?: FindingPolicy;
  /** 省略时使用 package 默认代码行策略。 */
  readonly codeLines?: FileMetricsCodeLineOptions;
}

/** file-metrics 用于识别可豁免 finding 的稳定语义字段。 */
export interface FileMetricsFindingIdentity {
  /** file-metrics 当前只产生文件代码行 finding。 */
  readonly metric: "code-lines";
  /** 已 normalized 的 project-root-relative slash path；不得为绝对、含反斜杠或含 `.`/`..` 的路径。 */
  readonly path: string;
}

/** 一项 file-metrics finding 的声明式豁免；执行时仍会扫描并发布该 finding。 */
export type FileMetricsFindingWaiver = FindingWaiver<FileMetricsFindingIdentity>;

/** `fileMetrics(options?)` 接受并补齐默认值的公开策略。 */
export interface FileMetricsOptions {
  /** 省略时建立默认 `project` 区域；显式映射必须非空。 */
  readonly codeAreas?: Readonly<Record<string, FileMetricsCodeAreaOptions>>;
  /** 省略时为 `non-blocking`；区域可局部覆盖。 */
  readonly findingPolicy?: FindingPolicy;
  /** 省略时没有豁免；每项以 `{ metric, path }` 精确匹配，并必须提供非空理由。 */
  readonly findingWaivers?: readonly FileMetricsFindingWaiver[];
  /** 省略时直接执行 `scc`；CLI 协议由 owning adapter 固定。 */
  readonly scanner?: FileMetricsScannerOptions;
}

/** 构造函数生成并由 Check preflight/execution 消费的完整 options。 */
export interface ResolvedFileMetricsOptions {
  readonly codeAreas: Readonly<Record<string, ResolvedFileMetricsCodeAreaOptions>>;
  readonly findingWaivers: readonly FileMetricsFindingWaiver[];
  readonly scanner: ResolvedFileMetricsScannerOptions;
}

export interface ResolvedFileMetricsCodeAreaOptions {
  readonly codeLines: ResolvedFileMetricsCodeLineOptions;
  readonly files: ProjectFileSelection;
  readonly findingPolicy: FindingPolicy;
}

export interface ResolvedFileMetricsCodeLineOptions {
  readonly lowDecisionTokenAllowance: ResolvedFileMetricsLowDecisionTokenAllowanceOptions;
  readonly maximum: number;
}

export interface ResolvedFileMetricsLowDecisionTokenAllowanceOptions {
  readonly maximumCodeLines: number;
  readonly maximumDecisionTokens: number;
}

export interface ResolvedFileMetricsScannerOptions {
  readonly executable: string;
}

import type { FileMetric } from "./measurement-model.ts";
import type { FileMetricsFindingIdentity, ResolvedFileMetricsCodeAreaOptions } from "./options.ts";
import { isBlockingFinding } from "../code-quality-findings/policy.ts";
import { isNormalizedProjectRelativePath } from "../host-environment/path.ts";
import type { MaterializedFindingWaiver } from "../../finding-waivers/reconciliation.ts";
import {
  buildFindingWaiverAuditRecordData,
  type FindingWaiverAuditRecordData,
  type FindingWaiverRecordAudit
} from "../code-quality-findings/finding-waiver-evidence.ts";
import type {
  CanonicalJsonObject,
  CanonicalJsonValue
} from "../../data-boundary/canonical-data.ts";

const FILE_CODE_LINES_METRIC = "code-lines" as const;
const FINDING_WAIVER_AUDIT_RECORD_ID_PREFIX = "/finding-waiver-audit/";

interface FileMetricsAreaPolicyContext {
  readonly areaIdsByPath: ReadonlyMap<string, readonly string[]>;
  readonly codeAreas: Readonly<Record<string, ResolvedFileMetricsCodeAreaOptions>>;
}

interface EffectiveFileRecordPolicy {
  readonly areaIds: readonly string[];
  readonly blocking: boolean;
  readonly limit: number;
}

/** 一条超出文件代码行上限的 supplemental Record data。 */
export type FileMetricsFindingRecordData = Readonly<{
  readonly blocking: boolean;
  readonly codeAreas: readonly string[];
  readonly codeLines: number;
  readonly limit: number;
  readonly metric: "code-lines";
  readonly path: string;
  /** 精确匹配 waiver 时保留理由，并令该 finding 不再参与 actionable settlement。 */
  readonly waiver?: Readonly<{ readonly reason: string }>;
}>;

/** 未使用或过宽 file-metrics waiver 的 supplemental audit Record data。 */
export type FileMetricsFindingWaiverAuditRecordData =
  FindingWaiverAuditRecordData<FileMetricsFindingIdentity>;

/** file-metrics 发布的 finding 或 waiver-audit supplemental Record data。 */
export type FileMetricsRecordData =
  | FileMetricsFindingRecordData
  | FileMetricsFindingWaiverAuditRecordData;

export interface FileRecordCandidate {
  readonly data: FileMetricsFindingRecordData;
  readonly id: string;
}

/** 仅为未使用和过宽 waiver 构造补充 audit Record；正常 applied waiver 由 finding Record 自己保留。 */
export function fileMetricsWaiverAuditRecord(
  audit: FindingWaiverRecordAudit
): Readonly<{ readonly data: FileMetricsFindingWaiverAuditRecordData; readonly id: string }> {
  const identity = fileMetricsWaiverIdentity(audit.waiver);
  return Object.freeze({
    data: buildFindingWaiverAuditRecordData(identity, audit),
    id: `${FINDING_WAIVER_AUDIT_RECORD_ID_PREFIX}${identity.path}`
  });
}

export function fileMetricsWaiverIdentity(
  waiver: MaterializedFindingWaiver
): FileMetricsFindingIdentity {
  const identity = waiver.identity;
  if (
    !isCanonicalObject(identity) ||
    identity.metric !== "code-lines" ||
    typeof identity.path !== "string" ||
    !isNormalizedProjectRelativePath(identity.path)
  ) {
    throw new TypeError("fileMetrics waiver identity must retain a normalized code-lines path");
  }
  return Object.freeze({ metric: "code-lines", path: identity.path });
}

function isCanonicalObject(value: CanonicalJsonValue): value is CanonicalJsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/** Converts trusted scanner metrics into area-policy-owned supplemental facts. */
export function buildFileRecordCandidates(
  metrics: readonly FileMetric[],
  areaPolicy: FileMetricsAreaPolicyContext
): readonly FileRecordCandidate[] | undefined {
  const seenPaths = new Set<string>();
  const candidates: FileRecordCandidate[] = [];
  for (const metric of metrics) {
    if (!isValidUniqueFileMetric(metric, seenPaths)) return undefined;
    seenPaths.add(metric.path);

    const recordPolicy = effectiveFileRecordPolicy(metric, areaPolicy);
    if (recordPolicy === undefined) return undefined;
    if (metric.codeLines <= recordPolicy.limit) continue;
    candidates.push(createFileRecordCandidate(metric, recordPolicy));
  }
  candidates.sort((left, right) => compareText(left.id, right.id));
  return Object.freeze(candidates);
}

function isValidUniqueFileMetric(metric: FileMetric, seenPaths: ReadonlySet<string>): boolean {
  return (
    typeof metric.path === "string" &&
    metric.path.length > 0 &&
    Number.isSafeInteger(metric.codeLines) &&
    metric.codeLines >= 0 &&
    !seenPaths.has(metric.path)
  );
}

function effectiveFileRecordPolicy(
  metric: FileMetric,
  areaPolicy: FileMetricsAreaPolicyContext
): EffectiveFileRecordPolicy | undefined {
  const areaIds = areaPolicy.areaIdsByPath.get(metric.path);
  if (areaIds === undefined || areaIds.length === 0) return undefined;
  const matchingAreas: ResolvedFileMetricsCodeAreaOptions[] = [];
  let strictestMaximum: number | undefined;
  for (const areaId of areaIds) {
    const codeArea = areaPolicy.codeAreas[areaId];
    if (codeArea === undefined) return undefined;
    matchingAreas.push(codeArea);
    const maximum = fileCodeLineMaximum(metric, codeArea);
    strictestMaximum =
      strictestMaximum === undefined ? maximum : Math.min(strictestMaximum, maximum);
  }
  return strictestMaximum === undefined
    ? undefined
    : Object.freeze({
        areaIds,
        blocking: isBlockingFinding(matchingAreas.map((area) => area.findingPolicy)),
        limit: strictestMaximum
      });
}

function createFileRecordCandidate(
  metric: FileMetric,
  recordPolicy: EffectiveFileRecordPolicy
): FileRecordCandidate {
  return Object.freeze({
    id: metric.path,
    data: Object.freeze({
      blocking: recordPolicy.blocking,
      codeAreas: Object.freeze([...recordPolicy.areaIds]),
      codeLines: metric.codeLines,
      limit: recordPolicy.limit,
      metric: FILE_CODE_LINES_METRIC,
      path: metric.path
    })
  });
}

function fileCodeLineMaximum(metric: FileMetric, area: ResolvedFileMetricsCodeAreaOptions): number {
  const allowance = area.codeLines.lowDecisionTokenAllowance;
  const decisionTokens = metric.decisionTokens.value;
  return decisionTokens !== null && decisionTokens <= allowance.maximumDecisionTokens
    ? allowance.maximumCodeLines
    : area.codeLines.maximum;
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import { errorMessage } from "../../host-environment/error-message.ts";
import { processFailure, runProcess } from "../../host-environment/process/command.ts";
import type { ResolvedFileMetricsScannerOptions } from "../options.ts";
import { SCC_VERSION_OUTPUT } from "./parser.ts";

const SCC_VERSION_ARGUMENTS = Object.freeze(["--version"]);

type SccAvailability = Readonly<
  | {
      readonly available: true;
      readonly error: null;
      readonly name: "scc";
      readonly reason: null;
      readonly source: "configured command";
      readonly version: string;
    }
  | {
      readonly available: false;
      readonly error: string;
      readonly name: "scc";
      readonly reason: "contract-error" | "execution-error" | "tool-unavailable";
      readonly source: "configured command";
      readonly version: null;
    }
>;

type SccVersionCommandResult = Awaited<ReturnType<typeof runProcess>>;

export async function checkScc(
  rootDir: string,
  scanner: ResolvedFileMetricsScannerOptions
): Promise<SccAvailability> {
  try {
    const commandResult = await runProcess({
      args: SCC_VERSION_ARGUMENTS,
      command: scanner.executable,
      cwd: rootDir
    });
    return availabilityFromVersionResult(commandResult);
  } catch (error: unknown) {
    return unavailableScc(`scc version error: ${errorMessage(error)}`, "execution-error");
  }
}

function availabilityFromVersionResult(commandResult: SccVersionCommandResult): SccAvailability {
  if (commandResult.error) return processErrorAvailability(commandResult.error);
  const version = commandOutput(commandResult);
  if (commandResult.status !== 0) {
    return unavailableScc(
      `scc --version failed, ${processTermination(commandResult)}${version ? `: ${version}` : ""}`,
      "execution-error"
    );
  }
  if (version !== SCC_VERSION_OUTPUT) {
    return unavailableScc(
      `expected ${SCC_VERSION_OUTPUT}, got "${version || "unknown"}"`,
      "contract-error"
    );
  }
  return {
    name: "scc",
    available: true,
    version,
    error: null,
    source: "configured command",
    reason: null
  };
}

function processErrorAvailability(error: Error): SccAvailability {
  const isMissingTool = processFailure(error).code === "ENOENT";
  return unavailableScc(
    isMissingTool ? `scc not installed: ${error.message}` : `scc version error: ${error.message}`,
    isMissingTool ? "tool-unavailable" : "execution-error"
  );
}

function unavailableScc(
  error: string,
  reason: Exclude<SccAvailability["reason"], null>
): SccAvailability {
  return {
    name: "scc",
    available: false,
    version: null,
    error,
    source: "configured command",
    reason
  };
}

function commandOutput(commandResult: SccVersionCommandResult): string {
  return (commandResult.stdout || "").trim() || (commandResult.stderr || "").trim();
}

function processTermination(commandResult: SccVersionCommandResult): string {
  return typeof commandResult.status === "number"
    ? `exit ${commandResult.status}`
    : `signal ${commandResult.signal || "unknown"}`;
}

import type { ExactInputMeasurement } from "../../project-files/exact-input-measurement.ts";
import { errorMessage } from "../../host-environment/error-message.ts";
import { normalizeScannerReportedPath } from "../../project-files/reported-path.ts";
import type { FileMetric } from "../measurement-model.ts";
import { parseCsvRows } from "../../host-environment/csv.ts";

export const SCC_VERSION = "4.0.0";
export const SCC_VERSION_OUTPUT = `scc version ${SCC_VERSION}`;
export const SCC_BY_FILE_CSV_HEADER =
  "Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,ULOC";

export type SccScanResult =
  | {
      readonly measurements: readonly ExactInputMeasurement<FileMetric>[];
      readonly ok: true;
    }
  | {
      readonly error: string;
      readonly ok: false;
      readonly reason: "execution" | "invalid-result";
    };

interface SccColumnIndexes {
  blanks: number;
  code: number;
  comments: number;
  complexity: number;
  filename: number;
  lines: number;
  provider: number;
}

interface ParsedSccRow {
  readonly codeLines: number;
  readonly complexity: number | null;
  readonly path: string;
}

interface SccRawRow {
  readonly blankLines: string;
  readonly codeLines: string;
  readonly commentLines: string;
  readonly complexity: string;
  readonly filename: string;
  readonly lineCount: string;
  readonly providerPath: string;
}

/**
 * 解析 scc CSV 输出。
 *
 * scc 4.0.0 `--no-config --by-file --format csv` 列：
 * Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,ULOC
 *
 * - Lines 包含所有行（code + comments + blanks）
 * - Code 是文件级代码行数，用于 code-line finding
 * - Complexity 是 scc complexitychecks token 命中数，用于 low-decision-token allowance，不是函数级 CC
 * - ULOC (Usable Lines of Code) 由 4.0.0 输出，但首期不进入稳定 metrics
 */
export function parseSccCSV(csv: string, cwd: string): SccScanResult {
  try {
    const rows = parseCsvRows(csv);
    const headerIndex = findSccHeaderIndex(rows);
    if (headerIndex < 0) {
      return {
        ok: false,
        error: `expected scc ${SCC_VERSION} by-file CSV header "${SCC_BY_FILE_CSV_HEADER}", got "${observedSccHeader(rows)}"`,
        reason: "invalid-result"
      };
    }

    const columns = sccColumnIndexes(rows[headerIndex] ?? []);
    const measurements = parseSccMetrics(
      rows.slice(headerIndex + 1),
      columns,
      headerIndex + 2,
      cwd
    );
    return {
      ok: true,
      measurements
    };
  } catch (error: unknown) {
    return {
      ok: false,
      error: `Failed to parse scc CSV: ${errorMessage(error)}`,
      reason: "invalid-result"
    };
  }
}

function findSccHeaderIndex(rows: string[][]): number {
  const expectedHeader = SCC_BY_FILE_CSV_HEADER.split(",");
  return rows.findIndex((row) => isCsvRow(row, expectedHeader));
}

function observedSccHeader(rows: string[][]): string {
  return rows.find((row) => row[0] === "Language")?.join(",") ?? rows[0]?.join(",") ?? "";
}

function sccColumnIndexes(headerColumns: string[]): SccColumnIndexes {
  return {
    provider: headerColumns.indexOf("Provider"),
    filename: headerColumns.indexOf("Filename"),
    lines: headerColumns.indexOf("Lines"),
    code: headerColumns.indexOf("Code"),
    comments: headerColumns.indexOf("Comments"),
    blanks: headerColumns.indexOf("Blanks"),
    complexity: headerColumns.indexOf("Complexity")
  };
}

function parseSccMetrics(
  rows: string[][],
  columns: SccColumnIndexes,
  firstRowNumber: number,
  cwd: string
): ExactInputMeasurement<FileMetric>[] {
  const measurements: ExactInputMeasurement<FileMetric>[] = [];

  for (const [index, row] of rows.entries()) {
    const measurement = parseSccFileMetric(row, columns, firstRowNumber + index, cwd);
    measurements.push(measurement);
  }

  measurements.sort((left, right) => compareText(left.payload.path, right.payload.path));
  return measurements;
}

function parseSccFileMetric(
  rowValues: string[],
  columns: SccColumnIndexes,
  rowNumber: number,
  cwd: string
): ExactInputMeasurement<FileMetric> {
  const row = parseSccRow(rowValues, columns, rowNumber);
  const sourcePath = normalizeScannerReportedPath(row.path, cwd);
  return {
    sourcePaths: [sourcePath],
    payload: {
      path: sourcePath,
      codeLines: row.codeLines,
      decisionTokens: {
        value: row.complexity,
        source: "scc"
      }
    }
  };
}

function parseSccRow(
  rowValues: string[],
  columns: SccColumnIndexes,
  rowNumber: number
): ParsedSccRow {
  const expectedColumnCount = SCC_BY_FILE_CSV_HEADER.split(",").length;
  if (rowValues.length !== expectedColumnCount) {
    throw new Error(
      `row ${rowNumber} has ${rowValues.length} columns; expected ${expectedColumnCount}`
    );
  }
  const rawRow = sccRawRow(rowValues, columns);
  if (!rawRow.filename) {
    throw new Error(`row ${rowNumber} field Filename must not be empty`);
  }
  validateSccRowCounts(rawRow, rowNumber);

  return {
    path: rawRow.providerPath || rawRow.filename,
    codeLines: parseRequiredInteger(rawRow.codeLines, "Code", rowNumber),
    complexity: parseOptionalInteger(rawRow.complexity, "Complexity", rowNumber)
  };
}

function validateSccRowCounts(row: SccRawRow, rowNumber: number): void {
  parseRequiredInteger(row.lineCount, "Lines", rowNumber);
  parseRequiredInteger(row.commentLines, "Comments", rowNumber);
  parseRequiredInteger(row.blankLines, "Blanks", rowNumber);
}

function sccRawRow(rowValues: string[], columns: SccColumnIndexes): SccRawRow {
  return {
    blankLines: sccColumnValue(rowValues, columns.blanks),
    codeLines: sccColumnValue(rowValues, columns.code),
    commentLines: sccColumnValue(rowValues, columns.comments),
    complexity: sccColumnValue(rowValues, columns.complexity),
    filename: sccColumnValue(rowValues, columns.filename),
    lineCount: sccColumnValue(rowValues, columns.lines),
    providerPath: sccColumnValue(rowValues, columns.provider)
  };
}

function parseRequiredInteger(value: string, field: string, rowNumber: number): number {
  if (!/^\d+$/.test(value)) {
    throw new Error(`row ${rowNumber} field ${field} must be a non-negative integer`);
  }
  const parsed = Number(value);
  if (!Number.isSafeInteger(parsed)) {
    throw new Error(`row ${rowNumber} field ${field} exceeds the supported integer range`);
  }
  return parsed;
}

function parseOptionalInteger(value: string, field: string, rowNumber: number): number | null {
  return value === "" ? null : parseRequiredInteger(value, field, rowNumber);
}

function sccColumnValue(rowValues: string[], index: number): string {
  return index >= 0 ? (rowValues[index] ?? "") : "";
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

function isCsvRow(row: string[], expectedValues: string[]): boolean {
  return (
    row.length === expectedValues.length &&
    row.every((value, index) => value === expectedValues[index])
  );
}

/**
 * scc 文件级 code-line 指标 wrapper。
 *
 * 封装 adapter-owned CLI 调用，输出 exact-path code lines 与 decision-token count。
 */

import { errorMessage } from "../../host-environment/error-message.ts";
import { runProcessSync } from "../../host-environment/process/command.ts";
import type { ResolvedFileMetricsScannerOptions } from "../options.ts";
import { parseSccCSV, type SccScanResult } from "./parser.ts";

const SCC_BY_FILE_ARGUMENTS = Object.freeze(["--no-config", "--by-file", "--format", "csv"]);
const SCC_SCAN_TIMEOUT_MS = 300_000;

interface ScanWithSccOptions {
  readonly cwd: string;
  readonly includePaths: readonly string[];
  readonly scanner: ResolvedFileMetricsScannerOptions;
}

export function scanWithScc({ cwd, includePaths, scanner }: ScanWithSccOptions): SccScanResult {
  try {
    if (includePaths.length === 0) return { ok: true, measurements: [] };

    const scanArguments = buildSccArgs(includePaths);

    const commandResult = runProcessSync({
      args: scanArguments,
      command: scanner.executable,
      cwd,
      timeout: SCC_SCAN_TIMEOUT_MS
    });

    if (commandResult.error) {
      return {
        ok: false,
        error: `scc process error: ${commandResult.error.message}`,
        reason: "execution"
      };
    }

    if (commandResult.status !== 0) {
      const stderr = (commandResult.stderr || "").trim();
      const stdout = (commandResult.stdout || "").trim();
      const termination =
        commandResult.status === null
          ? `signal ${commandResult.signal ?? "unknown"}`
          : `exit ${commandResult.status}`;
      return {
        ok: false,
        error: `scc ${termination}: ${stderr || stdout || "no output"}`,
        reason: "execution"
      };
    }

    return parseSccCSV(commandResult.stdout || "", cwd);
  } catch (error: unknown) {
    return {
      ok: false,
      error: `scc adapter error: ${errorMessage(error)}`,
      reason: "execution"
    };
  }
}

function buildSccArgs(includePaths: readonly string[]): string[] {
  return [...SCC_BY_FILE_ARGUMENTS, ...includePaths];
}

import {
  hasExactPlainRecordKeys,
  snapshotClosedArray,
  snapshotClosedRecord
} from "../data-boundary/closed-values.ts";
import type { FindingSummary } from "./code-quality-findings/policy.ts";

/** Parses the final-data shape shared by the three area-based quality Checks. */
export function parseFindingSummaryData(data: unknown, checkName: string): FindingSummary {
  const summary = exactFinalDataRecord(data, ["blockingFindingCount", "findingCount"], checkName);
  const blockingFindingCount = nonNegativeSafeInteger(summary.blockingFindingCount);
  const findingCount = nonNegativeSafeInteger(summary.findingCount);
  if (
    blockingFindingCount === undefined ||
    findingCount === undefined ||
    blockingFindingCount > findingCount
  ) {
    throw invalidFinalData(checkName);
  }
  return Object.freeze({ blockingFindingCount, findingCount });
}

/** Returns a detached exact record or rejects an unsupported final-data shape. */
export function exactFinalDataRecord(
  data: unknown,
  keys: readonly string[],
  checkName: string
): Readonly<Record<string, unknown>> {
  const record = snapshotClosedRecord(data);
  if (record === undefined || !hasExactPlainRecordKeys(record, keys)) {
    throw invalidFinalData(checkName);
  }
  return record;
}

/** Returns a detached closed array or rejects an unsupported final-data shape. */
export function finalDataArray(data: unknown, checkName: string): readonly unknown[] {
  const items = snapshotClosedArray(data);
  if (items === undefined) throw invalidFinalData(checkName);
  return items;
}

export function nonNegativeSafeInteger(value: unknown): number | undefined {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : undefined;
}

export function invalidFinalData(checkName: string): TypeError {
  return new TypeError(`${checkName} final data does not match the supported package contract`);
}

import type { FunctionMetric } from "./measurement-model.ts";
import { canonicalJsonBytes } from "../../data-boundary/canonical-data.ts";

export interface FunctionMetricInstance {
  readonly metric: FunctionMetric;
  readonly semanticSubject: string;
}

export interface FunctionMetricAnalysis {
  readonly instances: readonly FunctionMetricInstance[];
}

export function analyzeFunctionMetrics(
  metrics: readonly FunctionMetric[]
): FunctionMetricAnalysis | undefined {
  const metricsByIdentity = groupValidMetrics(metrics);
  if (metricsByIdentity === undefined) {
    return undefined;
  }
  const instances: FunctionMetricInstance[] = [];
  for (const group of metricsByIdentity.values()) {
    const sortedGroup = [...group].sort(compareFunctionInstances);
    instances.push(...createFunctionInstances(sortedGroup));
  }
  instances.sort((left, right) => compareText(left.semanticSubject, right.semanticSubject));
  return Object.freeze({ instances: Object.freeze(instances) });
}

function groupValidMetrics(
  metrics: readonly FunctionMetric[]
): Map<string, FunctionMetric[]> | undefined {
  const groups = new Map<string, FunctionMetric[]>();
  for (const metric of metrics) {
    if (!isValidFunctionMetric(metric)) {
      return undefined;
    }
    const key = functionIdentityKey(metric);
    const group = groups.get(key) ?? [];
    group.push(metric);
    groups.set(key, group);
  }
  return groups;
}

function createFunctionInstances(sortedGroup: readonly FunctionMetric[]): FunctionMetricInstance[] {
  return sortedGroup.map((metric, index) =>
    Object.freeze({
      metric,
      semanticSubject:
        isStableFunctionName(metric.name) && sortedGroup.length === 1
          ? functionSubject(metric)
          : ambiguousFunctionSubject(metric, index + 1)
    })
  );
}

function isValidFunctionMetric(metric: FunctionMetric): boolean {
  return (
    typeof metric.file === "string" &&
    metric.file.length > 0 &&
    typeof metric.name === "string" &&
    metric.name.length > 0 &&
    hasValidFunctionLocation(metric) &&
    hasValidFunctionMeasurements(metric)
  );
}

function hasValidFunctionLocation(metric: FunctionMetric): boolean {
  return (
    Number.isSafeInteger(metric.startLine) &&
    metric.startLine >= 1 &&
    Number.isSafeInteger(metric.endLine) &&
    metric.endLine >= metric.startLine
  );
}

function hasValidFunctionMeasurements(metric: FunctionMetric): boolean {
  const complexity = metric.cyclomaticComplexity.value;
  return (
    Number.isSafeInteger(metric.lines) &&
    metric.lines >= 0 &&
    Number.isSafeInteger(metric.parameterCount) &&
    metric.parameterCount >= 0 &&
    (complexity === null || isValidComplexity(complexity))
  );
}

function isValidComplexity(complexity: number): boolean {
  return Number.isSafeInteger(complexity) && complexity >= 0;
}

function functionSubject(metric: Pick<FunctionMetric, "file" | "name">): string {
  const identity = new TextDecoder().decode(
    canonicalJsonBytes({
      file: metric.file,
      name: metric.name
    })
  );
  return `function:${identity}`;
}

function ambiguousFunctionSubject(
  metric: Pick<FunctionMetric, "file" | "name">,
  occurrence: number
): string {
  const identity = new TextDecoder().decode(
    canonicalJsonBytes({
      file: metric.file,
      name: metric.name,
      occurrence
    })
  );
  return `function-instance:${identity}`;
}

function functionIdentityKey(metric: Pick<FunctionMetric, "file" | "name">): string {
  return `${metric.file}\u0000${metric.name}`;
}

function compareFunctionInstances(left: FunctionMetric, right: FunctionMetric): number {
  return (
    left.startLine - right.startLine ||
    left.endLine - right.endLine ||
    left.lines - right.lines ||
