      this.next(this._def_parameters);
    } else {
      this.subState(this.cloneState(), finishDefinition, token);
    }
  };

  /** Source `_def_class_method` seam used by Lua _defs. */
  protected readonly _def_class_method = (token: string): void => {
    this.context.addToFunctionName(token);
    this.next(this._def_continue);
  };

  /** Source `_def_parameters` seam used by Lua's `_anonymous_def` transition. */
  protected readonly _def_parameters = (token: string): void => {
    if (token === ")") {
      this.next(this._def_continue);
    } else {
      this.context.parameter(token);
      return;
    }
    this.context.addToLongFunctionName(` ${token}`);
  };

  private readonly _if = (token: string): void => {
    if (this.is_newline()) {
      this.next(this.globalState, token);
    } else if (token === "then") {
      this.next(this.globalState);
      this.subState(this.cloneState());
    }
  };

  private readonly _for_while = (token: string): void => {
    if (this.is_newline() || token === "do") {
      this.next(this.globalState);
      if (token !== "end") this.subState(this.cloneState());
    }
  };
}

/** Shared reader configuration for Ruby-like languages. */
export class RubylikeReader extends CodeReader {
  public static override controlFlowKeywords: ReadonlySet<string> = new Set([
    "if",
    "elsif",
    "elseif",
    "until",
    "for",
    "while",
    "rescue",
    "ensure",
    "when"
  ]);
  public static override logicalOperators: ReadonlySet<string> = new Set(["and", "or", "||", "&&"]);
  public static override caseKeywords: ReadonlySet<string> = new Set();
  public static override ternaryOperators: ReadonlySet<string> = new Set(["?"]);

  public constructor(context: FileInfoBuilder) {
    super(context);
    this.parallelStates = [new RubylikeStateMachine(context)];
  }

  public override get_comment_from_token(token: string): string | undefined {
    return ScriptLanguageMixIn.get_comment_from_token(token);
  }
}

function hasFunctionKeyword(value: object): value is { readonly FUNC_KEYWORD?: unknown } {
  return "FUNC_KEYWORD" in value;
}

/**
 * Derived from terryyin/lizard 1.24.0.
 * Source: lizard_languages/script_language.py.
 * Upstream revision: 308b1c3efd8c1c69bcc3eb82deeaec64fd3662ec.
 * SPDX-License-Identifier: MIT
 * Modified: translated to TypeScript while retaining the source mixin's
 * static comment and tokenizer members.
 */

import { CodeReader, type TokenFactory } from "./code-reader.ts";

/** Common comment extraction and tokenization used by script-language readers. */
export class ScriptLanguageMixIn {
  public static get_comment_from_token(token: string): string | undefined {
    if (!token.startsWith("#")) return undefined;

    const stripped = token.replace(/^#+/u, "").trim();
    if (
      stripped.startsWith("lizard forgive global") ||
      stripped.startsWith("#lizard forgive global")
    ) {
      return "#lizard forgive global";
    }
    if (stripped.startsWith("lizard forgive") || stripped.startsWith("#lizard forgive")) {
      return "#lizard forgive";
    }
    return stripped;
  }

  public static generate_common_tokens(
    sourceCode: string,
    addition: string,
    tokenFactory?: TokenFactory
  ): Generator<string> {
    return CodeReader.generateTokens(sourceCode, String.raw`|#[^\n]*${addition}`, tokenFactory);
  }

  /** TS-facing call sites share the source methods' implementations. */
  public static getCommentFromToken(token: string): string | undefined {
    return this.get_comment_from_token(token);
  }

  public static generateCommonTokens(
    sourceCode: string,
    addition: string,
    tokenFactory?: TokenFactory
  ): Generator<string> {
    return this.generate_common_tokens(sourceCode, addition, tokenFactory);
  }
}

import { defineCheck, type TypedCheckWithOptions } from "../../check/check.ts";
import { executeFunctionMetrics } from "./execution.ts";
import { parseFunctionMetricsData } from "./final-data.ts";
import type { FunctionMetricsOptions, ResolvedFunctionMetricsOptions } from "./options.ts";
import { resolveFunctionMetricsOptions } from "./options-resolution.ts";
import { validResolvedFunctionMetricsOptions } from "./options-validation.ts";

const FUNCTION_METRICS_CHECK_DEFINITION = {
  checkId: "function-metrics",
  displayName: "Function metrics"
} as const;

/**
 * 使用可省略的区域、阈值与 finding policy 构造一个完整 function-metrics Check。
 *
 * @param options - 省略字段由 package 补齐；显式 files 数组完整替换对应字段的默认数组。
 * @returns 固定 `function-metrics` identity、完整冻结 options、preflight 与 execution。
 * @throws {TypeError} input 含未知字段、空 area、非法 finding policy/waiver 或非法 limit 时抛出。
 */
export function functionMetrics(
  options: FunctionMetricsOptions = {}
): TypedCheckWithOptions<
  "function-metrics",
  ResolvedFunctionMetricsOptions,
  typeof parseFunctionMetricsData
> {
  const resolvedOptions = resolveFunctionMetricsOptions(options);
  if (resolvedOptions === undefined) {
    throw new TypeError(
      "functionMetrics options must use the documented closed policy: a non-empty area map, recognized finding policies and waivers, and positive safe-integer limits"
    );
  }
  return defineCheck({
    ...FUNCTION_METRICS_CHECK_DEFINITION,
    execution: executeFunctionMetrics,
    parseData: parseFunctionMetricsData,
    preflight: (preparedOptions) =>
      validResolvedFunctionMetricsOptions(preparedOptions)
        ? { status: "success", preparedOptions }
        : {
            status: "failure",
            action: "block",
            reason: { code: "invalid-options" },
            messages: [
              {
                code: "invalid-options",
                level: "error",
                message:
                  "functionMetrics options are invalid; recreate the Check with functionMetrics(options) or restore its complete resolved options."
              }
            ]
          },
    options: resolvedOptions
  });
}

import type { CheckExecutionContext, CheckMessage, CheckResult } from "../../check/check.ts";
import {
  reconcileFindingWaivers,
  type FindingWaiverReconciliation
} from "../../finding-waivers/reconciliation.ts";
import { collectProjectFileSets, requireProjectFileSet } from "../project-files/collection.ts";
import { partitionProjectFilesByEligibility } from "../project-files/input-eligibility.ts";
import { settleFindings } from "../code-quality-findings/policy.ts";
import {
  reportFindingWaiverAudits,
  reportReconciledCodeQualityFindingRecords
} from "../code-quality-findings/finding-waiver-evidence.ts";
import { appendCheckMessages } from "../../check/finding-presentation.ts";
import { functionFindingMessages, functionWaiverMessages } from "./finding-messages.ts";
import { analyzeFunctionMetrics } from "./analysis.ts";
import { measureFunctionMetrics, type FunctionMeasurementResult } from "./measurement.ts";
import type {
  FunctionMetricsAreaInput,
  FunctionMetricsExactInputSet
} from "./measurement-model.ts";
import type {
  FunctionMetricsFindingWaiver,
  ResolvedFunctionMetricsCodeAreaOptions,
  ResolvedFunctionMetricsOptions
} from "./options.ts";
import { validResolvedFunctionMetricsOptions } from "./options-validation.ts";
import {
  buildFunctionInputRejectedCandidates,
  buildFunctionRecordCandidates,
  functionMetricsFindingIdentity,
  functionMetricsWaiverAuditRecord,
  type FunctionInputRejectedCandidate,
  type FunctionRecordCandidate
} from "./records.ts";
import { isFunctionMetricsTarget } from "./target-files.ts";
import type { FunctionMetricsFinalData } from "./final-data.ts";

/** `function-metrics` whole-Check unavailable outcome 的稳定 reason code。 */
export type FunctionMetricsUnavailableReasonCode =
  | "analysis-failed"
  | "cancelled"
  | "invalid-options"
  | "resource-limit-exceeded"
  | "source-unavailable";

/** Default Check callback；一次扫描完整 area exact-input union。 */
export async function executeFunctionMetrics(
  context: CheckExecutionContext<ResolvedFunctionMetricsOptions>
): Promise<CheckResult<FunctionMetricsFinalData>> {
  if (!validResolvedFunctionMetricsOptions(context.options)) return unavailable("invalid-options");
  if (context.signal.aborted) return unavailable("cancelled");

  let prepared: PreparedFunctionInputs;
  try {
    prepared = prepareFunctionInputs(context.project.root, context.options.codeAreas);
  } catch {
    return unavailable("source-unavailable");
  }
  if (context.signal.aborted) return unavailable("cancelled");
  return executePreparedFunctionMetrics(context, prepared);
}

async function executePreparedFunctionMetrics(
  context: CheckExecutionContext<ResolvedFunctionMetricsOptions>,
  prepared: PreparedFunctionInputs
): Promise<CheckResult<FunctionMetricsFinalData>> {
  if (prepared.selectedPathCount === 0) {
    return noEligibleFunctionInputResult(context);
  }
  reportInputRejections(context, prepared.rejectedCandidates);
  if (prepared.exactInput.approvedExactPaths.length === 0) {
    const reconciliation = reconcileFunctionMetricWaivers([], context.options.findingWaivers);
    reportFindingWaiverAudits(context, reconciliation, functionMetricsWaiverAuditRecord);
    return settleFunctionFindings(reconciliation, prepared.rejectedCandidates);
  }
  const measurement = await measureFunctionMetrics({
    input: prepared.exactInput,
    signal: context.signal
  });
  if (measurement.kind !== "complete") {
    return appendInputRejectedMessage(
      directMeasurementFailure(measurement),
      prepared.rejectedCandidates.length
    );
  }
  const analysis = analyzeFunctionMetrics(measurement.metrics);
  if (analysis === undefined) {
    return appendInputRejectedMessage(
      unavailable("analysis-failed"),
      prepared.rejectedCandidates.length
    );
  }
  const candidates = buildFunctionRecordCandidates(analysis, prepared.exactInput.areas);
  if (candidates === undefined) {
    return appendInputRejectedMessage(
      unavailable("analysis-failed"),
      prepared.rejectedCandidates.length
    );
  }
  const reconciliation = reconcileFunctionMetricWaivers(candidates, context.options.findingWaivers);
  reportReconciledCodeQualityFindingRecords(context, reconciliation);
  reportFindingWaiverAudits(context, reconciliation, functionMetricsWaiverAuditRecord);
  return settleFunctionFindings(reconciliation, prepared.rejectedCandidates);
}

function noEligibleFunctionInputResult(
  context: CheckExecutionContext<ResolvedFunctionMetricsOptions>
): CheckResult<FunctionMetricsFinalData> {
  const reconciliation = reconcileFunctionMetricWaivers([], context.options.findingWaivers);
  reportFindingWaiverAudits(context, reconciliation, functionMetricsWaiverAuditRecord);
  return appendCheckMessages(
    Object.freeze({ status: "not-applicable", reason: { code: "no-eligible-input" } }),
    functionWaiverMessages(reconciliation)
  );
}

function reconcileFunctionMetricWaivers(
  candidates: readonly FunctionRecordCandidate[],
  waivers: readonly FunctionMetricsFindingWaiver[]
): FindingWaiverReconciliation<FunctionRecordCandidate> {
  return reconcileFindingWaivers({
    findings: candidates,
    identify: functionMetricsFindingIdentity,
    waivers
  });
}

interface PreparedFunctionInputs {
  readonly exactInput: FunctionMetricsExactInputSet;
  readonly rejectedCandidates: readonly FunctionInputRejectedCandidate[];
  readonly selectedPathCount: number;
}

function prepareFunctionInputs(
  rootDir: string,
  codeAreas: ResolvedFunctionMetricsOptions["codeAreas"]
): PreparedFunctionInputs {
  const collected = collectAreaInputs(rootDir, codeAreas);
  return Object.freeze({
    exactInput: Object.freeze({
      approvedExactPaths: Object.freeze(
        uniqueSorted(collected.areas.flatMap((area) => area.approvedExactPaths))
      ),
      areas: collected.areas,
      rootDir
    }),
    rejectedCandidates: buildFunctionInputRejectedCandidates(
      new Map(
        [...collected.rejectedCodeAreasByPath].map(([path, matchingAreas]) => [
          path,
          Object.freeze(matchingAreas)
        ])
      )
    ),
    selectedPathCount: collected.selectedPaths.size
  });
}

interface CollectedFunctionAreaInputs {
  readonly areas: readonly FunctionMetricsAreaInput[];
  readonly rejectedCodeAreasByPath: ReadonlyMap<string, readonly string[]>;
  readonly selectedPaths: ReadonlySet<string>;
}

function collectAreaInputs(
  rootDir: string,
  codeAreas: Readonly<Record<string, ResolvedFunctionMetricsCodeAreaOptions>>
): CollectedFunctionAreaInputs {
  const areas: FunctionMetricsAreaInput[] = [];
  const rejectedCodeAreasByPath = new Map<string, string[]>();
  const selectedPaths = new Set<string>();
  const orderedPolicies = Object.entries(codeAreas).sort(([left], [right]) =>
    compareText(left, right)
  );
  const filesByArea = collectProjectFileSets(
    rootDir,
    Object.fromEntries(orderedPolicies.map(([areaId, policy]) => [areaId, policy.files]))
  );
  for (const [codeArea, policy] of orderedPolicies) {
    const selectedForArea = requireProjectFileSet(filesByArea, codeArea);
    for (const path of selectedForArea) selectedPaths.add(path);
    const partition = partitionProjectFilesByEligibility(selectedForArea, isFunctionMetricsTarget);
    for (const path of partition.rejectedPaths) {
      const matchingAreas = rejectedCodeAreasByPath.get(path) ?? [];
      matchingAreas.push(codeArea);
      rejectedCodeAreasByPath.set(path, matchingAreas);
    }
    if (partition.acceptedPaths.length === 0) continue;
    areas.push(
      Object.freeze({
        approvedExactPaths: partition.acceptedPaths,
        codeArea,
        findingPolicy: policy.findingPolicy,
        limits: policy.limits
      })
    );
  }
  return Object.freeze({
    areas: Object.freeze(areas),
    rejectedCodeAreasByPath,
    selectedPaths
  });
}

function reportInputRejections(
  context: CheckExecutionContext<ResolvedFunctionMetricsOptions>,
  candidates: readonly FunctionInputRejectedCandidate[]
): void {
  for (const candidate of candidates) {
    context.records.report({ id: candidate.id }, candidate.data);
  }
}

function settleFunctionFindings(
  reconciliation: FindingWaiverReconciliation<FunctionRecordCandidate>,
  rejectedCandidates: readonly FunctionInputRejectedCandidate[]
): CheckResult<FunctionMetricsFinalData> {
  const settlement = settleFindings([
    ...reconciliation.findings.map((finding) => ({
      actionable: finding.disposition !== "waived",
      blocking: finding.finding.data.blocking
    })),
    ...rejectedCandidates.map(() => ({ actionable: false, blocking: false }))
  ]);
  const actionableMetricCandidates = reconciliation.findings
    .filter(({ disposition }) => disposition !== "waived")
    .map(({ finding }) => finding);
  return appendCheckMessages(
    appendCheckMessages(
      appendInputRejectedMessage(settlement, rejectedCandidates.length),
      functionFindingMessages([...actionableMetricCandidates, ...rejectedCandidates])
    ),
    functionWaiverMessages(reconciliation)
  );
}

function appendInputRejectedMessage(
  result: CheckResult<FunctionMetricsFinalData>,
  rejectedInputCount: number
): CheckResult<FunctionMetricsFinalData> {
  if (rejectedInputCount === 0) return result;
  const message: CheckMessage = Object.freeze({
    code: "input-rejected",
    level: "warning",
    message: `${rejectedInputCount} selected functionMetrics input file(s) were rejected because their file type is unsupported; inspect this Check's Records and narrow files.include/exclude.`
  });
  return Object.freeze({
    ...result,
    messages: Object.freeze([...(result.messages ?? []), message])
  });
}

function directMeasurementFailure(
  measurement: Exclude<FunctionMeasurementResult, { kind: "complete" }>
): CheckResult<FunctionMetricsFinalData> {
  switch (measurement.kind) {
    case "cancelled":
      return unavailable("cancelled");
    case "analysis-failed":
      return unavailable("analysis-failed");
    case "resource-limit-exceeded":
      return unavailable("resource-limit-exceeded");
    case "source-unavailable":
      return unavailable("source-unavailable");
  }
  const exhaustiveMeasurement: never = measurement;
  return exhaustiveMeasurement;
}

function unavailable(
  code: FunctionMetricsUnavailableReasonCode
): CheckResult<FunctionMetricsFinalData> {
  return Object.freeze({
    status: "unavailable",
    reason: { code },
    messages: Object.freeze([
      Object.freeze({ code, level: "error" as const, message: unavailableMessage(code) })
    ])
  });
}

function unavailableMessage(code: FunctionMetricsUnavailableReasonCode): string {
  switch (code) {
    case "invalid-options":
      return "functionMetrics options are invalid; recreate the Check with functionMetrics(options) or restore its complete resolved options.";
    case "cancelled":
      return "Function metrics was cancelled before it could form a complete result; inspect the caller's cancellation reason and retry if appropriate.";
    case "source-unavailable":
      return "Function metrics could not collect its configured project files; check the project root, file permissions, and selected file source.";
    case "analysis-failed":
      return "Function metrics analysis did not produce a complete trusted result; inspect the selected source and retry after correcting it.";
    case "resource-limit-exceeded":
      return "Function metrics input exceeds the per-file or aggregate analysis resource limit; narrow the selected files or reduce their size.";
  }
}

function uniqueSorted(values: readonly string[]): string[] {
  return [...new Set(values)].sort(compareText);
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import type { FindingSummary } from "../code-quality-findings/policy.ts";
import { parseFindingSummaryData } from "../final-data-parsing.ts";

/** `function-metrics` 在 passed/failed outcome 中发布的主数据。 */
export type FunctionMetricsFinalData = FindingSummary;

/** 验证并脱离一份 `function-metrics` canonical final-data object。 */
export function parseFunctionMetricsData(data: unknown): FunctionMetricsFinalData {
  return parseFindingSummaryData(data, "functionMetrics");
}

import type { CheckMessage } from "../../check/check.ts";
import { presentCheckFindings } from "../../check/finding-presentation.ts";
import type {
  FindingWaiverAudit,
  FindingWaiverReconciliation
} from "../../finding-waivers/reconciliation.ts";
import {
  functionMetricsWaiverIdentity,
  type FunctionInputRejectedCandidate,
  type FunctionRecordCandidate
} from "./records.ts";

const PRESENTED_FINDING_LIMIT = 10;

type FunctionFindingCandidate = FunctionRecordCandidate | FunctionInputRejectedCandidate;

/** Projects metric and rejected-input Records into bounded terminal summaries. */
export function functionFindingMessages(
  findings: readonly FunctionFindingCandidate[]
): readonly CheckMessage[] {
  return presentCheckFindings({
    findings,
    limit: PRESENTED_FINDING_LIMIT,
    message: ({ data }) => {
      if ("kind" in data) {
        return Object.freeze({
          code: "finding-detail",
          level: "warning" as const,
          message: `${data.path}: selected input is not supported by function metrics (areas: ${data.codeAreas.join(", ")}).`
        });
      }
      return Object.freeze({
        code: "finding-detail",
        level: data.blocking ? ("error" as const) : ("warning" as const),
        message: `${data.path}:${data.startLine} ${data.functionName}: ${data.metric} ${data.value} exceeds the ${data.limit} limit (areas: ${data.codeAreas.join(", ")}).`
      });
    },
    omittedMessage: ({ omittedCount, omittedFindings }) =>
      Object.freeze({
        code: "findings-omitted",
        level: omittedFindings.some(({ data }) => !("kind" in data) && data.blocking)
          ? ("error" as const)
          : ("warning" as const),
        message: `${omittedCount} additional function metric finding(s) were not shown; inspect this Check's Records for the complete set.`
      })
  });
}

/** 将每项 function-metrics waiver audit 投影为可行动的 terminal message。 */
export function functionWaiverMessages(
  reconciliation: FindingWaiverReconciliation<FunctionRecordCandidate>
): readonly CheckMessage[] {
  return Object.freeze(reconciliation.waiverAudits.map(functionWaiverMessage));
}

function functionWaiverMessage(audit: FindingWaiverAudit): CheckMessage {
  const identity = functionMetricsWaiverIdentity(audit.waiver);
  const subject = `${identity.path}:${identity.startLine} ${identity.functionName} ${identity.metric}`;
  switch (audit.status) {
    case "applied":
      return Object.freeze({
        code: "finding-waived",
        level: "info",
        message: `Function metric finding for ${subject} was waived: ${audit.waiver.reason}`
      });
    case "unused":
      return Object.freeze({
        code: "unused-finding-waiver",
        level: "warning",
        message: `Configured function-metrics finding waiver for ${subject} matched no finding; remove it or update its identity. Reason: ${audit.waiver.reason}`
      });
    case "overmatched":
      return Object.freeze({
        code: "overmatched-finding-waiver",
        level: "warning",
        message: `Configured function-metrics finding waiver for ${subject} matched ${audit.matchCount} findings and was not applied; narrow its identity. Reason: ${audit.waiver.reason}`
      });
  }
}

import { snapshotClosedPolicyRecord } from "../../data-boundary/closed-values.ts";
import { isNonEmptyString, isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import { isNormalizedProjectRelativePath } from "../host-environment/path.ts";
import type { FunctionMetricsFindingIdentity, FunctionMetricsFindingMetric } from "./options.ts";

export function resolveFunctionMetricsFindingIdentity(
  value: unknown
): FunctionMetricsFindingIdentity | undefined {
  const identity = snapshotClosedPolicyRecord(value, {
    required: ["functionName", "metric", "path", "startLine"]
  });
  if (
    identity === undefined ||
    !isNonEmptyString(identity.functionName) ||
    !isFunctionMetricsFindingMetric(identity.metric) ||
    !isNormalizedProjectRelativePath(identity.path) ||
    !isPositiveSafeInteger(identity.startLine)
  ) {
    return undefined;
  }
  return Object.freeze({
    functionName: identity.functionName,
    metric: identity.metric,
    path: identity.path,
    startLine: identity.startLine
  });
}

function isFunctionMetricsFindingMetric(value: unknown): value is FunctionMetricsFindingMetric {
  return (
    value === "cyclomatic-complexity" ||
    value === "function-code-density" ||
    value === "parameter-count"
  );
}

import type { FindingPolicy } from "../code-quality-findings/policy.ts";
import type { ResolvedFunctionMetricsLimits } from "./options.ts";

export interface MetricValue {
  readonly source: "typescript-analyzer";
  readonly value: number | null;
}

export interface FunctionMetric {
  readonly cyclomaticComplexity: MetricValue;
  readonly endLine: number;
  readonly file: string;
  readonly lines: number;
  readonly name: string;
  readonly parameterCount: number;
  readonly startLine: number;
}

export interface FunctionMetricsAreaInput {
  readonly approvedExactPaths: readonly string[];
  readonly codeArea: string;
  readonly findingPolicy: FindingPolicy;
  readonly limits: ResolvedFunctionMetricsLimits;
}

export interface FunctionMetricsExactInputSet {
  readonly approvedExactPaths: readonly string[];
  readonly areas: readonly FunctionMetricsAreaInput[];
  readonly rootDir: string;
}

import { closeSync, openSync, readSync } from "node:fs";
import { resolve } from "node:path";

import type {
  FunctionMetricsAnalysisWorkerRequest,
  FunctionMetricsAnalysisWorkerResponse
} from "./analyzer-worker-contract.ts";
import type { FunctionMetric, FunctionMetricsExactInputSet } from "./measurement-model.ts";

const MAXIMUM_FILE_BYTES = 8 * 1024 * 1024;
const MAXIMUM_AGGREGATE_BYTES = 64 * 1024 * 1024;
const READ_CHUNK_BYTES = 32 * 1024;

export type FunctionMeasurementResult = Readonly<
  | { kind: "analysis-failed" }
  | { kind: "cancelled" }
  | { kind: "complete"; metrics: readonly FunctionMetric[] }
  | { kind: "resource-limit-exceeded" }
  | { kind: "source-unavailable" }
>;

interface FunctionMeasurementInput {
  readonly input: FunctionMetricsExactInputSet;
  readonly signal: AbortSignal;
}

/**
 * The Check parent admits exactly its selected sources and bounds their bytes;
 * one Worker only analyzes those source texts and never discovers or reads paths.
 */
export async function measureFunctionMetrics({
  input,
  signal
}: FunctionMeasurementInput): Promise<FunctionMeasurementResult> {
  const admitted = await readExactFunctionSources(input, signal);
  if (admitted.kind !== "complete") return admitted;
  if (signal.aborted) return Object.freeze({ kind: "cancelled" });
  return analyzeAdmittedSources(admitted.request, input.approvedExactPaths, signal);
}

async function readExactFunctionSources(
  input: FunctionMetricsExactInputSet,
  signal: AbortSignal
): Promise<
  | Readonly<{ readonly kind: "cancelled" }>
  | Readonly<{ readonly kind: "complete"; readonly request: FunctionMetricsAnalysisWorkerRequest }>
  | Readonly<{ readonly kind: "resource-limit-exceeded" }>
  | Readonly<{ readonly kind: "source-unavailable" }>
> {
  let aggregateBytes = 0;
  const files: FunctionMetricsAnalysisWorkerRequest["files"][number][] = [];
  for (const path of input.approvedExactPaths) {
    if (signal.aborted) return Object.freeze({ kind: "cancelled" });
    const source = await readBoundedSource(resolve(input.rootDir, path), aggregateBytes, signal);
    if (source.kind !== "complete") return source;
    aggregateBytes += source.byteLength;
    files.push(Object.freeze({ path, source: source.source }));
  }
  return Object.freeze({
    kind: "complete",
    request: Object.freeze({ files: Object.freeze(files) })
  });
}

async function readBoundedSource(
  absolutePath: string,
  aggregateBytes: number,
  signal: AbortSignal
): Promise<
  | Readonly<{ readonly kind: "cancelled" }>
  | Readonly<{ readonly kind: "complete"; readonly byteLength: number; readonly source: string }>
  | Readonly<{ readonly kind: "resource-limit-exceeded" }>
  | Readonly<{ readonly kind: "source-unavailable" }>
> {
  let descriptor: number;
  try {
    descriptor = openSync(absolutePath, "r");
  } catch {
    return Object.freeze({ kind: "source-unavailable" });
  }
  try {
    const chunks: Buffer[] = [];
    const chunk = Buffer.allocUnsafe(READ_CHUNK_BYTES);
    let fileBytes = 0;
    while (true) {
      if (signal.aborted) return Object.freeze({ kind: "cancelled" });
      const bytesRead = readSync(descriptor, chunk, 0, chunk.length, null);
      if (bytesRead === 0) break;
      fileBytes += bytesRead;
      if (fileBytes > MAXIMUM_FILE_BYTES || aggregateBytes + fileBytes > MAXIMUM_AGGREGATE_BYTES) {
        return Object.freeze({ kind: "resource-limit-exceeded" });
      }
      chunks.push(Buffer.from(chunk.subarray(0, bytesRead)));
      if (signal.aborted) return Object.freeze({ kind: "cancelled" });
      await new Promise<void>((resolveYield) => setTimeout(resolveYield, 0));
    }
    return Object.freeze({
      kind: "complete",
      byteLength: fileBytes,
      source: decodeLizardAutoRead(Buffer.concat(chunks, fileBytes))
    });
  } catch {
    return Object.freeze({ kind: "source-unavailable" });
  } finally {
    closeSync(descriptor);
  }
}

/**
 * Product-owned replacement for Lizard 1.24 `auto_open.auto_read` at the
 * admitted-source boundary. A valid initial UTF-8 BOM is `utf-8-sig` and text
 * newlines are universal; a decoding failure retries the complete byte sequence
 * with Python's `errors="ignore"`, which deliberately retains an initial BOM
 * and raw newlines on that retry.
 */
export function decodeLizardAutoRead(bytes: Uint8Array): string {
  try {
    return new TextDecoder("utf-8", { fatal: true }).decode(bytes).replace(/\r\n?/gu, "\n");
  } catch {
    return decodeUtf8IgnoringInvalidBytes(bytes);
  }
}

function decodeUtf8IgnoringInvalidBytes(bytes: Uint8Array): string {
  let decoded = "";
  for (let index = 0; index < bytes.length;) {
    const first = bytes[index];
    if (first <= 0x7f) {
      decoded += String.fromCodePoint(first);
      index += 1;
      continue;
    }
    const second = bytes[index + 1];
    const third = bytes[index + 2];
    const fourth = bytes[index + 3];
    if (first >= 0xc2 && first <= 0xdf && isUtf8Continuation(second)) {
      decoded += String.fromCodePoint(((first & 0x1f) << 6) | (second & 0x3f));
      index += 2;
      continue;
    }
    if (
      first >= 0xe0 &&
      first <= 0xef &&
      isUtf8SecondByteForThreeByteSequence(first, second) &&
      isUtf8Continuation(third)
    ) {
      decoded += String.fromCodePoint(
        ((first & 0x0f) << 12) | ((second & 0x3f) << 6) | (third & 0x3f)
      );
      index += 3;
      continue;
    }
    if (
      first >= 0xf0 &&
      first <= 0xf4 &&
      isUtf8SecondByteForFourByteSequence(first, second) &&
      isUtf8Continuation(third) &&
      isUtf8Continuation(fourth)
    ) {
      decoded += String.fromCodePoint(
        ((first & 0x07) << 18) | ((second & 0x3f) << 12) | ((third & 0x3f) << 6) | (fourth & 0x3f)
      );
      index += 4;
      continue;
    }
    index += 1;
  }
  return decoded;
}

function isUtf8Continuation(value: number | undefined): value is number {
  return value !== undefined && value >= 0x80 && value <= 0xbf;
}

function isUtf8SecondByteForThreeByteSequence(
  first: number,
  second: number | undefined
): second is number {
  return (
    isUtf8Continuation(second) &&
    !(first === 0xe0 && second < 0xa0) &&
    !(first === 0xed && second > 0x9f)
  );
}

function isUtf8SecondByteForFourByteSequence(
  first: number,
  second: number | undefined
): second is number {
  return (
    isUtf8Continuation(second) &&
    !(first === 0xf0 && second < 0x90) &&
    !(first === 0xf4 && second > 0x8f)
  );
}

async function analyzeAdmittedSources(
  request: FunctionMetricsAnalysisWorkerRequest,
  approvedExactPaths: readonly string[],
  signal: AbortSignal
): Promise<FunctionMeasurementResult> {
  let worker: Worker;
  try {
    worker = new Worker(new URL("./analyzer-worker.ts", import.meta.url).href);
  } catch {
    return Object.freeze({ kind: "analysis-failed" });
  }
  return new Promise((resolveResult) => {
    let settled = false;
    const finish = (result: FunctionMeasurementResult): void => {
      if (settled) return;
      settled = true;
      signal.removeEventListener("abort", cancelled);
      worker.terminate();
      resolveResult(result);
    };
    const cancelled = (): void => finish(Object.freeze({ kind: "cancelled" }));
    worker.onmessage = (event: MessageEvent<unknown>): void => {
      if (signal.aborted) return cancelled();
      const response = parseWorkerResponse(event.data, approvedExactPaths);
      finish(response);
    };
    worker.onerror = (): void => finish(Object.freeze({ kind: "analysis-failed" }));
    signal.addEventListener("abort", cancelled, { once: true });
    if (signal.aborted) return cancelled();
    try {
      worker.postMessage(request);
    } catch {
      finish(Object.freeze({ kind: "analysis-failed" }));
    }
  });
}

function parseWorkerResponse(
  value: unknown,
  approvedExactPaths: readonly string[]
): FunctionMeasurementResult {
  if (!isWorkerResponse(value)) return Object.freeze({ kind: "analysis-failed" });
  if (value.kind === "analysis-failed") return value;
  const approvedPaths = new Set(approvedExactPaths);
  return value.metrics.every((metric) => approvedPaths.has(metric.file))
    ? Object.freeze({ kind: "complete", metrics: value.metrics })
    : Object.freeze({ kind: "analysis-failed" });
}

function isWorkerResponse(value: unknown): value is FunctionMetricsAnalysisWorkerResponse {
  return (
    typeof value === "object" &&
    value !== null &&
    "kind" in value &&
    (value.kind === "analysis-failed" ||
      (value.kind === "complete" &&
        "metrics" in value &&
        Array.isArray(value.metrics) &&
        value.metrics.every(isFunctionMetric)))
  );
}

function isFunctionMetric(value: unknown): value is FunctionMetric {
  return (
    typeof value === "object" &&
    value !== null &&
    "file" in value &&
    typeof value.file === "string" &&
    "name" in value &&
    typeof value.name === "string" &&
    "startLine" in value &&
    Number.isSafeInteger(value.startLine) &&
    "endLine" in value &&
    Number.isSafeInteger(value.endLine) &&
    "lines" in value &&
    Number.isSafeInteger(value.lines) &&
    "parameterCount" in value &&
    Number.isSafeInteger(value.parameterCount) &&
    "cyclomaticComplexity" in value &&
    typeof value.cyclomaticComplexity === "object" &&
    value.cyclomaticComplexity !== null &&
    "source" in value.cyclomaticComplexity &&
    value.cyclomaticComplexity.source === "typescript-analyzer" &&
    "value" in value.cyclomaticComplexity &&
    (value.cyclomaticComplexity.value === null ||
      (typeof value.cyclomaticComplexity.value === "number" &&
        Number.isSafeInteger(value.cyclomaticComplexity.value)))
  );
}

import { snapshotClosedPolicyRecord } from "../../data-boundary/closed-values.ts";
import { isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import {
  defaultProjectFileSelection,
  resolveProjectFileSelection,
  snapshotProjectFileSelection
} from "../project-files/configuration.ts";
import {
  DEFAULT_FINDING_POLICY,
  resolveCodeAreaPolicyMap,
  resolveFindingPolicy,
  type FindingPolicy
} from "../code-quality-findings/policy.ts";
import { resolveFindingWaiverAuthoring } from "../code-quality-findings/finding-waiver-authoring.ts";
import { resolveFunctionMetricsFindingIdentity } from "./finding-waiver-identity.ts";
import {
  type ResolvedFunctionMetricsCodeAreaOptions,
  type ResolvedFunctionMetricsLimits,
  type ResolvedFunctionMetricsOptions
} from "./options.ts";
import { validResolvedFunctionMetricsOptions } from "./options-validation.ts";
import { FUNCTION_METRICS_SUPPORTED_FILE_GLOBS } from "./target-files.ts";

const DEFAULT_CODE_LINE_MAXIMUM = 60;
const DEFAULT_LOW_COMPLEXITY_CODE_LINE_MAXIMUM = 180;
const DEFAULT_LOW_COMPLEXITY_BELOW = 6;
const DEFAULT_CYCLOMATIC_COMPLEXITY_MAXIMUM = 12;
const DEFAULT_PARAMETER_MAXIMUM = 6;
const DEFAULT_FILES = Object.freeze({
  exclude: defaultProjectFileSelection.exclude,
  include: FUNCTION_METRICS_SUPPORTED_FILE_GLOBS,
  source: defaultProjectFileSelection.source
});

/** 校验 constructor input，并物化完整、冻结的 function-metrics options。 */
export function resolveFunctionMetricsOptions(
  value: unknown
): ResolvedFunctionMetricsOptions | undefined {
  const input = snapshotClosedPolicyRecord(value, {
    optional: ["codeAreas", "findingPolicy", "findingWaivers"]
  });
  if (input === undefined) return undefined;

  const findingPolicy = resolveFindingPolicy(input.findingPolicy, DEFAULT_FINDING_POLICY);
  if (findingPolicy === undefined) return undefined;
  const codeAreas = resolveCodeAreas(input.codeAreas, findingPolicy);
  const findingWaivers = resolveFindingWaiverAuthoring(
    input.findingWaivers,
    resolveFunctionMetricsFindingIdentity
  );
  if (codeAreas === undefined || findingWaivers === undefined) return undefined;

  const options = Object.freeze({ codeAreas, findingWaivers });
  return validResolvedFunctionMetricsOptions(options) ? options : undefined;
}

function resolveCodeAreas(
  value: unknown,
  defaultFindingPolicy: FindingPolicy
): ResolvedFunctionMetricsOptions["codeAreas"] | undefined {
  return resolveCodeAreaPolicyMap(
    value,
    () => defaultCodeArea(defaultFindingPolicy),
    (candidate) => resolveCodeArea(candidate, defaultFindingPolicy)
  );
}

function defaultCodeArea(findingPolicy: FindingPolicy): ResolvedFunctionMetricsCodeAreaOptions {
  return Object.freeze({
    files: snapshotProjectFileSelection(DEFAULT_FILES),
    findingPolicy,
    limits: defaultLimits()
  });
}

function resolveCodeArea(
  value: unknown,
  defaultFindingPolicy: FindingPolicy
): ResolvedFunctionMetricsCodeAreaOptions | undefined {
  const area = snapshotClosedPolicyRecord(value, {
    optional: ["findingPolicy", "limits"],
    required: ["files"]
  });
  if (area === undefined) return undefined;
  const files = resolveProjectFileSelection(area.files, DEFAULT_FILES);
  const findingPolicy = resolveFindingPolicy(area.findingPolicy, defaultFindingPolicy);
  const limits = resolveLimits(area.limits);
  return files === undefined || findingPolicy === undefined || limits === undefined
    ? undefined
    : Object.freeze({ files, findingPolicy, limits });
}

function resolveLimits(value: unknown): ResolvedFunctionMetricsLimits | undefined {
  if (value === undefined) return defaultLimits();
  const limits = snapshotClosedPolicyRecord(value, {
    optional: ["codeLines", "cyclomaticComplexity", "parameters"]
  });
  if (limits === undefined) return undefined;
  const codeLines = resolveCodeLineLimits(limits.codeLines);
  const cyclomaticComplexity = resolveMaximum(
    limits.cyclomaticComplexity,
    DEFAULT_CYCLOMATIC_COMPLEXITY_MAXIMUM
  );
  const parameters = resolveMaximum(limits.parameters, DEFAULT_PARAMETER_MAXIMUM);
  if (codeLines === undefined || cyclomaticComplexity === undefined || parameters === undefined) {
    return undefined;
  }
  return Object.freeze({ codeLines, cyclomaticComplexity, parameters });
}

function resolveCodeLineLimits(
  value: unknown
): ResolvedFunctionMetricsLimits["codeLines"] | undefined {
  if (value === undefined) return defaultLimits().codeLines;
  const codeLines = snapshotClosedPolicyRecord(value, {
    optional: ["lowComplexityAllowance", "maximum"]
  });
  if (codeLines === undefined) return undefined;
  const maximum = codeLines.maximum ?? DEFAULT_CODE_LINE_MAXIMUM;
  const allowance = resolveLowComplexityAllowance(codeLines.lowComplexityAllowance);
  if (!isPositiveSafeInteger(maximum) || allowance === undefined || allowance.maximum < maximum) {
    return undefined;
  }
  return Object.freeze({ lowComplexityAllowance: allowance, maximum });
}

function resolveLowComplexityAllowance(
  value: unknown
): ResolvedFunctionMetricsLimits["codeLines"]["lowComplexityAllowance"] | undefined {
  if (value === undefined) {
    return Object.freeze({
      cyclomaticComplexityBelow: DEFAULT_LOW_COMPLEXITY_BELOW,
      maximum: DEFAULT_LOW_COMPLEXITY_CODE_LINE_MAXIMUM
    });
  }
  const allowance = snapshotClosedPolicyRecord(value, {
    optional: ["cyclomaticComplexityBelow", "maximum"]
  });
  if (allowance === undefined) return undefined;
  const cyclomaticComplexityBelow =
    allowance.cyclomaticComplexityBelow ?? DEFAULT_LOW_COMPLEXITY_BELOW;
  const maximum = allowance.maximum ?? DEFAULT_LOW_COMPLEXITY_CODE_LINE_MAXIMUM;
  return isPositiveSafeInteger(cyclomaticComplexityBelow) && isPositiveSafeInteger(maximum)
    ? Object.freeze({ cyclomaticComplexityBelow, maximum })
    : undefined;
}

function resolveMaximum(
  value: unknown,
  fallback: number
): Readonly<{ readonly maximum: number }> | undefined {
  if (value === undefined) return Object.freeze({ maximum: fallback });
  const input = snapshotClosedPolicyRecord(value, { optional: ["maximum"] });
  if (input === undefined) return undefined;
  const maximum = input.maximum ?? fallback;
  return isPositiveSafeInteger(maximum) ? Object.freeze({ maximum }) : undefined;
}

function defaultLimits(): ResolvedFunctionMetricsLimits {
  return Object.freeze({
    codeLines: Object.freeze({
      lowComplexityAllowance: Object.freeze({
        cyclomaticComplexityBelow: DEFAULT_LOW_COMPLEXITY_BELOW,
        maximum: DEFAULT_LOW_COMPLEXITY_CODE_LINE_MAXIMUM
      }),
      maximum: DEFAULT_CODE_LINE_MAXIMUM
    }),
    cyclomaticComplexity: Object.freeze({ maximum: DEFAULT_CYCLOMATIC_COMPLEXITY_MAXIMUM }),
    parameters: Object.freeze({ maximum: DEFAULT_PARAMETER_MAXIMUM })
  });
}

import {
  snapshotClosedRecord,
  snapshotExactClosedRecord
} from "../../data-boundary/closed-values.ts";
import { isNonEmptyString, isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import { validProjectFileSelection } from "../project-files/configuration.ts";
import { validFindingPolicy } from "../code-quality-findings/policy.ts";
import { validResolvedFindingWaivers } from "../code-quality-findings/finding-waiver-authoring.ts";
import { resolveFunctionMetricsFindingIdentity } from "./finding-waiver-identity.ts";
import type { ResolvedFunctionMetricsOptions } from "./options.ts";

/** 验证 constructor 已物化的完整 function-metrics options。 */
export function validResolvedFunctionMetricsOptions(
  value: unknown
): value is ResolvedFunctionMetricsOptions {
  const options = snapshotExactClosedRecord(value, ["codeAreas", "findingWaivers"]);
  return (
    options !== undefined &&
    validCodeAreas(options.codeAreas) &&
    validResolvedFindingWaivers(options.findingWaivers, resolveFunctionMetricsFindingIdentity)
  );
}

function validCodeAreas(value: unknown): boolean {
  const areas = snapshotClosedRecord(value);
  if (areas === undefined || Object.keys(areas).length === 0) return false;
  return Object.entries(areas).every(([areaId, candidate]) => {
    const area = snapshotExactClosedRecord(candidate, ["files", "findingPolicy", "limits"]);
    return (
      isNonEmptyString(areaId) &&
      area !== undefined &&
      validProjectFileSelection(area.files) &&
      validFindingPolicy(area.findingPolicy) &&
      validLimits(area.limits)
    );
  });
}

function validLimits(value: unknown): boolean {
  const limits = snapshotExactClosedRecord(value, [
    "codeLines",
    "cyclomaticComplexity",
    "parameters"
  ]);
  if (limits === undefined) return false;
  const codeLineLimits = codeLineLimitsFrom(limits.codeLines);
  const cyclomaticComplexity = maximumLimitFrom(limits.cyclomaticComplexity);
  const parameters = maximumLimitFrom(limits.parameters);
  return (
    codeLineLimits !== undefined &&
    cyclomaticComplexity !== undefined &&
    parameters !== undefined &&
    isPositiveSafeInteger(cyclomaticComplexity.maximum) &&
    isPositiveSafeInteger(parameters.maximum)
  );
}

function codeLineLimitsFrom(value: unknown): Readonly<Record<string, unknown>> | undefined {
  const codeLines = snapshotExactClosedRecord(value, ["lowComplexityAllowance", "maximum"]);
  const allowance = snapshotExactClosedRecord(codeLines?.lowComplexityAllowance, [
    "cyclomaticComplexityBelow",
    "maximum"
  ]);
  return codeLines !== undefined &&
    allowance !== undefined &&
    isPositiveSafeInteger(codeLines.maximum) &&
    isPositiveSafeInteger(allowance.maximum) &&
    allowance.maximum >= codeLines.maximum &&
    isPositiveSafeInteger(allowance.cyclomaticComplexityBelow)
    ? codeLines
    : undefined;
}

function maximumLimitFrom(value: unknown): Readonly<Record<string, unknown>> | undefined {
  return snapshotExactClosedRecord(value, ["maximum"]);
}

