export const PLAIN_TEXT_PROCESS_ENV = Object.freeze({
  CARGO_TERM_COLOR: "never",
  CLICOLOR: "0",
  CLICOLOR_FORCE: "0",
  FORCE_COLOR: "0",
  NO_COLOR: "1",
  PNPM_CONFIG_COLOR: "false",
  PY_COLORS: "0",
  TERM: "dumb",
  UV_NO_COLOR: "1",
  npm_config_color: "false"
} satisfies NodeJS.ProcessEnv);

export type PlainTextProcessEnvInput = {
  readonly env?: NodeJS.ProcessEnv;
};

export function plainTextProcessEnv({
  env = process.env
}: PlainTextProcessEnvInput = {}): NodeJS.ProcessEnv {
  return {
    ...env,
    ...PLAIN_TEXT_PROCESS_ENV
  };
}

import type { ProcessFailure, ProcessResult } from "./contract.ts";

export function processFailure(error: unknown): ProcessFailure {
  return error instanceof Error ? error : new Error(String(error));
}

export function processFailureFromResult(result: ProcessResult): ProcessFailure | null {
  if (result.error) {
    return attachProcessResult(processFailure(result.error), result);
  }
  if (result.status === 0) {
    return null;
  }
  return attachProcessResult(createExitFailure(result), result);
}

export function processFailed(result: Pick<ProcessResult, "error" | "status">): boolean {
  return result.error !== undefined || result.status !== 0;
}

function attachProcessResult(failure: ProcessFailure, result: ProcessResult): ProcessFailure {
  failure.stdout = result.stdout;
  failure.stderr = result.stderr;
  failure.signal = result.signal;
  failure.status = result.status;
  return failure;
}

function createExitFailure(result: ProcessResult): ProcessFailure {
  const failure: ProcessFailure = new Error(exitFailureMessage(result));
  failure.code = result.status ?? 1;
  return failure;
}

function exitFailureMessage(result: ProcessResult): string {
  if (result.status === null) {
    return `process terminated by signal ${result.signal ?? "unknown"}`;
  }
  return `process exited with status ${result.status}`;
}

import type { ExecaResultLike, ProcessResult } from "./contract.ts";

export function toProcessResult(result: ExecaResultLike, label: string): ProcessResult {
  return {
    error: processErrorFor(result, label),
    signal: result.signal ?? null,
    status: result.exitCode ?? null,
    stderr: outputString(result.stderr),
    stdout: outputString(result.stdout)
  };
}

function outputString(output: unknown): string {
  return typeof output === "string" ? output : "";
}

function processErrorFor(result: ExecaResultLike, label = "process"): Error | undefined {
  if (!isExecutionError(result)) {
    return undefined;
  }

  const message =
    result.originalMessage ?? result.shortMessage ?? result.message ?? `${label} failed`;
  const error: NodeJS.ErrnoException = new Error(message);
  if (result.code) {
    error.code = result.code;
  }
  return error;
}

function isExecutionError(result: ExecaResultLike): boolean {
  if (!result.failed) {
    return false;
  }
  if (typeof result.exitCode === "number") {
    return false;
  }
  return Boolean(result.code || result.timedOut || result.isMaxBuffer || result.signal);
}

import { execa, execaSync } from "execa";

import { plainTextProcessEnv } from "./env.ts";
import { toProcessResult } from "./result.ts";
import {
  DEFAULT_PROCESS_MAX_BUFFER_BYTES,
  type ProcessResult,
  type RunProcessOptions,
  type RunProcessSyncOptions
} from "./contract.ts";

export function runProcessSync(options: RunProcessSyncOptions): ProcessResult {
  const { args, command, ...processOptions } = options;
  const result = execaSync(command, args, {
    ...processOptions,
    encoding: processOptions.encoding ?? "utf8",
    env: plainTextProcessEnv({ env: processOptions.env }),
    maxBuffer: processOptions.maxBuffer ?? DEFAULT_PROCESS_MAX_BUFFER_BYTES,
    reject: false,
    stripFinalNewline: false,
    windowsHide: processOptions.windowsHide ?? true
  });
  return toProcessResult(result, command);
}

export function runProcess(options: RunProcessOptions): Promise<ProcessResult> {
  const {
    args = [],
    command,
    cwd,
    env,
    label = command,
    maxBuffer = DEFAULT_PROCESS_MAX_BUFFER_BYTES,
    timeout,
    windowsHide = true
  } = options;

  return execa(command, args, {
    cwd,
    env: plainTextProcessEnv({ env }),
    maxBuffer,
    reject: false,
    stripFinalNewline: false,
    timeout,
    windowsHide
  }).then((result) => toProcessResult(result, label));
}

import { closeSync, fstatSync, openSync, readSync } from "node:fs";

import { parse, type ValueNode } from "@humanwhocodes/momoa";

export type JsonDocumentIssue =
  | "too-large"
  | "bom"
  | "invalid-utf8"
  | "invalid-json"
  | "duplicate-key";

/**
 * A strict JSON value retained only inside Product source boundaries.
 * Objects have a null prototype and every aggregate is frozen, so document keys cannot affect ambient prototypes.
 */
export type StrictJsonArray = readonly StrictJsonValue[];

export interface StrictJsonObject {
  readonly [key: string]: StrictJsonValue;
}

export type StrictJsonValue = null | boolean | number | string | StrictJsonArray | StrictJsonObject;

export type StrictJsonDocumentResult =
  | Readonly<{ readonly kind: "valid"; readonly jsonValue: StrictJsonValue }>
  | Readonly<{ readonly kind: "issue"; readonly reason: JsonDocumentIssue }>
  | Readonly<{ readonly kind: "unavailable" }>;

interface StrictJsonDocumentReadInput {
  readonly filePath: string;
  /** Normally validated at the Check options boundary; malformed private input becomes unavailable. */
  readonly maximumBytes: number;
}

const UTF8_BOM = [0xef, 0xbb, 0xbf] as const;
const UNAVAILABLE_DOCUMENT = Object.freeze({ kind: "unavailable" } as const);

function isPositiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

/**
 * Reads one approved file with a byte limit, then applies the strict JSON document contract.
 * The caller owns exact-input authorization and maps `unavailable` to its Check outcome.
 */
export function readStrictJsonDocument(
  input: StrictJsonDocumentReadInput
): StrictJsonDocumentResult {
  if (!isPositiveSafeInteger(input.maximumBytes)) return UNAVAILABLE_DOCUMENT;

  const bytes = readBoundedFile(input.filePath, input.maximumBytes);
  if (bytes === undefined) return UNAVAILABLE_DOCUMENT;
  if (bytes === "too-large") return issue("too-large");
  return inspectStrictJsonBytes(bytes);
}

function readBoundedFile(
  filePath: string,
  maximumBytes: number
): Uint8Array | "too-large" | undefined {
  let descriptor: number | undefined;
  try {
    descriptor = openSync(filePath, "r");
    const before = fstatSync(descriptor);
    if (!before.isFile() || !Number.isSafeInteger(before.size)) return undefined;
    if (before.size > maximumBytes) return "too-large";

    const bytes = new Uint8Array(before.size);
    let offset = 0;
    while (offset < bytes.byteLength) {
      const bytesRead = readSync(descriptor, bytes, offset, bytes.byteLength - offset, null);
      if (bytesRead === 0) return undefined;
      offset += bytesRead;
    }

    const after = fstatSync(descriptor);
    return after.size === before.size ? bytes : undefined;
  } catch {
    return undefined;
  } finally {
    if (descriptor !== undefined) {
      try {
        closeSync(descriptor);
      } catch {
        // The read result is already fully normalized; closing cannot expose a native failure.
      }
    }
  }
}

/**
 * Applies strict JSON grammar and duplicate-key semantics to already bounded bytes.
 * This is package-private so controlled remote schema bytes use the same boundary as local files.
 */
export function inspectStrictJsonBytes(bytes: Uint8Array): StrictJsonDocumentResult {
  if (hasUtf8Bom(bytes)) return issue("bom");

  let source: string;
  try {
    source = new TextDecoder("utf-8", { fatal: true }).decode(bytes);
  } catch {
    return issue("invalid-utf8");
  }

  let document: ReturnType<typeof parse>;
  try {
    document = parse(source, { allowTrailingCommas: false, mode: "json" });
  } catch (error) {
    return isMomoaSyntaxError(error) ? issue("invalid-json") : UNAVAILABLE_DOCUMENT;
  }

  try {
    if (hasDuplicateKey(document.body)) return issue("duplicate-key");
    return valid(toStrictJsonValue(document.body));
  } catch {
    return UNAVAILABLE_DOCUMENT;
  }
}

function isMomoaSyntaxError(error: unknown): boolean {
  return (
    error instanceof Error &&
    hasNumericOwnProperty(error, "line") &&
    hasNumericOwnProperty(error, "column") &&
    hasNumericOwnProperty(error, "offset")
  );
}

function hasNumericOwnProperty(error: object, propertyName: string): boolean {
  return typeof Object.getOwnPropertyDescriptor(error, propertyName)?.value === "number";
}

function hasUtf8Bom(bytes: Uint8Array): boolean {
  return UTF8_BOM.every((byte, index) => bytes[index] === byte);
}

function hasDuplicateKey(node: ValueNode): boolean {
  if (node.type === "Array") {
    return node.elements.some((element) => hasDuplicateKey(element.value));
  }
  if (node.type !== "Object") return false;

  const names = new Set<string>();
  for (const member of node.members) {
    if (member.name.type !== "String")
      throw new TypeError("strict JSON object member must be a string");
    if (names.has(member.name.value)) return true;
    names.add(member.name.value);
    if (hasDuplicateKey(member.value)) return true;
  }
  return false;
}

function toStrictJsonValue(node: ValueNode): StrictJsonValue {
  switch (node.type) {
    case "Null":
      return null;
    case "Boolean":
    case "Number":
    case "String":
      return node.value;
    case "Array":
      return strictJsonArray(node);
    case "Object":
      return strictJsonObject(node);
    case "Infinity":
    case "NaN":
      throw new TypeError("strict JSON value node must not be a non-finite number");
    default:
      throw new TypeError("strict JSON value node must be a standard JSON node");
  }
}

function strictJsonArray(node: Extract<ValueNode, { type: "Array" }>): StrictJsonArray {
  return Object.freeze(node.elements.map((element) => toStrictJsonValue(element.value)));
}

function strictJsonObject(node: Extract<ValueNode, { type: "Object" }>): StrictJsonObject {
  const strictObject: Record<string, StrictJsonValue> = {};
  Object.setPrototypeOf(strictObject, null);
  for (const member of node.members) {
    defineStrictJsonProperty(strictObject, member.name, member.value);
  }
  return Object.freeze(strictObject);
}

function defineStrictJsonProperty(
  target: Record<string, StrictJsonValue>,
  name: { readonly type: string; readonly value?: string },
  value: ValueNode
): void {
  if (name.type !== "String" || name.value === undefined) {
    throw new TypeError("strict JSON object member must be a string");
  }
  Object.defineProperty(target, name.value, {
    configurable: false,
    enumerable: true,
    value: toStrictJsonValue(value),
    writable: false
  });
}

function issue(reason: JsonDocumentIssue): StrictJsonDocumentResult {
  return Object.freeze({ kind: "issue", reason });
}

function valid(jsonValue: StrictJsonValue): StrictJsonDocumentResult {
  return Object.freeze({ kind: "valid", jsonValue });
}

import { defineCheck, type TypedCheckWithOptions } from "../../check/check.ts";
import {
  JSON_SCHEMA_VALIDATION_CHECK_DEFINITION,
  executeJsonSchemaValidation
} from "./json-schema-validation.ts";
import { parseJsonSchemaValidationData } from "./final-data.ts";
import type {
  JsonSchemaValidationOptions,
  ResolvedJsonSchemaValidationOptions
} from "./options.ts";
import { resolveJsonSchemaValidationOptions } from "./options-resolution.ts";
import { validJsonSchemaValidationOptions } from "./options-validation.ts";

/**
 * 使用可省略的 file、identity、reference、schema 与 binding policy 构造 Check。
 *
 * @param options - 省略顶层字段和 file fields 使用 package defaults；显式数组是完整替换值。
 * @returns 固定 `json-schema-validation` identity、完整冻结 options、parser 与执行逻辑。
 * @throws {TypeError} input 不符合 closed authoring policy、identity 或 binding 不变量时抛出。
 */
export function jsonSchemaValidation(
  options: JsonSchemaValidationOptions = {}
): TypedCheckWithOptions<
  "json-schema-validation",
  ResolvedJsonSchemaValidationOptions,
  typeof parseJsonSchemaValidationData
> {
  const resolvedOptions = resolveJsonSchemaValidationOptions(options);
  if (resolvedOptions === undefined) {
    throw new TypeError("jsonSchemaValidation options must match the documented closed policy");
  }
  return defineCheck({
    ...JSON_SCHEMA_VALIDATION_CHECK_DEFINITION,
    execution: executeJsonSchemaValidation,
    parseData: parseJsonSchemaValidationData,
    preflight: (preparedOptions) =>
      validJsonSchemaValidationOptions(preparedOptions)
        ? { status: "success", preparedOptions }
        : {
            status: "failure",
            action: "block",
            reason: { code: "invalid-options" },
            messages: [
              {
                code: "invalid-options",
                level: "error",
                message:
                  "jsonSchemaValidation options are invalid; recreate the Check with jsonSchemaValidation(options) or restore its complete resolved options."
              }
            ]
          },
    options: resolvedOptions
  });
}

import { resolve } from "node:path";

import type { CheckExecutionContext } from "../../check/check.ts";
import { readStrictJsonDocument } from "../json-document/strict-document.ts";
import {
  normalizeValidationErrors,
  type CompiledSchemaSet,
  type LoadedSchema
} from "./schema-engine.ts";
import type { SchemaIssueCollector } from "./issue-collector.ts";
import type {
  JsonSchemaValidationRecordData,
  JsonSchemaValidationUnavailableCode
} from "./json-schema-validation.ts";
import type { ResolvedJsonSchemaValidationOptions } from "./options.ts";

type UnavailableStage = Readonly<{
  readonly code: JsonSchemaValidationUnavailableCode;
  readonly kind: "unavailable";
}>;

type Stage<T> = Readonly<{ readonly kind: "complete"; readonly value: T }> | UnavailableStage;

export interface LoadedSchemaStage {
  readonly failures: ReadonlySet<string>;
  readonly schemas: readonly LoadedSchema[];
}

export interface BindingCounts {
  readonly blockedBindingCount: number;
  readonly invalidBindingCount: number;
  readonly validBindingCount: number;
}

type SchemaContext = CheckExecutionContext<ResolvedJsonSchemaValidationOptions>;

export async function loadConfiguredSchemas(
  context: SchemaContext,
  selectedPaths: ReadonlySet<string>,
  issueCollector: SchemaIssueCollector
): Promise<Stage<LoadedSchemaStage>> {
  const failures = new Set<string>();
  const schemas: LoadedSchema[] = [];
  for (const schema of context.options.schemas) {
    const outcome = loadConfiguredSchema(context, selectedPaths, schema, issueCollector);
    if (outcome.kind === "unavailable") return outcome;
    if (outcome.kind === "failure") failures.add(schema.id);
    else schemas.push(outcome.value);
  }
  return complete({ failures, schemas });
}

type SchemaLoadOutcome =
  | Readonly<{ readonly kind: "failure" }>
  | Readonly<{ readonly kind: "loaded"; readonly value: LoadedSchema }>
  | Readonly<{ readonly code: JsonSchemaValidationUnavailableCode; readonly kind: "unavailable" }>;

function loadConfiguredSchema(
  context: SchemaContext,
  selectedPaths: ReadonlySet<string>,
  schema: ResolvedJsonSchemaValidationOptions["schemas"][number],
  issueCollector: SchemaIssueCollector
): SchemaLoadOutcome {
  if (context.signal.aborted) return unavailable("execution-cancelled");
  if (!selectedPaths.has(schema.path)) {
    issueCollector.add(schemaDocumentIssue(schema, "out-of-scope"));
    return { kind: "failure" };
  }
  const document = readStrictJsonDocument({
    filePath: resolve(context.project.root, schema.path),
    maximumBytes: context.options.maximumBytes
  });
  if (context.signal.aborted) return unavailable("execution-cancelled");
  if (document.kind === "unavailable") return unavailable("document-unavailable");
  if (document.kind === "issue") {
    issueCollector.add(schemaDocumentIssue(schema, document.reason));
    return { kind: "failure" };
  }
  return {
    kind: "loaded",
    value: Object.freeze({ documentValue: document.jsonValue, id: schema.id })
  };
}

function schemaDocumentIssue(
  schema: ResolvedJsonSchemaValidationOptions["schemas"][number],
  reason: Extract<JsonSchemaValidationRecordData, { readonly kind: "schema-document" }>["reason"]
): Extract<JsonSchemaValidationRecordData, { readonly kind: "schema-document" }> {
  return Object.freeze({ kind: "schema-document", path: schema.path, reason, schemaId: schema.id });
}

export function reportCompilationFailures(
  context: SchemaContext,
  compiled: CompiledSchemaSet,
  failures: Set<string>,
  issueCollector: SchemaIssueCollector
): void {
  for (const schema of context.options.schemas) {
    const reason = compiled.failures.get(schema.id);
    if (reason === undefined) continue;
    failures.add(schema.id);
    issueCollector.add(
      Object.freeze({ kind: "schema-compile", path: schema.path, reason, schemaId: schema.id })
    );
  }
}

export async function validateSchemaBindings(
  context: SchemaContext,
  selectedPaths: ReadonlySet<string>,
  compiled: CompiledSchemaSet,
  schemaFailures: ReadonlySet<string>,
  issueCollector: SchemaIssueCollector
): Promise<Stage<BindingCounts>> {
  const counts = { blockedBindingCount: 0, invalidBindingCount: 0, validBindingCount: 0 };
  for (const binding of context.options.bindings) {
    const outcome = validateSchemaBinding({
      binding,
      compiled,
      context,
      issueCollector,
      schemaFailures,
      selectedPaths
    });
    if (outcome.kind === "unavailable") return outcome;
    counts[outcome.kind] += 1;
  }
  return complete(counts);
}

type BindingOutcome =
  | Readonly<{ readonly kind: "blockedBindingCount" | "invalidBindingCount" | "validBindingCount" }>
  | Readonly<{ readonly code: JsonSchemaValidationUnavailableCode; readonly kind: "unavailable" }>;

interface BindingValidationInput {
  readonly binding: ResolvedJsonSchemaValidationOptions["bindings"][number];
  readonly compiled: CompiledSchemaSet;
  readonly context: SchemaContext;
  readonly issueCollector: SchemaIssueCollector;
  readonly schemaFailures: ReadonlySet<string>;
  readonly selectedPaths: ReadonlySet<string>;
}

function validateSchemaBinding(input: Readonly<BindingValidationInput>): BindingOutcome {
  const { binding, compiled, context, issueCollector, schemaFailures, selectedPaths } = input;
  if (context.signal.aborted) return unavailable("execution-cancelled");
  const inScope = selectedPaths.has(binding.instancePath);
  if (!inScope) issueCollector.add(instanceDocumentIssue(binding, "out-of-scope"));
  if (schemaFailures.has(binding.schemaId)) return { kind: "blockedBindingCount" };
  if (!inScope) return { kind: "invalidBindingCount" };
  return validateBoundDocument(context, compiled, binding, issueCollector);
}

function validateBoundDocument(
  context: SchemaContext,
  compiled: CompiledSchemaSet,
  binding: ResolvedJsonSchemaValidationOptions["bindings"][number],
  issueCollector: SchemaIssueCollector
): BindingOutcome {
  const document = readStrictJsonDocument({
    filePath: resolve(context.project.root, binding.instancePath),
    maximumBytes: context.options.maximumBytes
  });
  if (context.signal.aborted) return unavailable("execution-cancelled");
  if (document.kind === "unavailable") return unavailable("document-unavailable");
  if (document.kind === "issue") {
    issueCollector.add(instanceDocumentIssue(binding, document.reason));
    return { kind: "invalidBindingCount" };
  }
  return validateDocumentValue(compiled, binding, document.jsonValue, issueCollector);
}

function validateDocumentValue(
  compiled: CompiledSchemaSet,
  binding: ResolvedJsonSchemaValidationOptions["bindings"][number],
  value: LoadedSchema["documentValue"],
  issueCollector: SchemaIssueCollector
): BindingOutcome {
  const validator = compiled.validators.get(binding.schemaId);
  if (validator === undefined) return unavailable("engine-unavailable");
  try {
    if (validator(value)) return { kind: "validBindingCount" };
  } catch {
    return unavailable("engine-unavailable");
  }
  reportKeywordViolations(binding, normalizeValidationErrors(validator.errors), issueCollector);
  return { kind: "invalidBindingCount" };
}

function instanceDocumentIssue(
  binding: ResolvedJsonSchemaValidationOptions["bindings"][number],
  reason: Extract<JsonSchemaValidationRecordData, { readonly kind: "instance-document" }>["reason"]
): Extract<JsonSchemaValidationRecordData, { readonly kind: "instance-document" }> {
  return Object.freeze({
    bindingId: binding.id,
    kind: "instance-document",
    path: binding.instancePath,
    reason,
    schemaId: binding.schemaId
  });
}

function reportKeywordViolations(
  binding: ResolvedJsonSchemaValidationOptions["bindings"][number],
  violations: ReturnType<typeof normalizeValidationErrors>,
  issueCollector: SchemaIssueCollector
): void {
  const reported =
    violations.length === 0 ? [Object.freeze({ keyword: "other", pointer: "" })] : violations;
  for (const violation of reported) {
    issueCollector.add(
      Object.freeze({
        bindingId: binding.id,
        keyword: violation.keyword,
        kind: "keyword-violation",
        path: binding.instancePath,
        pointer: violation.pointer,
        schemaId: binding.schemaId
      })
    );
  }
}

function complete<T>(value: T): Stage<T> {
  return Object.freeze({ kind: "complete", value });
}

function unavailable(code: JsonSchemaValidationUnavailableCode): UnavailableStage {
  return Object.freeze({ code, kind: "unavailable" });
}

import {
  exactFinalDataRecord,
  invalidFinalData,
  nonNegativeSafeInteger
} from "../final-data-parsing.ts";

/** 单次运行最多发布的 JSON Schema issue Record 数量。 */
export const MAX_REPORTED_JSON_SCHEMA_ISSUES = 100;

/** `json-schema-validation` 在 passed/failed outcome 中发布的主数据。 */
export interface JsonSchemaValidationFinalData {
  readonly bindingCount: number;
  readonly blockedBindingCount: number;
  readonly invalidBindingCount: number;
  readonly issueCount: number;
  readonly issuesTruncated: boolean;
  readonly reportedIssueCount: number;
  readonly schemaCount: number;
  readonly validBindingCount: number;
}

/** 验证计数与截断不变量并脱离 canonical final data。 */
export function parseJsonSchemaValidationData(data: unknown): JsonSchemaValidationFinalData {
  const value = jsonSchemaFinalDataRecord(data);
  const counts = parsedCounts(value);
  const issuesTruncated = value.issuesTruncated;
  if (typeof issuesTruncated !== "boolean" || !validFinalDataInvariants(issuesTruncated, counts)) {
    throw invalidFinalData("jsonSchemaValidation");
  }
  return Object.freeze({
    bindingCount: counts.bindingCount,
    blockedBindingCount: counts.blockedBindingCount,
    invalidBindingCount: counts.invalidBindingCount,
    issueCount: counts.issueCount,
    issuesTruncated,
    reportedIssueCount: counts.reportedIssueCount,
    schemaCount: counts.schemaCount,
    validBindingCount: counts.validBindingCount
  });
}

function jsonSchemaFinalDataRecord(data: unknown): Readonly<Record<string, unknown>> {
  return exactFinalDataRecord(
    data,
    [
      "bindingCount",
      "blockedBindingCount",
      "invalidBindingCount",
      "issueCount",
      "issuesTruncated",
      "reportedIssueCount",
      "schemaCount",
      "validBindingCount"
    ],
    "jsonSchemaValidation"
  );
}

interface ParsedCounts {
  readonly bindingCount: number | undefined;
  readonly blockedBindingCount: number | undefined;
  readonly invalidBindingCount: number | undefined;
  readonly issueCount: number | undefined;
  readonly reportedIssueCount: number | undefined;
  readonly schemaCount: number | undefined;
  readonly validBindingCount: number | undefined;
}

function parsedCounts(value: Readonly<Record<string, unknown>>): ParsedCounts {
  return {
    bindingCount: nonNegativeSafeInteger(value.bindingCount),
    blockedBindingCount: nonNegativeSafeInteger(value.blockedBindingCount),
    invalidBindingCount: nonNegativeSafeInteger(value.invalidBindingCount),
    issueCount: nonNegativeSafeInteger(value.issueCount),
    reportedIssueCount: nonNegativeSafeInteger(value.reportedIssueCount),
    schemaCount: nonNegativeSafeInteger(value.schemaCount),
    validBindingCount: nonNegativeSafeInteger(value.validBindingCount)
  };
}

interface CompleteCounts {
  readonly bindingCount: number;
  readonly blockedBindingCount: number;
  readonly invalidBindingCount: number;
  readonly issueCount: number;
  readonly reportedIssueCount: number;
  readonly schemaCount: number;
  readonly validBindingCount: number;
}

function validFinalDataInvariants(
  issuesTruncated: boolean,
  counts: ParsedCounts
): counts is CompleteCounts {
  if (!allCountsDefined(counts)) return false;
  return (
    counts.bindingCount ===
      counts.blockedBindingCount + counts.invalidBindingCount + counts.validBindingCount &&
    counts.reportedIssueCount <= counts.issueCount &&
    counts.reportedIssueCount <= MAX_REPORTED_JSON_SCHEMA_ISSUES &&
    issuesTruncated === counts.issueCount > counts.reportedIssueCount
  );
}

function allCountsDefined(counts: ParsedCounts): counts is CompleteCounts {
  return (
    counts.bindingCount !== undefined &&
    counts.blockedBindingCount !== undefined &&
    counts.invalidBindingCount !== undefined &&
    counts.issueCount !== undefined &&
    counts.reportedIssueCount !== undefined &&
    counts.schemaCount !== undefined &&
    counts.validBindingCount !== undefined
  );
}

import { createHash } from "node:crypto";

import type { CheckExecutionContext } from "../../check/check.ts";
import { MAX_REPORTED_JSON_SCHEMA_ISSUES } from "./final-data.ts";
import type { JsonSchemaValidationRecordData } from "./json-schema-validation.ts";
import type { ResolvedJsonSchemaValidationOptions } from "./options.ts";

/** Owns the invocation-local issue count, display cap, and deterministic Record identity ordinal. */
export class SchemaIssueCollector {
  #count = 0;
  #reportedCount = 0;
  readonly #issueOccurrences = new Map<string, number>();
  readonly #checkContext: CheckExecutionContext<ResolvedJsonSchemaValidationOptions>;

  constructor(context: CheckExecutionContext<ResolvedJsonSchemaValidationOptions>) {
    this.#checkContext = context;
  }

  get count(): number {
    return this.#count;
  }

  get reportedCount(): number {
    return this.#reportedCount;
  }

  get truncated(): boolean {
    return this.#count > this.#reportedCount;
  }

  add(issue: JsonSchemaValidationRecordData): void {
    this.#count += 1;
    if (this.#reportedCount >= MAX_REPORTED_JSON_SCHEMA_ISSUES) return;
    const semanticKey = JSON.stringify(issue);
    const occurrence = this.#issueOccurrences.get(semanticKey) ?? 0;
    this.#issueOccurrences.set(semanticKey, occurrence + 1);
    const digest = createHash("sha256")
      .update(`${semanticKey}\n${occurrence}`, "utf8")
      .digest("hex");
    this.#checkContext.records.report({ id: `json-schema:${issue.kind}:${digest}` }, issue);
    this.#reportedCount += 1;
  }
}

import type { CheckExecutionContext, CheckResult } from "../../check/check.ts";
import { collectProjectFiles } from "../project-files/collection.ts";
import type { JsonDocumentIssue } from "../json-document/strict-document.ts";
import { compileSchemaSet, type SchemaCompileReason } from "./schema-engine.ts";
import {
  loadConfiguredSchemas,
  reportCompilationFailures,
  validateSchemaBindings
} from "./execution-stages.ts";
import { type JsonSchemaValidationFinalData } from "./final-data.ts";
import { SchemaIssueCollector } from "./issue-collector.ts";
import type { ResolvedJsonSchemaValidationOptions } from "./options.ts";
import { validJsonSchemaValidationOptions } from "./options-validation.ts";

export const JSON_SCHEMA_VALIDATION_CHECK_DEFINITION = {
  checkId: "json-schema-validation",
  displayName: "JSON Schema validation"
} as const;

/** `json-schema-validation` whole-Check unavailable outcome 的稳定 reason code。 */
export type JsonSchemaValidationUnavailableCode =
  | "invalid-options"
  | "engine-unavailable"
  | "execution-cancelled"
  | "reference-transport-unavailable"
  | "scan-input-unavailable"
  | "document-unavailable";

/** Schema 或 instance document Record 的稳定 document reason。 */
export type JsonSchemaDocumentReason = JsonDocumentIssue | "out-of-scope";

/** Schema/document Record 中带 `reason` branch 的稳定问题原因。 */
export type JsonSchemaValidationRecordReason = JsonSchemaDocumentReason | SchemaCompileReason;

/** 一条 schema document、compile、instance 或 keyword issue Record 的 data。 */
export type JsonSchemaValidationRecordData =
  | Readonly<{
      readonly kind: "schema-document";
      readonly path: string;
      readonly reason: JsonSchemaDocumentReason;
      readonly schemaId: string;
    }>
  | Readonly<{
      readonly kind: "schema-compile";
      readonly path: string;
      readonly reason: SchemaCompileReason;
      readonly schemaId: string;
    }>
  | Readonly<{
      readonly bindingId: string;
      readonly kind: "instance-document";
      readonly path: string;
      readonly reason: JsonSchemaDocumentReason;
      readonly schemaId: string;
    }>
  | Readonly<{
      readonly bindingId: string;
      readonly keyword: string;
      readonly kind: "keyword-violation";
      readonly path: string;
      readonly pointer: string;
      readonly schemaId: string;
    }>;

/** Validates only explicitly registered/bound JSON files inside the current global scan scope. */
export async function executeJsonSchemaValidation(
  context: CheckExecutionContext<ResolvedJsonSchemaValidationOptions>
): Promise<CheckResult<JsonSchemaValidationFinalData>> {
  if (!validJsonSchemaValidationOptions(context.options)) return unavailable("invalid-options");

  try {
    return await execute(context);
  } catch {
    return unavailable("engine-unavailable");
  }
}

async function execute(
  context: CheckExecutionContext<ResolvedJsonSchemaValidationOptions>
): Promise<CheckResult<JsonSchemaValidationFinalData>> {
  if (context.signal.aborted) return unavailable("execution-cancelled");
  if (context.options.bindings.length === 0) return noBindingsResult();
  const selectedPaths = selectedProjectPaths(context);
  if (selectedPaths === undefined) return unavailable("scan-input-unavailable");
  if (context.signal.aborted) return unavailable("execution-cancelled");

  const issueCollector = new SchemaIssueCollector(context);
  const loaded = await loadConfiguredSchemas(context, selectedPaths, issueCollector);
  if (loaded.kind === "unavailable") return unavailable(loaded.code);
  const compilation = await compileSchemaSet({
    referenceResolution: context.options.referenceResolution,
    schemaIdentity: context.options.schemaIdentity,
    schemas: loaded.value.schemas,
    signal: context.signal
  });
  if (compilation.kind === "unavailable") return unavailable(compilation.reason);
  if (context.signal.aborted) return unavailable("execution-cancelled");

  const schemaFailures = new Set(loaded.value.failures);
  reportCompilationFailures(context, compilation.compiledSchemaSet, schemaFailures, issueCollector);
  const bindings = await validateSchemaBindings(
    context,
    selectedPaths,
    compilation.compiledSchemaSet,
    schemaFailures,
    issueCollector
  );
  if (bindings.kind === "unavailable") return unavailable(bindings.code);
  return completedValidationResult(context, bindings.value, issueCollector);
}

function selectedProjectPaths(
  context: CheckExecutionContext<ResolvedJsonSchemaValidationOptions>
): ReadonlySet<string> | undefined {
  try {
    return new Set(collectProjectFiles(context.project.root, context.options.files));
  } catch {
    return undefined;
  }
}

function noBindingsResult(): CheckResult<JsonSchemaValidationFinalData> {
  return Object.freeze({ status: "not-applicable", reason: { code: "no-bindings" } });
}

function completedValidationResult(
  context: CheckExecutionContext<ResolvedJsonSchemaValidationOptions>,
  bindings: Readonly<{
    readonly blockedBindingCount: number;
    readonly invalidBindingCount: number;
    readonly validBindingCount: number;
  }>,
  issueCollector: SchemaIssueCollector
): CheckResult<JsonSchemaValidationFinalData> {
  const data = Object.freeze({
    bindingCount: context.options.bindings.length,
    blockedBindingCount: bindings.blockedBindingCount,
    invalidBindingCount: bindings.invalidBindingCount,
    issueCount: issueCollector.count,
    issuesTruncated: issueCollector.truncated,
    reportedIssueCount: issueCollector.reportedCount,
    schemaCount: context.options.schemas.length,
    validBindingCount: bindings.validBindingCount
  });
  if (issueCollector.count === 0) return Object.freeze({ data, status: "passed" });
  return Object.freeze({
    data,
    messages: Object.freeze([
      Object.freeze({
        code: "schema-validation-issues",
        level: "error" as const,
        message: validationIssueMessage(issueCollector)
      })
    ]),
    status: "failed"
  });
}

function validationIssueMessage(issueCollector: SchemaIssueCollector): string {
  const truncation = issueCollector.truncated ? " (the published Record list is truncated)" : "";
  return `${issueCollector.count} schema validation issue(s) were found; inspect this Check's Records${truncation}.`;
}

function unavailable(
  code: JsonSchemaValidationUnavailableCode
): CheckResult<JsonSchemaValidationFinalData> {
  return Object.freeze({
    status: "unavailable",
    reason: { code },
    messages: Object.freeze([
      Object.freeze({ code, level: "error" as const, message: unavailableMessage(code) })
    ])
  });
}

function unavailableMessage(code: JsonSchemaValidationUnavailableCode): string {
  switch (code) {
    case "invalid-options":
      return "jsonSchemaValidation options are invalid; recreate the Check with jsonSchemaValidation(options) or restore its complete resolved options.";
    case "scan-input-unavailable":
      return "JSON Schema validation could not collect its configured project files; check the project root, permissions, and selected file source.";
    case "document-unavailable":
      return "A selected schema or instance document could not be read safely; check that it still exists, is readable, and was not replaced during the Run.";
    case "reference-transport-unavailable":
      return "An allowlisted HTTPS schema reference could not be loaded; check the allowlist, network, and remote availability.";
    case "engine-unavailable":
      return "The schema engine could not form a trusted complete result; check package/runtime integrity and inspect any retained issue Records.";
    case "execution-cancelled":
      return "JSON Schema validation was cancelled before it could form a complete result; inspect the caller's cancellation reason and retry if appropriate.";
  }
}

import { canonicalizeJsonObject } from "../../data-boundary/canonical-data.ts";
import {
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedRecord
} from "../../data-boundary/closed-values.ts";
import {
  resolveProjectFileSelection,
  snapshotDefaultProjectFileSelection
} from "../project-files/configuration.ts";
import type { ResolvedJsonSchemaValidationOptions } from "./options.ts";
import { validJsonSchemaValidationOptions } from "./options-validation.ts";

const DEFAULT_MAXIMUM_BYTES = 1_048_576;

/** 将可省略 schema registry policy 物化为完整、冻结的 execution options。 */
export function resolveJsonSchemaValidationOptions(
  value: unknown
): ResolvedJsonSchemaValidationOptions | undefined {
  const input = snapshotClosedRecord(value);
  if (!validOptionInput(input)) return undefined;
  const files = resolvedFiles(input.files);
  if (files === undefined) return undefined;
  const candidate = canonicalizeJsonObject({
    files,
    maximumBytes: input.maximumBytes === undefined ? DEFAULT_MAXIMUM_BYTES : input.maximumBytes,
    schemaIdentity:
      input.schemaIdentity === undefined ? { mode: "require-match" } : input.schemaIdentity,
    referenceResolution:
      input.referenceResolution === undefined ? { mode: "offline" } : input.referenceResolution,
    schemas: input.schemas === undefined ? [] : input.schemas,
    bindings: input.bindings === undefined ? [] : input.bindings
  });
  return candidate !== undefined && validJsonSchemaValidationOptions(candidate)
    ? candidate
    : undefined;
}

function validOptionInput(
  input: Readonly<Record<string, unknown>> | undefined
): input is Readonly<Record<string, unknown>> {
  return (
    input !== undefined &&
    hasRequiredAndOptionalRecordKeys(input, {
      optional: [
        "files",
        "maximumBytes",
        "schemaIdentity",
        "referenceResolution",
        "schemas",
        "bindings"
      ],
      required: []
    })
  );
}

function resolvedFiles(value: unknown) {
  return value === undefined
    ? snapshotDefaultProjectFileSelection()
    : resolveProjectFileSelection(value);
}

import {
  snapshotClosedArray,
  snapshotClosedRecord,
  snapshotExactClosedRecord
} from "../../data-boundary/closed-values.ts";
import { isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import { validProjectFileSelection } from "../project-files/configuration.ts";
import type { ResolvedJsonSchemaValidationOptions } from "./options.ts";

export function validJsonSchemaValidationOptions(
  candidateOptions: unknown
): candidateOptions is ResolvedJsonSchemaValidationOptions {
  const options = snapshotExactClosedRecord(candidateOptions, [
    "files",
    "maximumBytes",
    "schemaIdentity",
    "referenceResolution",
    "schemas",
    "bindings"
  ]);
  if (
    options === undefined ||
    !validProjectFileSelection(options.files) ||
    !isPositiveSafeInteger(options.maximumBytes) ||
    !validJsonSchemaIdentity(options.schemaIdentity) ||
    !validJsonSchemaReferenceResolution(options.referenceResolution)
  ) {
    return false;
  }

  const schemas = snapshotClosedArray(options.schemas);
  const bindings = snapshotClosedArray(options.bindings);
  const declaredSchemaIds = schemas === undefined ? undefined : validatedSchemaRegistryIds(schemas);
  return (
    bindings !== undefined &&
    declaredSchemaIds !== undefined &&
    validJsonSchemaBindings(bindings, declaredSchemaIds)
  );
}

function validJsonSchemaIdentity(candidateIdentity: unknown): boolean {
  const identity = snapshotExactClosedRecord(candidateIdentity, ["mode"]);
  return (
    identity !== undefined &&
    (identity.mode === "require-match" ||
      identity.mode === "configuration-authoritative" ||
      identity.mode === "document-authoritative")
  );
}

function validJsonSchemaReferenceResolution(candidateResolution: unknown): boolean {
  const referenceResolution = snapshotClosedRecord(candidateResolution);
  if (referenceResolution === undefined || typeof referenceResolution.mode !== "string") {
    return false;
  }
  if (referenceResolution.mode === "offline") {
    return snapshotExactClosedRecord(referenceResolution, ["mode"]) !== undefined;
  }
  if (referenceResolution.mode !== "allowlisted") return false;

  const allowlisted = snapshotExactClosedRecord(referenceResolution, ["mode", "sources"]);
  const sources = allowlisted === undefined ? undefined : snapshotClosedArray(allowlisted.sources);
  return sources !== undefined && sources.length > 0 && validJsonSchemaReferenceSources(sources);
}

function validJsonSchemaReferenceSources(sources: readonly unknown[]): boolean {
  const sourceIds = new Set<string>();
  const sourceLocations = new Set<string>();
  let bundledCatalogCount = 0;
  for (const sourceCandidate of sources) {
    const source = validatedReferenceSource(sourceCandidate);
    if (source === undefined) return false;
    if (source.kind === "bundled") {
      bundledCatalogCount += 1;
      if (bundledCatalogCount > 1) return false;
      continue;
    }
    if (sourceIds.has(source.id) || sourceLocations.has(source.location)) return false;
    sourceIds.add(source.id);
    sourceLocations.add(source.location);
  }
  return true;
}

function validatedReferenceSource(sourceCandidate: unknown) {
  const source = snapshotClosedRecord(sourceCandidate);
  if (source === undefined || typeof source.kind !== "string") return undefined;
  if (source.kind === "bundled")
    return validBundledSource(source) ? { kind: "bundled" as const } : undefined;
  if (source.kind !== "https") return undefined;
  const httpsSource = validatedHttpsSource(source);
  return httpsSource === undefined ? undefined : { kind: "https" as const, ...httpsSource };
}

function validBundledSource(source: Readonly<Record<string, unknown>>): boolean {
  return snapshotExactClosedRecord(source, ["kind", "catalog"])?.catalog === "json-schema-2020-12";
}

function validatedHttpsSource(source: Readonly<Record<string, unknown>>) {
  const httpsSource = snapshotExactClosedRecord(source, ["kind", "id", "origin", "pathPrefix"]);
  if (
    httpsSource === undefined ||
    !safeAbsoluteIdentifier(httpsSource.id) ||
    !safeHttpsOrigin(httpsSource.origin) ||
    !safePathPrefix(httpsSource.pathPrefix)
  )
    return undefined;
  return { id: httpsSource.id, location: `${httpsSource.origin}\n${httpsSource.pathPrefix}` };
}

/** Returns declared IDs only after the whole schema registry satisfies its closed authoring invariant. */
function validatedSchemaRegistryIds(schemas: readonly unknown[]): ReadonlySet<string> | undefined {
  const declaredSchemaIds = new Set<string>();
  const schemaPaths = new Set<string>();
  for (const schemaCandidate of schemas) {
    const schemaRecord = snapshotExactClosedRecord(schemaCandidate, ["id", "path"]);
    if (
      schemaRecord === undefined ||
      !safeAbsoluteIdentifier(schemaRecord.id) ||
      !normalizedProjectJsonPath(schemaRecord.path) ||
      declaredSchemaIds.has(schemaRecord.id) ||
      schemaPaths.has(schemaRecord.path)
    ) {
      return undefined;
    }
    declaredSchemaIds.add(schemaRecord.id);
    schemaPaths.add(schemaRecord.path);
  }
  return declaredSchemaIds;
}

function validJsonSchemaBindings(
  bindings: readonly unknown[],
  declaredSchemaIds: ReadonlySet<string>
): boolean {
  const bindingIds = new Set<string>();
  const bindingTargets = new Set<string>();
  for (const bindingCandidate of bindings) {
    const bindingRecord = snapshotExactClosedRecord(bindingCandidate, [
      "id",
      "instancePath",
      "schemaId"
    ]);
    if (
      bindingRecord === undefined ||
      !safeBindingId(bindingRecord.id) ||
      !normalizedProjectJsonPath(bindingRecord.instancePath) ||
      typeof bindingRecord.schemaId !== "string" ||
      !declaredSchemaIds.has(bindingRecord.schemaId) ||
      bindingIds.has(bindingRecord.id)
    ) {
      return false;
    }
    const bindingTarget = `${bindingRecord.instancePath}\n${bindingRecord.schemaId}`;
    if (bindingTargets.has(bindingTarget)) return false;
    bindingIds.add(bindingRecord.id);
    bindingTargets.add(bindingTarget);
  }
  return true;
}

function safeAbsoluteIdentifier(identifier: unknown): identifier is string {
  if (!boundedNonEmptyString(identifier, 256)) return false;
  try {
    const url = new URL(identifier);
    return safeIdentifierUrl(url, identifier);
  } catch {
    return false;
  }
}

function safeIdentifierUrl(url: URL, identifier: string): boolean {
  return (
    (url.protocol === "https:" || url.protocol === "urn:") &&
    url.username.length === 0 &&
    url.password.length === 0 &&
    url.search.length === 0 &&
    url.hash.length === 0 &&
    url.href === identifier
  );
}

function safeHttpsOrigin(origin: unknown): origin is string {
  if (!boundedNonEmptyString(origin, 200)) return false;
  try {
    const url = new URL(origin);
    return safeHttpsOriginUrl(url, origin);
  } catch {
    return false;
  }
}

function safeHttpsOriginUrl(url: URL, origin: string): boolean {
  return (
    url.protocol === "https:" &&
    url.hostname.length > 0 &&
    url.username.length === 0 &&
    url.password.length === 0 &&
    url.search.length === 0 &&
    url.hash.length === 0 &&
    url.pathname === "/" &&
    url.origin === origin
  );
}

function safePathPrefix(pathPrefix: unknown): pathPrefix is string {
  if (!validPathPrefixSyntax(pathPrefix)) return false;
  const segments = pathPrefix.split("/");
  return segments.every(
    (segment, index) => index === 0 || segment === "" || (segment !== "." && segment !== "..")
  );
}

function validPathPrefixSyntax(pathPrefix: unknown): pathPrefix is string {
  return (
    boundedNonEmptyString(pathPrefix, 256) &&
    pathPrefix.startsWith("/") &&
    (pathPrefix === "/" || pathPrefix.endsWith("/")) &&
    !pathPrefix.includes("\\") &&
    !pathPrefix.includes("?") &&
    !pathPrefix.includes("#") &&
    !pathPrefix.includes("//")
  );
}

function boundedNonEmptyString(value: unknown, maximumLength: number): value is string {
  return typeof value === "string" && value.length > 0 && value.length <= maximumLength;
}

function normalizedProjectJsonPath(projectPath: unknown): projectPath is string {
  if (
    typeof projectPath !== "string" ||
    projectPath.length === 0 ||
    projectPath.length > 512 ||
    !projectPath.endsWith(".json") ||
    projectPath.startsWith("/") ||
    projectPath.includes("\\") ||
    projectPath.includes("\u0000")
  ) {
    return false;
  }
  return projectPath
    .split("/")
    .every((segment) => segment.length > 0 && segment !== "." && segment !== "..");
}

function safeBindingId(bindingId: unknown): bindingId is string {
  return typeof bindingId === "string" && /^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$/u.test(bindingId);
}

import type {
  ProjectFileSelection,
  ProjectFileSelectionOptions
} from "../project-files/configuration.ts";

export type JsonSchemaIdentityMode =
  | "require-match"
  | "configuration-authoritative"
  | "document-authoritative";

export interface JsonSchemaIdentity {
  readonly mode: JsonSchemaIdentityMode;
}

export type JsonSchemaReferenceSource =
  | Readonly<{ readonly kind: "bundled"; readonly catalog: "json-schema-2020-12" }>
  | Readonly<{
      readonly kind: "https";
      readonly id: string;
      readonly origin: string;
      readonly pathPrefix: string;
    }>;

export type JsonSchemaReferenceResolution =
  | Readonly<{ readonly mode: "offline" }>
  | Readonly<{
      readonly mode: "allowlisted";
      readonly sources: readonly JsonSchemaReferenceSource[];
    }>;

export interface RegisteredJsonSchema {
  readonly id: string;
  readonly path: string;
}

export interface JsonSchemaInstanceBinding {
  readonly id: string;
  readonly instancePath: string;
  readonly schemaId: string;
}

/** `jsonSchemaValidation(options?)` 接受的可省略 authoring policy。 */
export interface JsonSchemaValidationOptions {
  /** schema/instance declarations 必须属于的 repository-file selection。 */
  readonly files?: ProjectFileSelectionOptions;
  /** 每个 local schema/instance document 允许的最大 raw byte 数；省略时为 1 MiB。 */
  readonly maximumBytes?: number;
  /** 整个 Check 共用的 schema root identity 规则；不得按 schema 混用。 */
  readonly schemaIdentity?: JsonSchemaIdentity;
  /** 默认离线；额外 schema source 必须显式 allowlist。 */
  readonly referenceResolution?: JsonSchemaReferenceResolution;
  /** 显式注册的 schema resources；ID 是 binding 和 public fact 使用的安全 authoring identity。 */
  readonly schemas?: readonly RegisteredJsonSchema[];
  /** 明确把一个由本 Check file selection 批准的 instance path 绑定到已声明 schema。 */
  readonly bindings?: readonly JsonSchemaInstanceBinding[];
}

/** `json-schema-validation` execution 消费的完整、冻结 options。 */
export interface ResolvedJsonSchemaValidationOptions {
  readonly files: ProjectFileSelection;
  readonly maximumBytes: number;
  readonly schemaIdentity: JsonSchemaIdentity;
  readonly referenceResolution: JsonSchemaReferenceResolution;
  readonly schemas: readonly RegisteredJsonSchema[];
  readonly bindings: readonly JsonSchemaInstanceBinding[];
}

import type { AnySchemaObject } from "ajv";

import type { ResolvedJsonSchemaValidationOptions } from "./options.ts";
import type { SchemaCompileReason } from "./schema-engine.ts";
import { inspectSchemaPolicy, isJsonObject } from "./schema-policy.ts";
import { inspectStrictJsonBytes } from "../json-document/strict-document.ts";
import { normalizeRemoteReference, readBoundedResponse } from "./remote-response.ts";

interface ControlledResolverInput {
  readonly referenceResolution: ResolvedJsonSchemaValidationOptions["referenceResolution"];
  readonly signal: AbortSignal;
}

const MAX_REMOTE_RESPONSE_BYTES = 1_048_576;
const REMOTE_TIMEOUT_MS = 5_000;

export class ControlledReferenceResolver {
  readonly #cache = new Map<string, Promise<AnySchemaObject>>();
  #loadQueue: Promise<void> = Promise.resolve();
  readonly #allowedHttpsSources: readonly Readonly<{
    readonly origin: string;
    readonly pathPrefix: string;
  }>[];
  readonly #resolverInput: ControlledResolverInput;

  constructor(input: ControlledResolverInput) {
    this.#resolverInput = input;
    this.#allowedHttpsSources =
      input.referenceResolution.mode === "allowlisted"
        ? Object.freeze(
            input.referenceResolution.sources.flatMap((source) =>
              source.kind === "https"
                ? [Object.freeze({ origin: source.origin, pathPrefix: source.pathPrefix })]
                : []
            )
          )
        : Object.freeze([]);
  }

  load(referenceUri: string): Promise<AnySchemaObject> {
    let normalizedReferenceUri: string;
    try {
      normalizedReferenceUri = normalizeRemoteReference(referenceUri);
    } catch {
      return Promise.reject(new ReferenceResolutionFailure("unapproved-reference"));
    }
    const cached = this.#cache.get(normalizedReferenceUri);
    if (cached !== undefined) return cached;
    const loading = this.queueLoad(normalizedReferenceUri);
    this.#cache.set(normalizedReferenceUri, loading);
    return loading;
  }

  private queueLoad(referenceUri: string): Promise<AnySchemaObject> {
    const loading = this.#loadQueue.then(
      () => this.loadUncached(referenceUri),
      () => this.loadUncached(referenceUri)
    );
    this.#loadQueue = loading.then(
      () => undefined,
      () => undefined
    );
    return loading;
  }

  private async loadUncached(referenceUri: string): Promise<AnySchemaObject> {
    if (!this.isAllowedReference(referenceUri))
      throw new ReferenceResolutionFailure("unapproved-reference");
    if (this.#resolverInput.signal.aborted) throw new ReferenceTransportFailure();
    const controller = new AbortController();
    const abortForCaller = (): void => controller.abort();
    this.#resolverInput.signal.addEventListener("abort", abortForCaller, { once: true });
    const timeout = setTimeout(() => controller.abort(), REMOTE_TIMEOUT_MS);
    try {
      return await this.loadWithController(referenceUri, controller);
    } catch (error) {
      if (
        error instanceof ReferenceResolutionFailure ||
        error instanceof ReferenceTransportFailure
      ) {
        throw error;
      }
      throw new ReferenceTransportFailure();
    } finally {
      clearTimeout(timeout);
      this.#resolverInput.signal.removeEventListener("abort", abortForCaller);
    }
  }

  private async loadWithController(
    referenceUri: string,
    controller: AbortController
  ): Promise<AnySchemaObject> {
    const response = await fetchSchemaResponse(referenceUri, controller.signal);
    assertAllowedResponse(response);
    if (this.#resolverInput.signal.aborted) throw new ReferenceTransportFailure();
    const bytes = await readBoundedResponse(
      response,
      MAX_REMOTE_RESPONSE_BYTES,
      this.#resolverInput.signal
    );
    return schemaFromRemoteBytes(bytes, referenceUri);
  }

  private isAllowedReference(referenceUri: string): boolean {
    let url: URL;
    try {
      url = new URL(referenceUri);
    } catch {
      return false;
    }
    return this.#allowedHttpsSources.some(
      (source) =>
        url.origin === source.origin &&
        (source.pathPrefix === "/" || url.pathname.startsWith(source.pathPrefix))
    );
  }
}

async function fetchSchemaResponse(referenceUri: string, signal: AbortSignal): Promise<Response> {
  if (typeof globalThis.fetch !== "function") throw new ReferenceTransportFailure();
  return globalThis.fetch(referenceUri, {
    credentials: "omit",
    method: "GET",
    redirect: "manual",
    signal
  });
}

function assertAllowedResponse(response: Response): void {
  if (response.redirected || (response.status >= 300 && response.status < 400)) {
    throw new ReferenceResolutionFailure("unapproved-reference");
  }
  if (response.ok) return;
  if (response.status >= 500) throw new ReferenceTransportFailure();
  throw new ReferenceResolutionFailure("unapproved-reference");
}

function schemaFromRemoteBytes(
  bytes: Uint8Array | "too-large",
  referenceUri: string
): AnySchemaObject {
  if (bytes === "too-large") throw new ReferenceResolutionFailure("remote-document-invalid");
  const document = inspectStrictJsonBytes(bytes);
  if (document.kind !== "valid" || !isJsonObject(document.jsonValue)) {
    throw new ReferenceResolutionFailure("remote-document-invalid");
  }
  if (document.jsonValue.$id !== referenceUri) {
    throw new ReferenceResolutionFailure("remote-schema-id-mismatch");
  }
  const referenceReason = inspectSchemaPolicy(document.jsonValue);
  if (referenceReason !== undefined) throw new ReferenceResolutionFailure(referenceReason);
  return document.jsonValue;
}

export class ReferenceResolutionFailure extends Error {
  readonly reason: SchemaCompileReason;

  constructor(reason: SchemaCompileReason) {
    super(reason);
    this.reason = reason;
  }
}

export class ReferenceTransportFailure extends Error {}

export async function readBoundedResponse(
  response: Response,
  maximumBytes: number,
  signal: AbortSignal
): Promise<Uint8Array | "too-large"> {
  if (declaredResponseIsTooLarge(response, maximumBytes)) return "too-large";
  const reader = response.body?.getReader();
  if (reader === undefined) return new Uint8Array();

  const chunks = await readResponseChunks(reader, maximumBytes, signal);
  return chunks === "too-large" ? chunks : assembleResponseBytes(chunks);
}

function declaredResponseIsTooLarge(response: Response, maximumBytes: number): boolean {
  const length = response.headers.get("content-length");
  return length !== null && /^\d+$/u.test(length) && Number(length) > maximumBytes;
}

async function readResponseChunks(
  reader: ReadableStreamDefaultReader<Uint8Array>,
  maximumBytes: number,
  signal: AbortSignal
): Promise<readonly Uint8Array[] | "too-large"> {
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    while (true) {
      if (signal.aborted) throw transportFailure();
      const chunk = await reader.read();
      if (chunk.done) break;
      total += chunk.value.byteLength;
      if (total > maximumBytes) {
        await cancelRejectedReader(reader);
        return "too-large";
      }
      chunks.push(chunk.value);
    }
    return chunks;
  } catch {
    throw transportFailure();
  } finally {
    reader.releaseLock();
  }
}

async function cancelRejectedReader(
  reader: ReadableStreamDefaultReader<Uint8Array>
): Promise<void> {
  try {
    await reader.cancel();
  } catch {
    // The bounded response has already been rejected; cancellation detail is not a transport fact.
  }
}

function assembleResponseBytes(chunks: readonly Uint8Array[]): Uint8Array {
  const responseBytes = new Uint8Array(
    chunks.reduce((total, chunk) => total + chunk.byteLength, 0)
  );
  let offset = 0;
  for (const chunk of chunks) {
    responseBytes.set(chunk, offset);
    offset += chunk.byteLength;
  }
  return responseBytes;
}

function transportFailure(): Error {
  return new Error("remote response transport failed");
}

export function normalizeRemoteReference(referenceUri: string): string {
  const url = new URL(referenceUri);
  if (
    url.protocol !== "https:" ||
    url.username.length > 0 ||
    url.password.length > 0 ||
    url.search.length > 0 ||
    url.hash.length > 0
  ) {
    throw new TypeError("unapproved remote reference");
  }
  return url.href;
}

import { Ajv2020 } from "ajv/dist/2020.js";
import type { ErrorObject, ValidateFunction } from "ajv";

import type { ResolvedJsonSchemaValidationOptions } from "./options.ts";
import { prepareSchema, rejectDuplicateEngineIds, type PreparedSchema } from "./schema-policy.ts";
import {
  ControlledReferenceResolver,
  ReferenceResolutionFailure,
  ReferenceTransportFailure
} from "./reference-resolver.ts";
import type { StrictJsonValue } from "../json-document/strict-document.ts";

export type SchemaCompileReason =
  | "duplicate-engine-id"
  | "invalid-document-id"
  | "invalid-schema"
  | "missing-schema-id"
  | "schema-id-mismatch"
  | "unapproved-reference"
  | "unsupported-reference"
  | "remote-document-invalid"
  | "remote-schema-id-mismatch";

export interface LoadedSchema {
  readonly id: string;
  readonly documentValue: StrictJsonValue;
}

export interface CompiledSchemaSet {
  readonly failures: ReadonlyMap<string, SchemaCompileReason>;
  readonly validators: ReadonlyMap<string, ValidateFunction>;
}

/** The only validation fields that may cross from the Ajv adapter to Check-owned Record settlement. */
export interface NormalizedValidationError {
  readonly keyword: string;
  readonly pointer: string;
}

export type CompileSchemaSetResult =
  | Readonly<{ readonly compiledSchemaSet: CompiledSchemaSet; readonly kind: "settled" }>
  | Readonly<{
      readonly kind: "unavailable";
      readonly reason:
        | "engine-unavailable"
        | "execution-cancelled"
        | "reference-transport-unavailable";
    }>;

/** Compiles a closed set without exposing Ajv objects, errors, or resolved remote material to callers. */
export async function compileSchemaSet(input: {
  readonly referenceResolution: ResolvedJsonSchemaValidationOptions["referenceResolution"];
  readonly schemaIdentity: ResolvedJsonSchemaValidationOptions["schemaIdentity"];
  readonly schemas: readonly LoadedSchema[];
  readonly signal: AbortSignal;
}): Promise<CompileSchemaSetResult> {
  if (input.signal.aborted) return unavailable("execution-cancelled");
  const prepared = prepareSchemas(input);
  const resolver = new ControlledReferenceResolver({
    referenceResolution: input.referenceResolution,
    signal: input.signal
  });
  const ajv = createSchemaEngine(resolver);
  if (ajv === undefined) return unavailable("engine-unavailable");
  const registered = registerSchemas(ajv, prepared, input.signal);
  if (registered === undefined) return unavailable("execution-cancelled");
  const validators = await compileRegisteredSchemas(ajv, prepared, registered, input.signal);
  if (validators === "cancelled") return unavailable("execution-cancelled");
  if (validators === "transport-failed") return unavailable("reference-transport-unavailable");

  return Object.freeze({
    compiledSchemaSet: Object.freeze({
      failures: new Map(prepared.failures),
      validators: new Map(validators)
    }),
    kind: "settled"
  });
}

interface PreparedSchemaSet {
  readonly failures: Map<string, SchemaCompileReason>;
  readonly schemas: Map<string, PreparedSchema>;
}

function prepareSchemas(input: {
  readonly schemaIdentity: ResolvedJsonSchemaValidationOptions["schemaIdentity"];
  readonly schemas: readonly LoadedSchema[];
}): PreparedSchemaSet {
  const failures = new Map<string, SchemaCompileReason>();
  const schemas = new Map<string, PreparedSchema>();
  for (const loadedSchema of input.schemas) {
    const preparation = prepareSchema(loadedSchema, input.schemaIdentity.mode);
    if (typeof preparation === "string") failures.set(loadedSchema.id, preparation);
    else schemas.set(loadedSchema.id, preparation);
  }
  rejectDuplicateEngineIds(schemas, failures);
  return { failures, schemas };
}

function createSchemaEngine(resolver: ControlledReferenceResolver): Ajv2020 | undefined {
  try {
    return new Ajv2020({
      allErrors: true,
      coerceTypes: false,
      loadSchema: (uri) => resolver.load(uri),
      logger: false,
      messages: false,
      removeAdditional: false,
      strict: false,
      strictNumbers: true,
      strictRequired: false,
      strictSchema: true,
      strictTuples: false,
      strictTypes: false,
      useDefaults: false,
      validateFormats: false
    });
  } catch {
    return undefined;
  }
}

function registerSchemas(
  ajv: Ajv2020,
  prepared: PreparedSchemaSet,
  signal: AbortSignal
): ReadonlySet<string> | undefined {
  const registered = new Set<string>();
  for (const schema of prepared.schemas.values()) {
    if (signal.aborted) return undefined;
    try {
      ajv.addSchema(schema.engineSchema, schema.engineId);
      registered.add(schema.authoringId);
    } catch {
      prepared.failures.set(schema.authoringId, "invalid-schema");
    }
  }
  return registered;
}

async function compileRegisteredSchemas(
  ajv: Ajv2020,
  prepared: PreparedSchemaSet,
  registered: ReadonlySet<string>,
  signal: AbortSignal
): Promise<ReadonlyMap<string, ValidateFunction> | "cancelled" | "transport-failed"> {
  const validators = new Map<string, ValidateFunction>();
  for (const schema of prepared.schemas.values()) {
    const outcome = await compilePreparedSchema(ajv, schema, registered, signal);
    if (outcome === "cancelled" || outcome === "transport-failed") return outcome;
    if (outcome instanceof ReferenceResolutionFailure)
      prepared.failures.set(schema.authoringId, outcome.reason);
    else if (outcome === "invalid") prepared.failures.set(schema.authoringId, "invalid-schema");
    else if (outcome !== undefined) validators.set(schema.authoringId, outcome);
  }
  return validators;
}

async function compilePreparedSchema(
  ajv: Ajv2020,
  schema: PreparedSchema,
  registered: ReadonlySet<string>,
  signal: AbortSignal
): Promise<
  | ValidateFunction
  | ReferenceResolutionFailure
  | "cancelled"
  | "invalid"
  | "transport-failed"
  | undefined
> {
  if (!registered.has(schema.authoringId)) return undefined;
  if (signal.aborted) return "cancelled";
  try {
    return typeof schema.engineSchema === "boolean"
      ? ajv.compile(schema.engineSchema)
      : await ajv.compileAsync(schema.engineSchema);
  } catch (error) {
    if (signal.aborted) return "cancelled";
    if (error instanceof ReferenceTransportFailure) return "transport-failed";
    return error instanceof ReferenceResolutionFailure ? error : "invalid";
  }
}

/** Converts the only engine-visible error fields into fixed safe validation facts. */
export function normalizeValidationErrors(
  errors: readonly ErrorObject[] | null | undefined
): readonly NormalizedValidationError[] {
  if (errors === null || errors === undefined) return Object.freeze([]);
  const normalized = errors.map((error) =>
    Object.freeze({
      keyword: normalizeKeyword(error.keyword),
      pointer: normalizePointer(error.instancePath)
    })
  );
  normalized.sort((left, right) => {
    const leftKey = `${left.pointer}\n${left.keyword}`;
    const rightKey = `${right.pointer}\n${right.keyword}`;
    if (leftKey < rightKey) return -1;
    if (leftKey > rightKey) return 1;
    return 0;
  });
  return Object.freeze(normalized);
}

function normalizeKeyword(candidateKeyword: unknown): string {
  return typeof candidateKeyword === "string" && KNOWN_KEYWORDS.has(candidateKeyword)
    ? candidateKeyword
    : "other";
}

function normalizePointer(candidatePointer: unknown): string {
  if (typeof candidatePointer !== "string") return "/<redacted>";
  if (candidatePointer === "") return "";
  if (candidatePointer.length > 256 || !candidatePointer.startsWith("/")) {
    return "/<redacted>";
  }
  const segments = candidatePointer.slice(1).split("/");
  return segments.every((segment) => /^[A-Za-z0-9_.-]{1,64}$/u.test(segment))
    ? candidatePointer
    : "/<redacted>";
}

const KNOWN_KEYWORDS: ReadonlySet<string> = new Set([
  "additionalProperties",
  "allOf",
  "anyOf",
  "const",
  "contains",
  "dependentRequired",
  "enum",
  "exclusiveMaximum",
  "exclusiveMinimum",
  "format",
  "if",
  "maxContains",
  "maxItems",
  "maxLength",
  "maxProperties",
  "maximum",
  "minContains",
  "minItems",
  "minLength",
  "minProperties",
  "minimum",
  "multipleOf",
  "not",
  "oneOf",
  "pattern",
  "patternProperties",
  "propertyNames",
  "required",
  "type",
  "unevaluatedItems",
  "unevaluatedProperties",
  "uniqueItems"
]);

function unavailable(
  reason: Extract<CompileSchemaSetResult, { readonly kind: "unavailable" }>["reason"]
): CompileSchemaSetResult {
  return Object.freeze({ kind: "unavailable", reason });
}

import type { AnySchema } from "ajv";

import type { ResolvedJsonSchemaValidationOptions } from "./options.ts";
import type { LoadedSchema, SchemaCompileReason } from "./schema-engine.ts";
import type { StrictJsonValue } from "../json-document/strict-document.ts";

export interface PreparedSchema {
  readonly authoringId: string;
  readonly engineId: string;
  readonly engineSchema: AnySchema;
}

export function prepareSchema(
  loadedSchema: LoadedSchema,
  mode: ResolvedJsonSchemaValidationOptions["schemaIdentity"]["mode"]
): PreparedSchema | SchemaCompileReason {
  if (mode === "configuration-authoritative") {
    const documentValue = withConfigurationIdentity(loadedSchema.documentValue, loadedSchema.id);
    const engineSchema = toAjvSchema(documentValue);
    if (engineSchema === undefined) return "invalid-schema";
    const referenceReason = inspectSchemaPolicy(documentValue);
    if (referenceReason !== undefined) return referenceReason;
    return Object.freeze({
      authoringId: loadedSchema.id,
      engineId: loadedSchema.id,
      engineSchema
    });
  }

  if (!isJsonObject(loadedSchema.documentValue)) return "missing-schema-id";
  const documentId = loadedSchema.documentValue.$id;
  if (typeof documentId !== "string") return "missing-schema-id";
  if (!safeSchemaIdentifier(documentId)) return "invalid-document-id";
  if (mode === "require-match" && documentId !== loadedSchema.id) return "schema-id-mismatch";
  const referenceReason = inspectSchemaPolicy(loadedSchema.documentValue);
  if (referenceReason !== undefined) return referenceReason;
  return Object.freeze({
    authoringId: loadedSchema.id,
    engineId: documentId,
    engineSchema: loadedSchema.documentValue
  });
}

export function rejectDuplicateEngineIds(
  preparedSchemas: Map<string, PreparedSchema>,
  failures: Map<string, SchemaCompileReason>
): void {
  const byEngineId = new Map<string, string[]>();
  for (const preparedSchema of preparedSchemas.values()) {
    const authoringIds = byEngineId.get(preparedSchema.engineId) ?? [];
    authoringIds.push(preparedSchema.authoringId);
    byEngineId.set(preparedSchema.engineId, authoringIds);
  }
  for (const authoringIds of byEngineId.values()) {
    if (authoringIds.length < 2) continue;
    for (const authoringId of authoringIds) {
      preparedSchemas.delete(authoringId);
      failures.set(authoringId, "duplicate-engine-id");
    }
  }
}

function withConfigurationIdentity(
  documentValue: StrictJsonValue,
  configuredSchemaId: string
): StrictJsonValue {
  if (!isJsonObject(documentValue)) return documentValue;
  const copy: Record<string, StrictJsonValue> = {};
  Object.setPrototypeOf(copy, null);
  for (const [key, nested] of Object.entries(documentValue)) {
    Object.defineProperty(copy, key, {
      configurable: false,
      enumerable: true,
      value: key === "$id" ? configuredSchemaId : nested,
      writable: false
    });
  }
  if (!Object.hasOwn(copy, "$id")) {
    Object.defineProperty(copy, "$id", {
      configurable: false,
      enumerable: true,
      value: configuredSchemaId,
      writable: false
    });
  }
  return Object.freeze(copy);
}

/**
 * Inspects only JSON Schema-bearing locations. Annotation payloads and property names are data, not keywords,
 * so they must not be mistaken for `$ref`, `$dynamicRef`, or an Ajv extension.
 */
export function inspectSchemaPolicy(schemaValue: StrictJsonValue): SchemaCompileReason | undefined {
  if (!isJsonObject(schemaValue)) return undefined;
  return inspectSchemaObject(schemaValue);
}

function inspectSchemaObject(
  schemaObject: Readonly<Record<string, StrictJsonValue>>
): SchemaCompileReason | undefined {
  const directReason = inspectDirectSchemaPolicy(schemaObject);
  if (directReason !== undefined) return directReason;
  return inspectNestedSchemaPolicies(schemaObject);
}

function inspectDirectSchemaPolicy(
  schemaObject: Readonly<Record<string, StrictJsonValue>>
): SchemaCompileReason | undefined {
  if (Object.hasOwn(schemaObject, "$async")) return "invalid-schema";
  if (hasUnsupportedReferenceKeyword(schemaObject)) return "unsupported-reference";
  if (Object.hasOwn(schemaObject, "$id") && !permittedNestedIdentifier(schemaObject.$id)) {
    return "unsupported-reference";
  }
  return hasInvalidReferenceValue(schemaObject) ? "unsupported-reference" : undefined;
}

function hasUnsupportedReferenceKeyword(
  schemaObject: Readonly<Record<string, StrictJsonValue>>
): boolean {
  return Object.hasOwn(schemaObject, "$dynamicRef") || Object.hasOwn(schemaObject, "$recursiveRef");
}

function hasInvalidReferenceValue(
  schemaObject: Readonly<Record<string, StrictJsonValue>>
): boolean {
  return ["$ref", "$schema"].some(
    (key) => Object.hasOwn(schemaObject, key) && !permittedReference(schemaObject[key])
  );
}

function inspectNestedSchemaPolicies(
  schemaObject: Readonly<Record<string, StrictJsonValue>>
): SchemaCompileReason | undefined {
  for (const [keyword, keywordValue] of Object.entries(schemaObject)) {
    const reason = inspectNestedSchemaPolicy(keyword, keywordValue);
    if (reason !== undefined) return reason;
  }
  return undefined;
}

function inspectNestedSchemaPolicy(
  keyword: string,
  keywordValue: StrictJsonValue
): SchemaCompileReason | undefined {
  if (SCHEMA_MAP_KEYWORDS.has(keyword)) return inspectSchemaMap(keywordValue);
  if (SCHEMA_VALUE_KEYWORDS.has(keyword)) return inspectSchemaValue(keywordValue);
  if (SCHEMA_ARRAY_KEYWORDS.has(keyword)) return inspectSchemaArray(keywordValue);
  if (keyword === "dependencies") return inspectLegacyDependencies(keywordValue);
  return undefined;
}

function inspectSchemaMap(schemaMap: StrictJsonValue): SchemaCompileReason | undefined {
  if (!isJsonObject(schemaMap)) return undefined;
  for (const nestedSchema of Object.values(schemaMap)) {
    const reason = inspectSchemaValue(nestedSchema);
    if (reason !== undefined) return reason;
  }
  return undefined;
}

function inspectSchemaValue(candidateSchema: StrictJsonValue): SchemaCompileReason | undefined {
  if (!isJsonObject(candidateSchema)) return undefined;
  return inspectSchemaObject(candidateSchema);
}

function inspectSchemaArray(schemaArray: StrictJsonValue): SchemaCompileReason | undefined {
  if (!isStrictJsonArray(schemaArray)) return undefined;
  for (const nestedSchema of schemaArray) {
    const reason = inspectSchemaValue(nestedSchema);
    if (reason !== undefined) return reason;
  }
  return undefined;
}

function inspectLegacyDependencies(
  dependencyMap: StrictJsonValue
): SchemaCompileReason | undefined {
  if (!isJsonObject(dependencyMap)) return undefined;
  for (const dependencySchema of Object.values(dependencyMap)) {
    const reason = inspectSchemaValue(dependencySchema);
    if (reason !== undefined) return reason;
  }
  return undefined;
}

const SCHEMA_MAP_KEYWORDS: ReadonlySet<string> = new Set([
  "$defs",
  "definitions",
  "dependentSchemas",
  "patternProperties",
  "properties"
]);

const SCHEMA_VALUE_KEYWORDS: ReadonlySet<string> = new Set([
  "additionalItems",
  "additionalProperties",
  "contains",
  "contentSchema",
  "else",
  "if",
  "items",
  "not",
  "propertyNames",
  "then",
  "unevaluatedItems",
  "unevaluatedProperties"
]);

const SCHEMA_ARRAY_KEYWORDS: ReadonlySet<string> = new Set([
  "allOf",
  "anyOf",
  "oneOf",
  "prefixItems"
]);

function permittedReference(referenceValue: StrictJsonValue): boolean {
  if (typeof referenceValue !== "string") return false;
  if (referenceValue.startsWith("#")) return true;
  try {
    const url = new URL(referenceValue);
    return (
      (url.protocol === "https:" || url.protocol === "urn:") &&
      url.username.length === 0 &&
      url.password.length === 0 &&
      url.search.length === 0
    );
  } catch {
    return false;
  }
}

function permittedNestedIdentifier(identifierValue: StrictJsonValue): boolean {
  return (
    typeof identifierValue === "string" &&
    (identifierValue.startsWith("#") || safeSchemaIdentifier(identifierValue))
  );
}

function safeSchemaIdentifier(identifier: string): boolean {
  try {
    const url = new URL(identifier);
    return (
      (url.protocol === "https:" || url.protocol === "urn:") &&
      url.username.length === 0 &&
      url.password.length === 0 &&
      url.search.length === 0 &&
      url.hash.length === 0 &&
      url.href === identifier
    );
  } catch {
    return false;
  }
}

export function isJsonObject(
  candidateValue: StrictJsonValue
): candidateValue is Readonly<Record<string, StrictJsonValue>> {
  return (
    typeof candidateValue === "object" &&
    candidateValue !== null &&
    !isStrictJsonArray(candidateValue)
  );
}

function isStrictJsonArray(
  candidateValue: StrictJsonValue
): candidateValue is readonly StrictJsonValue[] {
  return Array.isArray(candidateValue);
}

function toAjvSchema(documentValue: StrictJsonValue): AnySchema | undefined {
  if (typeof documentValue === "boolean") return documentValue;
  if (!isJsonObject(documentValue)) return undefined;
  return documentValue;
}

import { defineCheck, type TypedCheckWithOptions } from "../../check/check.ts";
import { JSON_VALIDATION_CHECK_DEFINITION, executeJsonValidation } from "./json-validation.ts";
import { parseJsonValidationData } from "./final-data.ts";
import type { JsonValidationOptions, ResolvedJsonValidationOptions } from "./options.ts";
import { resolveJsonValidationOptions } from "./options-resolution.ts";
import { validJsonValidationOptions } from "./options-validation.ts";

/**
 * 使用可省略的文件范围与 byte limit 构造严格 JSON document Check。
 *
 * @param options - 省略字段由 package 补齐；显式 files 数组作为对应字段的完整替换值。
 * @returns 固定 `json-validation` identity、完整冻结 options、final-data parser 与执行逻辑。
 * @throws {TypeError} input 含未知字段、非法文件选择或非法 byte limit 时抛出。
 */
export function jsonValidation(
  options: JsonValidationOptions = {}
): TypedCheckWithOptions<
  "json-validation",
  ResolvedJsonValidationOptions,
  typeof parseJsonValidationData
> {
  const resolvedOptions = resolveJsonValidationOptions(options);
  if (resolvedOptions === undefined) {
    throw new TypeError("jsonValidation options must match the documented closed policy");
  }
  return defineCheck({
    ...JSON_VALIDATION_CHECK_DEFINITION,
    execution: executeJsonValidation,
    parseData: parseJsonValidationData,
    preflight: (preparedOptions) =>
      validJsonValidationOptions(preparedOptions)
        ? { status: "success", preparedOptions }
        : {
            status: "failure",
            action: "block",
            reason: { code: "invalid-options" },
            messages: [
              {
                code: "invalid-options",
                level: "error",
                message:
                  "jsonValidation options are invalid; recreate the Check with jsonValidation(options) or restore its complete resolved options."
              }
            ]
          },
    options: resolvedOptions
  });
}

import {
  exactFinalDataRecord,
  invalidFinalData,
  nonNegativeSafeInteger
} from "../final-data-parsing.ts";

/** `json-validation` 在 passed/failed outcome 中发布的主数据。 */
export interface JsonValidationFinalData {
  readonly scannedFileCount: number;
  readonly validFileCount: number;
  readonly invalidFileCount: number;
  readonly issueCount: number;
  readonly rejectedInputCount: number;
}

/** 验证计数不变量并脱离一份 `json-validation` canonical final-data object。 */
export function parseJsonValidationData(data: unknown): JsonValidationFinalData {
  const value = exactFinalDataRecord(
    data,
    ["scannedFileCount", "validFileCount", "invalidFileCount", "issueCount", "rejectedInputCount"],
    "jsonValidation"
  );
  const scannedFileCount = nonNegativeSafeInteger(value.scannedFileCount);
  const validFileCount = nonNegativeSafeInteger(value.validFileCount);
  const invalidFileCount = nonNegativeSafeInteger(value.invalidFileCount);
  const issueCount = nonNegativeSafeInteger(value.issueCount);
  const rejectedInputCount = nonNegativeSafeInteger(value.rejectedInputCount);
  if (
    scannedFileCount === undefined ||
    validFileCount === undefined ||
    invalidFileCount === undefined ||
    issueCount === undefined ||
    rejectedInputCount === undefined ||
    scannedFileCount !== validFileCount + invalidFileCount ||
    issueCount !== invalidFileCount + rejectedInputCount
  ) {
    throw invalidFinalData("jsonValidation");
  }
  return Object.freeze({
    scannedFileCount,
    validFileCount,
    invalidFileCount,
    issueCount,
    rejectedInputCount
  });
}

import { resolve } from "node:path";

import type { CheckExecutionContext, CheckMessage, CheckResult } from "../../check/check.ts";
import {
  readStrictJsonDocument,
  type JsonDocumentIssue
} from "../json-document/strict-document.ts";
import { collectProjectFiles } from "../project-files/collection.ts";
import { partitionProjectFilesByEligibility } from "../project-files/input-eligibility.ts";
import type { JsonValidationFinalData } from "./final-data.ts";
import type { ResolvedJsonValidationOptions } from "./options.ts";
import { validJsonValidationOptions } from "./options-validation.ts";

export const JSON_VALIDATION_CHECK_DEFINITION = {
  checkId: "json-validation",
  displayName: "JSON validation"
} as const;

/** `json-validation` whole-Check unavailable outcome 的稳定 reason code。 */
export type JsonValidationUnavailableCode =
  | "invalid-options"
  | "document-unavailable"
  | "execution-cancelled"
  | "scan-input-unavailable";

/** Validates the lower-case JSON subset selected by this Check's options. */
export function executeJsonValidation(
  context: CheckExecutionContext<ResolvedJsonValidationOptions>
): CheckResult<JsonValidationFinalData> {
  if (!validJsonValidationOptions(context.options)) return unavailable("invalid-options");
  if (context.signal.aborted) return unavailable("execution-cancelled");

  const inputs = jsonInputPaths(context);
  if (inputs === undefined) return unavailable("scan-input-unavailable");
  if (context.signal.aborted) return unavailable("execution-cancelled");
  if (inputs.selectedPathCount === 0) return noEligibleInput();
  reportRejectedInputs(context, inputs.rejectedPaths);
  return appendRejectedInputMessage(
    validateJsonPaths(context, inputs.acceptedPaths, inputs.rejectedPaths.length),
    inputs.rejectedPaths.length
  );
}

function validateJsonPaths(
  context: CheckExecutionContext<ResolvedJsonValidationOptions>,
  paths: readonly string[],
  rejectedInputCount: number
): CheckResult<JsonValidationFinalData> {
  const counts = { invalidFileCount: 0, validFileCount: 0 };
  for (const path of paths) {
    if (context.signal.aborted) return unavailable("execution-cancelled");
    const document = readJsonDocument(context, path);
    if (context.signal.aborted) return unavailable("execution-cancelled");
    if (document.kind === "unavailable") return unavailable("document-unavailable");
    if (document.kind === "valid") {
      counts.validFileCount += 1;
      continue;
    }

    counts.invalidFileCount += 1;
    reportInvalidDocument(context, path, document.reason);
  }

  return resultForValidationCounts(paths.length, rejectedInputCount, counts);
}

interface JsonInputPaths {
  readonly acceptedPaths: readonly string[];
  readonly rejectedPaths: readonly string[];
  readonly selectedPathCount: number;
}

function jsonInputPaths(
  context: CheckExecutionContext<ResolvedJsonValidationOptions>
): JsonInputPaths | undefined {
  try {
    const selectedPaths = collectProjectFiles(context.project.root, context.options.files);
    const partition = partitionProjectFilesByEligibility(selectedPaths, isJsonInputPath);
    return Object.freeze({ ...partition, selectedPathCount: selectedPaths.length });
  } catch {
    return undefined;
  }
}

function isJsonInputPath(path: string): boolean {
  return path.endsWith(".json");
}

function noEligibleInput(): CheckResult<JsonValidationFinalData> {
  return Object.freeze({ status: "not-applicable", reason: { code: "no-eligible-input" } });
}

function readJsonDocument(
  context: CheckExecutionContext<ResolvedJsonValidationOptions>,
  path: string
) {
  return readStrictJsonDocument({
    filePath: resolve(context.project.root, path),
    maximumBytes: context.options.maximumBytes
  });
}

function reportInvalidDocument(
  context: CheckExecutionContext<ResolvedJsonValidationOptions>,
  path: string,
  reason: JsonDocumentIssue
): void {
  const record: JsonValidationRecordData = Object.freeze({ path, reason });
  context.records.report({ id: path }, record);
}

function resultForValidationCounts(
  scannedFileCount: number,
  rejectedInputCount: number,
  counts: Readonly<{ invalidFileCount: number; validFileCount: number }>
): CheckResult<JsonValidationFinalData> {
  const data = Object.freeze({
    scannedFileCount,
    validFileCount: counts.validFileCount,
    invalidFileCount: counts.invalidFileCount,
    issueCount: counts.invalidFileCount + rejectedInputCount,
    rejectedInputCount
  });
  if (counts.invalidFileCount === 0) return Object.freeze({ data, status: "passed" });
  return Object.freeze({
    data,
    messages: Object.freeze([
      Object.freeze({
        code: "invalid-json-documents",
        level: "error" as const,
        message: `${counts.invalidFileCount} JSON document(s) are invalid; inspect this Check's Records for each path and reason.`
      })
    ]),
    status: "failed"
  });
}

function reportRejectedInputs(
  context: CheckExecutionContext<ResolvedJsonValidationOptions>,
  paths: readonly string[]
): void {
  for (const path of paths) {
    const data: JsonValidationInputRejectedRecordData = Object.freeze({
      blocking: false,
      kind: "input-rejected",
      path,
      reason: "unsupported-file-type"
    });
    context.records.report({ id: `/input-rejected/${path}` }, data);
  }
}

function appendRejectedInputMessage(
  result: CheckResult<JsonValidationFinalData>,
  rejectedInputCount: number
): CheckResult<JsonValidationFinalData> {
  if (rejectedInputCount === 0) return result;
  const message: CheckMessage = Object.freeze({
    code: "input-rejected",
    level: "warning",
    message: `${rejectedInputCount} selected jsonValidation input file(s) were rejected because only lower-case .json paths are supported; inspect this Check's Records and narrow files.include/exclude.`
  });
  return Object.freeze({
    ...result,
    messages: Object.freeze([...(result.messages ?? []), message])
  });
}

function unavailable(code: JsonValidationUnavailableCode): CheckResult<JsonValidationFinalData> {
  return Object.freeze({
    status: "unavailable",
    reason: { code },
    messages: Object.freeze([
      Object.freeze({ code, level: "error" as const, message: unavailableMessage(code) })
    ])
  });
}

function unavailableMessage(code: JsonValidationUnavailableCode): string {
  switch (code) {
    case "invalid-options":
      return "jsonValidation options are invalid; recreate the Check with jsonValidation(options) or restore its complete resolved options.";
    case "scan-input-unavailable":
      return "JSON validation could not collect its configured project files; check the project root, permissions, and selected file source.";
    case "document-unavailable":
      return "A selected JSON document could not be read safely; check that the file still exists, is readable, and was not replaced during the Run.";
    case "execution-cancelled":
      return "JSON validation was cancelled before it could form a complete result; inspect the caller's cancellation reason and retry if appropriate.";
  }
}

/** 一条 invalid JSON document supplemental Record 的 data。 */
export interface JsonValidationDocumentRecordData {
  readonly path: string;
  readonly reason: JsonValidationRecordReason;
}

/** 一条 files policy 已选中但不受 JSON validation 支持的输入 Finding。 */
export interface JsonValidationInputRejectedRecordData {
  readonly blocking: false;
  readonly kind: "input-rejected";
  readonly path: string;
  readonly reason: "unsupported-file-type";
}

/** JSON validation 发布的 document issue 或 input-rejection Record data。 */
export type JsonValidationRecordData =
  | JsonValidationDocumentRecordData
  | JsonValidationInputRejectedRecordData;

/** JSON document Record 的稳定问题原因。 */
export type JsonValidationRecordReason = JsonDocumentIssue;

import {
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedRecord
} from "../../data-boundary/closed-values.ts";
import {
  defaultProjectFileSelection,
  resolveProjectFileSelection,
  snapshotProjectFileSelection
} from "../project-files/configuration.ts";
import type { ResolvedJsonValidationOptions } from "./options.ts";
import { validJsonValidationOptions } from "./options-validation.ts";

const DEFAULT_MAXIMUM_BYTES = 1_048_576;
const DEFAULT_FILES = Object.freeze({
  exclude: defaultProjectFileSelection.exclude,
  include: Object.freeze(["**/*.json"]),
  source: defaultProjectFileSelection.source
});

/** 将可省略 JSON validation policy 物化为完整、冻结的 execution options。 */
export function resolveJsonValidationOptions(
  value: unknown
): ResolvedJsonValidationOptions | undefined {
  const input = snapshotClosedRecord(value);
  if (
    input === undefined ||
    !hasRequiredAndOptionalRecordKeys(input, {
      optional: ["files", "maximumBytes"],
      required: []
    })
  ) {
    return undefined;
  }
  const files =
    input.files === undefined
      ? snapshotProjectFileSelection(DEFAULT_FILES)
      : resolveProjectFileSelection(input.files, DEFAULT_FILES);
  const maximumBytes =
    input.maximumBytes === undefined ? DEFAULT_MAXIMUM_BYTES : input.maximumBytes;
  if (
    files === undefined ||
    typeof maximumBytes !== "number" ||
    !Number.isSafeInteger(maximumBytes) ||
    maximumBytes <= 0
  ) {
    return undefined;
  }
  const options = Object.freeze({ files, maximumBytes });
  return validJsonValidationOptions(options) ? options : undefined;
}

import { snapshotExactClosedRecord } from "../../data-boundary/closed-values.ts";
import { isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import { validProjectFileSelection } from "../project-files/configuration.ts";
import type { ResolvedJsonValidationOptions } from "./options.ts";

export function validJsonValidationOptions(value: unknown): value is ResolvedJsonValidationOptions {
  const options = snapshotExactClosedRecord(value, ["files", "maximumBytes"]);
  return (
    options !== undefined &&
    validProjectFileSelection(options.files) &&
    isPositiveSafeInteger(options.maximumBytes)
  );
}

import type {
  ProjectFileSelection,
  ProjectFileSelectionOptions
} from "../project-files/configuration.ts";

/** `jsonValidation(options?)` 接受的可省略 authoring policy。 */
export interface JsonValidationOptions {
  /** 参与本 Check 的 repository-file selection；省略字段使用 package defaults。 */
  readonly files?: ProjectFileSelectionOptions;
  /** 单个 JSON document 允许的最大 raw byte 数；省略时为 1 MiB。 */
  readonly maximumBytes?: number;
}

/** `json-validation` execution 消费的完整、冻结 options。 */
export interface ResolvedJsonValidationOptions {
  readonly files: ProjectFileSelection;
  readonly maximumBytes: number;
}

import type { CheckMessage, CheckResult } from "../../check/check.ts";
import type {
  MaintenanceReminder,
  MaintenanceRemindersUnavailableCode,
  ReminderEvaluation,
  ReminderMeasurement,
  FirstParentHistoryResolution,
  FirstParentHistoryUnavailableReason
} from "./maintenance-reminders.ts";
import type {
  MaintenanceReminderAssessment,
  MaintenanceReminderMode,
  MaintenanceReminderUnavailableReason,
  MaintenanceRemindersFinalData,
  UnavailableMaintenanceReminderAssessment
} from "./final-data.ts";

const REMINDER_MESSAGE_CODE = Object.freeze({
  due: "maintenance-reminder-due",
  unavailable: "maintenance-reminder-unavailable"
});

export function completedResult(
  evaluations: readonly ReminderEvaluation[]
): CheckResult<MaintenanceRemindersFinalData> {
  const assessments = evaluations.map((evaluation) => evaluation.assessment);
  const messages = evaluations.flatMap(messageForEvaluation);
  const failed = evaluations.some(
    (evaluation) =>
      evaluation.assessment.mode === "enforcing" && evaluation.assessment.assessment !== "clear"
  );
  return {
    status: failed ? ("failed" as const) : ("passed" as const),
    data: { entries: assessments },
    ...(messages.length === 0 ? {} : { messages })
  };
}

export function unavailableResult(
  code: MaintenanceRemindersUnavailableCode
): CheckResult<MaintenanceRemindersFinalData> {
  return {
    status: "unavailable" as const,
    reason: { code },
    messages: [{ code, level: "error", message: wholeCheckUnavailableMessage(code) }]
  };
}

function wholeCheckUnavailableMessage(code: MaintenanceRemindersUnavailableCode): string {
  switch (code) {
    case "invalid-options":
      return "maintenanceReminders options are invalid; recreate the Check with maintenanceReminders(entries) or restore its complete resolved options.";
    case "execution-cancelled":
      return "Maintenance reminder evaluation was cancelled before it could form a complete result; inspect the caller's cancellation reason and retry if appropriate.";
    case "maintenance-reminders-internal-failure":
      return "Maintenance reminders could not form a complete ordered assessment; check package/runtime integrity and retry.";
  }
}

function messageForEvaluation(evaluation: ReminderEvaluation): readonly CheckMessage[] {
  const { assessment, message } = evaluation;
  if (assessment.assessment === "clear") return [];
  const level = assessment.mode === "enforcing" ? ("error" as const) : ("warning" as const);
  const suffix = assessment.assessment === "unavailable" ? ` (${assessment.reason})` : "";
  return [
    {
      code:
        assessment.assessment === "due"
          ? REMINDER_MESSAGE_CODE.due
          : REMINDER_MESSAGE_CODE.unavailable,
      level,
      message: `${assessment.id}: ${message}${suffix}`
    }
  ];
}

export function unavailableAssessment(
  entry: Readonly<MaintenanceReminder>,
  headCommit: string | null,
  reason: MaintenanceReminderUnavailableReason
): UnavailableMaintenanceReminderAssessment {
  return {
    assessment: "unavailable",
    baseCommit: entry.baseCommit,
    changedLines: null,
    commitCount: null,
    exceeded: [],
    headCommit,
    id: entry.id,
    mode: modeOf(entry),
    reason
  };
}

export function modeOf(entry: Readonly<MaintenanceReminder>): MaintenanceReminderMode {
  return entry.mode === "enforcing" ? "enforcing" : "advisory";
}

export function unavailableHistory(
  reason: FirstParentHistoryUnavailableReason
): FirstParentHistoryResolution {
  return { kind: "unavailable", reason };
}

export function reminderEvaluation(
  entry: Readonly<MaintenanceReminder>,
  assessment: MaintenanceReminderAssessment
): ReminderEvaluation {
  return { assessment, message: entry.message };
}

export function completedMeasurement(
  entry: Readonly<MaintenanceReminder>,
  assessment: MaintenanceReminderAssessment
): ReminderMeasurement {
  return { kind: "succeeded", value: reminderEvaluation(entry, assessment) };
}

import { snapshotClosedRecord } from "../../data-boundary/closed-values.ts";
import {
  exactFinalDataRecord,
  finalDataArray,
  invalidFinalData,
  nonNegativeSafeInteger
} from "../final-data-parsing.ts";

const EMPTY_EXCEEDED: readonly [] = Object.freeze([]);

const FULL_COMMIT_ID = /^(?:[0-9a-f]{40}|[0-9a-f]{64})$/i;
const REMINDER_ID = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;

/** 单条维护提醒无法测量时使用的稳定 reason code。 */
export const MAINTENANCE_REMINDER_UNAVAILABLE_REASON = Object.freeze({
  baseCommitUnavailable: "base-commit-unavailable",
  baseNotFirstParentAncestor: "base-not-first-parent-ancestor",
  firstParentHistoryInvalid: "first-parent-history-invalid",
  firstParentHistoryUnavailable: "first-parent-history-unavailable",
  headInvalid: "head-invalid",
  headUnavailable: "head-unavailable",
  numstatInvalid: "numstat-invalid",
  numstatUnavailable: "numstat-unavailable"
} as const);

export type MaintenanceReminderMode = "advisory" | "enforcing";

/** 单条维护提醒无法测量时保留在 final data 中的稳定 reason。 */
export type MaintenanceReminderUnavailableReason =
  (typeof MAINTENANCE_REMINDER_UNAVAILABLE_REASON)[keyof typeof MAINTENANCE_REMINDER_UNAVAILABLE_REASON];

const MAINTENANCE_REMINDER_UNAVAILABLE_REASONS: readonly MaintenanceReminderUnavailableReason[] =
  Object.freeze(Object.values(MAINTENANCE_REMINDER_UNAVAILABLE_REASON));

/** 判断 unknown value 是否为维护提醒的稳定局部 ID。 */
export function isMaintenanceReminderId(value: unknown): value is string {
  return typeof value === "string" && REMINDER_ID.test(value);
}

/** 判断 unknown value 是否为 Git 的完整 SHA-1 或 SHA-256 commit ID。 */
export function isMaintenanceCommitId(value: unknown): value is string {
  return typeof value === "string" && FULL_COMMIT_ID.test(value);
}

export type MeasuredMaintenanceReminderAssessment = Readonly<{
  readonly assessment: "clear" | "due";
  readonly baseCommit: string;
  readonly changedLines: number;
  readonly commitCount: number;
  readonly exceeded: readonly ("commits" | "changed-lines")[];
  readonly headCommit: string;
  readonly id: string;
  readonly mode: MaintenanceReminderMode;
}>;

export type UnavailableMaintenanceReminderAssessment = Readonly<{
  readonly assessment: "unavailable";
  readonly baseCommit: string;
  readonly changedLines: null;
  readonly commitCount: null;
  readonly exceeded: readonly [];
  readonly headCommit: string | null;
  readonly id: string;
  readonly mode: MaintenanceReminderMode;
  readonly reason: MaintenanceReminderUnavailableReason;
}>;

/** 单条维护提醒的 measured 或 unavailable discriminated assessment。 */
export type MaintenanceReminderAssessment =
  | MeasuredMaintenanceReminderAssessment
  | UnavailableMaintenanceReminderAssessment;

/** `maintenance-reminders` 在 passed/failed outcome 中发布的主数据。 */
export interface MaintenanceRemindersFinalData {
  readonly entries: readonly MaintenanceReminderAssessment[];
}

/** 验证 discriminated entry assessments 并脱离 canonical final data。 */
export function parseMaintenanceRemindersData(data: unknown): MaintenanceRemindersFinalData {
  const value = exactFinalDataRecord(data, ["entries"], "maintenanceReminders");
  const entries = finalDataArray(value.entries, "maintenanceReminders");
  const parsedEntries: MaintenanceReminderAssessment[] = [];
  const ids = new Set<string>();
  for (const entry of entries) {
    const parsed = parseAssessment(entry);
    if (ids.has(parsed.id)) throw invalidFinalData("maintenanceReminders");
    ids.add(parsed.id);
    parsedEntries.push(parsed);
  }
  return Object.freeze({ entries: Object.freeze(parsedEntries) });
}

function parseAssessment(value: unknown): MaintenanceReminderAssessment {
  const record = assessmentRecord(value);
  const identity = assessmentIdentity(record);
  if (record.assessment === "unavailable") {
    return parseUnavailableAssessment(record, identity);
  }
  return parseMeasuredAssessment(record, identity);
}

function assessmentRecord(value: unknown): Readonly<Record<string, unknown>> {
  return exactFinalDataRecord(
    value,
    valueAssessment(value) === "unavailable"
      ? unavailableAssessmentKeys()
      : measuredAssessmentKeys(),
    "maintenanceReminders"
  );
}

function unavailableAssessmentKeys(): readonly string[] {
  return [
    "assessment",
    "baseCommit",
    "changedLines",
    "commitCount",
    "exceeded",
    "headCommit",
    "id",
    "mode",
    "reason"
  ];
}

function measuredAssessmentKeys(): readonly string[] {
  return [
    "assessment",
    "baseCommit",
    "changedLines",
    "commitCount",
    "exceeded",
    "headCommit",
    "id",
    "mode"
  ];
}

function assessmentIdentity(record: Readonly<Record<string, unknown>>): Readonly<{
  readonly baseCommit: string;
  readonly id: string;
  readonly mode: MaintenanceReminderMode;
}> {
  const id = isMaintenanceReminderId(record.id) ? record.id : undefined;
  const mode = record.mode === "advisory" || record.mode === "enforcing" ? record.mode : undefined;
  const baseCommit = isMaintenanceCommitId(record.baseCommit) ? record.baseCommit : undefined;
  if (id === undefined || mode === undefined || baseCommit === undefined)
    throw invalidFinalData("maintenanceReminders");
  return { baseCommit, id, mode };
}

function parseMeasuredAssessment(
  record: Readonly<Record<string, unknown>>,
  identity: Readonly<{
    readonly baseCommit: string;
    readonly id: string;
    readonly mode: MaintenanceReminderMode;
  }>
): MeasuredMaintenanceReminderAssessment {
  if (record.assessment !== "clear" && record.assessment !== "due")
    throw invalidFinalData("maintenanceReminders");
  const commitCount = nonNegativeSafeInteger(record.commitCount);
  const changedLines = nonNegativeSafeInteger(record.changedLines);
  const headCommit = isMaintenanceCommitId(record.headCommit) ? record.headCommit : undefined;
  const exceeded = parseExceeded(record.exceeded);
  if (
    commitCount === undefined ||
    changedLines === undefined ||
    headCommit === undefined ||
    exceeded === undefined ||
    (record.assessment === "clear" ? exceeded.length !== 0 : exceeded.length === 0)
  ) {
    throw invalidFinalData("maintenanceReminders");
  }
  return Object.freeze({
    assessment: record.assessment,
    baseCommit: identity.baseCommit,
    changedLines,
    commitCount,
    exceeded,
    headCommit,
    id: identity.id,
    mode: identity.mode
  });
}

function parseUnavailableAssessment(
  record: Readonly<Record<string, unknown>>,
  identity: Readonly<{
    readonly baseCommit: string;
    readonly id: string;
    readonly mode: MaintenanceReminderMode;
  }>
): UnavailableMaintenanceReminderAssessment {
  const exceeded = finalDataArray(record.exceeded, "maintenanceReminders");
  const headCommit = record.headCommit;
  if (
    record.changedLines !== null ||
    record.commitCount !== null ||
    exceeded.length !== 0 ||
    (headCommit !== null && !isMaintenanceCommitId(headCommit)) ||
    !isUnavailableReason(record.reason)
  ) {
    throw invalidFinalData("maintenanceReminders");
  }
  return Object.freeze({
    assessment: "unavailable",
    baseCommit: identity.baseCommit,
    changedLines: null,
    commitCount: null,
    exceeded: EMPTY_EXCEEDED,
    headCommit,
    id: identity.id,
    mode: identity.mode,
    reason: record.reason
  });
}

function valueAssessment(value: unknown): unknown {
  return snapshotClosedRecord(value)?.assessment;
}

function parseExceeded(value: unknown): readonly ("commits" | "changed-lines")[] | undefined {
  const entries = finalDataArray(value, "maintenanceReminders");
  const exceeded: ("commits" | "changed-lines")[] = [];
  const uniqueEntries = new Set<string>();
  for (const entry of entries) {
    if ((entry !== "commits" && entry !== "changed-lines") || uniqueEntries.has(entry)) {
      return undefined;
    }
    uniqueEntries.add(entry);
    exceeded.push(entry);
  }
  return Object.freeze(exceeded);
}

function isUnavailableReason(value: unknown): value is MaintenanceReminderUnavailableReason {
  return MAINTENANCE_REMINDER_UNAVAILABLE_REASONS.some((reason) => reason === value);
}

import {
  defineCheck,
  type CheckExecutionContext,
  type CheckResult,
  type TypedCheckWithOptions
} from "../../check/check.ts";
import {
  MAINTENANCE_REMINDER_UNAVAILABLE_REASON,
  parseMaintenanceRemindersData,
  type MaintenanceReminderAssessment,
  type MaintenanceRemindersFinalData
} from "./final-data.ts";
import { runGit } from "./maintenance-support.ts";
import { exactRecord, validEntries, validGit } from "./options-validation.ts";
import {
  completedResult,
  reminderEvaluation,
  unavailableAssessment,
  unavailableHistory,
  unavailableResult
} from "./assessment-results.ts";
import { measureReminder, parseCommitId, parseFirstParentHistory } from "./measurement.ts";

export const MAINTENANCE_REMINDERS_CHECK_ID = "maintenance-reminders";

const MAINTENANCE_REMINDER_OPTION_KEYS: readonly string[] = ["entries", "git"];
const WHOLE_CHECK_UNAVAILABLE_CODE = Object.freeze({
  invalidOptions: "invalid-options",
  executionCancelled: "execution-cancelled",
  internalFailure: "maintenance-reminders-internal-failure"
});

/** 一项维护提醒的项目政策输入。 */
export interface MaintenanceReminder {
  /** 在同一次构造函数调用中唯一的小写短横线命名局部标识。 */
  readonly id: string;
  /** 维护者在完成真实复核后手动推进的不可变完整 Git commit ID。 */
  readonly baseCommit: string;
  /** 超过任一已配置上限时触发该提醒。 */
  readonly limits: Readonly<{
    /** 从基线到 `HEAD` 的 `first-parent` 提交数上限。 */
    readonly commits?: number;
    /** 从基线到 `HEAD` 的累计 Git `numstat` 增加行加删除行上限。 */
    readonly changedLines?: number;
  }>;
  /** 到期或无法评估时展示给人的非空提醒正文。 */
  readonly message: string;
  /** 省略时只提示；`enforcing` 会使到期或不可测量的条目令所属 Check 失败。 */
  readonly mode?: "advisory" | "enforcing";
}

/** `maintenanceReminders` 生成且完全由 Check 持有的选项。 */
export interface MaintenanceReminderOptions {
  /** 保留作者声明顺序的提醒政策条目。 */
  readonly entries: readonly MaintenanceReminder[];
  /** 执行已提交历史测量的 Git 可执行文件。 */
  readonly git: Readonly<{
    readonly executable: string;
  }>;
}

/** `maintenance-reminders` whole-Check unavailable outcome 的稳定 reason code。 */
export type MaintenanceRemindersUnavailableCode =
  (typeof WHOLE_CHECK_UNAVAILABLE_CODE)[keyof typeof WHOLE_CHECK_UNAVAILABLE_CODE];
export type FirstParentHistoryUnavailableReason =
  | typeof MAINTENANCE_REMINDER_UNAVAILABLE_REASON.firstParentHistoryInvalid
  | typeof MAINTENANCE_REMINDER_UNAVAILABLE_REASON.firstParentHistoryUnavailable
  | typeof MAINTENANCE_REMINDER_UNAVAILABLE_REASON.headInvalid
  | typeof MAINTENANCE_REMINDER_UNAVAILABLE_REASON.headUnavailable;

export type ReminderEvaluation = Readonly<{
  readonly assessment: MaintenanceReminderAssessment;
  readonly message: string;
}>;

export type GitCommandResult =
  | Readonly<{ readonly kind: "cancelled" }>
  | Readonly<{ readonly kind: "failed" }>
  | Readonly<{ readonly kind: "succeeded"; readonly stdout: string }>;

export type FirstParentHistory = Readonly<{
  readonly commits: readonly string[];
  readonly headCommit: string;
}>;

export type FirstParentHistoryResolution =
  | Readonly<{ readonly kind: "cancelled" }>
  | Readonly<{ readonly kind: "unavailable"; readonly reason: FirstParentHistoryUnavailableReason }>
  | Readonly<{ readonly kind: "succeeded"; readonly value: FirstParentHistory }>;

export type ReminderMeasurement =
  | Readonly<{ readonly kind: "cancelled" }>
  | Readonly<{ readonly kind: "succeeded"; readonly value: ReminderEvaluation }>;

/**
 * 创建一个固定 ID 的普通 Check，并在其局部最终数据中评估多条维护提醒。
 *
 * @remarks 构造函数只接收项目无法可靠推断的提醒政策；它补齐 Git 可执行文件、身份、可见性和直接执行逻辑。返回值仍是普通 Check，可按现有原生对象组合规则替换完整 `options` 分支。
 * @example 创建一个单一 Check 的维护提醒
 * ```ts
 * import { defineConfig, maintenanceReminders, run } from "@zxyycom/vibe-check";
 *
 * // 下列 baseCommit 都是示例占位值；实际使用时，每条都必须替换为该提醒最近一次真实复核对应的完整 commit ID。
 * const maintenance = maintenanceReminders([
 *   {
 *     id: "documentation-review",
 *     baseCommit: "0123456789abcdef0123456789abcdef01234567",
 *     limits: { commits: 40, changedLines: 2_000 },
 *     message: "Review the documentation structure after this body of change."
 *   },
 *   {
 *     id: "optimization-audit",
 *     baseCommit: "89abcdef0123456789abcdef0123456789abcdef",
 *     limits: { commits: 80 },
 *     message: "Audit optimization quality before this becomes older.",
 *     mode: "enforcing"
 *   }
 * ]);
 *
 * const definition = defineConfig({
 *   checks: [maintenance],
 *   outputs: {
 *     diagnosticLogging: { enabled: false },
 *     machinePublication: { enabled: false },
 *     progressRendering: { enabled: false }
 *   }
 * });
 *
 * const result = await run(definition);
 * if (result.kind !== "completed") throw new Error(`Run did not complete: ${result.kind}`);
 * ```
 */
export function maintenanceReminders(
  entries: readonly MaintenanceReminder[]
): TypedCheckWithOptions<
  typeof MAINTENANCE_REMINDERS_CHECK_ID,
  MaintenanceReminderOptions,
  typeof parseMaintenanceRemindersData
> {
  return defineCheck({
    checkId: MAINTENANCE_REMINDERS_CHECK_ID,
    displayName: "Maintenance reminders",
    execution: executeMaintenanceReminders,
    parseData: parseMaintenanceRemindersData,
    preflight: (options) =>
      validMaintenanceReminderOptions(options)
        ? { status: "success", preparedOptions: options }
        : {
            status: "failure",
            action: "block",
            reason: { code: "invalid-options" },
            messages: [
              {
                code: "invalid-options",
                level: "error",
                message:
                  "maintenanceReminders options are invalid; recreate the Check with maintenanceReminders(entries) or restore its complete resolved options."
              }
            ]
          },
    options: {
      entries,
      git: { executable: "git" }
    },
    visibility: "attention"
  });
}

/** 在普通对象组合后验证完整的选项形状。 */
export function validMaintenanceReminderOptions(
  value: unknown
): value is MaintenanceReminderOptions {
  const options = exactRecord(value, MAINTENANCE_REMINDER_OPTION_KEYS);
  return options !== undefined && validEntries(options.entries) && validGit(options.git);
}

async function executeMaintenanceReminders(
  context: CheckExecutionContext<MaintenanceReminderOptions>
): Promise<CheckResult<MaintenanceRemindersFinalData>> {
  if (!validMaintenanceReminderOptions(context.options))
    return unavailableResult("invalid-options");
  if (context.signal.aborted)
    return unavailableResult(WHOLE_CHECK_UNAVAILABLE_CODE.executionCancelled);

  try {
    const history = await resolveFirstParentHistory({
      executable: context.options.git.executable,
      projectRoot: context.project.root,
      signal: context.signal
    });
    if (history.kind === "cancelled") {
      return unavailableResult(WHOLE_CHECK_UNAVAILABLE_CODE.executionCancelled);
    }

    if (history.kind === "unavailable") {
      return completedResult(
        context.options.entries.map((entry) =>
          reminderEvaluation(entry, unavailableAssessment(entry, null, history.reason))
        )
      );
    }

    const evaluations: ReminderEvaluation[] = [];
    for (const entry of context.options.entries) {
      const measurement = await measureReminder({
        entry,
        executable: context.options.git.executable,
        history: history.value,
        projectRoot: context.project.root,
        signal: context.signal
      });
      if (measurement.kind === "cancelled") {
        return unavailableResult(WHOLE_CHECK_UNAVAILABLE_CODE.executionCancelled);
      }
      evaluations.push(measurement.value);
    }
    return completedResult(evaluations);
  } catch {
    return unavailableResult(WHOLE_CHECK_UNAVAILABLE_CODE.internalFailure);
  }
}

async function resolveFirstParentHistory(input: {
  readonly executable: string;
  readonly projectRoot: string;
  readonly signal: AbortSignal;
}): Promise<FirstParentHistoryResolution> {
  const head = await runGit({
    args: ["rev-parse", "--verify", "HEAD^{commit}"],
    executable: input.executable,
    projectRoot: input.projectRoot,
    signal: input.signal
  });
  if (head.kind === "cancelled") return head;
  if (head.kind === "failed")
    return unavailableHistory(MAINTENANCE_REMINDER_UNAVAILABLE_REASON.headUnavailable);

  const headCommit = parseCommitId(head.stdout);
  if (headCommit === null)
    return unavailableHistory(MAINTENANCE_REMINDER_UNAVAILABLE_REASON.headInvalid);

  const history = await runGit({
    args: ["rev-list", "--first-parent", "HEAD"],
    executable: input.executable,
    projectRoot: input.projectRoot,
    signal: input.signal
  });
  if (history.kind === "cancelled") return history;
  if (history.kind === "failed") {
    return unavailableHistory(
      MAINTENANCE_REMINDER_UNAVAILABLE_REASON.firstParentHistoryUnavailable
    );
  }

  const firstParentHistory = parseFirstParentHistory(history.stdout, headCommit);
  if (firstParentHistory === undefined) {
    return unavailableHistory(MAINTENANCE_REMINDER_UNAVAILABLE_REASON.firstParentHistoryInvalid);
  }

  return {
    kind: "succeeded",
    value: firstParentHistory
  };
}

import { spawn } from "node:child_process";

import type { GitCommandResult } from "./maintenance-reminders.ts";

const MAX_GIT_OUTPUT_BYTES = 64 * 1024 * 1024;

export async function runGit(input: {
  readonly args: readonly string[];
  readonly executable: string;
  readonly projectRoot: string;
  readonly signal: AbortSignal;
}): Promise<GitCommandResult> {
  if (input.signal.aborted) return { kind: "cancelled" };

  return new Promise((resolve) => {
    let settled = false;
    let outputBytes = 0;
    let stdout = "";
    let overflowed = false;
    let child: ReturnType<typeof spawn>;

    const settle = (result: GitCommandResult): void => {
      if (settled) return;
      settled = true;
      input.signal.removeEventListener("abort", abort);
      resolve(result);
    };
    const abort = (): void => {
      child.kill("SIGTERM");
    };

    try {
      child = spawn(input.executable, input.args, {
        cwd: input.projectRoot,
        stdio: ["ignore", "pipe", "ignore"],
        windowsHide: true
      });
    } catch {
      settle({ kind: "failed" });
      return;
    }

    input.signal.addEventListener("abort", abort, { once: true });
    child.stdout?.on("data", (chunk: Buffer | string) => {
      const text = String(chunk);
      outputBytes += Buffer.byteLength(text);
      if (outputBytes > MAX_GIT_OUTPUT_BYTES) {
        overflowed = true;
        child.kill("SIGTERM");
        return;
      }
      stdout += text;
    });
    child.once("error", () =>
      settle(input.signal.aborted ? { kind: "cancelled" } : { kind: "failed" })
    );
    child.once("close", (status) => {
      if (input.signal.aborted) {
        settle({ kind: "cancelled" });
      } else if (overflowed || status !== 0) {
        settle({ kind: "failed" });
      } else {
        settle({ kind: "succeeded", stdout });
      }
    });
  });
}

import {
  isMaintenanceCommitId,
  type MaintenanceReminderAssessment,
  type MaintenanceReminderUnavailableReason
} from "./final-data.ts";
import { completedMeasurement, modeOf, unavailableAssessment } from "./assessment-results.ts";
import { runGit } from "./maintenance-support.ts";
import type {
  FirstParentHistory,
  MaintenanceReminder,
  ReminderMeasurement
} from "./maintenance-reminders.ts";

export async function measureReminder(input: {
  readonly entry: Readonly<MaintenanceReminder>;
  readonly executable: string;
  readonly history: FirstParentHistory;
  readonly projectRoot: string;
  readonly signal: AbortSignal;
}): Promise<ReminderMeasurement> {
  const base = await resolvedBaseCommit(input);
  if (base.kind === "cancelled") return base;
  if (base.kind === "unavailable") return unavailableMeasurement(input, base.reason);
  const changedLines = await measuredChangedLines(input, base.value);
  if (changedLines.kind === "cancelled") return changedLines;
  if (changedLines.kind === "unavailable")
    return unavailableMeasurement(input, changedLines.reason);
  return completedMeasurement(
    input.entry,
    measuredAssessment(input, base.value, changedLines.value)
  );
}

type ReminderMeasureStage<T> =
  | Readonly<{ readonly kind: "cancelled" }>
  | Readonly<{ readonly kind: "complete"; readonly value: T }>
  | Readonly<{
      readonly kind: "unavailable";
      readonly reason: MaintenanceReminderUnavailableReason;
    }>;

async function resolvedBaseCommit(input: {
  readonly entry: Readonly<MaintenanceReminder>;
  readonly executable: string;
  readonly history: FirstParentHistory;
  readonly projectRoot: string;
  readonly signal: AbortSignal;
}): Promise<ReminderMeasureStage<number>> {
  const base = await runGit({
    args: ["rev-parse", "--verify", `${input.entry.baseCommit}^{commit}`],
    executable: input.executable,
    projectRoot: input.projectRoot,
    signal: input.signal
  });
  if (base.kind === "cancelled") return base;
  if (base.kind === "failed") return unavailableMeasure("base-commit-unavailable");

  const baseCommit = parseCommitId(base.stdout);
  if (baseCommit === null) return unavailableMeasure("base-commit-unavailable");

  const baseIndex = input.history.commits.indexOf(baseCommit);
  return baseIndex < 0
    ? unavailableMeasure("base-not-first-parent-ancestor")
    : completeMeasure(baseIndex);
}

async function measuredChangedLines(
  input: {
    readonly executable: string;
    readonly history: FirstParentHistory;
    readonly projectRoot: string;
    readonly signal: AbortSignal;
  },
  baseIndex: number
): Promise<ReminderMeasureStage<number>> {
  let changedLines = 0;
  for (const commit of input.history.commits.slice(0, baseIndex)) {
    const numstat = await runGit({
      args: ["diff-tree", "--no-commit-id", "--numstat", "-r", `${commit}^`, commit],
      executable: input.executable,
      projectRoot: input.projectRoot,
      signal: input.signal
    });
    if (numstat.kind === "cancelled") return numstat;
    if (numstat.kind === "failed") return unavailableMeasure("numstat-unavailable");
    const count = parseChangedLines(numstat.stdout);
    if (count === null || !Number.isSafeInteger(changedLines + count))
      return unavailableMeasure("numstat-invalid");
    changedLines += count;
  }
  return completeMeasure(changedLines);
}

function measuredAssessment(
  input: Readonly<{
    readonly entry: Readonly<MaintenanceReminder>;
    readonly history: FirstParentHistory;
  }>,
  baseIndex: number,
  changedLines: number
): MaintenanceReminderAssessment {
  const mode = modeOf(input.entry);
  const exceeded = [
    ...(input.entry.limits.commits !== undefined && baseIndex > input.entry.limits.commits
      ? (["commits"] as const)
      : []),
    ...(input.entry.limits.changedLines !== undefined &&
    changedLines > input.entry.limits.changedLines
      ? (["changed-lines"] as const)
      : [])
  ];
  return {
    assessment: exceeded.length > 0 ? "due" : "clear",
    baseCommit: input.entry.baseCommit,
    changedLines,
    commitCount: baseIndex,
    exceeded,
    headCommit: input.history.headCommit,
    id: input.entry.id,
    mode
  };
}

function unavailableMeasurement(
  input: Readonly<{
    readonly entry: Readonly<MaintenanceReminder>;
    readonly history: FirstParentHistory;
  }>,
  reason: MaintenanceReminderUnavailableReason
): ReminderMeasurement {
  return completedMeasurement(
    input.entry,
    unavailableAssessment(input.entry, input.history.headCommit, reason)
  );
}

function completeMeasure<T>(value: T): ReminderMeasureStage<T> {
  return { kind: "complete", value };
}

function unavailableMeasure(
  reason: MaintenanceReminderUnavailableReason
): ReminderMeasureStage<never> {
  return { kind: "unavailable", reason };
}

export function parseCommitId(stdout: string): string | null {
  const value = stdout.trim();
  return isMaintenanceCommitId(value) ? value.toLowerCase() : null;
}

export function parseFirstParentHistory(
  stdout: string,
  headCommit: string
): FirstParentHistory | undefined {
  const commits: string[] = [];
  for (const line of stdout.split(/\r?\n/)) {
    if (line.trim().length === 0) continue;
    const commit = parseCommitId(line);
    if (commit === null) return undefined;
    commits.push(commit);
  }
  if (commits.length === 0 || commits[0] !== headCommit) return undefined;
  return Object.freeze({ commits: Object.freeze(commits), headCommit });
}

function parseChangedLines(stdout: string): number | null {
  let changedLines = 0;
  for (const line of stdout.split(/\r?\n/)) {
    if (line.length === 0) continue;
    const [additions, deletions] = line.split("\t", 3);
    if (additions === "-" && deletions === "-") continue;
    if (!decimal(additions) || !decimal(deletions)) return null;
    const count = Number(additions) + Number(deletions);
    if (!Number.isSafeInteger(count) || !Number.isSafeInteger(changedLines + count)) return null;
    changedLines += count;
  }
  return changedLines;
}

function decimal(value: string | undefined): value is string {
  return value !== undefined && /^(?:0|[1-9]\d*)$/.test(value);
}

import { snapshotClosedArray, snapshotClosedRecord } from "../../data-boundary/closed-values.ts";
import { isMaintenanceCommitId, isMaintenanceReminderId } from "./final-data.ts";

const MAINTENANCE_REMINDER_ENTRY_KEYS: readonly string[] = [
  "id",
  "baseCommit",
  "limits",
  "message",
  "mode"
];
const MAINTENANCE_REMINDER_LIMIT_KEYS: readonly string[] = ["commits", "changedLines"];
const MAINTENANCE_REMINDER_GIT_KEYS: readonly string[] = ["executable"];

export function validEntries(value: unknown): boolean {
  const entries = snapshotClosedArray(value);
  if (entries === undefined) return false;
  const identifiers = new Set<string>();
  return entries.every((candidate) => {
    const entry = snapshotClosedRecord(candidate);
    if (entry === undefined || !validEntry(entry)) return false;
    const identifier = entry.id;
    if (typeof identifier !== "string" || identifiers.has(identifier)) return false;
    identifiers.add(identifier);
    return true;
  });
}

function validEntry(entry: Readonly<Record<string, unknown>>): boolean {
  return (
    hasExpectedEntryKeys(entry) &&
    validEntryIdentity(entry) &&
    validLimits(entry.limits) &&
    validEntryMode(entry)
  );
}

function hasExpectedEntryKeys(entry: Readonly<Record<string, unknown>>): boolean {
  return (
    Object.keys(entry).every((key) => MAINTENANCE_REMINDER_ENTRY_KEYS.includes(key)) &&
    ["id", "baseCommit", "limits", "message"].every((key) => Object.hasOwn(entry, key))
  );
}

function validEntryIdentity(entry: Readonly<Record<string, unknown>>): boolean {
  return (
    isMaintenanceReminderId(entry.id) &&
    isMaintenanceCommitId(entry.baseCommit) &&
    typeof entry.message === "string" &&
    entry.message.length > 0
  );
}

function validEntryMode(entry: Readonly<Record<string, unknown>>): boolean {
  return !Object.hasOwn(entry, "mode") || entry.mode === "advisory" || entry.mode === "enforcing";
}

export function validGit(value: unknown): boolean {
  const git = exactRecord(value, MAINTENANCE_REMINDER_GIT_KEYS);
  return git !== undefined && typeof git.executable === "string" && git.executable.length > 0;
}

function validLimits(value: unknown): boolean {
  const limits = snapshotClosedRecord(value);
  if (limits === undefined) return false;
  const keys = Object.keys(limits);
  return (
    keys.length > 0 &&
    keys.every((key) => MAINTENANCE_REMINDER_LIMIT_KEYS.includes(key)) &&
    (!Object.hasOwn(limits, "commits") || positiveSafeInteger(limits.commits)) &&
    (!Object.hasOwn(limits, "changedLines") || positiveSafeInteger(limits.changedLines))
  );
}

export function exactRecord(
  value: unknown,
  keys: readonly string[]
): Readonly<Record<string, unknown>> | undefined {
  const record = snapshotClosedRecord(value);
  return record !== undefined &&
    Object.keys(record).length === keys.length &&
    keys.every((key) => Object.hasOwn(record, key))
    ? record
    : undefined;
}

function positiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

import { defineCheck, type TypedCheckWithOptions } from "../../check/check.ts";
import {
  MARKDOWN_LINK_VALIDATION_CHECK_DEFINITION,
  executeMarkdownLinkValidation
} from "./execution.ts";
import { parseMarkdownLinkValidationData } from "./final-data.ts";
import type {
  MarkdownLinkValidationOptions,
  ResolvedMarkdownLinkValidationOptions
} from "./options.ts";
import { resolveMarkdownLinkValidationOptions } from "./options-resolution.ts";
import { validMarkdownLinkValidationOptions } from "./options-validation.ts";

/**
 * 使用可省略的 source、target 与 work-limit policy 构造离线 Markdown 引用 Check。
 *
 * @param options - 省略字段由 package 补齐；files 数组是完整替换值，limits fields 可分别省略。
 * @returns 固定 `markdown-link-validation` identity、完整冻结 options、parser 与执行逻辑。
 * @throws {TypeError} input 含未知字段、非法 target policy 或非法 work limit 时抛出。
 * @example 离线 Markdown 本地链接完整性
 * ```ts
 * import { defineConfig, markdownLinkValidation, run } from "@zxyycom/vibe-check";
 *
 * const definition = defineConfig({
 *   checks: [markdownLinkValidation()],
 *   outputs: {
 *     diagnosticLogging: { enabled: false },
 *     machinePublication: { enabled: false },
 *     progressRendering: { enabled: false }
 *   }
 * });
 *
 * const result = await run(definition);
 * if (result.kind !== "completed") throw new Error(`Run did not complete: ${result.kind}`);
 * ```
 */
export function markdownLinkValidation(
  options: MarkdownLinkValidationOptions = {}
): TypedCheckWithOptions<
  "markdown-link-validation",
  ResolvedMarkdownLinkValidationOptions,
  typeof parseMarkdownLinkValidationData
> {
  const resolvedOptions = resolveMarkdownLinkValidationOptions(options);
  if (resolvedOptions === undefined) {
    throw new TypeError("markdownLinkValidation options must match the documented closed policy");
  }
  return defineCheck({
    ...MARKDOWN_LINK_VALIDATION_CHECK_DEFINITION,
    execution: executeMarkdownLinkValidation,
    parseData: parseMarkdownLinkValidationData,
    preflight: (preparedOptions) =>
      validMarkdownLinkValidationOptions(preparedOptions)
        ? { status: "success", preparedOptions }
        : {
            status: "failure",
            action: "block",
            reason: { code: "invalid-options" },
            messages: [
              {
                code: "invalid-options",
                level: "error",
                message:
                  "markdownLinkValidation options are invalid; recreate the Check with markdownLinkValidation(options) or restore its complete resolved options."
              }
            ]
          },
    options: resolvedOptions
  });
}

import path from "node:path";

import type { ResolvedMarkdownLinkValidationOptions } from "./options.ts";
import type { CheckExecutionContext, CheckResult } from "../../check/check.ts";
import { collectProjectFiles } from "../project-files/collection.ts";
import type { ProjectFileSelection } from "../project-files/configuration.ts";
import { partitionProjectFilesByEligibility } from "../project-files/input-eligibility.ts";
import { appendCheckMessages } from "../../check/finding-presentation.ts";
import { createMarkdownLocalResolver, type MarkdownLocalResolver } from "./local-resolver.ts";
import type { MarkdownLinkValidationFinalData } from "./final-data.ts";
import { markdownFindingMessages } from "./finding-messages.ts";
import {
  buildMarkdownInputRejectedRecord,
  buildMarkdownLinkRecordCandidate,
  type MarkdownLinkRecordCandidate
} from "./records.ts";
import { settledMarkdownTraversalResult } from "./traversal-result.ts";
import {
  markdownLinkUnavailableMessage,
  type MarkdownLinkValidationUnavailableReason
} from "./unavailable-reasons.ts";
import { validMarkdownLinkValidationOptions } from "./options-validation.ts";

export type { MarkdownLinkValidationUnavailableReason } from "./unavailable-reasons.ts";

export const MARKDOWN_LINK_VALIDATION_CHECK_DEFINITION = {
  checkId: "markdown-link-validation",
  displayName: "Markdown link validation"
} as const;

interface MarkdownLinkValidationRun {
  readonly options: ResolvedMarkdownLinkValidationOptions;
  readonly resolver: MarkdownLocalResolver;
  readonly signal: AbortSignal;
}

type MarkdownLinkValidationUnavailable = Readonly<{
  readonly kind: "unavailable";
  readonly reason: MarkdownLinkValidationUnavailableReason;
}>;

type MarkdownSourceDiscovery =
  | Readonly<{
      readonly kind: "complete";
      readonly rejectedPaths: readonly string[];
      readonly selectedPathCount: number;
      readonly sourcePaths: readonly string[];
    }>
  | MarkdownLinkValidationUnavailable;

type MarkdownSourceValidation =
  | Readonly<{
      readonly kind: "complete";
      readonly candidates: readonly MarkdownLinkRecordCandidate[];
      readonly occurrenceCount: number;
    }>
  | MarkdownLinkValidationUnavailable;

type MarkdownLinkTraversal =
  | Readonly<{
      readonly kind: "complete";
      readonly candidates: readonly MarkdownLinkRecordCandidate[];
      readonly occurrenceCount: number;
      readonly sourceFileCount: number;
    }>
  | MarkdownLinkValidationUnavailable;

/** 验证本 Check 选中的 Markdown source 的离线本地链接完整性。 */
export async function executeMarkdownLinkValidation(
  context: CheckExecutionContext<ResolvedMarkdownLinkValidationOptions>
): Promise<CheckResult<MarkdownLinkValidationFinalData>> {
  if (!validMarkdownLinkValidationOptions(context.options)) return unavailable("invalid-options");
  const prepared = await prepareMarkdownTraversal(context);
  if (prepared.kind === "result") return prepared.result;
  const { rejectedPaths, traversal, resolver } = prepared;

  for (const candidate of traversal.candidates) {
    context.records.report({ id: candidate.id }, candidate.data);
  }
  return appendCheckMessages(
    settledMarkdownTraversalResult({
      findingCount: traversal.candidates.length,
      findingPolicy: context.options.findingPolicy,
      occurrenceCount: traversal.occurrenceCount,
      rejectedInputCount: rejectedPaths.length,
      sourceFileCount: traversal.sourceFileCount,
      targetReadCount: resolver.targetReadCount
    }),
    markdownFindingMessages(
      traversal.candidates,
      rejectedPaths,
      context.options.findingPolicy === "blocking"
    )
  );
}

type PreparedMarkdownTraversal =
  | Readonly<{
      readonly kind: "result";
      readonly result: CheckResult<MarkdownLinkValidationFinalData>;
    }>
  | Readonly<{
      readonly kind: "traversal";
      readonly rejectedPaths: readonly string[];
      readonly resolver: MarkdownLocalResolver;
      readonly traversal: Extract<MarkdownLinkTraversal, { readonly kind: "complete" }>;
    }>;

async function prepareMarkdownTraversal(
  context: CheckExecutionContext<ResolvedMarkdownLinkValidationOptions>
): Promise<PreparedMarkdownTraversal> {
  if (context.signal.aborted) return result(unavailable("cancelled"));
  const created = await createMarkdownLocalResolver(
    context.project.root,
    context.options.limits.maxTargetReads
  );
  if (!created.ok) return result(unavailable(created.reason));
  if (context.signal.aborted) return result(unavailable("cancelled"));
  const sourceDiscovery = discoverMarkdownSourcePaths(context.project, context.options.files);
  if (sourceDiscovery.kind === "unavailable") return result(unavailable(sourceDiscovery.reason));
  if (sourceDiscovery.selectedPathCount === 0) return result(noEligibleInput());
  if (context.signal.aborted) return result(unavailable("cancelled"));
  reportRejectedInputs(context, sourceDiscovery.rejectedPaths);
  const traversal = await traverseMarkdownSources(sourceDiscovery.sourcePaths, {
    resolver: created.resolver,
    options: context.options,
    signal: context.signal
  });
  if (traversal.kind === "unavailable") {
    return result(
      appendRejectedInputMessage(
        unavailable(traversal.reason),
        sourceDiscovery.rejectedPaths.length
      )
    );
  }
  if (context.signal.aborted) {
    return result(
      appendRejectedInputMessage(unavailable("cancelled"), sourceDiscovery.rejectedPaths.length)
    );
  }
  return Object.freeze({
    kind: "traversal",
    rejectedPaths: sourceDiscovery.rejectedPaths,
    resolver: created.resolver,
    traversal
  });
}

function result(
  checkResult: CheckResult<MarkdownLinkValidationFinalData>
): PreparedMarkdownTraversal {
  return Object.freeze({ kind: "result", result: checkResult });
}

function noEligibleInput(): CheckResult<MarkdownLinkValidationFinalData> {
  return Object.freeze({ status: "not-applicable", reason: { code: "no-eligible-input" } });
}

function discoverMarkdownSourcePaths(
  project: CheckExecutionContext<ResolvedMarkdownLinkValidationOptions>["project"],
  files: ProjectFileSelection
): MarkdownSourceDiscovery {
  try {
    const selectedPaths = collectProjectFiles(project.root, files);
    const partition = partitionProjectFilesByEligibility(selectedPaths, isMarkdownSourcePath);
    return Object.freeze({
      kind: "complete" as const,
      rejectedPaths: partition.rejectedPaths,
      selectedPathCount: selectedPaths.length,
      sourcePaths: partition.acceptedPaths
    });
  } catch {
    return unavailableValidation("source-unavailable");
  }
}

function reportRejectedInputs(
  context: CheckExecutionContext<ResolvedMarkdownLinkValidationOptions>,
  paths: readonly string[]
): void {
  for (const selectedPath of paths) {
    const record = buildMarkdownInputRejectedRecord(selectedPath);
    context.records.report({ id: record.id }, record.data);
  }
}

function appendRejectedInputMessage(
  checkResult: CheckResult<MarkdownLinkValidationFinalData>,
  rejectedInputCount: number
): CheckResult<MarkdownLinkValidationFinalData> {
  if (rejectedInputCount === 0) return checkResult;
  return Object.freeze({
    ...checkResult,
    messages: Object.freeze([
      ...(checkResult.messages ?? []),
      Object.freeze({
        code: "input-rejected",
        level: "warning" as const,
        message: `${rejectedInputCount} selected markdownLinkValidation input file(s) were rejected because only .md/.markdown paths are supported; inspect this Check's Records and narrow files.include/exclude.`
      })
    ])
  });
}

function unavailableValidation(
  reason: MarkdownLinkValidationUnavailableReason
): MarkdownLinkValidationUnavailable {
  return Object.freeze({ kind: "unavailable", reason });
}

async function traverseMarkdownSources(
  sourcePaths: readonly string[],
  run: MarkdownLinkValidationRun
): Promise<MarkdownLinkTraversal> {
  const candidates: MarkdownLinkRecordCandidate[] = [];
  let occurrenceCount = 0;
  let sourceFileCount = 0;

  for (const sourcePath of sourcePaths) {
    const sourceValidation = await validateMarkdownSource(sourcePath, occurrenceCount, run);
    if (sourceValidation.kind === "unavailable") return sourceValidation;

    candidates.push(...sourceValidation.candidates);
    occurrenceCount = sourceValidation.occurrenceCount;
    sourceFileCount += 1;
  }

  return Object.freeze({
    kind: "complete" as const,
    candidates: Object.freeze(candidates),
    occurrenceCount,
    sourceFileCount
  });
}

async function validateMarkdownSource(
  sourcePath: string,
  occurrenceCountBeforeSource: number,
  run: MarkdownLinkValidationRun
): Promise<MarkdownSourceValidation> {
  if (run.signal.aborted) return unavailableValidation("cancelled");
  const sourceRead = await run.resolver.readSource(sourcePath, run.options.limits.maxMarkdownBytes);
  if (run.signal.aborted) return unavailableValidation("cancelled");
  if (!sourceRead.ok) return unavailableValidation(sourceRead.reason);

  const candidates: MarkdownLinkRecordCandidate[] = [];
  let occurrenceCount = occurrenceCountBeforeSource;
  for (const [occurrenceIndex, occurrence] of sourceRead.source.facts.occurrences.entries()) {
    if (run.signal.aborted) return unavailableValidation("cancelled");
    occurrenceCount += 1;
    if (occurrenceCount > run.options.limits.maxOccurrences) {
      return unavailableValidation("occurrence-limit-exceeded");
    }

    const resolution = await run.resolver.resolve({
      source: sourceRead.source,
      rawDestination: occurrence.rawDestination,
      rootExternalTargetMode: run.options.rootExternalTargetMode,
      requireExistingTargets: run.options.requireExistingTargets,
      requireNonEmptyDirectories: run.options.requireNonEmptyDirectories,
      validateSameDocumentAnchors: run.options.validateSameDocumentAnchors,
      validateCrossDocumentAnchors: run.options.validateCrossDocumentAnchors,
      maxMarkdownBytes: run.options.limits.maxMarkdownBytes
    });
    if (run.signal.aborted) return unavailableValidation("cancelled");
    if (resolution.kind === "unavailable") return unavailableValidation(resolution.reason);
    const candidate = buildMarkdownLinkRecordCandidate(
      sourceRead.source.path,
      occurrenceIndex,
      occurrence,
      resolution
    );
    if (candidate !== undefined) candidates.push(candidate);
  }

  return Object.freeze({
    kind: "complete" as const,
    candidates: Object.freeze(candidates),
    occurrenceCount
  });
}

function isMarkdownSourcePath(filePath: string): boolean {
  const extension = path.extname(filePath).toLowerCase();
  return extension === ".md" || extension === ".markdown";
}

function unavailable(
  reason: MarkdownLinkValidationUnavailableReason
): CheckResult<MarkdownLinkValidationFinalData> {
  return Object.freeze({
    status: "unavailable",
    reason: { code: reason },
    messages: Object.freeze([
      Object.freeze({
        code: reason,
        level: "error" as const,
        message: markdownLinkUnavailableMessage(reason)
      })
    ])
  });
}

import { constants } from "node:fs";
import { lstat, open, readlink } from "node:fs/promises";
import path from "node:path";

import {
  isNotFound,
  isWithinRoot,
  relativeSegments,
  type EndpointProbe,
  type RootProbe
} from "./local-resolution.ts";

export async function probeRootContainedPath(
  canonicalProjectRoot: string,
  candidatePath: string
): Promise<RootProbe> {
  if (!isWithinRoot(canonicalProjectRoot, candidatePath)) {
    return Object.freeze({ kind: "outside" as const });
  }
  let pendingSegments = relativeSegments(canonicalProjectRoot, candidatePath);
  let currentPath = canonicalProjectRoot;
  let symlinkHops = 0;

  while (pendingSegments.length > 0) {
    const segment = pendingSegments.shift();
    if (segment === undefined) {
      return Object.freeze({ kind: "unavailable" as const });
    }
    const nextPath = path.join(currentPath, segment);
    let status: Awaited<ReturnType<typeof lstat>>;
    try {
      status = await lstat(nextPath);
    } catch (error: unknown) {
      if (isNotFound(error)) {
        return Object.freeze({ kind: "missing" as const, absolutePath: nextPath });
      }
      return Object.freeze({ kind: "unavailable" as const });
    }
    if (!status.isSymbolicLink()) {
      currentPath = nextPath;
      continue;
    }
    if (symlinkHops >= 40) {
      return Object.freeze({ kind: "unavailable" as const });
    }
    symlinkHops += 1;
    let linkDestination: string;
    try {
      linkDestination = path.resolve(path.dirname(nextPath), await readlink(nextPath));
    } catch {
      return Object.freeze({ kind: "unavailable" as const });
    }
    if (!isWithinRoot(canonicalProjectRoot, linkDestination)) {
      return Object.freeze({ kind: "outside" as const });
    }
    pendingSegments = [
      ...relativeSegments(canonicalProjectRoot, linkDestination),
      ...pendingSegments
    ];
    currentPath = canonicalProjectRoot;
  }

  return Object.freeze({ kind: "contained" as const, absolutePath: currentPath });
}

export async function probeEndpoint(targetPath: string): Promise<EndpointProbe> {
  let status: Awaited<ReturnType<typeof lstat>>;
  try {
    status = await lstat(targetPath);
  } catch (error: unknown) {
    return isNotFound(error)
      ? Object.freeze({ kind: "missing" as const })
      : Object.freeze({ kind: "unavailable" as const });
  }
  if (status.isSymbolicLink()) {
    return Object.freeze({ kind: "unavailable" as const });
  }
  if (status.isDirectory()) {
    return Object.freeze({ kind: "directory" as const });
  }
  if (status.isFile()) {
    return Object.freeze({ kind: "file" as const });
  }
  return Object.freeze({ kind: "unsupported" as const });
}

export async function readRegularFile(
  filePath: string,
  maxBytes: number
): Promise<
  | Readonly<{ readonly ok: true; readonly bytes: Uint8Array }>
  | Readonly<{ readonly ok: false; readonly reason: "too-large" | "unavailable" }>
> {
  let handle: Awaited<ReturnType<typeof open>> | undefined;
  try {
    handle = await open(filePath, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
    const status = await handle.stat();
    if (!status.isFile()) {
      return Object.freeze({ ok: false as const, reason: "unavailable" as const });
    }
    if (status.size > maxBytes) {
      return Object.freeze({ ok: false as const, reason: "too-large" as const });
    }
    const bytes = await readBoundedBytes(handle, maxBytes);
    return bytes === null
      ? Object.freeze({ ok: false as const, reason: "too-large" as const })
      : Object.freeze({ ok: true as const, bytes });
  } catch {
    return Object.freeze({ ok: false as const, reason: "unavailable" as const });
  } finally {
    await handle?.close().catch(() => undefined);
  }
}

async function readBoundedBytes(
  handle: Awaited<ReturnType<typeof open>>,
  maxBytes: number
): Promise<Uint8Array | null> {
  const bytes = new Uint8Array(maxBytes + 1);
  let offset = 0;
  while (offset < bytes.byteLength) {
    const result = await handle.read(bytes, offset, bytes.byteLength - offset, offset);
    if (result.bytesRead === 0) break;
    offset += result.bytesRead;
  }
  return offset > maxBytes ? null : bytes.slice(0, offset);
}

import {
  exactFinalDataRecord,
  invalidFinalData,
  nonNegativeSafeInteger
} from "../final-data-parsing.ts";

/** `markdown-link-validation` 在 passed/failed outcome 中发布的主数据。 */
export interface MarkdownLinkValidationFinalData {
  readonly sourceFileCount: number;
  readonly occurrenceCount: number;
  readonly targetReadCount: number;
  readonly findingCount: number;
  readonly rejectedInputCount: number;
}

/** 验证计数不变量并脱离一份 canonical final-data object。 */
export function parseMarkdownLinkValidationData(data: unknown): MarkdownLinkValidationFinalData {
  const value = exactFinalDataRecord(
    data,
    ["sourceFileCount", "occurrenceCount", "targetReadCount", "findingCount", "rejectedInputCount"],
    "markdownLinkValidation"
  );
  const sourceFileCount = nonNegativeSafeInteger(value.sourceFileCount);
  const occurrenceCount = nonNegativeSafeInteger(value.occurrenceCount);
  const targetReadCount = nonNegativeSafeInteger(value.targetReadCount);
  const findingCount = nonNegativeSafeInteger(value.findingCount);
  const rejectedInputCount = nonNegativeSafeInteger(value.rejectedInputCount);
  if (
    sourceFileCount === undefined ||
    occurrenceCount === undefined ||
    targetReadCount === undefined ||
    findingCount === undefined ||
    rejectedInputCount === undefined ||
    targetReadCount > occurrenceCount ||
    findingCount < rejectedInputCount ||
    findingCount - rejectedInputCount > occurrenceCount
  ) {
    throw invalidFinalData("markdownLinkValidation");
  }
  return Object.freeze({
    sourceFileCount,
    occurrenceCount,
    targetReadCount,
    findingCount,
    rejectedInputCount
  });
}

import type { CheckMessage } from "../../check/check.ts";
import { presentCheckFindings } from "../../check/finding-presentation.ts";
import type { MarkdownLinkRecordCandidate } from "./records.ts";

const PRESENTED_FINDING_LIMIT = 10;

type PresentedMarkdownFinding =
  | Readonly<{ readonly kind: "link"; readonly candidate: MarkdownLinkRecordCandidate }>
  | Readonly<{ readonly kind: "input-rejected"; readonly path: string }>;

/** Projects completed Link findings without copying raw destinations into presentation. */
export function markdownFindingMessages(
  candidates: readonly MarkdownLinkRecordCandidate[],
  rejectedPaths: readonly string[],
  blocking: boolean
): readonly CheckMessage[] {
  const findings: PresentedMarkdownFinding[] = [
    ...candidates.map((candidate) => Object.freeze({ kind: "link" as const, candidate })),
    ...rejectedPaths.map((path) => Object.freeze({ kind: "input-rejected" as const, path }))
  ];
  return presentCheckFindings({
    findings,
    limit: PRESENTED_FINDING_LIMIT,
    message: (finding) => {
      if (finding.kind === "input-rejected") {
        return Object.freeze({
          code: "finding-detail",
          level: "warning" as const,
          message: `${finding.path}: selected input is not a supported Markdown source.`
        });
      }
      const { occurrenceKind, range, reason, sourcePath } = finding.candidate.data;
      return Object.freeze({
        code: "finding-detail",
        level: blocking ? ("error" as const) : ("warning" as const),
        message: `${sourcePath}:${range.start.line}:${range.start.column} ${occurrenceKind}: ${reason}.`
      });
    },
    omittedMessage: ({ omittedCount, omittedFindings }) =>
      Object.freeze({
        code: "findings-omitted",
        level: omittedFindings.some((finding) => finding.kind === "link" && blocking)
          ? ("error" as const)
          : ("warning" as const),
        message: `${omittedCount} additional Markdown link finding(s) were not shown; inspect this Check's Records for the complete set.`
      })
  });
}

import path from "node:path";

import type { MarkdownHeading, ParsedMarkdownLinkFacts } from "./markdown-parser.ts";

type RootExternalTargetMode = "ignore" | "report" | "validate";
const NOT_LOCAL_FILE_URI: unique symbol = Symbol("not-local-file-uri");

/** Markdown local-link finding Record 的稳定 reason。 */
export type MarkdownLinkFindingReason =
  | "anchor-on-directory"
  | "anchor-target-not-markdown"
  | "empty-directory"
  | "missing-anchor"
  | "missing-target"
  | "target-outside-project-root"
  | "unsupported-target-type";

type MarkdownLocalResolutionReason =
  | "invalid-local-destination"
  | "target-read-limit-exceeded"
  | "target-unavailable";

type MarkdownSourceReadFailureReason =
  | "markdown-parse-failed"
  | "source-unavailable"
  | "source-too-large";

interface MarkdownLinkSource {
  readonly path: string;
  readonly facts: ParsedMarkdownLinkFacts;
}

interface MarkdownLocalResolver {
  readSource(rootRelativePath: string, maxMarkdownBytes: number): Promise<MarkdownSourceReadResult>;
  resolve(request: MarkdownLocalResolutionRequest): Promise<MarkdownLocalResolution>;
  readonly targetReadCount: number;
}

interface MarkdownLocalResolutionRequest {
  readonly source: MarkdownLinkSource;
  readonly rawDestination: string;
  readonly rootExternalTargetMode: RootExternalTargetMode;
  readonly requireExistingTargets: boolean;
  readonly requireNonEmptyDirectories: boolean;
  readonly validateSameDocumentAnchors: boolean;
  readonly validateCrossDocumentAnchors: boolean;
  readonly maxMarkdownBytes: number;
}

type MarkdownLocalResolverCreation =
  | Readonly<{ readonly ok: true; readonly resolver: MarkdownLocalResolver }>
  | Readonly<{ readonly ok: false; readonly reason: "project-root-unavailable" }>;

type MarkdownSourceReadResult =
  | Readonly<{ readonly ok: true; readonly source: MarkdownLinkSource }>
  | Readonly<{
      readonly ok: false;
      readonly reason: MarkdownSourceReadFailureReason;
    }>;

type MarkdownLocalResolution =
  | Readonly<{ readonly kind: "not-local" | "ignored" }>
  | Readonly<{ readonly kind: "valid"; readonly target: MarkdownSafeTargetDescriptor }>
  | Readonly<{
      readonly kind: "finding";
      readonly reason: MarkdownLinkFindingReason;
      readonly target: MarkdownSafeTargetDescriptor;
    }>
  | Readonly<{ readonly kind: "unavailable"; readonly reason: MarkdownLocalResolutionReason }>;

type MarkdownSafeTargetDescriptor =
  | Readonly<{
      readonly kind: "same-document" | "project-file" | "project-directory" | "project-path";
      readonly path: string;
      readonly fragment: string | null;
    }>
  | Readonly<{ readonly kind: "outside-project-root" }>;

interface ParsedLocalDestination {
  readonly path: string;
  readonly fragment: string | null;
  readonly isAbsolute: boolean;
}

interface RootContainedPath {
  readonly kind: "contained" | "missing";
  readonly absolutePath: string;
}

type RootProbe =
  | RootContainedPath
  | Readonly<{ readonly kind: "outside" }>
  | Readonly<{ readonly kind: "unavailable" }>;

type EndpointProbe =
  | Readonly<{ readonly kind: "missing" }>
  | Readonly<{ readonly kind: "directory" | "file" | "unsupported" | "unavailable" }>;

export function parseLocalDestination(
  rawDestination: string
): ParsedLocalDestination | "not-local" | null {
  if (rawDestination.startsWith("//") || rawDestination.startsWith("\\\\")) {
    return "not-local";
  }
  if (isHostWindowsDriveAbsolute(rawDestination)) {
    return parsePathAndFragment(rawDestination, false);
  }
  const scheme = /^([A-Za-z][A-Za-z\d+.-]*):/u.exec(rawDestination);
  if (scheme !== null) {
    if (scheme[1]?.toLowerCase() !== "file") {
      return "not-local";
    }
    return parseFileDestination(rawDestination);
  }
  if (path.sep !== "\\" && /^[A-Za-z]:[\\/]/u.test(rawDestination)) {
    return "not-local";
  }
  return parsePathAndFragment(rawDestination, false);
}

function parseFileDestination(rawDestination: string): ParsedLocalDestination | "not-local" | null {
  const match = /^file:\/\/(\/.*)$/iu.exec(rawDestination);
  if (match === null) {
    return "not-local";
  }
  const uriPathAndFragment = match[1];
  if (uriPathAndFragment === undefined || uriPathAndFragment.startsWith("//")) {
    return "not-local";
  }
  if (hasUriQuery(uriPathAndFragment) || containsUnsafeRawFileCharacter(uriPathAndFragment)) {
    return "not-local";
  }
  const parsed = parsePathAndFragment(uriPathAndFragment, true);
  if (parsed === null || parsed === "not-local") {
    return parsed;
  }
  return Object.freeze({ ...parsed, isAbsolute: true });
}

function parsePathAndFragment(
  rawDestination: string,
  isFileUri: boolean
): ParsedLocalDestination | "not-local" | null {
  const hashIndex = rawDestination.indexOf("#");
  const queryIndex = rawDestination.indexOf("?");
  const pathEnd = [hashIndex, queryIndex]
    .filter((index) => index >= 0)
    .reduce((smallest, index) => Math.min(smallest, index), rawDestination.length);
  const rawPath = rawDestination.slice(0, pathEnd);
  const rawFragment = hashIndex >= 0 ? rawDestination.slice(hashIndex + 1) : null;
  const decodedPath = decodeLocalComponent(rawPath);
  const decodedFragment = rawFragment === null ? null : decodeLocalComponent(rawFragment);
  if (decodedPath === null || (decodedFragment === null && rawFragment !== null)) {
    return null;
  }
  const resolvedPath = isFileUri ? hostFileUriPath(decodedPath) : decodedPath;
  if (resolvedPath === null) return null;
  if (resolvedPath === NOT_LOCAL_FILE_URI) return "not-local";
  return Object.freeze({
    path: resolvedPath,
    fragment: decodedFragment,
    isAbsolute: isFileUri || path.isAbsolute(resolvedPath)
  });
}

function decodeLocalComponent(rawComponent: string): string | null {
  if (containsControlCharacter(rawComponent) || /%(?:2f|5c|00|0[0-9a-f]|7f)/iu.test(rawComponent)) {
    return null;
  }
  try {
    const decoded = decodeURIComponent(rawComponent);
    return containsControlCharacter(decoded) ? null : decoded;
  } catch {
    return null;
  }
}

function isHostWindowsDriveAbsolute(value: string): boolean {
  return path.sep === "\\" && /^[A-Za-z]:[\\/]/u.test(value);
}

function hostFileUriPath(decodedPath: string): string | typeof NOT_LOCAL_FILE_URI | null {
  if (decodedPath.includes("\\")) return null;
  if (path.sep === "\\") {
    if (!/^\/[A-Za-z]:\//u.test(decodedPath)) return NOT_LOCAL_FILE_URI;
    return path.normalize(decodedPath.slice(1));
  }
  if (/^\/[A-Za-z]:\//u.test(decodedPath)) return NOT_LOCAL_FILE_URI;
  return path.isAbsolute(decodedPath) ? decodedPath : null;
}

function hasUriQuery(uriPathAndFragment: string): boolean {
  const queryIndex = uriPathAndFragment.indexOf("?");
  if (queryIndex < 0) return false;
  const fragmentIndex = uriPathAndFragment.indexOf("#");
  return fragmentIndex < 0 || queryIndex < fragmentIndex;
}

export function anchorResolution(
  headings: readonly MarkdownHeading[],
  fragment: string,
  target: MarkdownSafeTargetDescriptor
): MarkdownLocalResolution {
  return headings.some((heading) => heading.slug === fragment)
    ? valid(target)
    : finding("missing-anchor", target);
}

export function isRootRelativePath(
  canonicalProjectRoot: string,
  rootRelativePath: string
): boolean {
  return (
    !path.isAbsolute(rootRelativePath) &&
    isWithinRoot(canonicalProjectRoot, path.resolve(canonicalProjectRoot, rootRelativePath))
  );
}

export function isWithinRoot(root: string, candidate: string): boolean {
  const relativePath = path.relative(root, candidate);
  return (
    relativePath === "" ||
    (!relativePath.startsWith(`..${path.sep}`) &&
      relativePath !== ".." &&
      !path.isAbsolute(relativePath))
  );
}

export function relativeSegments(root: string, candidate: string): string[] {
  const relativePath = path.relative(root, candidate);
  return relativePath === ""
    ? []
    : relativePath.split(path.sep).filter((segment) => segment !== "");
}

export function sameRootRelativePath(
  rootRelativePath: string,
  targetPath: string,
  canonicalProjectRoot: string
): boolean {
  return toSlashPath(path.relative(canonicalProjectRoot, targetPath)) === rootRelativePath;
}

export function isMarkdownPath(targetPath: string): boolean {
  const extension = path.extname(targetPath).toLowerCase();
  return extension === ".md" || extension === ".markdown";
}

export function toSlashPath(filePath: string): string {
  return filePath.split(path.sep).join("/");
}

function containsUnsafeRawFileCharacter(value: string): boolean {
  return value.includes("\\") || containsControlCharacter(value) || /\s/u.test(value);
}

function containsControlCharacter(value: string): boolean {
  for (const character of value) {
    const codePoint = character.codePointAt(0);
    if (
      codePoint !== undefined &&
      (codePoint <= 0x1f || (codePoint >= 0x7f && codePoint <= 0x9f))
    ) {
      return true;
    }
  }
  return false;
}

export function isNotFound(error: unknown): boolean {
  return typeof error === "object" && error !== null && "code" in error && error.code === "ENOENT";
}

export function sourceUnavailable(): MarkdownSourceReadResult {
  return Object.freeze({ ok: false as const, reason: "source-unavailable" as const });
}

export function valid(target: MarkdownSafeTargetDescriptor): MarkdownLocalResolution {
  return Object.freeze({ kind: "valid" as const, target });
}

export function finding(
  reason: MarkdownLinkFindingReason,
  target: MarkdownSafeTargetDescriptor
): MarkdownLocalResolution {
  return Object.freeze({ kind: "finding" as const, reason, target });
}

export function unavailable(reason: MarkdownLocalResolutionReason): MarkdownLocalResolution {
  return Object.freeze({ kind: "unavailable" as const, reason });
}

