import GithubSlugger from "github-slugger";
import { fromMarkdown } from "mdast-util-from-markdown";
import { frontmatterFromMarkdown } from "mdast-util-frontmatter";
import { gfmFromMarkdown } from "mdast-util-gfm";
import { frontmatter } from "micromark-extension-frontmatter";
import { gfm } from "micromark-extension-gfm";

interface MarkdownAstPoint {
  readonly line: number;
  readonly column: number;
  readonly offset?: number;
}

interface MarkdownAstPosition {
  readonly start: MarkdownAstPoint;
  readonly end: MarkdownAstPoint;
}

interface MarkdownAstNode {
  readonly type: string;
  readonly position?: MarkdownAstPosition;
  readonly children?: readonly MarkdownAstNode[];
  readonly value?: string;
  readonly url?: string;
  readonly identifier?: string;
  readonly alt?: string | null;
}

type MarkdownOccurrenceKind = "image" | "link";

interface MarkdownSourcePosition {
  readonly line: number;
  readonly column: number;
}

interface MarkdownSourceRange {
  readonly startOffset: number;
  readonly endOffset: number;
  readonly start: MarkdownSourcePosition;
  readonly end: MarkdownSourcePosition;
}

interface MarkdownLinkOccurrence {
  readonly kind: MarkdownOccurrenceKind;
  readonly rawDestination: string;
  readonly range: MarkdownSourceRange;
}

interface MarkdownHeading {
  readonly slug: string;
  readonly range: MarkdownSourceRange;
}

interface ParsedMarkdownLinkFacts {
  readonly occurrences: readonly MarkdownLinkOccurrence[];
  readonly headings: readonly MarkdownHeading[];
}

type MarkdownLinkParseResult =
  | Readonly<{
      readonly ok: true;
      readonly facts: ParsedMarkdownLinkFacts;
    }>
  | Readonly<{
      readonly ok: false;
      readonly reason: "markdown-parse-failure";
    }>;

/**
 * Link-private Markdown grammar adapter. It deliberately exposes facts rather
 * than the dependency AST, so resolver ownership starts after parsing.
 */
export function parseMarkdownLinkFacts(markdown: string): MarkdownLinkParseResult {
  if (hasUnpairedSurrogate(markdown)) {
    return parseFailure();
  }

  try {
    const tree: unknown = fromMarkdown(markdown, {
      extensions: [gfm(), frontmatter(["yaml"])],
      mdastExtensions: [gfmFromMarkdown(), frontmatterFromMarkdown(["yaml"])]
    });
    if (!isMarkdownAstNode(tree)) {
      return parseFailure();
    }
    return collectMarkdownLinkFacts(tree);
  } catch {
    return parseFailure();
  }
}

function collectMarkdownLinkFacts(tree: MarkdownAstNode): MarkdownLinkParseResult {
  const definitions = definitionsByIdentifier(tree);
  const occurrences: MarkdownLinkOccurrence[] = [];
  const headings: MarkdownHeading[] = [];
  const slugger = new GithubSlugger();

  forEachNode(tree, (node) => {
    const occurrence = occurrenceFromNode(node, definitions);
    if (occurrence !== null) {
      occurrences.push(occurrence);
    }

    if (node.type === "heading") {
      const heading = headingFromNode(node, slugger);
      if (heading === null) {
        throw new Error("Markdown heading did not include a source range.");
      }
      headings.push(heading);
    }
  });

  return Object.freeze({
    ok: true as const,
    facts: Object.freeze({
      occurrences: Object.freeze(occurrences),
      headings: Object.freeze(headings)
    })
  });
}

function definitionsByIdentifier(tree: MarkdownAstNode): ReadonlyMap<string, string> {
  const definitions = new Map<string, string>();

  forEachNode(tree, (node) => {
    if (node.type !== "definition") {
      return;
    }
    if (node.identifier === undefined || node.url === undefined) {
      throw new Error("Markdown definition was missing a destination.");
    }
    if (!definitions.has(node.identifier)) {
      definitions.set(node.identifier, node.url);
    }
  });

  return definitions;
}

function occurrenceFromNode(
  node: MarkdownAstNode,
  definitions: ReadonlyMap<string, string>
): MarkdownLinkOccurrence | null {
  if (node.type === "link") {
    return occurrenceFromResource(node, "link");
  }
  if (node.type === "image") {
    return occurrenceFromResource(node, "image");
  }
  if (node.type === "linkReference") {
    return occurrenceFromReference(node, "link", definitions);
  }
  if (node.type === "imageReference") {
    return occurrenceFromReference(node, "image", definitions);
  }
  return null;
}

function occurrenceFromResource(
  node: MarkdownAstNode,
  kind: MarkdownOccurrenceKind
): MarkdownLinkOccurrence | null {
  if (node.url === undefined) {
    throw new Error("Markdown occurrence was missing a destination.");
  }
  return occurrenceWithDestination(node, kind, node.url);
}

function occurrenceWithDestination(
  node: MarkdownAstNode,
  kind: MarkdownOccurrenceKind,
  rawDestination: string
): MarkdownLinkOccurrence | null {
  const range = sourceRangeFromPosition(node.position);
  if (range === null) {
    throw new Error("Markdown occurrence did not include a source range.");
  }
  return Object.freeze({ kind, rawDestination, range });
}

function occurrenceFromReference(
  node: MarkdownAstNode,
  kind: MarkdownOccurrenceKind,
  definitions: ReadonlyMap<string, string>
): MarkdownLinkOccurrence | null {
  if (node.identifier === undefined) {
    throw new Error("Markdown reference was missing an identifier.");
  }
  const rawDestination = definitions.get(node.identifier);
  if (rawDestination === undefined) {
    return null;
  }
  return occurrenceWithDestination(node, kind, rawDestination);
}

function headingFromNode(node: MarkdownAstNode, slugger: GithubSlugger): MarkdownHeading | null {
  const range = sourceRangeFromPosition(node.position);
  if (range === null) {
    return null;
  }
  return Object.freeze({
    slug: slugger.slug(markdownText(node)),
    range
  });
}

function markdownText(node: MarkdownAstNode): string {
  if (node.value !== undefined) {
    return node.value;
  }
  if (node.children !== undefined) {
    return node.children.map(markdownText).join("");
  }
  if (node.type === "image" || node.type === "imageReference") {
    return node.alt ?? "";
  }
  return "";
}

function isMarkdownAstNode(value: unknown): value is MarkdownAstNode {
  if (
    typeof value !== "object" ||
    value === null ||
    !("type" in value) ||
    !("children" in value) ||
    !Array.isArray(value.children)
  ) {
    return false;
  }
  return typeof value.type === "string";
}

function sourceRangeFromPosition(
  position: MarkdownAstPosition | undefined
): MarkdownSourceRange | null {
  if (
    position === undefined ||
    position.start.offset === undefined ||
    position.end.offset === undefined
  ) {
    return null;
  }

  return Object.freeze({
    startOffset: position.start.offset,
    endOffset: position.end.offset,
    start: Object.freeze({ line: position.start.line, column: position.start.column }),
    end: Object.freeze({ line: position.end.line, column: position.end.column })
  });
}

function forEachNode(root: MarkdownAstNode, visitor: (node: MarkdownAstNode) => void): void {
  const nodes: MarkdownAstNode[] = [root];

  while (nodes.length > 0) {
    const node = nodes.pop();
    if (node === undefined) {
      return;
    }
    visitor(node);
    if (node.children !== undefined) {
      for (let index = node.children.length - 1; index >= 0; index -= 1) {
        const child = node.children[index];
        if (child !== undefined) {
          nodes.push(child);
        }
      }
    }
  }
}

function hasUnpairedSurrogate(markdown: string): boolean {
  for (let index = 0; index < markdown.length; index += 1) {
    const codeUnit = markdown.charCodeAt(index);
    if (codeUnit >= 0xd800 && codeUnit <= 0xdbff) {
      const nextCodeUnit = markdown.charCodeAt(index + 1);
      if (!(nextCodeUnit >= 0xdc00 && nextCodeUnit <= 0xdfff)) {
        return true;
      }
      index += 1;
      continue;
    }
    if (codeUnit >= 0xdc00 && codeUnit <= 0xdfff) {
      return true;
    }
  }
  return false;
}

function parseFailure(): MarkdownLinkParseResult {
  return Object.freeze({ ok: false as const, reason: "markdown-parse-failure" as const });
}

export type {
  MarkdownHeading,
  MarkdownLinkOccurrence,
  MarkdownLinkParseResult,
  MarkdownOccurrenceKind,
  MarkdownSourcePosition,
  MarkdownSourceRange,
  ParsedMarkdownLinkFacts
};

import { canonicalizeJsonObject } from "../../data-boundary/canonical-data.ts";
import {
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedRecord
} from "../../data-boundary/closed-values.ts";
import {
  defaultProjectFileSelection,
  resolveProjectFileSelection,
  snapshotProjectFileSelection
} from "../project-files/configuration.ts";
import { DEFAULT_FINDING_POLICY, resolveFindingPolicy } from "../code-quality-findings/policy.ts";
import type { ResolvedMarkdownLinkValidationOptions } from "./options.ts";
import { validMarkdownLinkValidationOptions } from "./options-validation.ts";

const DEFAULT_LIMITS = Object.freeze({
  maxMarkdownBytes: 1_048_576,
  maxOccurrences: 10_000,
  maxTargetReads: 1_000
});
const DEFAULT_FILES = Object.freeze({
  exclude: defaultProjectFileSelection.exclude,
  include: Object.freeze(["**/*.[mM][dD]", "**/*.[mM][aA][rR][kK][dD][oO][wW][nN]"]),
  source: defaultProjectFileSelection.source
});

/** 将可省略 Markdown link policy 物化为完整、冻结的 execution options。 */
export function resolveMarkdownLinkValidationOptions(
  value: unknown
): ResolvedMarkdownLinkValidationOptions | undefined {
  const input = snapshotClosedRecord(value);
  if (!isMarkdownLinkValidationInput(input)) return undefined;
  const limits = resolvedLimits(input.limits);
  const files = resolvedFiles(input.files);
  const findingPolicy = resolveFindingPolicy(input.findingPolicy, DEFAULT_FINDING_POLICY);
  if (limits === undefined || files === undefined || findingPolicy === undefined) return undefined;
  const candidate = optionsCandidate(input, files, findingPolicy, limits);
  return candidate !== undefined && validMarkdownLinkValidationOptions(candidate)
    ? candidate
    : undefined;
}

function optionsCandidate(
  input: Readonly<Record<string, unknown>>,
  files: Exclude<ReturnType<typeof resolvedFiles>, undefined>,
  findingPolicy: Exclude<ReturnType<typeof resolveFindingPolicy>, undefined>,
  limits: Readonly<Record<string, unknown>>
) {
  return canonicalizeJsonObject({
    files,
    findingPolicy,
    requireExistingTargets:
      input.requireExistingTargets === undefined ? true : input.requireExistingTargets,
    validateSameDocumentAnchors:
      input.validateSameDocumentAnchors === undefined ? true : input.validateSameDocumentAnchors,
    validateCrossDocumentAnchors:
      input.validateCrossDocumentAnchors === undefined ? true : input.validateCrossDocumentAnchors,
    rootExternalTargetMode:
      input.rootExternalTargetMode === undefined ? "report" : input.rootExternalTargetMode,
    requireNonEmptyDirectories:
      input.requireNonEmptyDirectories === undefined ? false : input.requireNonEmptyDirectories,
    limits
  });
}

function isMarkdownLinkValidationInput(
  input: Readonly<Record<string, unknown>> | undefined
): input is Readonly<Record<string, unknown>> {
  return (
    input !== undefined &&
    hasRequiredAndOptionalRecordKeys(input, {
      optional: [
        "files",
        "findingPolicy",
        "requireExistingTargets",
        "validateSameDocumentAnchors",
        "validateCrossDocumentAnchors",
        "rootExternalTargetMode",
        "requireNonEmptyDirectories",
        "limits"
      ],
      required: []
    })
  );
}

function resolvedFiles(value: unknown) {
  return value === undefined
    ? snapshotProjectFileSelection(DEFAULT_FILES)
    : resolveProjectFileSelection(value, DEFAULT_FILES);
}

function resolvedLimits(value: unknown): Readonly<Record<string, unknown>> | undefined {
  if (value === undefined) return DEFAULT_LIMITS;
  const limits = snapshotClosedRecord(value);
  if (
    limits === undefined ||
    !hasRequiredAndOptionalRecordKeys(limits, {
      optional: ["maxMarkdownBytes", "maxOccurrences", "maxTargetReads"],
      required: []
    })
  ) {
    return undefined;
  }
  return Object.freeze({
    maxMarkdownBytes:
      limits.maxMarkdownBytes === undefined
        ? DEFAULT_LIMITS.maxMarkdownBytes
        : limits.maxMarkdownBytes,
    maxOccurrences:
      limits.maxOccurrences === undefined ? DEFAULT_LIMITS.maxOccurrences : limits.maxOccurrences,
    maxTargetReads:
      limits.maxTargetReads === undefined ? DEFAULT_LIMITS.maxTargetReads : limits.maxTargetReads
  });
}

import { snapshotExactClosedRecord } from "../../data-boundary/closed-values.ts";
import { isPositiveSafeInteger } from "../../data-boundary/value-shapes.ts";
import { validProjectFileSelection } from "../project-files/configuration.ts";
import { validFindingPolicy } from "../code-quality-findings/policy.ts";
import type { ResolvedMarkdownLinkValidationOptions } from "./options.ts";

function boundedPositiveSafeInteger(value: unknown, maximum: number): value is number {
  return isPositiveSafeInteger(value) && value <= maximum;
}

export function validMarkdownLinkValidationOptions(
  value: unknown
): value is ResolvedMarkdownLinkValidationOptions {
  const options = snapshotExactClosedRecord(value, [
    "files",
    "findingPolicy",
    "requireExistingTargets",
    "validateSameDocumentAnchors",
    "validateCrossDocumentAnchors",
    "rootExternalTargetMode",
    "requireNonEmptyDirectories",
    "limits"
  ]);
  return options !== undefined && validOptionFields(options);
}

function validOptionFields(options: Readonly<Record<string, unknown>>): boolean {
  return (
    validProjectFileSelection(options.files) &&
    validFindingPolicy(options.findingPolicy) &&
    validAnchorValidationOptions(options) &&
    validMarkdownLinkLimits(options.limits)
  );
}

function validAnchorValidationOptions(options: Readonly<Record<string, unknown>>): boolean {
  return (
    typeof options.requireExistingTargets === "boolean" &&
    typeof options.validateSameDocumentAnchors === "boolean" &&
    typeof options.validateCrossDocumentAnchors === "boolean" &&
    validRootExternalTargetMode(options.rootExternalTargetMode) &&
    typeof options.requireNonEmptyDirectories === "boolean"
  );
}

function validRootExternalTargetMode(value: unknown): boolean {
  return value === "ignore" || value === "report" || value === "validate";
}

function validMarkdownLinkLimits(value: unknown): boolean {
  const limits = snapshotExactClosedRecord(value, [
    "maxMarkdownBytes",
    "maxOccurrences",
    "maxTargetReads"
  ]);
  return (
    limits !== undefined &&
    boundedPositiveSafeInteger(limits.maxMarkdownBytes, 16_777_216) &&
    boundedPositiveSafeInteger(limits.maxOccurrences, 100_000) &&
    boundedPositiveSafeInteger(limits.maxTargetReads, 10_000)
  );
}

import type {
  ProjectFileSelection,
  ProjectFileSelectionOptions
} from "../project-files/configuration.ts";
import type { FindingPolicy } from "../code-quality-findings/policy.ts";

export type MarkdownRootExternalTargetMode = "ignore" | "report" | "validate";

/** 可省略的 Markdown validation work limits。 */
export interface MarkdownLinkValidationLimitOptions {
  readonly maxMarkdownBytes?: number;
  readonly maxOccurrences?: number;
  readonly maxTargetReads?: number;
}

/** `markdownLinkValidation(options?)` 接受的可省略 authoring policy。 */
export interface MarkdownLinkValidationOptions {
  /** 参与本 Check 的 Markdown source selection；省略字段使用 package defaults。 */
  readonly files?: ProjectFileSelectionOptions;
  /** local-reference finding 是否使本 Check failed；省略时为 non-blocking。 */
  readonly findingPolicy?: FindingPolicy;
  /** `false` 时缺失的本地文件或目录不构成 finding。 */
  readonly requireExistingTargets?: boolean;
  /** 是否检查 `#anchor` 对当前 Markdown 文档标题的引用。 */
  readonly validateSameDocumentAnchors?: boolean;
  /** 是否检查直接指向的 Markdown 文件中的 `#anchor`。 */
  readonly validateCrossDocumentAnchors?: boolean;
  /** root 外本机目标的授权模式；不授权网络请求。 */
  readonly rootExternalTargetMode?: MarkdownRootExternalTargetMode;
  /** 是否将空目录目标视为 finding。 */
  readonly requireNonEmptyDirectories?: boolean;
  /** 每次运行的 Markdown 内容、occurrence 和 direct target work 上限。 */
  readonly limits?: MarkdownLinkValidationLimitOptions;
}

/** `markdown-link-validation` execution 消费的完整、冻结 options。 */
export interface ResolvedMarkdownLinkValidationOptions {
  readonly files: ProjectFileSelection;
  readonly findingPolicy: FindingPolicy;
  readonly requireExistingTargets: boolean;
  readonly validateSameDocumentAnchors: boolean;
  readonly validateCrossDocumentAnchors: boolean;
  readonly rootExternalTargetMode: MarkdownRootExternalTargetMode;
  readonly requireNonEmptyDirectories: boolean;
  readonly limits: Readonly<{
    readonly maxMarkdownBytes: number;
    readonly maxOccurrences: number;
    readonly maxTargetReads: number;
  }>;
}

import type {
  MarkdownLinkFindingReason,
  MarkdownLocalResolution,
  MarkdownSafeTargetDescriptor
} from "./local-resolver.ts";
import type { MarkdownLinkOccurrence, MarkdownSourceRange } from "./markdown-parser.ts";

/** 一条本地 Markdown link finding supplemental Record 的 data。 */
export type MarkdownLinkFindingRecordData = Readonly<{
  readonly occurrenceKind: "link" | "image";
  readonly range: Readonly<{
    readonly end: Readonly<{ readonly column: number; readonly line: number }>;
    readonly start: Readonly<{ readonly column: number; readonly line: number }>;
  }>;
  readonly reason: MarkdownLinkFindingReason;
  readonly sourcePath: string;
  readonly target: MarkdownSafeTargetDescriptor;
}>;

/** 一条 files policy 已选中但不受 Markdown Link 支持的输入 Finding。 */
export type MarkdownLinkInputRejectedRecordData = Readonly<{
  readonly blocking: false;
  readonly kind: "input-rejected";
  readonly path: string;
  readonly reason: "unsupported-file-type";
}>;

/** Markdown Link 发布的 link 或 input-rejection Record data。 */
export type MarkdownLinkValidationRecordData =
  | MarkdownLinkFindingRecordData
  | MarkdownLinkInputRejectedRecordData;

export interface MarkdownLinkRecordCandidate {
  readonly data: MarkdownLinkFindingRecordData;
  readonly id: string;
}

export function buildMarkdownLinkRecordCandidate(
  sourcePath: string,
  occurrenceIndex: number,
  occurrence: MarkdownLinkOccurrence,
  resolution: MarkdownLocalResolution
): MarkdownLinkRecordCandidate | undefined {
  if (resolution.kind !== "finding") return undefined;
  return Object.freeze({
    id: `source:${encodeURIComponent(sourcePath)}:occurrence:${occurrenceIndex + 1}:reason:${resolution.reason}`,
    data: Object.freeze({
      reason: resolution.reason,
      occurrenceKind: occurrence.kind,
      sourcePath,
      range: publicRange(occurrence.range),
      target: resolution.target
    })
  });
}

export function buildMarkdownInputRejectedRecord(path: string): Readonly<{
  readonly data: MarkdownLinkInputRejectedRecordData;
  readonly id: string;
}> {
  return Object.freeze({
    data: Object.freeze({
      blocking: false,
      kind: "input-rejected",
      path,
      reason: "unsupported-file-type"
    }),
    id: `/input-rejected/${path}`
  });
}

function publicRange(range: MarkdownSourceRange): MarkdownLinkFindingRecordData["range"] {
  return Object.freeze({
    start: Object.freeze({ line: range.start.line, column: range.start.column }),
    end: Object.freeze({ line: range.end.line, column: range.end.column })
  });
}

import { opendir } from "node:fs/promises";
import path from "node:path";

import { parseMarkdownLinkFacts } from "./markdown-parser.ts";
import {
  directoryTarget,
  fileTargetDescriptor,
  outsideProjectRootTarget,
  projectTarget
} from "./target-descriptor.ts";
import { probeEndpoint, probeRootContainedPath, readRegularFile } from "./filesystem-probes.ts";
import {
  anchorResolution,
  finding,
  isMarkdownPath,
  isRootRelativePath,
  isWithinRoot,
  parseLocalDestination,
  sameRootRelativePath,
  sourceUnavailable,
  toSlashPath,
  unavailable,
  valid,
  type MarkdownLocalResolution,
  type MarkdownLocalResolutionRequest,
  type MarkdownLocalResolver,
  type MarkdownSafeTargetDescriptor,
  type MarkdownSourceReadResult
} from "./local-resolution.ts";

export class LinkLocalResolver implements MarkdownLocalResolver {
  #targetReadCount = 0;
  readonly #canonicalProjectRoot: string;
  readonly #maxTargetReads: number;

  constructor(canonicalProjectRoot: string, maxTargetReads: number) {
    this.#canonicalProjectRoot = canonicalProjectRoot;
    this.#maxTargetReads = maxTargetReads;
  }

  get targetReadCount(): number {
    return this.#targetReadCount;
  }

  async readSource(
    rootRelativePath: string,
    maxMarkdownBytes: number
  ): Promise<MarkdownSourceReadResult> {
    if (!isRootRelativePath(this.#canonicalProjectRoot, rootRelativePath)) {
      return sourceUnavailable();
    }

    const sourcePath = path.resolve(this.#canonicalProjectRoot, rootRelativePath);
    const rootProbe = await probeRootContainedPath(this.#canonicalProjectRoot, sourcePath);
    if (
      rootProbe.kind === "outside" ||
      rootProbe.kind === "unavailable" ||
      rootProbe.kind === "missing"
    ) {
      return sourceUnavailable();
    }

    const sourceBytes = await readRegularFile(rootProbe.absolutePath, maxMarkdownBytes);
    if (!sourceBytes.ok) {
      return sourceBytes.reason === "too-large"
        ? Object.freeze({ ok: false as const, reason: "source-too-large" as const })
        : sourceUnavailable();
    }

    let markdown: string;
    try {
      markdown = new TextDecoder("utf-8", { fatal: true }).decode(sourceBytes.bytes);
    } catch {
      return sourceUnavailable();
    }

    const parsed = parseMarkdownLinkFacts(markdown);
    if (!parsed.ok) {
      return Object.freeze({ ok: false as const, reason: "markdown-parse-failed" as const });
    }

    return Object.freeze({
      ok: true as const,
      source: Object.freeze({
        path: toSlashPath(path.relative(this.#canonicalProjectRoot, sourcePath)),
        facts: parsed.facts
      })
    });
  }

  async resolve(request: MarkdownLocalResolutionRequest): Promise<MarkdownLocalResolution> {
    const destination = parseLocalDestination(request.rawDestination);
    if (destination === "not-local") {
      return Object.freeze({ kind: "not-local" as const });
    }
    if (destination === null) {
      return unavailable("invalid-local-destination");
    }

    let targetPath: string;
    if (destination.path === "") {
      targetPath = path.resolve(this.#canonicalProjectRoot, request.source.path);
    } else if (destination.isAbsolute) {
      targetPath = path.normalize(destination.path);
    } else {
      targetPath = path.resolve(
        this.#canonicalProjectRoot,
        path.dirname(request.source.path),
        destination.path
      );
    }
    const isSameDocument =
      !destination.isAbsolute &&
      sameRootRelativePath(request.source.path, targetPath, this.#canonicalProjectRoot);
    if (isSameDocument) {
      return this.resolveSameDocument(destination.fragment, request);
    }
    const lexicalTargetIsExternal =
      destination.isAbsolute || !isWithinRoot(this.#canonicalProjectRoot, targetPath);

    if (lexicalTargetIsExternal) {
      return this.resolveExternalTarget(targetPath, destination.fragment, request);
    }

    return this.resolveRootContainedTarget(targetPath, destination.fragment, request);
  }

  async resolveRootContainedTarget(
    targetPath: string,
    fragment: string | null,
    request: MarkdownLocalResolutionRequest
  ): Promise<MarkdownLocalResolution> {
    const rootProbe = await probeRootContainedPath(this.#canonicalProjectRoot, targetPath);
    if (rootProbe.kind === "outside") {
      return this.resolveExternalTarget(targetPath, fragment, request);
    }
    if (rootProbe.kind === "unavailable") {
      return unavailable("target-unavailable");
    }
    if (rootProbe.kind === "missing") {
      if (!this.beginTargetValidation()) {
        return unavailable("target-read-limit-exceeded");
      }
      const target = projectTarget(this.#canonicalProjectRoot, targetPath, fragment);
      return request.requireExistingTargets ? finding("missing-target", target) : valid(target);
    }
    if (!this.beginTargetValidation()) {
      return unavailable("target-read-limit-exceeded");
    }
    return this.resolveEndpoint(
      rootProbe.absolutePath,
      fragment,
      request,
      projectTarget(this.#canonicalProjectRoot, targetPath, fragment)
    );
  }

  async resolveExternalTarget(
    targetPath: string,
    fragment: string | null,
    request: MarkdownLocalResolutionRequest
  ): Promise<MarkdownLocalResolution> {
    if (request.rootExternalTargetMode === "ignore") {
      return Object.freeze({ kind: "ignored" as const });
    }
    if (request.rootExternalTargetMode === "report") {
      return finding("target-outside-project-root", outsideProjectRootTarget());
    }
    if (!this.beginTargetValidation()) {
      return unavailable("target-read-limit-exceeded");
    }
    return this.resolveEndpoint(targetPath, fragment, request, outsideProjectRootTarget());
  }

  async resolveEndpoint(
    targetPath: string,
    fragment: string | null,
    request: MarkdownLocalResolutionRequest,
    target: MarkdownSafeTargetDescriptor
  ): Promise<MarkdownLocalResolution> {
    const endpoint = await probeEndpoint(targetPath);
    if (endpoint.kind === "missing") {
      return request.requireExistingTargets ? finding("missing-target", target) : valid(target);
    }
    if (endpoint.kind === "unavailable") {
      return unavailable("target-unavailable");
    }
    if (endpoint.kind === "directory") {
      return this.resolveDirectory(targetPath, fragment, request, directoryTarget(target));
    }
    if (endpoint.kind === "unsupported") {
      return finding("unsupported-target-type", target);
    }

    return this.resolveFile(targetPath, fragment, request, fileTargetDescriptor(target));
  }

  async resolveFile(
    targetPath: string,
    fragment: string | null,
    request: MarkdownLocalResolutionRequest,
    target: MarkdownSafeTargetDescriptor
  ): Promise<MarkdownLocalResolution> {
    if (fragment === null || !request.validateCrossDocumentAnchors) {
      return valid(target);
    }
    if (!isMarkdownPath(targetPath)) {
      return finding("anchor-target-not-markdown", target);
    }

    const targetMarkdown = await readRegularFile(targetPath, request.maxMarkdownBytes);
    if (!targetMarkdown.ok) {
      return unavailable("target-unavailable");
    }
    let decodedTarget: string;
    try {
      decodedTarget = new TextDecoder("utf-8", { fatal: true }).decode(targetMarkdown.bytes);
    } catch {
      return unavailable("target-unavailable");
    }
    const parsedTarget = parseMarkdownLinkFacts(decodedTarget);
    if (!parsedTarget.ok) {
      return unavailable("target-unavailable");
    }
    return anchorResolution(parsedTarget.facts.headings, fragment, target);
  }

  async resolveDirectory(
    targetPath: string,
    fragment: string | null,
    request: MarkdownLocalResolutionRequest,
    target: MarkdownSafeTargetDescriptor
  ): Promise<MarkdownLocalResolution> {
    if (fragment !== null) {
      return finding("anchor-on-directory", target);
    }
    if (!request.requireNonEmptyDirectories) {
      return valid(target);
    }
    try {
      const directory = await opendir(targetPath);
      try {
        return (await directory.read()) === null
          ? finding("empty-directory", target)
          : valid(target);
      } finally {
        await directory.close();
      }
    } catch {
      return unavailable("target-unavailable");
    }
  }

  beginTargetValidation(): boolean {
    if (this.#targetReadCount >= this.#maxTargetReads) {
      return false;
    }
    this.#targetReadCount += 1;
    return true;
  }

  resolveSameDocument(
    fragment: string | null,
    request: MarkdownLocalResolutionRequest
  ): MarkdownLocalResolution {
    const target = Object.freeze({
      kind: "same-document" as const,
      path: request.source.path,
      fragment
    });
    if (fragment === null || !request.validateSameDocumentAnchors) {
      return valid(target);
    }
    return anchorResolution(request.source.facts.headings, fragment, target);
  }
}

import path from "node:path";

import { toSlashPath, type MarkdownSafeTargetDescriptor } from "./local-resolution.ts";

export function projectTarget(
  canonicalProjectRoot: string,
  targetPath: string,
  fragment: string | null,
  kind: "project-directory" | "project-file" | "project-path" = "project-path"
): MarkdownSafeTargetDescriptor {
  return Object.freeze({
    kind,
    path: toSlashPath(path.relative(canonicalProjectRoot, targetPath)),
    fragment
  });
}

export function outsideProjectRootTarget(): MarkdownSafeTargetDescriptor {
  return Object.freeze({ kind: "outside-project-root" as const });
}

export function fileTargetDescriptor(
  target: MarkdownSafeTargetDescriptor
): MarkdownSafeTargetDescriptor {
  if (target.kind === "outside-project-root") return target;
  return Object.freeze({ ...target, kind: "project-file" as const });
}

export function directoryTarget(
  target: MarkdownSafeTargetDescriptor
): MarkdownSafeTargetDescriptor {
  if (target.kind === "outside-project-root") return target;
  return Object.freeze({ ...target, kind: "project-directory" as const });
}

import type { CheckMessage, CheckResult } from "../../check/check.ts";

import type { MarkdownLinkValidationFinalData } from "./final-data.ts";
import type { ResolvedMarkdownLinkValidationOptions } from "./options.ts";

/** Materializes one completed source traversal into its Check-owned final result. */
export function settledMarkdownTraversalResult(
  input: Readonly<{
    readonly findingCount: number;
    readonly findingPolicy: ResolvedMarkdownLinkValidationOptions["findingPolicy"];
    readonly occurrenceCount: number;
    readonly rejectedInputCount: number;
    readonly sourceFileCount: number;
    readonly targetReadCount: number;
  }>
): CheckResult<MarkdownLinkValidationFinalData> {
  const data = Object.freeze({
    sourceFileCount: input.sourceFileCount,
    occurrenceCount: input.occurrenceCount,
    targetReadCount: input.targetReadCount,
    findingCount: input.findingCount + input.rejectedInputCount,
    rejectedInputCount: input.rejectedInputCount
  });
  const messages: CheckMessage[] = [];
  if (input.findingCount > 0) messages.push(linkFindingMessage(input));
  if (input.rejectedInputCount > 0) messages.push(rejectedInputMessage(input.rejectedInputCount));
  if (messages.length === 0) return Object.freeze({ data, status: "passed" });
  const isBlocking = input.findingPolicy === "blocking";
  return Object.freeze({
    data,
    messages: Object.freeze(messages),
    status: isBlocking && input.findingCount > 0 ? "failed" : "passed"
  });
}

function linkFindingMessage(
  input: Readonly<{
    readonly findingCount: number;
    readonly findingPolicy: ResolvedMarkdownLinkValidationOptions["findingPolicy"];
  }>
): CheckMessage {
  const isBlocking = input.findingPolicy === "blocking";
  return Object.freeze({
    code: "invalid-local-links",
    level: isBlocking ? ("error" as const) : ("warning" as const),
    message: isBlocking
      ? `${input.findingCount} local Markdown link finding(s) require attention; inspect this Check's Records for source ranges, targets, and reasons.`
      : `${input.findingCount} local Markdown link finding(s) were recorded as non-blocking; inspect this Check's Records for source ranges, targets, and reasons.`
  });
}

function rejectedInputMessage(rejectedInputCount: number): CheckMessage {
  return Object.freeze({
    code: "input-rejected",
    level: "warning" as const,
    message: `${rejectedInputCount} selected markdownLinkValidation input file(s) were rejected because only .md/.markdown paths are supported; inspect this Check's Records and narrow files.include/exclude.`
  });
}

import type {
  MarkdownLocalResolutionReason,
  MarkdownSourceReadFailureReason
} from "./local-resolver.ts";

/** `markdown-link-validation` whole-Check unavailable outcome 的稳定 reason code。 */
export type MarkdownLinkValidationUnavailableReason =
  | "invalid-options"
  | "cancelled"
  | "occurrence-limit-exceeded"
  | "project-root-unavailable"
  | MarkdownLocalResolutionReason
  | MarkdownSourceReadFailureReason;

const UNAVAILABLE_MESSAGES: Readonly<Record<MarkdownLinkValidationUnavailableReason, string>> = {
  "invalid-options":
    "markdownLinkValidation options are invalid; recreate the Check with markdownLinkValidation(options) or restore its complete resolved options.",
  "project-root-unavailable":
    "Markdown link validation could not resolve the project root; check that the path exists and is accessible.",
  "source-unavailable":
    "A selected Markdown source could not be collected, read, decoded, or contained safely; check the file source and permissions.",
  "source-too-large":
    "A selected Markdown source exceeds maxMarkdownBytes; narrow the file selection or raise the bounded limit.",
  "markdown-parse-failed":
    "A selected Markdown source could not be parsed completely; inspect that document's Markdown syntax and encoding.",
  "invalid-local-destination":
    "A local Markdown destination could not be parsed safely; inspect the affected link destination syntax.",
  "target-unavailable":
    "A local Markdown target could not be probed or read safely; check the target path, permissions, size, and encoding.",
  "occurrence-limit-exceeded":
    "Markdown link validation exceeded maxOccurrences; narrow the source selection or raise the bounded limit.",
  "target-read-limit-exceeded":
    "Markdown link validation exceeded maxTargetReads; narrow the source selection or raise the bounded limit.",
  cancelled:
    "Markdown link validation was cancelled before it could form a complete result; inspect the caller's cancellation reason and retry if appropriate."
};

export function markdownLinkUnavailableMessage(
  reason: MarkdownLinkValidationUnavailableReason
): string {
  return UNAVAILABLE_MESSAGES[reason];
}

/** Project-root file discovery and selection helpers. */

import { lstatSync } from "node:fs";
import { resolve } from "node:path";

import { matchesAnyConfigGlob } from "./config-glob.ts";
import { collectSubmoduleWorktreeFiles } from "./revision-worktree-files.ts";
import { errorMessage } from "../host-environment/error-message.ts";
import { processFailed } from "../host-environment/process/command.ts";
import { runGit, splitNulDelimitedGitFileList } from "../host-environment/git.ts";
import { toSlashPath } from "../host-environment/path.ts";
import { walkFiles } from "../host-environment/filesystem.ts";
import type { ProjectFileSelection, ProjectFileSource } from "./configuration.ts";

type NamedProjectFileSelection = Readonly<{
  readonly id: string;
  readonly selection: ProjectFileSelection;
}>;

const CONFIG_GLOB_MAGIC = /[\\*?[\]{}()!+@]/u;

/**
 * Resolves multiple named file sets while enumerating each distinct candidate source once.
 */
export function collectProjectFileSets(
  rootDir: string,
  selections: Readonly<Record<string, ProjectFileSelection>>
): ReadonlyMap<string, readonly string[]> {
  const bySource = groupSelectionsBySource(selections);
  const selectedFiles = new Map<string, readonly string[]>();

  for (const [source, sourceSelections] of bySource) {
    const candidates = collectSourceCandidates(rootDir, source, sourceSelections);
    for (const { id, selection } of sourceSelections) {
      selectedFiles.set(id, Object.freeze(filterProjectFiles(candidates, selection)));
    }
  }

  return selectedFiles;
}

export function collectProjectFiles(rootDir: string, selection: ProjectFileSelection): string[] {
  return [...requireProjectFileSet(collectProjectFileSets(rootDir, { selection }), "selection")];
}

/** 返回已收集的命名文件集合；缺失表示收集完整性失效，不能解释为空集合。 */
export function requireProjectFileSet(
  fileSets: ReadonlyMap<string, readonly string[]>,
  selectionId: string
): readonly string[] {
  const selectedFiles = fileSets.get(selectionId);
  if (selectedFiles === undefined) {
    throw new Error(`project file collection did not produce selection ${selectionId}`);
  }
  return selectedFiles;
}

function groupSelectionsBySource(
  selections: Readonly<Record<string, ProjectFileSelection>>
): ReadonlyMap<ProjectFileSource, readonly NamedProjectFileSelection[]> {
  const mutableGroups = new Map<ProjectFileSource, NamedProjectFileSelection[]>();
  const entries = Object.entries(selections).sort(([left], [right]) => compareText(left, right));

  for (const [id, selection] of entries) {
    const group = mutableGroups.get(selection.source) ?? [];
    group.push({ id, selection });
    mutableGroups.set(selection.source, group);
  }

  return new Map(
    [...mutableGroups].map(([source, group]) => [source, Object.freeze(group)] as const)
  );
}

function collectSourceCandidates(
  rootDir: string,
  source: ProjectFileSource,
  selections: readonly NamedProjectFileSelection[]
): readonly string[] {
  switch (source) {
    case "filesystem":
      return uniqueSorted(
        walkFiles({
          ignoredDirs: commonExcludedDirectoryNames(selections),
          rootDir
        }).map(toSlashPath)
      );
    case "git-worktree":
      return collectGitWorktreeCandidates(rootDir, selections);
    default: {
      const unsupportedSource: never = source;
      throw new TypeError(`unsupported project file source: ${String(unsupportedSource)}`);
    }
  }
}

function collectGitWorktreeCandidates(
  rootDir: string,
  selections: readonly NamedProjectFileSelection[]
): readonly string[] {
  const result = runGit({
    args: ["ls-files", "-z", "--cached", "--others", "--exclude-standard", "--"],
    cwd: rootDir
  });
  if (processFailed(result)) {
    const detail =
      result.stderr.trim() ||
      result.error?.message ||
      (result.signal === null ? `exit status ${result.status}` : `signal ${result.signal}`);
    throw new Error(`could not enumerate git-worktree files in ${rootDir}: ${detail}`);
  }

  const include = uniqueSorted(selections.flatMap(({ selection }) => [...selection.include]));
  return uniqueSorted(
    [
      ...splitNulDelimitedGitFileList(result.stdout),
      ...collectSubmoduleWorktreeFiles({ repository: rootDir, scanInputPaths: include })
    ]
      .map(toSlashPath)
      .filter((filePath) => isGitWorktreeFile({ filePath, rootDir }))
  );
}

function isGitWorktreeFile({
  filePath,
  rootDir
}: Readonly<{ readonly filePath: string; readonly rootDir: string }>): boolean {
  try {
    const stats = lstatSync(resolve(rootDir, filePath));
    return stats.isFile() || stats.isSymbolicLink();
  } catch (error: unknown) {
    if (missingPath(error)) return false;
    throw new Error(
      `could not inspect git-worktree candidate ${filePath} in ${rootDir}: ${errorMessage(error)}`,
      { cause: error }
    );
  }
}

function missingPath(error: unknown): boolean {
  const code = error instanceof Error && "code" in error ? error.code : undefined;
  return code === "ENOENT" || code === "ENOTDIR";
}

function filterProjectFiles(
  candidates: readonly string[],
  selection: ProjectFileSelection
): string[] {
  return uniqueSorted(candidates.filter((filePath) => isProjectFile(filePath, selection)));
}

function isProjectFile(filePath: string, selection: ProjectFileSelection): boolean {
  const normalized = toSlashPath(filePath);
  return (
    matchesAnyConfigGlob(normalized, selection.include) &&
    !matchesAnyConfigGlob(normalized, selection.exclude)
  );
}

/**
 * Recognizes only whole-directory exclusions with one literal directory segment. The
 * intersection is a traversal optimization; public semantics remain in `isProjectFile`.
 */
function commonExcludedDirectoryNames(
  selections: readonly NamedProjectFileSelection[]
): readonly string[] {
  let common: Set<string> | undefined;
  for (const { selection } of selections) {
    const names = new Set(selection.exclude.map(literalExcludedDirectoryName).filter(isString));
    common =
      common === undefined
        ? names
        : new Set([...common].filter((directoryName) => names.has(directoryName)));
  }
  return common === undefined ? [] : [...common].sort();
}

function literalExcludedDirectoryName(configGlob: string): string | undefined {
  const prefix = "**/";
  const suffix = "/**";
  if (!configGlob.startsWith(prefix) || !configGlob.endsWith(suffix)) return undefined;
  const directoryName = configGlob.slice(prefix.length, -suffix.length);
  if (directoryName.length === 0 || directoryName.includes("/")) return undefined;
  return CONFIG_GLOB_MAGIC.test(directoryName) ? undefined : directoryName;
}

function isString(value: string | undefined): value is string {
  return value !== undefined;
}

function uniqueSorted(files: readonly string[]): string[] {
  return [...new Set(files)].sort(compareText);
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import { minimatch } from "minimatch";

import { toSlashPath } from "../host-environment/path.ts";

/**
 * Product config glob 的唯一 matcher boundary。
 * Candidate 使用 slash form；dot path 只由显式 glob 决定，不附加隐式忽略规则。
 */
export function matchesAnyConfigGlob(
  candidatePath: string,
  configGlobs: readonly string[]
): boolean {
  const normalizedCandidatePath = toSlashPath(candidatePath);
  return configGlobs.some((configGlob) =>
    minimatch(normalizedCandidatePath, configGlob, { dot: true })
  );
}

import {
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedArray,
  snapshotClosedRecord,
  snapshotExactClosedRecord
} from "../../data-boundary/closed-values.ts";

export const PROJECT_FILE_SOURCES = Object.freeze(["filesystem", "git-worktree"] as const);

/** 文件选择可使用的显式候选来源。 */
export type ProjectFileSource = (typeof PROJECT_FILE_SOURCES)[number];

/** 读取项目文件的 Check 所拥有的文件选择输入。 */
export interface ProjectFileSelectionOptions {
  /** 候选文件来源；省略时使用 owning Check 的来源默认值，当前随包 Check 均为 `filesystem`。 */
  readonly source?: ProjectFileSource;
  /** 相对项目根目录且使用 `/` 的 glob；省略时使用 owning Check 的 include 默认值，显式数组完整替换。 */
  readonly include?: readonly string[];
  /** 优先于 `include` 的 glob；省略时使用 owning Check 的 exclude 默认值，显式数组完整替换。 */
  readonly exclude?: readonly string[];
}

/** Check execution 消费的完整项目文件选择。 */
export interface ProjectFileSelection {
  readonly exclude: readonly string[];
  readonly include: readonly string[];
  readonly source: ProjectFileSource;
}

/**
 * Package-provided Checks 共用的通用文件选择基线。
 *
 * 对象与数组均不可变；需要保留默认排除并追加项目规则时，使用对象与数组 spread 建立新值。
 * 个别 Check 会从此 baseline 派生更精准的默认 include；显式组合此 value 仍表示通配全部路径。
 */
export const defaultProjectFileSelection: ProjectFileSelection = deepFreeze({
  exclude: [
    "**/.cache/**",
    "**/.git",
    "**/.git/**",
    "**/.log/**",
    "**/.pytest_cache/**",
    "**/.tmp/**",
    "**/.venv/**",
    "**/.vibe-check/**",
    "**/__pycache__/**",
    "**/artifacts/**",
    "**/build/**",
    "**/coverage/**",
    "**/dist/**",
    "**/generated/**",
    "**/*.generated.*",
    "**/node_modules/**",
    "**/target/**",
    "**/tmp/**",
    "**/vendor/**",
    "**/venv/**"
  ],
  include: ["**/*"],
  source: "filesystem"
});

/** 按 owning Check 提供的可信完整 defaults 解析并冻结一份 authoring selection。 */
export function resolveProjectFileSelection(
  value: unknown,
  defaults: ProjectFileSelection = defaultProjectFileSelection
): ProjectFileSelection | undefined {
  const selection = snapshotClosedRecord(value);
  if (
    selection === undefined ||
    !hasRequiredAndOptionalRecordKeys(selection, {
      optional: ["exclude", "include", "source"],
      required: []
    })
  ) {
    return undefined;
  }

  const exclude = resolveStringArray(selection.exclude, defaults.exclude);
  const include = resolveStringArray(selection.include, defaults.include);
  const source = selection.source ?? defaults.source;
  if (exclude === undefined || include === undefined || !isProjectFileSource(source)) {
    return undefined;
  }

  return Object.freeze({ exclude, include, source });
}

export function snapshotDefaultProjectFileSelection(): ProjectFileSelection {
  return snapshotProjectFileSelection(defaultProjectFileSelection);
}

/** 为 owning Check 对可信的完整 selection 建立 detached、冻结快照。 */
export function snapshotProjectFileSelection(
  selection: ProjectFileSelection
): ProjectFileSelection {
  return Object.freeze({
    exclude: Object.freeze([...selection.exclude]),
    include: Object.freeze([...selection.include]),
    source: selection.source
  });
}

export function validProjectFileSelection(value: unknown): value is ProjectFileSelection {
  const selection = snapshotExactClosedRecord(value, ["exclude", "include", "source"]);
  return (
    selection !== undefined &&
    validStringArray(selection.exclude) &&
    validStringArray(selection.include) &&
    isProjectFileSource(selection.source)
  );
}

function isProjectFileSource(value: unknown): value is ProjectFileSource {
  return PROJECT_FILE_SOURCES.some((source) => source === value);
}

function resolveStringArray(
  value: unknown,
  fallback: readonly string[]
): readonly string[] | undefined {
  if (value === undefined) return Object.freeze([...fallback]);
  const items = snapshotClosedArray(value);
  if (items === undefined || !items.every(isString)) return undefined;
  return Object.freeze([...items]);
}

function validStringArray(value: unknown): boolean {
  const items = snapshotClosedArray(value);
  return items !== undefined && items.every(isString);
}

function isString(value: unknown): value is string {
  return typeof value === "string";
}

function deepFreeze<T>(value: T): T {
  if (typeof value !== "object" || value === null || Object.isFrozen(value)) return value;
  for (const nested of Object.values(value)) deepFreeze(nested);
  return Object.freeze(value);
}

export type ExactInputMeasurement<T> = {
  readonly payload: T;
  readonly sourcePaths: readonly string[];
};

export type ExactInputMeasurementAcceptance<T> =
  | { readonly ok: true; readonly payloads: readonly T[] }
  | { readonly error: string; readonly ok: false };

export function acceptExactInputMeasurements<T>(
  measurements: readonly ExactInputMeasurement<T>[],
  approvedExactPaths: readonly string[]
): ExactInputMeasurementAcceptance<T> {
  const approvedPathSet = new Set(approvedExactPaths);

  for (const [index, measurement] of measurements.entries()) {
    if (measurement.sourcePaths.length === 0) {
      return {
        error: `scanner measurement #${index + 1} did not declare a source path`,
        ok: false
      };
    }

    for (const sourcePath of measurement.sourcePaths) {
      if (!approvedPathSet.has(sourcePath)) {
        return {
          error: `scanner measurement #${index + 1} references unapproved input path ${JSON.stringify(sourcePath)}`,
          ok: false
        };
      }
    }
  }

  return {
    ok: true,
    payloads: measurements.map((measurement) => measurement.payload)
  };
}

import { createHash } from "node:crypto";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

export interface FileInputFingerprint {
  readonly fileCount: number;
  readonly fileList: readonly string[];
  readonly fingerprint: string;
}

/** Fingerprints one exact path set from stable path order and normalized current file content. */
export function fingerprintProjectFiles(
  rootDir: string,
  paths: readonly string[]
): FileInputFingerprint {
  const sortedPaths = [...paths].sort(compareText);
  const inputDigest = createHash("sha256");

  for (const path of sortedPaths) {
    inputDigest.update(path, "utf8");
    inputDigest.update("\0");
    inputDigest.update(fileContentFingerprint(rootDir, path), "utf8");
    inputDigest.update("\n");
  }

  return Object.freeze({
    fileCount: sortedPaths.length,
    fileList: Object.freeze(sortedPaths.slice(0, 200)),
    fingerprint: `sha256:${inputDigest.digest("hex")}:${sortedPaths.length}`
  });
}

function fileContentFingerprint(rootDir: string, path: string): string {
  try {
    const content = readFileSync(resolve(rootDir, path), "utf8").replace(/\r\n?/g, "\n");
    return createHash("sha256").update(content).digest("hex");
  } catch {
    return "file-not-readable";
  }
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

/** Reads canonical gitlink entries from a named Git tree revision. */

import { processFailed } from "../host-environment/process/command.ts";
import { runGit } from "../host-environment/git.ts";
import { toSlashPath } from "../host-environment/path.ts";

export type Gitlink = Readonly<{
  readonly path: string;
  readonly sha: string;
}>;

export function gitlinksAtRevision({
  repository,
  revision
}: Readonly<{
  readonly repository: string;
  readonly revision: string;
}>): readonly Gitlink[] {
  const result = runGit({
    args: ["ls-tree", "-r", "-z", revision],
    cwd: repository
  });
  if (processFailed(result)) {
    const detail =
      result.stderr.trim() ||
      result.error?.message ||
      (result.signal === null ? `exit status ${result.status}` : `signal ${result.signal}`);
    throw new Error(`could not inspect gitlinks at ${revision} in ${repository}: ${detail}`);
  }

  const gitlinks: Gitlink[] = [];
  for (const entry of result.stdout.split("\0")) {
    if (!entry) continue;
    const gitlink = parseGitlinkEntry({ entry, repository, revision });
    if (gitlink !== null) gitlinks.push(gitlink);
  }
  return Object.freeze(gitlinks);
}

function parseGitlinkEntry({
  entry,
  repository,
  revision
}: Readonly<{
  readonly entry: string;
  readonly repository: string;
  readonly revision: string;
}>): Gitlink | null {
  const parsed = gitTreeEntryParts(entry);
  if (parsed === undefined) throw invalidTreeOutput(revision, repository);
  const [mode, type, sha] = parsed.metadata;
  if (!validGitTreeMetadata(mode, type, sha)) throw invalidTreeOutput(revision, repository);
  if (mode !== "160000") return null;
  if (type !== "commit") {
    throw new Error(`invalid gitlink output at ${revision} in ${repository}`);
  }
  return Object.freeze({ path: toSlashPath(parsed.path), sha });
}

function gitTreeEntryParts(entry: string): { metadata: string[]; path: string } | undefined {
  const separator = entry.indexOf("\t");
  if (separator < 0) return undefined;
  const metadata = entry.slice(0, separator).split(/\s+/u);
  const path = entry.slice(separator + 1);
  return metadata.length === 3 && path.length > 0 ? { metadata, path } : undefined;
}

function validGitTreeMetadata(
  mode: string | undefined,
  type: string | undefined,
  sha: string | undefined
): sha is string {
  return mode !== undefined && type !== undefined && sha !== undefined && isFullGitObjectId(sha);
}

function invalidTreeOutput(revision: string, repository: string): Error {
  return new Error(`invalid git tree output at ${revision} in ${repository}`);
}

function isFullGitObjectId(value: string): boolean {
  return /^(?:[0-9a-f]{40}|[0-9a-f]{64})$/u.test(value);
}

/** Canonical Git worktree checks for gitlink traversal. */

import { realpathSync, statSync } from "node:fs";
import { resolve } from "node:path";

import { errorMessage } from "../host-environment/error-message.ts";
import { processFailed } from "../host-environment/process/command.ts";
import { runGit } from "../host-environment/git.ts";

export type GitlinkWorktreeInspection =
  | { readonly kind: "initialized"; readonly repository: string }
  | { readonly kind: "inspection-failed"; readonly error: string }
  | { readonly kind: "missing" }
  | { readonly kind: "not-independent" };

export function canonicalRepositoryPath(repository: string): string {
  return realpathSync(resolve(repository));
}

export function inspectGitlinkWorktree({
  gitlinkPath,
  repository
}: Readonly<{
  readonly gitlinkPath: string;
  readonly repository: string;
}>): GitlinkWorktreeInspection {
  const submoduleRepository = resolve(repository, gitlinkPath);
  let canonicalSubmoduleRepository: string;
  try {
    if (!statSync(submoduleRepository).isDirectory()) return { kind: "missing" };
    canonicalSubmoduleRepository = canonicalRepositoryPath(submoduleRepository);
  } catch (error: unknown) {
    return missingPath(error)
      ? { kind: "missing" }
      : inspectionFailure(`could not inspect submodule worktree ${gitlinkPath}`, error);
  }

  const topLevelResult = runGit({
    args: ["rev-parse", "--show-toplevel"],
    cwd: canonicalSubmoduleRepository
  });
  if (processFailed(topLevelResult)) {
    const topLevelFailureDetail =
      topLevelResult.error?.message ||
      topLevelResult.stderr.trim() ||
      `exit ${topLevelResult.status}`;
    return {
      kind: "inspection-failed",
      error: `git rev-parse --show-toplevel failed while inspecting submodule ${gitlinkPath}: ${topLevelFailureDetail}`
    };
  }

  const topLevel = topLevelResult.stdout.trim();
  if (!topLevel) {
    return {
      kind: "inspection-failed",
      error: `git rev-parse --show-toplevel returned no repository path for submodule ${gitlinkPath}`
    };
  }

  try {
    return canonicalRepositoryPath(resolve(canonicalSubmoduleRepository, topLevel)) ===
      canonicalSubmoduleRepository
      ? { kind: "initialized", repository: canonicalSubmoduleRepository }
      : { kind: "not-independent" };
  } catch (error: unknown) {
    return inspectionFailure(`could not resolve Git top-level for submodule ${gitlinkPath}`, error);
  }
}

export function resolveDescendableGitlinkRepository({
  gitlinkPath,
  repository,
  visitedRepositories
}: Readonly<{
  readonly gitlinkPath: string;
  readonly repository: string;
  readonly visitedRepositories: ReadonlySet<string>;
}>): string | null {
  const inspection = inspectGitlinkWorktree({ gitlinkPath, repository });
  if (inspection.kind === "inspection-failed") {
    throw new Error(inspection.error);
  }
  return inspection.kind === "initialized" && !visitedRepositories.has(inspection.repository)
    ? inspection.repository
    : null;
}

export function visitRepository({
  repository,
  visitedRepositories
}: Readonly<{
  readonly repository: string;
  readonly visitedRepositories: ReadonlySet<string>;
}>): ReadonlySet<string> {
  return new Set([...visitedRepositories, repository]);
}

function missingPath(error: unknown): boolean {
  const code = error instanceof Error && "code" in error ? error.code : undefined;
  return code === "ENOENT" || code === "ENOTDIR";
}

function inspectionFailure(message: string, error: unknown): GitlinkWorktreeInspection {
  return { kind: "inspection-failed", error: `${message}: ${errorMessage(error)}` };
}

/** 一个 Check 对完整 selected path set 做 eligibility 分类后的结果。 */
export interface ProjectFileEligibilityPartition {
  readonly acceptedPaths: readonly string[];
  readonly rejectedPaths: readonly string[];
}

/** 保持输入顺序，将每个 selected path 恰好分配给 accepted 或 rejected。 */
export function partitionProjectFilesByEligibility(
  selectedPaths: readonly string[],
  accepts: (path: string) => boolean
): ProjectFileEligibilityPartition {
  const acceptedPaths: string[] = [];
  const rejectedPaths: string[] = [];
  for (const path of selectedPaths) {
    (accepts(path) ? acceptedPaths : rejectedPaths).push(path);
  }
  return Object.freeze({
    acceptedPaths: Object.freeze(acceptedPaths),
    rejectedPaths: Object.freeze(rejectedPaths)
  });
}

import path from "node:path";

import { toSlashPath } from "../host-environment/path.ts";

export function normalizeScannerReportedPath(reportedPath: string, projectRoot: string): string {
  const normalizedReportedPath = stripWindowsExtendedPathPrefix(reportedPath);
  const normalizedProjectRoot = stripWindowsExtendedPathPrefix(projectRoot);
  const pathApi = pathApiForScannerPath(normalizedReportedPath, normalizedProjectRoot);
  const nativePath = pathApi.normalize(normalizedReportedPath);
  const projectRelativePath = pathApi.isAbsolute(nativePath)
    ? pathApi.relative(pathApi.normalize(normalizedProjectRoot), nativePath)
    : nativePath;

  return toSlashPath(projectRelativePath);
}

function stripWindowsExtendedPathPrefix(filePath: string): string {
  if (filePath.startsWith("\\\\?\\UNC\\")) {
    return `\\\\${filePath.slice(8)}`;
  }
  if (filePath.startsWith("\\\\?\\")) {
    return filePath.slice(4);
  }
  return filePath;
}

function pathApiForScannerPath(reportedPath: string, projectRoot: string): path.PlatformPath {
  return isWindowsAbsolutePath(reportedPath) || isWindowsAbsolutePath(projectRoot)
    ? path.win32
    : path;
}

function isWindowsAbsolutePath(filePath: string): boolean {
  return /^[A-Za-z]:[\\/]/u.test(filePath) || filePath.startsWith("\\\\");
}

/** Path and Git-output projections shared by revision traversal helpers. */

import { toSlashPath } from "../host-environment/path.ts";
import { matchesAnyConfigGlob } from "./config-glob.ts";

export function uniqueSortedPaths(files: readonly string[]): string[] {
  return [...new Set(files.map(toSlashPath))].sort();
}

export function prefixAndFilter({
  files,
  prefix,
  scanInputPaths
}: Readonly<{
  readonly files: readonly string[];
  readonly prefix: string;
  readonly scanInputPaths: readonly string[];
}>): string[] {
  return files
    .map((file) => joinSlash({ path: file, prefix }))
    .filter((file) => scanInputPaths.length === 0 || matchesAnyConfigGlob(file, scanInputPaths));
}

export function joinSlash({
  path,
  prefix
}: Readonly<{ readonly path: string; readonly prefix: string }>): string {
  return prefix ? `${toSlashPath(prefix)}/${toSlashPath(path)}` : toSlashPath(path);
}

export function nonEmptyGitOutput(stdout: string | null | undefined): string | null {
  const value = (stdout || "").trim();
  return value || null;
}

/** Enumerates files from initialized, non-cyclic submodule working trees. */

import { processFailed } from "../host-environment/process/command.ts";
import { runGit, splitNulDelimitedGitFileList } from "../host-environment/git.ts";
import {
  canonicalRepositoryPath,
  resolveDescendableGitlinkRepository,
  visitRepository
} from "./gitlink-worktree.ts";
import { gitlinksAtRevision } from "./gitlink-revision.ts";
import {
  joinSlash,
  nonEmptyGitOutput,
  prefixAndFilter,
  uniqueSortedPaths
} from "./revision-paths.ts";

export function collectSubmoduleWorktreeFiles({
  repository,
  scanInputPaths
}: Readonly<{
  readonly repository: string;
  readonly scanInputPaths: readonly string[];
}>): string[] {
  const files: string[] = [];
  const visitedRepositories = new Set([canonicalRepositoryPath(repository)]);
  const revision = worktreeRevision(repository);
  if (revision === null) return files;

  for (const gitlink of gitlinksAtRevision({ repository, revision })) {
    const submoduleRepository = resolveDescendableGitlinkRepository({
      gitlinkPath: gitlink.path,
      repository,
      visitedRepositories
    });
    if (!submoduleRepository) continue;
    files.push(
      ...collectWorktreeFiles({
        prefix: gitlink.path,
        repository: submoduleRepository,
        scanInputPaths,
        visitedRepositories: visitRepository({
          repository: submoduleRepository,
          visitedRepositories
        })
      })
    );
  }
  return uniqueSortedPaths(files);
}

function collectWorktreeFiles({
  prefix,
  repository,
  scanInputPaths,
  visitedRepositories
}: Readonly<{
  readonly prefix: string;
  readonly repository: string;
  readonly scanInputPaths: readonly string[];
  readonly visitedRepositories: ReadonlySet<string>;
}>): string[] {
  const result = runGit({
    args: ["ls-files", "-z", "--cached", "--others", "--exclude-standard", "--"],
    cwd: repository
  });
  if (processFailed(result)) {
    const detail =
      result.stderr.trim() ||
      result.error?.message ||
      (result.signal === null ? `exit status ${result.status}` : `signal ${result.signal}`);
    throw new Error(`could not enumerate git-worktree files in ${repository}: ${detail}`);
  }

  const files = prefixAndFilter({
    files: splitNulDelimitedGitFileList(result.stdout),
    prefix,
    scanInputPaths
  });
  const revision = worktreeRevision(repository);
  if (revision === null) return uniqueSortedPaths(files);
  files.push(
    ...collectNestedWorktreeFiles({
      prefix,
      repository,
      revision,
      scanInputPaths,
      visitedRepositories
    })
  );
  return uniqueSortedPaths(files);
}

function collectNestedWorktreeFiles({
  prefix,
  repository,
  revision,
  scanInputPaths,
  visitedRepositories
}: Readonly<{
  readonly prefix: string;
  readonly repository: string;
  readonly revision: string;
  readonly scanInputPaths: readonly string[];
  readonly visitedRepositories: ReadonlySet<string>;
}>): string[] {
  const files: string[] = [];
  for (const gitlink of gitlinksAtRevision({ repository, revision })) {
    const submoduleRepository = resolveDescendableGitlinkRepository({
      gitlinkPath: gitlink.path,
      repository,
      visitedRepositories
    });
    if (!submoduleRepository) continue;
    files.push(
      ...collectWorktreeFiles({
        prefix: joinSlash({ path: gitlink.path, prefix }),
        repository: submoduleRepository,
        scanInputPaths,
        visitedRepositories: visitRepository({
          repository: submoduleRepository,
          visitedRepositories
        })
      })
    );
  }
  return files;
}

function worktreeRevision(repository: string): string | null {
  const result = runGit({ args: ["rev-parse", "--verify", "--quiet", "HEAD"], cwd: repository });
  if (!processFailed(result)) {
    const revision = nonEmptyGitOutput(result.stdout);
    if (revision !== null) return revision;
    throw new Error(`git-worktree revision inspection returned no revision in ${repository}`);
  }
  const headDoesNotExist =
    result.error === undefined &&
    result.signal === null &&
    result.status === 1 &&
    result.stderr.trim() === "";
  if (headDoesNotExist) return null;
  const detail =
    result.stderr.trim() ||
    result.error?.message ||
    (result.signal === null ? `exit status ${result.status}` : `signal ${result.signal}`);
  throw new Error(`could not inspect git-worktree revision in ${repository}: ${detail}`);
}

import type { CheckDescriptor } from "../../check/descriptor.ts";
import {
  type CheckVisibility,
  type CheckFlagEnablement,
  type CheckFlagEnablementMode,
  type CheckExecution,
  type CheckPreflight
} from "../../check/check.ts";
import { snapshotClosedArray, snapshotClosedRecord } from "../../data-boundary/closed-values.ts";
import { validateCheckDescriptor } from "../../check/descriptor-validation.ts";
import { snapshotJsonObject } from "../../check/options-snapshot.ts";
import { parseUniqueIdentifiers } from "./collection-authoring.ts";
import { parseCheckScheduling, type ParsedCheckCollection } from "./scheduling-authoring.ts";

export type { ParsedCheckCollection } from "./scheduling-authoring.ts";

type TrustedDataParser = (this: void, ...parameters: never[]) => unknown;

export interface ParsedCheck {
  readonly admissionPriority: number | undefined;
  readonly checkId: string;
  readonly checks: readonly ParsedCheck[];
  readonly definition: CheckDescriptor | null;
  readonly dependsOn: ParsedCheckCollection | undefined;
  readonly displayName: string;
  readonly enabledByFlags: CheckFlagEnablement | null;
  readonly execution: CheckExecution | null;
  readonly maxParallel: number | undefined;
  readonly mutex: ParsedCheckCollection | undefined;
  readonly observes: ParsedCheckCollection | undefined;
  readonly options: object | null;
  readonly path: string;
  readonly parseData: TrustedDataParser | null;
  readonly preflight: CheckPreflight | null;
  readonly visibility: CheckVisibility | null;
}

export interface ParsedCheckTree {
  readonly checks: readonly ParsedCheck[];
  readonly warnings: readonly MeaninglessCheckWarning[];
}

export interface MeaninglessCheckWarning {
  readonly code: "meaningless-check";
  readonly path: string;
  readonly checkId: string;
}

interface ParseState {
  readonly warnings: MeaninglessCheckWarning[];
}

interface CheckAuthoringData extends Readonly<Record<string, unknown>> {
  readonly checkId: string;
  readonly displayName: string;
}

interface ParsedCheckFields {
  readonly definition: CheckDescriptor | null;
  readonly enabledByFlags: CheckFlagEnablement | null;
  readonly execution: CheckExecution | null;
  readonly options: object | null;
  readonly parseData: TrustedDataParser | null;
  readonly preflight: CheckPreflight | null;
  readonly visibility: CheckVisibility | null;
}

const CHECK_KEYS = [
  "admissionPriority",
  "checkId",
  "checks",
  "dependsOn",
  "displayName",
  "enabledByFlags",
  "execution",
  "maxParallel",
  "mutex",
  "options",
  "observes",
  "parseData",
  "preflight",
  "visibility"
] as const;

const CONTAINER_CHECK_FIELDS: ParsedCheckFields = Object.freeze({
  definition: null,
  enabledByFlags: null,
  execution: null,
  options: null,
  parseData: null,
  preflight: null,
  visibility: null
});

/**
 * Parses only the closed recursive authoring grammar. Execution callbacks are
 * trusted project code, while every declarative field is copied and validated.
 */
export function parseCheckTreeAuthoring(value: unknown): ParsedCheckTree | undefined {
  const roots = snapshotClosedArray(value);
  if (roots === undefined) return undefined;
  const state: ParseState = { warnings: [] };
  const checks: ParsedCheck[] = [];
  for (let index = 0; index < roots.length; index += 1) {
    const check = parseCheck(roots[index], `definition.checks[${index}]`, state);
    if (check === undefined) return undefined;
    checks.push(check);
  }
  return Object.freeze({
    checks: Object.freeze(checks),
    warnings: Object.freeze(state.warnings)
  });
}

function parseCheck(value: unknown, path: string, state: ParseState): ParsedCheck | undefined {
  const data = parseCheckData(value);
  if (data === undefined) return undefined;
  const execution = parseExecution(data);
  if (execution === undefined) return undefined;
  const parseData = parseDataParser(data);
  if (parseData === undefined) return undefined;
  const preflight = parsePreflight(data);
  if (preflight === undefined) return undefined;
  const enabledByFlags = parseEnabledByFlags(data);
  if (enabledByFlags === undefined) return undefined;
  const checks = parseChildren(data, path, state);
  if (checks === undefined) return undefined;
  const scheduling = parseCheckScheduling(data);
  if (scheduling === undefined) return undefined;
  const fields = parseCheckFields(data, enabledByFlags, execution, parseData, preflight);
  if (fields === undefined) return undefined;
  warnForMeaninglessCheck(data, checks, fields, path, state);

  return Object.freeze({
    admissionPriority: scheduling.admissionPriority,
    checkId: data.checkId,
    checks,
    definition: fields.definition,
    dependsOn: scheduling.dependsOn,
    displayName: data.displayName,
    enabledByFlags: fields.enabledByFlags,
    execution: fields.execution,
    maxParallel: scheduling.maxParallel,
    mutex: scheduling.mutex,
    observes: scheduling.observes,
    options: fields.options,
    path,
    parseData: fields.parseData,
    preflight: fields.preflight,
    visibility: fields.visibility
  });
}

function parseCheckData(value: unknown): CheckAuthoringData | undefined {
  const data = snapshotClosedRecord(value);
  if (data === undefined) return undefined;
  return hasValidCheckIdentity(data) ? data : undefined;
}

function hasValidCheckIdentity(
  data: Readonly<Record<string, unknown>>
): data is CheckAuthoringData {
  return (
    hasOnlyCheckKeys(data) &&
    typeof data.checkId === "string" &&
    data.checkId.length > 0 &&
    typeof data.displayName === "string" &&
    data.displayName.length > 0
  );
}

function hasOnlyCheckKeys(data: Readonly<Record<string, unknown>>): boolean {
  return Object.keys(data).every((key) => CHECK_KEYS.some((checkKey) => checkKey === key));
}

function parseExecution(data: CheckAuthoringData): CheckExecution | null | undefined {
  if (!Object.hasOwn(data, "execution")) return null;
  return isTrustedFunction<CheckExecution>(data.execution) ? data.execution : undefined;
}

function parseDataParser(data: CheckAuthoringData): TrustedDataParser | null | undefined {
  if (!Object.hasOwn(data, "parseData") || data.parseData === undefined) return null;
  return isTrustedFunction<TrustedDataParser>(data.parseData) ? data.parseData : undefined;
}

function parsePreflight(data: CheckAuthoringData): CheckPreflight | null | undefined {
  if (!Object.hasOwn(data, "preflight")) return null;
  return isTrustedFunction<CheckPreflight>(data.preflight) ? data.preflight : undefined;
}

function isTrustedFunction<FunctionType extends (...parameters: never[]) => unknown>(
  value: unknown
): value is FunctionType {
  return typeof value === "function";
}

function parseChildren(
  data: CheckAuthoringData,
  path: string,
  state: ParseState
): readonly ParsedCheck[] | undefined {
  if (!Object.hasOwn(data, "checks")) return Object.freeze([]);
  const values = snapshotClosedArray(data.checks);
  if (values === undefined) return undefined;
  const checks: ParsedCheck[] = [];
  for (let index = 0; index < values.length; index += 1) {
    const check = parseCheck(values[index], `${path}.checks[${index}]`, state);
    if (check === undefined) return undefined;
    checks.push(check);
  }
  return Object.freeze(checks);
}

function parseDefinition(data: CheckAuthoringData): CheckDescriptor | undefined {
  const definition = validateCheckDescriptor({
    checkId: data.checkId,
    displayName: data.displayName
  });
  return definition.ok ? definition.value : undefined;
}

function parseOptions(data: CheckAuthoringData): object | undefined {
  if (!Object.hasOwn(data, "options")) return Object.freeze({});
  const options = snapshotClosedRecord(data.options);
  if (options === undefined) return undefined;
  return snapshotJsonObject(options);
}

function parseCheckFields(
  data: CheckAuthoringData,
  enabledByFlags: CheckFlagEnablement | null,
  execution: CheckExecution | null,
  parseData: TrustedDataParser | null,
  preflight: CheckPreflight | null
): ParsedCheckFields | undefined {
  if (execution === null) {
    return Object.hasOwn(data, "options") ||
      Object.hasOwn(data, "enabledByFlags") ||
      Object.hasOwn(data, "visibility") ||
      parseData !== null ||
      preflight !== null
      ? undefined
      : CONTAINER_CHECK_FIELDS;
  }
  const definition = parseDefinition(data);
  if (definition === undefined) return undefined;
  const options = parseOptions(data);
  if (options === undefined) return undefined;
  const visibility = parseVisibility(data);
  if (visibility === undefined) return undefined;
  return Object.freeze({
    definition,
    enabledByFlags,
    execution,
    options,
    parseData,
    preflight,
    visibility
  });
}

function parseEnabledByFlags(data: CheckAuthoringData): CheckFlagEnablement | null | undefined {
  if (!Object.hasOwn(data, "enabledByFlags")) return null;
  const control = snapshotClosedRecord(data.enabledByFlags);
  if (
    control === undefined ||
    Object.keys(control).length !== 2 ||
    !Object.hasOwn(control, "flags") ||
    !Object.hasOwn(control, "mode") ||
    !isCheckFlagEnablementMode(control.mode)
  ) {
    return undefined;
  }
  const flags = parseUniqueIdentifiers(control.flags);
  if (flags === undefined) return undefined;
  const [firstFlag, ...remainingFlags] = [...flags].sort();
  if (firstFlag === undefined) return undefined;
  const canonicalFlags: [string, ...string[]] = [firstFlag, ...remainingFlags];
  return Object.freeze({ flags: Object.freeze(canonicalFlags), mode: control.mode });
}

function isCheckFlagEnablementMode(value: unknown): value is CheckFlagEnablementMode {
  return value === "all" || value === "any" || value === "none" || value === "not-all";
}

function parseVisibility(data: CheckAuthoringData): CheckVisibility | undefined {
  if (!Object.hasOwn(data, "visibility")) return "always";
  const visibility = data.visibility;
  return visibility === undefined || visibility === "always" || visibility === "attention"
    ? (visibility ?? "always")
    : undefined;
}

function warnForMeaninglessCheck(
  data: CheckAuthoringData,
  checks: readonly ParsedCheck[],
  fields: ParsedCheckFields,
  path: string,
  state: ParseState
): void {
  if (fields.execution !== null || checks.length > 0) return;
  state.warnings.push(Object.freeze({ code: "meaningless-check", path, checkId: data.checkId }));
}

import { snapshotClosedArray } from "../../data-boundary/closed-values.ts";

/** Snapshots one closed array as unique, non-empty authored identifiers. */
export function parseUniqueIdentifiers(value: unknown): readonly string[] | undefined {
  const items = snapshotClosedArray(value);
  if (items === undefined) return undefined;
  const identifiers: string[] = [];
  for (const item of items) {
    if (typeof item !== "string" || item.length === 0) return undefined;
    if (!identifiers.includes(item)) identifiers.push(item);
  }
  return Object.freeze(identifiers);
}

import { inherit, type Check, type InheritableCheckCollection } from "../../check/check.ts";
import type { ParsedCheck, ParsedCheckCollection, ParsedCheckTree } from "./authoring.ts";

/** Rebuilds the validated public authoring shape without retaining untyped input. */
export function materializeCheckTreeAuthoring(parsed: ParsedCheckTree): readonly Check[] {
  return materializeChecks(parsed.checks);
}

function materializeChecks(checks: readonly ParsedCheck[]): readonly Check[] {
  return Object.freeze(checks.map((check) => materializeCheck(check)));
}

function materializeCheck(check: ParsedCheck): Check {
  const checks = materializeChecks(check.checks);
  const dependsOn = materializeCollection(check.dependsOn);
  const enabledByFlags = check.enabledByFlags;
  const mutex = materializeCollection(check.mutex);
  const observes = materializeCollection(check.observes);
  const visibility = check.visibility;
  const preflight = check.preflight;
  const scheduling = {
    ...(check.admissionPriority === undefined
      ? {}
      : { admissionPriority: check.admissionPriority }),
    ...(dependsOn === undefined ? {} : { dependsOn }),
    ...(check.maxParallel === undefined ? {} : { maxParallel: check.maxParallel }),
    ...(mutex === undefined ? {} : { mutex }),
    ...(observes === undefined ? {} : { observes })
  };
  if (
    check.definition === null ||
    check.execution === null ||
    check.options === null ||
    visibility === null
  ) {
    return Object.freeze({
      checkId: check.checkId,
      checks,
      displayName: check.displayName,
      ...scheduling
    });
  }
  return Object.freeze({
    checkId: check.checkId,
    checks,
    displayName: check.displayName,
    ...(enabledByFlags === null ? {} : { enabledByFlags }),
    execution: check.execution,
    ...(check.parseData === null ? {} : { parseData: check.parseData }),
    options: check.options,
    ...(preflight === null ? {} : { preflight }),
    ...scheduling,
    visibility
  });
}

function materializeCollection(
  collection: ParsedCheckCollection | undefined
): InheritableCheckCollection<string> | undefined {
  if (collection === undefined) return undefined;
  if (collection.kind === "exact") return collection.values;
  return inherit({ add: collection.add, remove: collection.remove });
}

import type { CheckDescriptor } from "../../check/descriptor.ts";
import type {
  CheckExecution,
  CheckFlagEnablement,
  CheckPreflight,
  CheckVisibility
} from "../../check/check.ts";
import {
  parseCheckTreeAuthoring,
  type MeaninglessCheckWarning,
  type ParsedCheck,
  type ParsedCheckCollection,
  type ParsedCheckTree
} from "./authoring.ts";

export type { Check, InheritableCheckCollection } from "../../check/check.ts";

export interface ResolvedCheckTreeLeaf {
  readonly admissionPriority: number;
  readonly definition: CheckDescriptor;
  readonly dependsOn: readonly string[];
  readonly enabledByFlags?: CheckFlagEnablement;
  readonly execution: CheckExecution;
  readonly maxParallel: number;
  readonly mutex: readonly string[];
  readonly observes: readonly string[];
  readonly options: object;
  readonly preflight?: CheckPreflight;
  readonly visibility: CheckVisibility;
}

export interface ResolvedCheckTree {
  readonly leaves: readonly ResolvedCheckTreeLeaf[];
  readonly warnings: readonly MeaninglessCheckWarning[];
}

interface InheritedScheduling {
  readonly admissionPriority: number;
  readonly dependsOn: readonly string[];
  readonly maxParallel: number;
  readonly mutex: readonly string[];
  readonly observes: readonly string[];
}

/**
 * Traverses the recursive authoring tree. Containment only passes scheduling
 * values to descendants; it never creates an execution dependency or output
 * hierarchy.
 */
export function resolveCheckTree(
  value: unknown,
  rootMaxParallel: number
): ResolvedCheckTree | undefined {
  const parsed = parseCheckTreeAuthoring(value);
  return parsed === undefined ? undefined : resolveParsedCheckTree(parsed, rootMaxParallel);
}

export function resolveParsedCheckTree(
  parsed: ParsedCheckTree,
  rootMaxParallel: number
): ResolvedCheckTree | undefined {
  if (!Number.isSafeInteger(rootMaxParallel) || rootMaxParallel <= 0) return undefined;
  const leaves: ResolvedCheckTreeLeaf[] = [];
  const root: InheritedScheduling = Object.freeze({
    admissionPriority: 0,
    dependsOn: Object.freeze([]),
    maxParallel: rootMaxParallel,
    mutex: Object.freeze([]),
    observes: Object.freeze([])
  });
  for (const check of parsed.checks) flattenCheck(check, root, leaves);
  return Object.freeze({ leaves: Object.freeze(leaves), warnings: parsed.warnings });
}

function flattenCheck(
  check: ParsedCheck,
  inherited: InheritedScheduling,
  leaves: ResolvedCheckTreeLeaf[]
): void {
  const scheduling: InheritedScheduling = Object.freeze({
    admissionPriority: check.admissionPriority ?? inherited.admissionPriority,
    dependsOn: resolveCollection(inherited.dependsOn, check.dependsOn),
    maxParallel: check.maxParallel ?? inherited.maxParallel,
    mutex: resolveCollection(inherited.mutex, check.mutex),
    observes: resolveCollection(inherited.observes, check.observes)
  });
  const visibility = check.visibility;
  if (
    check.execution !== null &&
    check.definition !== null &&
    check.options !== null &&
    visibility !== null
  ) {
    leaves.push(
      Object.freeze({
        admissionPriority: scheduling.admissionPriority,
        definition: check.definition,
        dependsOn: scheduling.dependsOn,
        ...(check.enabledByFlags === null ? {} : { enabledByFlags: check.enabledByFlags }),
        execution: check.execution,
        maxParallel: scheduling.maxParallel,
        mutex: scheduling.mutex,
        observes: scheduling.observes,
        options: check.options,
        ...(check.preflight === null ? {} : { preflight: check.preflight }),
        visibility
      })
    );
  }
  for (const child of check.checks) flattenCheck(child, scheduling, leaves);
}

function resolveCollection(
  inherited: readonly string[],
  authored: ParsedCheckCollection | undefined
): readonly string[] {
  if (authored === undefined) return inherited;
  if (authored.kind === "exact") return canonicalize(authored.values);
  const removed = new Set(authored.remove);
  return canonicalize([...inherited.filter((value) => !removed.has(value)), ...authored.add]);
}

function canonicalize(values: readonly string[]): readonly string[] {
  return Object.freeze([...new Set(values)].sort());
}

import {
  isInheritedCheckCollection,
  snapshotInheritedCheckCollection,
  type InheritedCheckCollection
} from "../../check/check.ts";
import { parseUniqueIdentifiers } from "./collection-authoring.ts";

export type ParsedCheckCollection = Readonly<
  | { readonly kind: "exact"; readonly values: readonly string[] }
  | {
      readonly kind: "inherit";
      readonly add: readonly string[];
      readonly remove: readonly string[];
    }
>;

export type ParsedCheckScheduling = Readonly<{
  readonly admissionPriority: number | undefined;
  readonly dependsOn: ParsedCheckCollection | undefined;
  readonly maxParallel: number | undefined;
  readonly mutex: ParsedCheckCollection | undefined;
  readonly observes: ParsedCheckCollection | undefined;
}>;

/** Parses the closed relation, priority, and capacity fields for one authored Check. */
export function parseCheckScheduling(
  data: Readonly<Record<string, unknown>>
): ParsedCheckScheduling | undefined {
  const dependsOn = parseCollection(data, "dependsOn");
  const mutex = parseCollection(data, "mutex");
  const observes = parseCollection(data, "observes");
  const admissionPriority = parseAdmissionPriority(data.admissionPriority);
  const maxParallel = parseMaxParallel(data.maxParallel);
  if (dependsOn === null || mutex === null || observes === null) return undefined;
  if (admissionPriority === null || maxParallel === null) return undefined;
  return resolvedScheduling({ admissionPriority, dependsOn, maxParallel, mutex, observes });
}

function resolvedScheduling(
  scheduling: Readonly<{
    readonly admissionPriority: number | undefined;
    readonly dependsOn: ParsedCheckCollection | undefined;
    readonly maxParallel: number | undefined;
    readonly mutex: ParsedCheckCollection | undefined;
    readonly observes: ParsedCheckCollection | undefined;
  }>
): ParsedCheckScheduling {
  return Object.freeze({
    admissionPriority: scheduling.admissionPriority,
    dependsOn: scheduling.dependsOn ?? undefined,
    maxParallel: scheduling.maxParallel,
    mutex: scheduling.mutex ?? undefined,
    observes: scheduling.observes ?? undefined
  });
}

function parseAdmissionPriority(value: unknown): number | null | undefined {
  if (value === undefined) return undefined;
  return typeof value === "number" && Number.isSafeInteger(value) ? value : null;
}

function parseMaxParallel(value: unknown): number | null | undefined {
  if (value === undefined) return undefined;
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : null;
}

function parseCollection(
  data: Readonly<Record<string, unknown>>,
  field: "dependsOn" | "mutex" | "observes"
): ParsedCheckCollection | null | undefined {
  if (!Object.hasOwn(data, field)) return undefined;
  const value = data[field];
  if (isInheritedCheckCollection(value)) return parseInheritedCollection(value);
  const values = parseUniqueIdentifiers(value);
  return values === undefined ? null : Object.freeze({ kind: "exact", values });
}

function parseInheritedCollection(
  value: InheritedCheckCollection<unknown>
): ParsedCheckCollection | null {
  const data = snapshotInheritedCheckCollection(value);
  if (data === undefined || !hasExactInheritedKeys(data)) return null;
  const add = data.add === undefined ? Object.freeze([]) : parseUniqueIdentifiers(data.add);
  const remove =
    data.remove === undefined ? Object.freeze([]) : parseUniqueIdentifiers(data.remove);
  if (add === undefined || remove === undefined) return null;
  return Object.freeze({ kind: "inherit", add, remove });
}

function hasExactInheritedKeys(data: Readonly<Record<string, unknown>>): boolean {
  const keys = Object.keys(data);
  return keys.length > 0 && keys.every((key) => key === "add" || key === "remove");
}

/** Default Run-owned output values applied when a Project Definition omits an override. */
export const DEFAULT_PROJECT_OUTPUTS = Object.freeze({
  machinePublication: Object.freeze({ directory: "artifacts/vibe-check", enabled: true }),
  progressRendering: Object.freeze({ enabled: true }),
  diagnosticLogging: Object.freeze({ directory: ".log/vibe-check", enabled: false })
} as const);

import type { ProjectOutputs } from "./project-definition.ts";
import { snapshotClosedRecord } from "../data-boundary/closed-values.ts";

const OUTPUT_NAMES = ["machinePublication", "progressRendering", "diagnosticLogging"] as const;

export function parseOutputs(value: unknown): ProjectOutputs | undefined {
  const data = exactKeys(value, OUTPUT_NAMES);
  if (data === undefined) return undefined;
  const machinePublication = parseDirectoryOutput(data.machinePublication);
  const progressRendering = parseSwitchOutput(data.progressRendering);
  const diagnosticLogging = parseDirectoryOutput(data.diagnosticLogging);
  return machinePublication === undefined ||
    progressRendering === undefined ||
    diagnosticLogging === undefined
    ? undefined
    : Object.freeze({ machinePublication, progressRendering, diagnosticLogging });
}

/** Accepts trusted output targets without claiming filesystem containment. */
export function isOutputDirectory(directory: string): boolean {
  return directory.length > 0 && !directory.includes("\0");
}

function parseDirectoryOutput(
  value: unknown
): Readonly<{ readonly directory: string; readonly enabled: boolean }> | undefined {
  const data = exactKeys(value, ["directory", "enabled"]);
  return typeof data?.directory === "string" &&
    isOutputDirectory(data.directory) &&
    typeof data.enabled === "boolean"
    ? Object.freeze({ directory: data.directory, enabled: data.enabled })
    : undefined;
}

function parseSwitchOutput(value: unknown): Readonly<{ readonly enabled: boolean }> | undefined {
  const data = exactKeys(value, ["enabled"]);
  return typeof data?.enabled === "boolean" ? Object.freeze({ enabled: data.enabled }) : undefined;
}

function exactKeys(
  value: unknown,
  keys: readonly string[]
): Readonly<Record<string, unknown>> | undefined {
  const data = snapshotClosedRecord(value);
  return data !== undefined &&
    Object.keys(data).length === keys.length &&
    keys.every((key) => Object.hasOwn(data, key))
    ? data
    : undefined;
}

import { resolveParsedCheckTree } from "./check-tree/resolution.ts";
import { parseCheckTreeAuthoring } from "./check-tree/authoring.ts";
import { materializeCheckTreeAuthoring } from "./check-tree/materialization.ts";
import { parseOutputs } from "./output-validation.ts";
import {
  type ProjectDefinitionDiagnostic,
  type ProjectDefinitionValidationResult,
  type AdmissionPolicy,
  type SchedulerMeasurementHook,
  type SchedulerPolicy
} from "./project-definition.ts";
import { snapshotClosedArray, snapshotClosedRecord } from "../data-boundary/closed-values.ts";

type DefinitionValidationResult<T> = Readonly<
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: ProjectDefinitionDiagnostic }
>;

const PROJECT_DEFINITION_KEYS = ["apiVersion", "checks", "outputs", "scheduler"] as const;

/**
 * Validates one closed Definition before Run can invoke any project callback.
 * Successful validation carries information-only Check warnings separately.
 */
export function validateProjectDefinition(value: unknown): ProjectDefinitionValidationResult {
  try {
    return validateProjectDefinitionValue(value);
  } catch {
    return invalidDefinition("definition");
  }
}

function validateProjectDefinitionValue(value: unknown): ProjectDefinitionValidationResult {
  const data = exactProjectDefinition(value);
  if (!data.ok) return data;
  return parseProjectDefinitionFields(data.value);
}

function parseProjectDefinitionFields(
  data: Readonly<Record<string, unknown>>
): ProjectDefinitionValidationResult {
  const scheduler = parseScheduler(data.scheduler);
  if (scheduler === undefined) return invalidDefinition("definition.scheduler");
  const checks = snapshotClosedArray(data.checks);
  if (checks === undefined) return invalidDefinition("definition.checks");
  const parsedChecks = parseCheckTreeAuthoring(checks);
  if (parsedChecks === undefined) return invalidDefinition("definition.checks");
  const tree = resolveParsedCheckTree(parsedChecks, scheduler.maxParallel);
  if (tree === undefined) return invalidDefinition("definition.checks");
  const outputs = parseOutputs(data.outputs);
  if (outputs === undefined) return invalidDefinition("definition.outputs");
  return Object.freeze({
    ok: true,
    value: {
      apiVersion: "1" as const,
      checks: materializeCheckTreeAuthoring(parsedChecks),
      outputs,
      scheduler
    },
    warnings: tree.warnings
  });
}

function exactProjectDefinition(
  value: unknown
): DefinitionValidationResult<Readonly<Record<string, unknown>>> {
  const data = exactRecord(
    value,
    PROJECT_DEFINITION_KEYS,
    "invalid-project-definition",
    "definition"
  );
  if (!data.ok) return data;
  return data.value.apiVersion === "1"
    ? data
    : invalid("invalid-project-definition", "definition.apiVersion", "invalid-value");
}

function exactRecord(
  value: unknown,
  allowedKeys: readonly string[],
  kind: ProjectDefinitionDiagnostic["kind"],
  path: string
): DefinitionValidationResult<Readonly<Record<string, unknown>>> {
  const data = snapshotClosedRecord(value);
  if (data === undefined) return invalid(kind, path, "invalid-value");
  const unknownKey = Object.keys(data).find((key) => !allowedKeys.includes(key));
  if (unknownKey !== undefined) return invalid(kind, `${path}.${unknownKey}`, "unknown-key");
  return Object.freeze({ ok: true, value: data });
}

function parseScheduler(value: unknown): SchedulerPolicy | undefined {
  const data = snapshotClosedRecord(value);
  if (
    data === undefined ||
    !Object.hasOwn(data, "maxParallel") ||
    Object.keys(data).some(
      (key) => key !== "admissionPolicy" && key !== "maxParallel" && key !== "measurementHooks"
    )
  ) {
    return undefined;
  }
  const admissionPolicy = Object.hasOwn(data, "admissionPolicy")
    ? parseAdmissionPolicy(data.admissionPolicy)
    : Object.freeze({ kind: "static" as const });
  const measurementHooks = parseMeasurementHooks(data.measurementHooks);
  return typeof data.maxParallel === "number" &&
    Number.isSafeInteger(data.maxParallel) &&
    data.maxParallel > 0 &&
    admissionPolicy !== undefined &&
    measurementHooks !== undefined
    ? Object.freeze({
        admissionPolicy,
        maxParallel: data.maxParallel,
        measurementHooks
      })
    : undefined;
}

function parseMeasurementHooks(
  value: unknown
): readonly import("./project-definition.ts").SchedulerMeasurementHook[] | undefined {
  if (value === undefined) return Object.freeze([]);
  if (!Array.isArray(value)) return undefined;
  const hooks: SchedulerMeasurementHook[] = [];
  for (const hook of value) {
    if (!isMeasurementHook(hook)) return undefined;
    hooks.push(hook);
  }
  return Object.freeze(hooks);
}

function isMeasurementHook(value: unknown): value is SchedulerMeasurementHook {
  return typeof value === "function";
}

function parseAdmissionPolicy(value: unknown): AdmissionPolicy | undefined {
  const data = snapshotClosedRecord(value);
  if (data === undefined || typeof data.kind !== "string") return undefined;
  if (data.kind === "static") {
    return exactKeys(data, ["kind"]) === undefined ? undefined : Object.freeze({ kind: "static" });
  }
  if (data.kind === "custom") {
    const policy = exactKeys(data, ["kind", "proposeAdmission"]);
    const proposeAdmission = policy?.proposeAdmission;
    if (!isCustomAdmissionCallback(proposeAdmission)) return undefined;
    return Object.freeze({
      kind: "custom",
      proposeAdmission
    });
  }
  return undefined;
}

function isCustomAdmissionCallback(
  value: unknown
): value is Extract<AdmissionPolicy, { readonly kind: "custom" }>["proposeAdmission"] {
  return typeof value === "function";
}

function exactKeys(
  value: unknown,
  keys: readonly string[]
): Readonly<Record<string, unknown>> | undefined {
  const data = snapshotClosedRecord(value);
  if (data === undefined) return undefined;
  return Object.keys(data).length === keys.length && keys.every((key) => Object.hasOwn(data, key))
    ? data
    : undefined;
}

function invalidDefinition(path: string): ProjectDefinitionValidationResult {
  return Object.freeze({
    ok: false,
    error: Object.freeze({
      kind: "invalid-project-definition",
      path,
      reason: "invalid-value"
    })
  });
}

function invalid(
  kind: ProjectDefinitionDiagnostic["kind"],
  path: string,
  reason: ProjectDefinitionDiagnostic["reason"]
): DefinitionValidationResult<never> {
  return Object.freeze({
    ok: false,
    error: Object.freeze({ kind, path, reason })
  });
}

