  readonly definitionWarnings: readonly DefinitionWarning[];
  /** Runtime scheduler policy；custom callback 保留在此处，不进入 declarative snapshot。 */
  readonly scheduler: SchedulerPolicy;
}
const STATIC_ADMISSION_POLICY: AdmissionPolicy = Object.freeze({
  kind: "static"
});
type ExactAdmissionPolicy<T extends AdmissionPolicy> =
  T extends Readonly<{ readonly kind: "static" }>
    ? T & Record<Exclude<keyof T, "kind">, never>
    : T extends Readonly<{ readonly kind: "custom" }>
      ? T & Record<Exclude<keyof T, "kind" | "proposeAdmission">, never>
      : never;

/**
 * 为 custom admission policy 保留 callback/context 的 TypeScript inference，不创建额外运行语义。
 *
 * @remarks inline `{ kind: "custom", proposeAdmission }` 与此 helper 的结果完全等价；callback 会在
 * Run 中以调用方 closure 同步调用，重叠 Run 的可重入性由调用方负责。
 */
export function defineAdmissionPolicy<const T extends AdmissionPolicy>(
  policy: ExactAdmissionPolicy<T>
): T {
  return policy;
}

/** 使用 Product 默认输出创建普通 Project Definition。 */
export function defineConfig<const T extends ProjectDefinitionInput>(
  value: T & Record<Exclude<keyof T, keyof ProjectDefinitionInput>, never>
): ProjectDefinition {
  return {
    apiVersion: value.apiVersion ?? "1",
    checks: value.checks ?? [],
    outputs: {
      machinePublication: {
        directory:
          value.outputs?.machinePublication?.directory ??
          DEFAULT_PROJECT_OUTPUTS.machinePublication.directory,
        enabled:
          value.outputs?.machinePublication?.enabled ??
          DEFAULT_PROJECT_OUTPUTS.machinePublication.enabled
      },
      progressRendering: {
        enabled:
          value.outputs?.progressRendering?.enabled ??
          DEFAULT_PROJECT_OUTPUTS.progressRendering.enabled
      },
      diagnosticLogging: {
        directory:
          value.outputs?.diagnosticLogging?.directory ??
          DEFAULT_PROJECT_OUTPUTS.diagnosticLogging.directory,
        enabled:
          value.outputs?.diagnosticLogging?.enabled ??
          DEFAULT_PROJECT_OUTPUTS.diagnosticLogging.enabled
      }
    },
    scheduler: {
      admissionPolicy: value.scheduler?.admissionPolicy ?? STATIC_ADMISSION_POLICY,
      maxParallel: value.scheduler?.maxParallel ?? 4,
      measurementHooks: value.scheduler?.measurementHooks ?? []
    }
  };
}
export function normalizeProjectDefinition(
  definition: ProjectDefinition
): NormalizedProjectDefinition {
  const tree = resolveCheckTree(definition.checks, definition.scheduler.maxParallel);
  if (tree === undefined)
    throw new TypeError("Project Definition Check tree failed closed normalization");
  const checks = Object.freeze(tree.leaves.map(normalizeCheck));
  return Object.freeze({
    checks,
    declarative: freezeDeclarativeSnapshot(definition, checks),
    definitionWarnings: tree.warnings,
    scheduler: normalizeSchedulerPolicy(definition.scheduler)
  });
}
function normalizeCheck(leaf: ResolvedCheckTreeLeaf): NormalizedCheck {
  return Object.freeze({
    admissionPriority: leaf.admissionPriority,
    definition: leaf.definition,
    dependsOn: leaf.dependsOn,
    ...(leaf.enabledByFlags === undefined ? {} : { enabledByFlags: leaf.enabledByFlags }),
    execution: leaf.execution,
    maxParallel: leaf.maxParallel,
    mutex: leaf.mutex,
    observes: leaf.observes,
    options: leaf.options,
    ...(leaf.preflight === undefined ? {} : { preflight: leaf.preflight }),
    visibility: leaf.visibility
  });
}
export function createDeclarativeFingerprint(snapshot: DeclarativeProjectSnapshot): string {
  return createHash("sha256").update(stableJson(snapshot)).digest("hex");
}
function freezeDeclarativeSnapshot(
  definition: ProjectDefinition,
  checks: readonly NormalizedCheck[]
): DeclarativeProjectSnapshot {
  const declarations = checks
    .map(({ execution: _execution, preflight: _preflight, ...declaration }) => declaration)
    .sort((left, right) => compareText(left.definition.checkId, right.definition.checkId));
  return deepFreeze({
    apiVersion: definition.apiVersion,
    checks: declarations,
    outputs: definition.outputs,
    scheduler: Object.freeze({
      admissionPolicy: Object.freeze({
        kind: definition.scheduler.admissionPolicy.kind
      }),
      maxParallel: definition.scheduler.maxParallel
    })
  });
}
function normalizeSchedulerPolicy(policy: SchedulerPolicy): SchedulerPolicy {
  const admissionPolicy =
    policy.admissionPolicy.kind === "static"
      ? STATIC_ADMISSION_POLICY
      : Object.freeze({
          kind: "custom" as const,
          proposeAdmission: policy.admissionPolicy.proposeAdmission
        });
  return Object.freeze({
    admissionPolicy,
    maxParallel: policy.maxParallel,
    measurementHooks: Object.freeze([...policy.measurementHooks])
  });
}
function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}
function deepFreeze<T>(value: T): T {
  if (typeof value !== "object" || value === null || Object.isFrozen(value)) return value;
  for (const item of Object.values(value)) deepFreeze(item);
  return Object.freeze(value);
}
function stableJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stableJson).join(",")}]`;
  if (isNonArrayRecord(value))
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`)
      .join(",")}}`;
  return JSON.stringify(value);
}

/** 自定义准入 policy 对当前 Task 的唯一提议。 */
export type AdmissionProposal =
  | Readonly<{ readonly kind: "select"; readonly taskId: string }>
  | Readonly<{ readonly kind: "wait" }>;

/**
 * 自定义准入 policy 每轮获得的不可变普通数据快照。
 *
 * 它只提供完整调度图及当前可观察的准入事实，不能启动、取消或结算 Task。
 */
export interface AdmissionPolicyContext {
  /** 已规范化的完整静态调度图；Task metadata 是拓扑和 priority 的唯一来源。 */
  readonly graph: SchedulerGraphSnapshot;
  /** 已满足 relation/mutex 条件的 pending Task 及其本轮 capacity 可准入性。 */
  readonly candidates: readonly Readonly<{
    readonly canAdmit: boolean;
    readonly taskId: string;
  }>[];
  /** 当前 root 与已激活 scope 合成后的 capacity 事实。 */
  readonly capacity: Readonly<{
    readonly effectiveMaxParallel: number;
    readonly maxParallel: number;
    readonly running: number;
  }>;
  /** 当前已激活 scope 的 canonical IDs。 */
  readonly activeScopeIds: readonly string[];
  /** 当前正在执行的 Task IDs。 */
  readonly runningTaskIds: readonly string[];
  /** 当前已结算的 Task IDs；不携带 Check result、data 或 message。 */
  readonly settledTaskIds: readonly string[];
  /** 调用前已 flush 的有界累计事实与 captured action-observation prefix。 */
  readonly measurement: AdmissionPolicyMeasurement;
  /** 本轮与生命周期有关的最小只读事实。 */
  readonly runtime: Readonly<{
    readonly abortRequested: boolean;
    readonly cancelled: boolean;
  }>;
}

/** Definition authoring 的 closed admission policy；custom callback 必须同步返回 {@link AdmissionProposal}。 */
export type AdmissionPolicy =
  | Readonly<{ readonly kind: "static" }>
  | Readonly<{
      readonly kind: "custom";
      readonly proposeAdmission: (this: void, context: AdmissionPolicyContext) => AdmissionProposal;
    }>;

/** 定义级的 Check 调度预算与 admission policy。 */
export type SchedulerMeasurementTimingUnavailableReason =
  | "clock-threw"
  | "clock-non-finite"
  | "clock-backward"
  | "interval-invalid"
  | "integral-invalid";

export type SchedulerMeasurementTiming =
  | Readonly<{ readonly availability: "available" }>
  | Readonly<{
      readonly availability: "unavailable";
      readonly reason: SchedulerMeasurementTimingUnavailableReason;
    }>;

/** 所有公开 Scheduler context 共用的图 DTO；Task identity 一律为 `taskId`。 */
export interface SchedulerGraphSnapshot {
  readonly scopes: readonly Readonly<{
    readonly activationTaskIds: readonly string[];
    readonly id: string;
    readonly maxParallel: number;
    readonly terminalTaskId: string;
  }>[];
  readonly tasks: readonly Readonly<{
    readonly admissionPriority: number;
    readonly dependsOn: readonly string[];
    readonly mutex: readonly string[];
    readonly observes: readonly string[];
    readonly scopeId: string | null;
    readonly taskId: string;
  }>[];
}

/** 一条已关闭 occupancy interval 对累计值的有界贡献。 */
export interface SchedulerMeasurementIntervalContribution {
  readonly admissiblePendingTaskMs: number;
  readonly acceptedWaitMs: number;
  readonly capacityBlockedTaskMs: number;
  readonly effectiveCapacitySlotMs: number;
  readonly mutexBlockedTaskMs: number;
  readonly rootCapacitySlotMs: number;
  readonly taskSlotMs: number;
}

/** 已关闭 action-observation interval 的 timing 边界；不可用 timing 不伪造数值贡献。 */
export type SchedulerMeasurementActionObservationInterval =
  | Readonly<{
      readonly availability: "available";
      readonly contribution: SchedulerMeasurementIntervalContribution;
    }>
  | Readonly<{
      readonly availability: "unavailable";
      readonly reason: SchedulerMeasurementTimingUnavailableReason;
    }>;

/** 一条 policy action 之后发生的离散 Scheduler effect。 */
export type SchedulerMeasurementEffect =
  | Readonly<{ readonly kind: "admitted"; readonly taskId: string }>
  | Readonly<{
      readonly kind: "settled";
      readonly settlementKind:
        | "completed"
        | "prerequisite-unsatisfied"
        | "failed"
        | "blocked"
        | "cancelled-before-start";
      readonly taskId: string;
    }>;

/** 上一 accepted policy action 之后的已 flush state observation，不声明 causality 或 critical path。 */
export type SchedulerMeasurementActionObservation =
  | Readonly<{
      readonly effects: readonly SchedulerMeasurementEffect[];
      readonly interval: SchedulerMeasurementActionObservationInterval;
      readonly kind: "select";
      /** invocation 内的 accepted action 序号，从一开始。 */
      readonly sequence: number;
      readonly taskId: string;
    }>
  | Readonly<{
      readonly effects: readonly SchedulerMeasurementEffect[];
      readonly interval: SchedulerMeasurementActionObservationInterval;
      readonly kind: "wait";
      /** invocation 内的 accepted action 序号，从一开始。 */
      readonly sequence: number;
      readonly taskId: null;
    }>;

/** custom policy 的有界 decision-boundary measurement reader。 */
export interface AdmissionPolicyMeasurement {
  /** 当前 decision boundary 的累计标量；完整逐 Task table 只属于终态 measurement。 */
  readonly cumulative: SchedulerDecisionMeasurementCumulative;
  /** 当前 invocation 已捕获且不可变的 action observation prefix 长度。 */
  readonly measurementCount: number;
  /** 只读取当前 context 冻结的 observation prefix；越界 index 返回 `undefined`。 */
  readonly measurementAt: (
    this: void,
    index: number
  ) => SchedulerMeasurementActionObservation | undefined;
}

/** policy 决策时的有界累计事实；刻意不含 terminal per-Task table。 */
interface SchedulerDecisionMeasurementCumulativeFacts {
  readonly declarativeFingerprint: string;
  readonly discrete: Readonly<{
    readonly acceptedWaitCount: number;
    readonly admittedCount: number;
    readonly maxRunning: number;
  }>;
  readonly peaks: SchedulerMeasurementPeakCounts;
}

interface AvailableSchedulerDecisionMeasurementCumulative extends SchedulerDecisionMeasurementCumulativeFacts {
  readonly timing: Readonly<{ readonly availability: "available" }>;
  readonly timingFacts: Readonly<{
    readonly acceptedWaitMs: number;
    readonly effectiveCapacitySlotMs: number;
    readonly rootCapacitySlotMs: number;
    readonly taskSlotMs: number;
  }>;
}

interface UnavailableSchedulerDecisionMeasurementCumulative extends SchedulerDecisionMeasurementCumulativeFacts {
  readonly timing: Readonly<{
    readonly availability: "unavailable";
    readonly reason: SchedulerMeasurementTimingUnavailableReason;
  }>;
  readonly timingFacts?: never;
}

/** custom policy 在 decision boundary 读取的有界累计 measurement；不含终态逐 Task table。 */
export type SchedulerDecisionMeasurementCumulative =
  | AvailableSchedulerDecisionMeasurementCumulative
  | UnavailableSchedulerDecisionMeasurementCumulative;

export interface SchedulerMeasurementPeakCounts {
  readonly admissionViablePendingTaskCount: number;
  readonly admissiblePendingTaskCount: number;
  readonly capacityBlockedTaskCount: number;
  readonly mutexBlockedTaskCount: number;
}

export interface SchedulerMeasurementAdmission {
  readonly admissionDelay: Readonly<{
    readonly admissiblePendingMs: number;
    readonly capacityBlockedMs: number;
    readonly mutexBlockedMs: number;
  }>;
  /** Scheduler monotonic-clock timestamp in milliseconds, or no admission occurred. */
  readonly admittedAtMonotonicMs: number | null;
  /** Scheduler monotonic-clock timestamp in milliseconds, or no settlement occurred. */
  readonly settledAtMonotonicMs: number | null;
  readonly taskId: string;
}

export interface SchedulerMeasurementTimingFacts {
  readonly acceptedWaitMs: number;
  readonly admissions: readonly SchedulerMeasurementAdmission[];
  readonly effectiveCapacitySlotMs: number;
  /** Terminal Scheduler monotonic-clock timestamp in milliseconds. */
  readonly endedAtMonotonicMs: number;
  readonly rootCapacitySlotMs: number;
  readonly schedulerControlPathMs: number;
  readonly schedulerDecisionObservationMs: number;
  /** First Scheduler monotonic-clock timestamp in milliseconds. */
  readonly startedAtMonotonicMs: number;
  readonly taskSlotMs: number;
}

interface SchedulerRawMeasurementFacts {
  readonly declarativeFingerprint: string;
  readonly discrete: Readonly<{
    readonly acceptedWaitCount: number;
    readonly admittedCount: number;
    readonly completionTailActiveTaskIds: readonly string[];
    readonly lastSettledTaskId: string | null;
    readonly maxRunning: number;
  }>;
  readonly peaks: SchedulerMeasurementPeakCounts;
}

interface AvailableSchedulerRawMeasurement extends SchedulerRawMeasurementFacts {
  readonly timing: Readonly<{ readonly availability: "available" }>;
  readonly timingFacts: SchedulerMeasurementTimingFacts;
}

interface UnavailableSchedulerRawMeasurement extends SchedulerRawMeasurementFacts {
  readonly timing: Readonly<{
    readonly availability: "unavailable";
    readonly reason: SchedulerMeasurementTimingUnavailableReason;
  }>;
  readonly timingFacts?: never;
}

/** Scheduler-owned terminal 一阶事实；全部二级 summary 都由 Hook 投影。 */
export type SchedulerRawMeasurement =
  | AvailableSchedulerRawMeasurement
  | UnavailableSchedulerRawMeasurement;

/**
 * 一次 Scheduler 终态 Hook 可读取的递归冻结上下文；不包含 Task 值、错误或可变 engine 对象。
 */
export interface SchedulerMeasurementContext {
  readonly graph: SchedulerGraphSnapshot;
  readonly execution: Readonly<{
    readonly admittedTaskIds: readonly string[];
    readonly settledTasks: readonly Readonly<{
      readonly kind:
        | "completed"
        | "prerequisite-unsatisfied"
        | "failed"
        | "blocked"
        | "cancelled-before-start";
      readonly taskId: string;
    }>[];
  }>;
  readonly rawMeasurement: SchedulerRawMeasurement;
}

/** 一次 terminal Scheduler measurement 的 caller-owned sync/async consumer。 */
export type SchedulerMeasurementHook =
  | ((this: void, context: SchedulerMeasurementContext) => void)
  | ((this: void, context: SchedulerMeasurementContext) => Promise<void>);

/** 定义级的 Scheduler 预算、admission policy 与终态 measurement consumer。 */
export interface SchedulerPolicy {
  readonly admissionPolicy: AdmissionPolicy;
  readonly maxParallel: number;
  readonly measurementHooks: readonly SchedulerMeasurementHook[];
}

export interface DeclarativeSchedulerPolicy {
  readonly admissionPolicy: Readonly<{
    readonly kind: AdmissionPolicy["kind"];
  }>;
  readonly maxParallel: number;
}

import type {
  RunControlDiagnostic,
  RunControlValidationResult
} from "./controls/validation-result.ts";
import type { CheckAggregate, CheckAggregation } from "./controls/contract.ts";
import type { CoreCheck, CoreSnapshot } from "../check-settlement/facts.ts";

type AggregateStatus = Exclude<CheckAggregate, "not-applicable">;

/** Validates that aggregation selects only normalized executable Check IDs. */
export function validateCheckAggregationSelection(
  aggregation: CheckAggregation | undefined,
  checkIds: readonly string[]
): RunControlValidationResult<CheckAggregation | undefined> {
  if (aggregation === undefined) return Object.freeze({ ok: true, value: undefined });
  if (aggregation.checks === "all") return Object.freeze({ ok: true, value: aggregation });
  const knownCheckIds = new Set(checkIds);
  const selectedCheckIds = new Set<string>();
  for (const checkId of aggregation.checks) {
    if (!knownCheckIds.has(checkId) || selectedCheckIds.has(checkId)) {
      return invalidControls("controls.checkAggregation.checks");
    }
    selectedCheckIds.add(checkId);
  }
  return Object.freeze({ ok: true, value: aggregation });
}

/** Derives one explicit consumer-selected aggregate from settled Check statuses only. */
export function aggregateCheckOutcomes(
  snapshot: CoreSnapshot,
  aggregation: CheckAggregation
): CheckAggregate {
  const statuses = selectedChecks(snapshot, aggregation.checks).map((check) =>
    aggregateStatus(check, aggregation)
  );
  if (statuses.includes("unavailable")) return "unavailable";
  return aggregateSelectedStatuses(
    statuses.filter(
      (status): status is Exclude<AggregateStatus, "unavailable"> =>
        status !== null && status !== "unavailable"
    ),
    aggregation
  );
}

function selectedChecks(
  snapshot: CoreSnapshot,
  selection: CheckAggregation["checks"]
): readonly CoreCheck[] {
  if (selection === "all") return snapshot.checks;
  return selection.map((checkId) => {
    const check = snapshot.checks.find((candidate) => candidate.checkId === checkId);
    if (check === undefined) throw new TypeError("Aggregation selection was not validated");
    return check;
  });
}

function aggregateStatus(check: CoreCheck, aggregation: CheckAggregation): AggregateStatus | null {
  switch (check.outcome.status) {
    case "passed":
    case "failed":
      return check.outcome.status;
    case "unavailable": {
      if (aggregation.unavailable === "propagate") return "unavailable";
      return aggregation.unavailable === "fail" ? "failed" : null;
    }
    case "not-applicable": {
      if (aggregation.notApplicable === "pass") return "passed";
      return aggregation.notApplicable === "fail" ? "failed" : null;
    }
  }
}

function aggregateSelectedStatuses(
  statuses: readonly Exclude<AggregateStatus, "unavailable">[],
  aggregation: CheckAggregation
): CheckAggregate {
  if (statuses.length === 0) return aggregation.empty;
  if (aggregation.mode === "all") return statuses.includes("failed") ? "failed" : "passed";
  return statuses.includes("passed") ? "passed" : "failed";
}

function invalidControls(path: string): RunControlValidationResult<never> {
  const error: RunControlDiagnostic = Object.freeze({
    kind: "invalid-run-controls",
    path,
    reason: "invalid-value"
  });
  return Object.freeze({ ok: false, error });
}

import type {
  CheckDependencies,
  CheckExecutionContext,
  CheckMessage,
  CheckOutcome,
  CheckProjectContext
} from "../../check/check.ts";
import type { NormalizedCheck } from "../../project-definition/project-definition.ts";
import { CoreInvariantFailure, type TrustedCheckScope } from "../../check-settlement/session.ts";
import { diagnosticTags, type DiagnosticLogger } from "../diagnostic-logging/logger.ts";
import { invokeWithCapturedConsole } from "./console-capture.ts";

const EMPTY_MESSAGES: readonly CheckMessage[] = Object.freeze([]);

export type CallbackExecution = Readonly<
  | {
      /** Raw author result; Core owns its sole validation and canonicalization. */
      readonly source: "author";
      readonly result: unknown;
      readonly consoleMessages: readonly CheckMessage[];
    }
  | {
      /** Only callback containment may create a Product-controlled outcome. */
      readonly source: "product";
      readonly result: CheckOutcome;
      readonly consoleMessages: readonly CheckMessage[];
    }
>;

interface CheckCallbackInput {
  readonly check: NormalizedCheck;
  readonly dependencies: CheckDependencies;
  readonly diagnosticLogger?: DiagnosticLogger;
  readonly project: CheckProjectContext;
  readonly scope: TrustedCheckScope;
  readonly signal: AbortSignal;
}

interface CheckReporterLifecycle {
  readonly records: CheckExecutionContext<object>["records"];
  close(): void;
}

/** Runs one trusted callback and closes its Check-owned reporter before return. */
export async function executeCheckCallback(input: CheckCallbackInput): Promise<CallbackExecution> {
  const checkId = input.check.definition.checkId;
  const checkTags = diagnosticTags(`CHECK:${checkId}`, "EXECUTION");
  const reporter = createCheckReporter(input.scope, input.diagnosticLogger, checkTags);
  let result: CallbackExecution;
  let consoleMessages = EMPTY_MESSAGES;
  try {
    const context = Object.freeze({
      dependencies: input.dependencies,
      options: input.check.options,
      project: input.project,
      records: reporter.records,
      signal: input.signal
    });
    const invocation = await invokeWithCapturedConsole(() => input.check.execution(context));
    consoleMessages = invocation.messages;
    if (invocation.kind === "threw") throw invocation.error;
    const callbackResult = invocation.output;
    if (input.signal.aborted) {
      input.diagnosticLogger?.observe({
        event: "callback.cancelled",
        tags: diagnosticTags(...checkTags, "CANCELLED"),
        details: { result: callbackResult }
      });
    }
    result = input.signal.aborted
      ? productResult("execution-cancelled", consoleMessages)
      : Object.freeze({
          source: "author",
          result: callbackResult,
          consoleMessages
        });
  } catch (error) {
    if (error instanceof CoreInvariantFailure) throw error;
    input.diagnosticLogger?.observe({
      event: input.signal.aborted ? "callback.cancelled" : "callback.threw",
      tags: diagnosticTags(...checkTags, input.signal.aborted ? "CANCELLED" : "THREW"),
      details: { error }
    });
    result = productResult(
      input.signal.aborted ? "execution-cancelled" : "execution-threw",
      consoleMessages
    );
  } finally {
    reporter.close();
  }
  return result;
}

function createCheckReporter(
  scope: TrustedCheckScope,
  diagnosticLogger: DiagnosticLogger | undefined,
  checkTags: readonly string[]
): CheckReporterLifecycle {
  let isOpen = true;
  return Object.freeze({
    close: (): void => {
      isOpen = false;
    },
    records: Object.freeze({
      report: (identity: unknown, data: unknown): void => {
        if (!isOpen) throw new Error("Check record reporter is closed");
        const result = scope.records.report(identity, data);
        diagnosticLogger?.observe({
          event: "record.reported",
          tags: diagnosticTags(...checkTags, "RECORD", result.toUpperCase()),
          details: { data, identity, result }
        });
      }
    })
  });
}

function productResult(code: string, consoleMessages: readonly CheckMessage[]): CallbackExecution {
  return Object.freeze({
    consoleMessages,
    source: "product",
    result: Object.freeze({ status: "unavailable", reason: Object.freeze({ code }) })
  });
}

import { AsyncLocalStorage } from "node:async_hooks";
import { Console } from "node:console";
import { Writable } from "node:stream";
import { formatWithOptions } from "node:util";

import type { CheckMessage, CheckMessageLevel } from "../../check/check.ts";

type ConsoleInvocation<Result> = Readonly<
  | {
      readonly kind: "returned";
      readonly output: Result;
      readonly messages: readonly CheckMessage[];
    }
  | {
      readonly kind: "threw";
      readonly error: unknown;
      readonly messages: readonly CheckMessage[];
    }
>;

type ConsoleStream = "stderr" | "stdout";

interface ActiveConsoleCall {
  readonly chunks: Array<Readonly<{ readonly stream: ConsoleStream; readonly text: string }>>;
  readonly method: string;
}

interface InstalledConsoleMethod {
  readonly descriptor: PropertyDescriptor | undefined;
  readonly method: string;
}

const HOST_CONSOLE = globalThis.console;
const captureContext = new AsyncLocalStorage<CheckConsoleCapture>();
let activeRouterOwnerCount = 0;
let installedMethods: readonly InstalledConsoleMethod[] = Object.freeze([]);

/** Installs one shared router around the complete resolved-Check execution lifecycle. */
export async function runWithCheckConsoleRouter<Result>(
  operation: () => Result | Promise<Result>
): Promise<Result> {
  const release = acquireConsoleRouter();
  try {
    return await operation();
  } finally {
    release();
  }
}

/**
 * Runs one author-owned Check function in an isolated console capture context. Concurrent contexts
 * keep separate buffers; the resolved-Check lifecycle owns router installation and restoration.
 */
export async function invokeWithCapturedConsole<Result>(
  operation: () => Result | Promise<Result>
): Promise<ConsoleInvocation<Result>> {
  const capture = new CheckConsoleCapture();
  return captureContext.run(capture, async () => {
    try {
      const output = await operation();
      return Object.freeze({ kind: "returned", messages: capture.snapshot(), output });
    } catch (error) {
      return Object.freeze({ kind: "threw", error, messages: capture.snapshot() });
    }
  });
}

class CheckConsoleCapture {
  readonly #console: Console;
  readonly #messages: CheckMessage[] = [];
  #activeCall: ActiveConsoleCall | undefined;

  public constructor() {
    this.#console = new Console({
      colorMode: false,
      ignoreErrors: true,
      stderr: this.#writer("stderr"),
      stdout: this.#writer("stdout")
    });
  }

  public invoke(method: string, arguments_: readonly unknown[]): void {
    const activeCall: ActiveConsoleCall = { chunks: [], method };
    const previousCall = this.#activeCall;
    this.#activeCall = activeCall;
    try {
      const captureMethod: unknown = Reflect.get(this.#console, method);
      if (typeof captureMethod === "function") {
        Reflect.apply(captureMethod, this.#console, arguments_);
      } else {
        activeCall.chunks.push({
          stream: streamForMethod(method),
          text: fallbackConsoleText(method, arguments_)
        });
      }
    } catch {
      activeCall.chunks.push({
        stream: "stderr",
        text: `console.${method} output could not be formatted safely`
      });
    } finally {
      this.#activeCall = previousCall;
      this.#appendCall(activeCall);
    }
  }

  public snapshot(): readonly CheckMessage[] {
    return this.#messages.length === 0 ? Object.freeze([]) : Object.freeze([...this.#messages]);
  }

  #appendCall(call: ActiveConsoleCall): void {
    const chunks = combineAdjacentChunks(call.chunks);
    for (const chunk of chunks) {
      this.#messages.push(
        Object.freeze({
          code: consoleMessageCode(call.method),
          level: levelForConsoleCall(call.method, chunk.stream),
          message: removeTerminalLineEnding(chunk.text)
        })
      );
    }
  }

  #writer(stream: ConsoleStream): Writable {
    return new Writable({
      write: (
        chunk: unknown,
        _encoding: BufferEncoding,
        callback: (error?: Error | null) => void
      ) => {
        const activeCall = this.#activeCall;
        if (activeCall !== undefined) {
          activeCall.chunks.push({ stream, text: String(chunk) });
        }
        callback();
      }
    });
  }
}

function acquireConsoleRouter(): () => void {
  if (activeRouterOwnerCount === 0) installConsoleRouter();
  activeRouterOwnerCount += 1;
  let released = false;
  return () => {
    if (released) return;
    released = true;
    activeRouterOwnerCount -= 1;
    if (activeRouterOwnerCount === 0) restoreConsoleRouter();
  };
}

function installConsoleRouter(): void {
  const installed: InstalledConsoleMethod[] = [];
  try {
    for (const method of consoleMethodNames(HOST_CONSOLE)) {
      const original: unknown = Reflect.get(HOST_CONSOLE, method);
      if (typeof original !== "function") continue;
      const descriptor = Object.getOwnPropertyDescriptor(HOST_CONSOLE, method);
      const routed = function (this: Console, ...arguments_: unknown[]): unknown {
        const capture = captureContext.getStore();
        if (capture !== undefined) {
          capture.invoke(method, arguments_);
          return undefined;
        }
        return Reflect.apply(original, HOST_CONSOLE, arguments_);
      };
      Object.defineProperty(HOST_CONSOLE, method, {
        configurable: true,
        enumerable: descriptor?.enumerable ?? false,
        value: routed,
        writable: true
      });
      installed.push(Object.freeze({ descriptor, method }));
    }
    installedMethods = Object.freeze(installed);
  } catch (error) {
    restoreInstalledMethods(installed);
    throw error;
  }
}

function restoreConsoleRouter(): void {
  restoreInstalledMethods(installedMethods);
  installedMethods = Object.freeze([]);
}

function restoreInstalledMethods(methods: readonly InstalledConsoleMethod[]): void {
  for (const { descriptor, method } of [...methods].reverse()) {
    if (descriptor === undefined) {
      Reflect.deleteProperty(HOST_CONSOLE, method);
    } else {
      Object.defineProperty(HOST_CONSOLE, method, descriptor);
    }
  }
}

function consoleMethodNames(value: Console): readonly string[] {
  const names = new Set<string>();
  let current: object | null = value;
  while (current !== null && current !== Object.prototype) {
    for (const key of Reflect.ownKeys(current)) {
      if (typeof key === "string" && key !== "Console" && key !== "constructor") names.add(key);
    }
    current = Reflect.getPrototypeOf(current);
  }
  return Object.freeze(
    [...names].filter((name) => typeof Reflect.get(value, name) === "function").sort(compareText)
  );
}

function combineAdjacentChunks(
  chunks: readonly Readonly<{ readonly stream: ConsoleStream; readonly text: string }>[]
): readonly Readonly<{ readonly stream: ConsoleStream; readonly text: string }>[] {
  const combined: Array<{ stream: ConsoleStream; text: string }> = [];
  for (const chunk of chunks) {
    const previous = combined.at(-1);
    if (previous?.stream === chunk.stream) {
      previous.text += chunk.text;
    } else {
      combined.push({ stream: chunk.stream, text: chunk.text });
    }
  }
  return combined;
}

function fallbackConsoleText(method: string, arguments_: readonly unknown[]): string {
  const formatted = formatWithOptions({ colors: false }, ...arguments_);
  return formatted.length === 0 ? `console.${method}()` : formatted;
}

function consoleMessageCode(method: string): string {
  const normalized = method
    .replaceAll(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replaceAll(/[^a-zA-Z0-9-]/g, "-")
    .toLowerCase();
  return `console-${normalized}`;
}

function levelForConsoleCall(method: string, stream: ConsoleStream): CheckMessageLevel {
  if (method === "warn") return "warning";
  if (method === "assert" || method === "error" || method === "trace") return "error";
  return stream === "stderr" ? "error" : "info";
}

function streamForMethod(method: string): ConsoleStream {
  return method === "assert" || method === "error" || method === "trace" || method === "warn"
    ? "stderr"
    : "stdout";
}

function removeTerminalLineEnding(text: string): string {
  if (text.endsWith("\r\n") && text.length > 2) return text.slice(0, -2);
  if (text.endsWith("\n") && text.length > 1) return text.slice(0, -1);
  return text;
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import type {
  CheckDependencies,
  CheckOutcome,
  DependencyObservation,
  DependencyReadResult
} from "../../check/check.ts";
import type { CoreCheckSession } from "../../check-settlement/session.ts";
import { diagnosticTags, type DiagnosticLogger } from "../diagnostic-logging/logger.ts";

export function createCheckDependencies(
  input: Readonly<{
    readonly checkId: string;
    readonly diagnosticLogger: DiagnosticLogger | undefined;
    readonly directRelationCheckIds: readonly string[];
    readonly session: CoreCheckSession;
  }>
): CheckDependencies {
  return Object.freeze({
    get: (dependencyId: string): DependencyReadResult => {
      const result = readDirectRelation(input.session, input.directRelationCheckIds, dependencyId);
      input.diagnosticLogger?.observe({
        event: "dependency.read",
        tags: diagnosticTags(`CHECK:${input.checkId}`, "EXECUTION", "DEPENDENCY-READ"),
        details: dependencyReadDetails(dependencyId, result)
      });
      return result;
    },
    list: (): readonly DependencyObservation[] => {
      const observations = listDirectRelationObservations(
        input.session,
        input.directRelationCheckIds
      );
      input.diagnosticLogger?.observe({
        event: "dependency.list",
        tags: diagnosticTags(`CHECK:${input.checkId}`, "EXECUTION", "DEPENDENCY-LIST"),
        details: directRelationListDetails(observations)
      });
      return observations;
    }
  });
}

function listDirectRelationObservations(
  session: CoreCheckSession,
  directRelationCheckIds: readonly string[]
): readonly DependencyObservation[] {
  return Object.freeze(
    directRelationCheckIds.map((checkId) =>
      Object.freeze({ checkId, outcome: session.readSettledCheckOutcome(checkId) })
    )
  );
}

function directRelationListDetails(
  observations: readonly DependencyObservation[]
): Readonly<Record<string, unknown>> {
  return Object.freeze({
    dependencyIds: Object.freeze(observations.map(({ checkId }) => checkId)),
    count: observations.length
  });
}

function dependencyReadDetails(
  requestedCheckId: unknown,
  result: DependencyReadResult
): Readonly<Record<string, unknown>> {
  if (!result.ok) {
    return Object.freeze({ error: result.error, ok: false, requestedCheckId });
  }
  return Object.freeze({
    hasData: true,
    ok: true,
    producer: result.checkId,
    status: result.status
  });
}

function readDirectRelation(
  session: CoreCheckSession,
  directRelationCheckIds: readonly string[],
  checkId: string
): DependencyReadResult {
  if (typeof checkId !== "string" || !directRelationCheckIds.includes(checkId)) {
    return dependencyNotDeclared(checkId);
  }
  return dependencyReadResult(checkId, session.readSettledCheckOutcome(checkId));
}

function dependencyReadResult(checkId: string, outcome: CheckOutcome): DependencyReadResult {
  if (outcome.status === "passed" || outcome.status === "failed") {
    return Object.freeze({ ok: true, checkId, status: outcome.status, data: outcome.data });
  }
  return Object.freeze({
    ok: false,
    error: Object.freeze({ code: "upstream-data-unavailable", checkId, status: outcome.status })
  });
}

function dependencyNotDeclared(checkId: unknown): DependencyReadResult {
  return Object.freeze({
    ok: false,
    error: Object.freeze({
      code: "dependency-not-declared",
      checkId: typeof checkId === "string" ? checkId : ""
    })
  });
}

import type { CheckMessage } from "../../check/check.ts";
import type { CoreSnapshot } from "../../check-settlement/facts.ts";
import type { NormalizedCheck } from "../../project-definition/project-definition.ts";
import type { SettledTask } from "../task-scheduler/scheduler.ts";
import type { CheckDuration, CheckRunMessage } from "../result.ts";
import {
  CheckExecutionInvariantFailure,
  recordSettledCheck,
  type CheckIdentity,
  type SettledCheckFacts
} from "./execution-settlement.ts";
import type { CheckExecutionState, ResolvedCheckExecution } from "./resolved-checks.ts";

const EMPTY_MESSAGES: readonly CheckMessage[] = Object.freeze([]);

/** Closes the task graph, lifecycle facts, and canonical Check summaries as one Run boundary. */
export function closeResolvedChecks(
  input: Readonly<{
    readonly allChecks: readonly NormalizedCheck[];
    readonly graphRun: Awaited<
      ReturnType<typeof import("../task-scheduler/scheduler.ts").runTaskGraph<boolean>>
    >;
    readonly state: CheckExecutionState;
  }>
): ResolvedCheckExecution {
  try {
    assertNoTaskEngineFailures(input.graphRun.settlements);
    if (input.graphRun.admissionPolicyFault !== undefined) {
      return closeAdmissionPolicyFailed({
        normalizedChecks: input.allChecks,
        state: input.state
      });
    }
    if (input.graphRun.cancelled) {
      return closeCancelledExecution({
        normalizedChecks: input.allChecks,
        state: input.state
      });
    }
    assertEveryCheckClosed(input.allChecks, input.graphRun.settlements);
    return resolvedExecution("completed", input.state.session.freeze(), input.state);
  } catch (error) {
    throw trustedFailure(error);
  }
}

export function closeAdmissionPolicyFailed(
  input: Readonly<{
    readonly normalizedChecks: readonly NormalizedCheck[];
    readonly state: CheckExecutionState;
  }>
): ResolvedCheckExecution {
  input.state.session.closeUnresolvedAsCancelled();
  const snapshot = input.state.session.freeze();
  settleUnstartedCancelledChecks({ ...input, snapshot });
  return resolvedExecution("admission-policy-failed", snapshot, input.state);
}

export function closeCancelledExecution(
  input: Readonly<{
    readonly normalizedChecks: readonly NormalizedCheck[];
    readonly state: CheckExecutionState;
  }>
): ResolvedCheckExecution {
  input.state.session.closeUnresolvedAsCancelled();
  const snapshot = input.state.session.freeze();
  settleUnstartedCancelledChecks({ ...input, snapshot });
  return resolvedExecution("cancelled", snapshot, input.state);
}

export function checkIdentity(
  check: Pick<NormalizedCheck, "definition" | "visibility">
): CheckIdentity {
  return Object.freeze({
    checkId: check.definition.checkId,
    displayName: check.definition.displayName,
    visibility: check.visibility
  });
}

export function trustedFailure(error: unknown): CheckExecutionInvariantFailure {
  return error instanceof CheckExecutionInvariantFailure
    ? error
    : new CheckExecutionInvariantFailure(
        "Check execution adapter escaped its contained failure boundary"
      );
}

function resolvedExecution(
  kind: ResolvedCheckExecution["kind"],
  snapshot: CoreSnapshot,
  state: CheckExecutionState
): ResolvedCheckExecution {
  return Object.freeze({
    kind,
    ...checkRunSummaries(snapshot, state.settledFactsByCheckId),
    snapshot
  });
}

function settleUnstartedCancelledChecks(
  input: Readonly<{
    readonly normalizedChecks: readonly NormalizedCheck[];
    readonly snapshot: CoreSnapshot;
    readonly state: CheckExecutionState;
  }>
): void {
  const normalizedByCheckId = new Map(
    input.normalizedChecks.map((check) => [check.definition.checkId, check])
  );
  for (const check of input.snapshot.checks) {
    if (input.state.settledFactsByCheckId.has(check.checkId)) continue;
    const normalized = normalizedByCheckId.get(check.checkId);
    if (normalized === undefined) {
      throw new CheckExecutionInvariantFailure(
        "Cancelled Check does not identify a normalized Check"
      );
    }
    recordSettledCheck({
      check: checkIdentity(normalized),
      durationMs: null,
      messages: EMPTY_MESSAGES,
      outcome: check.outcome,
      phase: "execution",
      state: input.state
    });
  }
}

function checkRunSummaries(
  snapshot: CoreSnapshot,
  settledFactsByCheckId: ReadonlyMap<string, SettledCheckFacts>
): Readonly<{
  readonly checkDurations: readonly CheckDuration[];
  readonly checkMessages: readonly CheckRunMessage[];
}> {
  if (snapshot.checks.length !== settledFactsByCheckId.size) {
    throw new CheckExecutionInvariantFailure("Check settled facts do not close every Check");
  }
  const checkDurations: CheckDuration[] = [];
  const messages: CheckRunMessage[] = [];
  for (const check of snapshot.checks) {
    const settledFacts = settledFactsByCheckId.get(check.checkId);
    if (settledFacts === undefined) {
      throw new CheckExecutionInvariantFailure("Check settled facts are missing a Check");
    }
    checkDurations.push(
      Object.freeze({ checkId: check.checkId, durationMs: settledFacts.durationMs })
    );
    messages.push(
      ...settledFacts.messages.map((message) =>
        Object.freeze({ checkId: check.checkId, ...message })
      )
    );
  }
  return Object.freeze({
    checkDurations: Object.freeze(checkDurations),
    checkMessages: messages.length === 0 ? Object.freeze([]) : Object.freeze(messages)
  });
}

/** Closes one Scheduler-blocked Check before a terminal observer may start. */
export function settleBlockedDependent(
  input: Readonly<{
    readonly check: NormalizedCheck;
    readonly dependencyIds: readonly string[];
    readonly state: CheckExecutionState;
  }>
): void {
  const scope = input.state.session.openCheckScope(input.check.definition.checkId);
  const outcome = scope.settleProduct(
    Object.freeze({
      status: "unavailable" as const,
      reason: Object.freeze({
        code: "dependency-not-passed",
        checkIds: Object.freeze([...input.dependencyIds])
      })
    })
  );
  recordSettledCheck({
    check: checkIdentity(input.check),
    durationMs: null,
    messages: EMPTY_MESSAGES,
    outcome,
    phase: "dependency",
    state: input.state
  });
}

function assertNoTaskEngineFailures(settlements: readonly SettledTask<boolean>[]): void {
  for (const settled of settlements) {
    if (settled.settlement.kind === "failed") {
      throw new CheckExecutionInvariantFailure(
        "Task engine received an unexpected execution failure"
      );
    }
  }
}

function assertEveryCheckClosed(
  checks: readonly NormalizedCheck[],
  settlements: readonly SettledTask<boolean>[]
): void {
  if (settlements.some((settled) => settled.settlement.kind === "cancelled-before-start")) {
    throw new CheckExecutionInvariantFailure("Non-cancelled Task graph left a Check unstarted");
  }
  if (checks.length !== settlements.length) {
    throw new CheckExecutionInvariantFailure(
      "Task graph does not have one Task per executable Check"
    );
  }
}

import type { CheckMessage, CheckOutcome, CheckVisibility } from "../../check/check.ts";
import type { CoreCheckSession } from "../../check-settlement/session.ts";
import {
  diagnosticTags,
  summarizeDiagnosticValue,
  type DiagnosticLogger
} from "../diagnostic-logging/logger.ts";
import { parseCheckTerminalResult } from "./terminal-result.ts";
import { combineCheckMessages } from "./messages.ts";
import type { CheckExecutionLifecycle } from "./lifecycle.ts";
import type { executeCheckCallback } from "./callback.ts";

export type CheckIdentity = Readonly<{
  readonly checkId: string;
  readonly displayName: string;
  readonly visibility: CheckVisibility;
}>;

export interface SettledCheckFacts {
  readonly durationMs: number | null;
  readonly messages: readonly CheckMessage[];
}

export type CheckExecutionSettlementState = Readonly<{
  readonly diagnosticLogger: DiagnosticLogger | undefined;
  readonly lifecycle: CheckExecutionLifecycle | undefined;
  readonly settledFactsByCheckId: Map<string, SettledCheckFacts>;
}>;

export class CheckExecutionInvariantFailure extends Error {
  public constructor(message: string) {
    super(message);
    this.name = "CheckExecutionInvariantFailure";
  }
}

export function settleCallback(
  input: Readonly<{
    readonly callback: Awaited<ReturnType<typeof executeCheckCallback>>;
    readonly checkId: string;
    readonly diagnosticLogger: DiagnosticLogger | undefined;
    readonly preflightMessages: readonly CheckMessage[];
    readonly scope: ReturnType<CoreCheckSession["openCheckScope"]>;
  }>
): Readonly<{ readonly messages: readonly CheckMessage[]; readonly outcome: CheckOutcome }> {
  const executionTags = diagnosticTags(`CHECK:${input.checkId}`, "EXECUTION");
  const { callback } = input;
  if (callback.source === "product") {
    const outcome = input.scope.settleProduct(callback.result);
    return Object.freeze({
      messages: combineCheckMessages(input.preflightMessages, callback.consoleMessages),
      outcome
    });
  }
  const terminal = parseCheckTerminalResult(callback.result);
  if (terminal === undefined) {
    input.diagnosticLogger?.observe({
      event: "callback.malformed",
      tags: diagnosticTags(...executionTags, "MALFORMED"),
      details: { result: callback.result }
    });
  }
  const settlement = input.scope.settle(terminal?.result ?? callback.result);
  if (terminal !== undefined && !settlement.authorResultAccepted) {
    input.diagnosticLogger?.observe({
      event: "check.contained",
      tags: diagnosticTags(...executionTags, "CONTAINED"),
      details: { outcome: diagnosticOutcome(settlement.outcome), raw: callback.result }
    });
  }
  return Object.freeze({
    messages:
      terminal !== undefined && settlement.authorResultAccepted
        ? combineCheckMessages(input.preflightMessages, callback.consoleMessages, terminal.messages)
        : combineCheckMessages(input.preflightMessages, callback.consoleMessages),
    outcome: settlement.outcome
  });
}

/** Records one terminal Check lifecycle fact after its owning Core scope has closed. */
export function recordSettledCheck(
  input: Readonly<{
    readonly check: CheckIdentity;
    readonly durationMs: number | null;
    readonly messages: readonly CheckMessage[];
    readonly outcome: CheckOutcome;
    readonly phase: "control" | "dependency" | "execution" | "preflight";
    readonly state: CheckExecutionSettlementState;
  }>
): void {
  if (input.state.settledFactsByCheckId.has(input.check.checkId)) {
    throw new CheckExecutionInvariantFailure("Check lifecycle settled more than once");
  }
  input.state.settledFactsByCheckId.set(
    input.check.checkId,
    Object.freeze({ durationMs: input.durationMs, messages: input.messages })
  );
  input.state.diagnosticLogger?.observe({
    event: "check.finished",
    tags: diagnosticTags(
      `CHECK:${input.check.checkId}`,
      input.phase.toUpperCase(),
      "FINISHED",
      input.outcome.status.toUpperCase()
    ),
    details: {
      durationMs: input.durationMs,
      ...(input.messages.length === 0 ? {} : { messages: input.messages }),
      ...diagnosticSettledOutcome(input.outcome)
    }
  });
  input.state.lifecycle?.settled(
    Object.freeze({
      checkId: input.check.checkId,
      displayName: input.check.displayName,
      outcome: input.outcome,
      durationMs: input.durationMs,
      messages: input.messages,
      visibility: input.check.visibility
    })
  );
}

function diagnosticSettledOutcome(outcome: CheckOutcome): Readonly<Record<string, unknown>> {
  switch (outcome.status) {
    case "passed":
    case "failed":
      return Object.freeze({ data: summarizeDiagnosticValue(outcome.data) });
    case "not-applicable":
      return outcome.reason === undefined
        ? Object.freeze({})
        : Object.freeze({ reason: outcome.reason });
    case "unavailable":
      return Object.freeze({ reason: outcome.reason });
  }
}

function diagnosticOutcome(outcome: CheckOutcome): Readonly<Record<string, unknown>> {
  switch (outcome.status) {
    case "passed":
    case "failed":
      return Object.freeze({
        data: summarizeDiagnosticValue(outcome.data),
        status: outcome.status
      });
    case "not-applicable":
      return Object.freeze({ reason: outcome.reason ?? null, status: outcome.status });
    case "unavailable":
      return Object.freeze({ reason: outcome.reason, status: outcome.status });
  }
}

import type { NormalizedCheck } from "../../project-definition/project-definition.ts";
import { diagnosticTags, type DiagnosticLogger } from "../diagnostic-logging/logger.ts";

export const FLAG_CONDITION_NOT_MATCHED_CODE = "flag-condition-not-matched";

type FlagControlledCheck = Pick<NormalizedCheck, "definition" | "visibility">;
type FlagControlOutcome = Readonly<{
  readonly status: "not-applicable";
  readonly reason: Readonly<{ readonly code: typeof FLAG_CONDITION_NOT_MATCHED_CODE }>;
}>;

export type FlagControlSettlement = Readonly<{
  readonly check: FlagControlledCheck;
  readonly outcome: FlagControlOutcome;
}>;

/** Resolves all flag-controlled outcomes before Scheduler admission or Check-owned work. */
export function resolveFlagControlSettlements(
  input: Readonly<{
    readonly checks: readonly NormalizedCheck[];
    readonly diagnosticLogger?: DiagnosticLogger;
    readonly flags: readonly string[];
    readonly signal: AbortSignal | undefined;
  }>
): readonly FlagControlSettlement[] {
  if (input.signal?.aborted === true) return Object.freeze([]);

  const settlements: FlagControlSettlement[] = [];
  for (const check of input.checks) {
    const settlement = resolveFlagControl(check, input.flags);
    if (settlement === undefined) continue;
    settlements.push(settlement);
    input.diagnosticLogger?.observe({
      event: "control.resolved",
      tags: diagnosticTags(
        `CHECK:${check.definition.checkId}`,
        "CONTROL",
        FLAG_CONDITION_NOT_MATCHED_CODE.toUpperCase()
      ),
      details: {
        enabledByFlags: check.enabledByFlags,
        outcome: settlement.outcome
      }
    });
  }
  return Object.freeze(settlements);
}

function resolveFlagControl(
  check: NormalizedCheck,
  runFlags: readonly string[]
): FlagControlSettlement | undefined {
  if (check.enabledByFlags === undefined || matchesFlagEnablement(check.enabledByFlags, runFlags)) {
    return undefined;
  }
  return Object.freeze({
    check: Object.freeze({
      definition: check.definition,
      visibility: check.visibility
    }),
    outcome: Object.freeze({
      status: "not-applicable",
      reason: Object.freeze({ code: FLAG_CONDITION_NOT_MATCHED_CODE })
    })
  });
}

function matchesFlagEnablement(
  enablement: NonNullable<NormalizedCheck["enabledByFlags"]>,
  runFlags: readonly string[]
): boolean {
  const isPresentInRun = (flag: string): boolean => runFlags.includes(flag);
  switch (enablement.mode) {
    case "all":
      return enablement.flags.every(isPresentInRun);
    case "any":
      return enablement.flags.some(isPresentInRun);
    case "none":
      return !enablement.flags.some(isPresentInRun);
    case "not-all":
      return !enablement.flags.every(isPresentInRun);
  }
}

import type { CheckMessage, CheckOutcome, CheckVisibility } from "../../check/check.ts";

/** Private Run handoff for Check lifecycle presentation and accounting. */
export type CheckExecutionLifecycle = Readonly<{
  /** Fires after the invocation-wide flag-control phase and before Scheduler execution starts. */
  readonly flagControlCompleted: () => void;
  readonly started: (fact: CheckStartedFact) => void;
  readonly settled: (fact: CheckSettledFact) => void;
}>;

export type CheckStartedFact = Readonly<{ checkId: string; displayName: string }>;

export type CheckSettledFact = CheckStartedFact &
  Readonly<{
    durationMs: number | null;
    messages: readonly CheckMessage[];
    outcome: CheckOutcome;
    visibility: CheckVisibility;
  }>;

import type { CheckMessage } from "../../check/check.ts";
import {
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedArray,
  snapshotClosedRecord
} from "../../data-boundary/closed-values.ts";

const EMPTY_MESSAGES: readonly CheckMessage[] = Object.freeze([]);

/** Preserves phase-local order while avoiding mutable or per-call empty message collections. */
export function combineCheckMessages(
  ...collections: readonly (readonly CheckMessage[])[]
): readonly CheckMessage[] {
  const messages = collections.flat();
  return messages.length === 0 ? EMPTY_MESSAGES : Object.freeze(messages);
}

/** Parses the shared closed Check-message attachment without retaining author input. */
export function parseCheckMessages(value: unknown): readonly CheckMessage[] | undefined {
  if (value === undefined) return EMPTY_MESSAGES;
  const authoredMessages = snapshotClosedArray(value);
  if (authoredMessages === undefined) return undefined;

  const messages: CheckMessage[] = [];
  for (const authoredMessage of authoredMessages) {
    const message = detachedMessage(authoredMessage);
    if (message === undefined) return undefined;
    messages.push(message);
  }
  return messages.length === 0 ? EMPTY_MESSAGES : Object.freeze(messages);
}

function detachedMessage(value: unknown): CheckMessage | undefined {
  const message = snapshotClosedRecord(value);
  if (
    message === undefined ||
    !hasRequiredAndOptionalRecordKeys(message, {
      required: ["level", "code", "message"],
      optional: []
    }) ||
    !isCheckMessageLevel(message.level) ||
    typeof message.code !== "string" ||
    message.code.length === 0 ||
    typeof message.message !== "string" ||
    message.message.length === 0
  ) {
    return undefined;
  }
  return Object.freeze({ code: message.code, level: message.level, message: message.message });
}

function isCheckMessageLevel(value: unknown): value is CheckMessage["level"] {
  return value === "info" || value === "warning" || value === "error";
}

import type { TaskGraph, TaskNode, TaskScope } from "../task-scheduler/graph.ts";
import type { NormalizedCheck } from "../../project-definition/project-definition.ts";

/**
 * Pure executable-Check projection. Check ids are the only scheduler Task
 * identities: containment has already been resolved by Definition and has no
 * runtime alias or completion semantics here.
 */
export function planStaticCheckGraph(checks: readonly NormalizedCheck[]): TaskGraph {
  const tasks = checks.map(taskForCheck);
  const scopes = checks.map(scopeForCheck);
  return Object.freeze({
    tasks: Object.freeze(tasks),
    scopes: Object.freeze(scopes)
  });
}

function taskForCheck(check: NormalizedCheck): TaskNode {
  return Object.freeze({
    admissionPriority: check.admissionPriority,
    dependsOn: check.dependsOn,
    id: check.definition.checkId,
    mutex: check.mutex,
    observes: check.observes,
    scopeId: scopeIdFor(check)
  });
}

function scopeForCheck(check: NormalizedCheck): TaskScope {
  const taskId = check.definition.checkId;
  return Object.freeze({
    activationTaskIds: Object.freeze([taskId]),
    id: scopeIdFor(check),
    maxParallel: check.maxParallel,
    terminalTaskId: taskId
  });
}

function scopeIdFor(check: NormalizedCheck): string {
  return `check/${check.definition.checkId}`;
}

import {
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedRecord
} from "../../data-boundary/closed-values.ts";
import type { CheckMessage } from "../../check/check.ts";
import { parseCheckMessages } from "./messages.ts";

export type ParsedCheckPreflightResult =
  | Readonly<{
      readonly status: "success";
      readonly preparedOptions: unknown;
      readonly messages: readonly CheckMessage[];
    }>
  | Readonly<{
      readonly status: "failure";
      readonly action: "block";
      readonly reason: { readonly code: string };
      readonly messages: readonly CheckMessage[];
    }>
  | Readonly<{
      readonly status: "failure";
      readonly action: "continue";
      readonly fallback: unknown;
      readonly reason: { readonly code: string };
      readonly messages: readonly CheckMessage[];
    }>;

/** Parses the closed result vocabulary returned by one trusted Check preflight. */
export function parseCheckPreflightResult(value: unknown): ParsedCheckPreflightResult | undefined {
  const preflightResult = snapshotClosedRecord(value);
  if (preflightResult === undefined) {
    return undefined;
  }
  const messages = parseCheckMessages(preflightResult.messages);
  if (messages === undefined) return undefined;
  switch (preflightResult.status) {
    case "success":
      return parseSuccessfulPreflight(preflightResult, messages);
    case "failure":
      return parseFailedPreflight(preflightResult, messages);
    default:
      return undefined;
  }
}

function parseSuccessfulPreflight(
  preflightResult: Readonly<Record<string, unknown>>,
  messages: readonly CheckMessage[]
): ParsedCheckPreflightResult | undefined {
  if (
    !hasRequiredAndOptionalRecordKeys(preflightResult, {
      optional: ["messages"],
      required: ["status", "preparedOptions"]
    })
  ) {
    return undefined;
  }
  return Object.freeze({
    status: "success",
    preparedOptions: preflightResult.preparedOptions,
    messages
  });
}

function parseFailedPreflight(
  preflightResult: Readonly<Record<string, unknown>>,
  messages: readonly CheckMessage[]
): ParsedCheckPreflightResult | undefined {
  if (typeof preflightResult.action !== "string") return undefined;
  const reason = parsePreflightReason(preflightResult.reason);
  if (reason === undefined) return undefined;
  switch (preflightResult.action) {
    case "block":
      return parseBlockedPreflight(preflightResult, reason, messages);
    case "continue":
      return parseContinuedPreflight(preflightResult, reason, messages);
    default:
      return undefined;
  }
}

function parseBlockedPreflight(
  preflightResult: Readonly<Record<string, unknown>>,
  reason: Readonly<{ readonly code: string }>,
  messages: readonly CheckMessage[]
): ParsedCheckPreflightResult | undefined {
  if (
    !hasRequiredAndOptionalRecordKeys(preflightResult, {
      optional: ["messages"],
      required: ["status", "action", "reason"]
    })
  ) {
    return undefined;
  }
  return Object.freeze({ status: "failure", action: "block", reason, messages });
}

function parseContinuedPreflight(
  preflightResult: Readonly<Record<string, unknown>>,
  reason: Readonly<{ readonly code: string }>,
  messages: readonly CheckMessage[]
): ParsedCheckPreflightResult | undefined {
  if (
    !hasRequiredAndOptionalRecordKeys(preflightResult, {
      optional: ["messages"],
      required: ["status", "action", "fallback", "reason"]
    })
  ) {
    return undefined;
  }
  return Object.freeze({
    status: "failure",
    action: "continue" as const,
    fallback: preflightResult.fallback,
    reason,
    messages
  });
}

function parsePreflightReason(value: unknown): Readonly<{ readonly code: string }> | undefined {
  const reason = snapshotClosedRecord(value);
  if (
    reason === undefined ||
    Object.keys(reason).length !== 1 ||
    typeof reason.code !== "string" ||
    reason.code.length === 0
  ) {
    return undefined;
  }
  return Object.freeze({ code: reason.code });
}

import type { CheckMessage, CheckOutcome } from "../../check/check.ts";
import type { NormalizedCheck } from "../../project-definition/project-definition.ts";
import { snapshotJsonObject } from "../../check/options-snapshot.ts";
import {
  diagnosticTags,
  summarizeDiagnosticValue,
  type DiagnosticLogger
} from "../diagnostic-logging/logger.ts";
import { parseCheckPreflightResult, type ParsedCheckPreflightResult } from "./preflight-result.ts";
import { invokeWithCapturedConsole } from "./console-capture.ts";
import { combineCheckMessages } from "./messages.ts";

const EMPTY_MESSAGES: readonly CheckMessage[] = Object.freeze([]);
const INERT_SIGNAL = new AbortController().signal;

export type PreparedCheck = Omit<NormalizedCheck, "options" | "preflight"> &
  Readonly<{ readonly options: object; readonly preflightMessages: readonly CheckMessage[] }>;

type BlockedCheck = Pick<NormalizedCheck, "definition" | "visibility"> &
  Readonly<{ readonly preflightMessages: readonly CheckMessage[] }>;

export type ReadyCheckPreflightResolution = Readonly<{
  readonly kind: "ready";
  readonly check: PreparedCheck;
}>;

export type BlockedCheckPreflightResolution = Readonly<{
  readonly kind: "blocked";
  readonly check: BlockedCheck;
  readonly outcome: CheckOutcome;
}>;

export type CheckPreflightResolution =
  | ReadyCheckPreflightResolution
  | BlockedCheckPreflightResolution;

type PreflightResolutionResult =
  | "skipped"
  | "prepared"
  | "continued"
  | "blocked"
  | "cancelled-before-callback"
  | "cancelled-after-callback"
  | "cancelled-after-throw"
  | "threw"
  | "malformed";

type PrepareCheckInput = Readonly<{
  readonly check: NormalizedCheck;
  readonly diagnosticLogger: DiagnosticLogger | undefined;
  readonly signal: AbortSignal | undefined;
}>;

type PreflightInvocation = Awaited<ReturnType<typeof invokeWithCapturedConsole<unknown>>>;

/** Resolves one Check's task-local preparation after Scheduler admission. */
export async function prepareCheck(input: PrepareCheckInput): Promise<CheckPreflightResolution> {
  if (input.signal?.aborted) {
    return observeBlockedPreflight({
      check: input.check,
      diagnosticLogger: input.diagnosticLogger,
      details: {},
      result: "cancelled-before-callback",
      reasonCode: "execution-cancelled"
    });
  }
  if (input.check.preflight === undefined) {
    return resolveAuthoredOptions(input);
  }
  return resolvePreflightInvocation(input, await invokePreflight(input.check, input.signal));
}

function resolveAuthoredOptions(input: PrepareCheckInput): CheckPreflightResolution {
  const resolution = readyResolution({
    authoredCheck: input.check,
    messages: EMPTY_MESSAGES,
    preparedOptions: input.check.options
  });
  observeReadyOrMalformedResolution(
    input.diagnosticLogger,
    input.check.definition.checkId,
    resolution,
    "skipped",
    { source: "authored" }
  );
  return resolution;
}

function resolvePreflightInvocation(
  input: PrepareCheckInput,
  invocation: PreflightInvocation
): CheckPreflightResolution {
  if (invocation.kind === "threw") {
    return observeBlockedPreflight({
      check: input.check,
      diagnosticLogger: input.diagnosticLogger,
      details: { error: invocation.error },
      messages: invocation.messages,
      result: input.signal?.aborted ? "cancelled-after-throw" : "threw",
      reasonCode: input.signal?.aborted ? "execution-cancelled" : "preflight-threw"
    });
  }
  return resolveReturnedPreflight(input, invocation.output, invocation.messages);
}

function resolveReturnedPreflight(
  input: PrepareCheckInput,
  preflightOutput: unknown,
  consoleMessages: readonly CheckMessage[]
): CheckPreflightResolution {
  if (input.signal?.aborted) {
    return observeBlockedPreflight({
      check: input.check,
      diagnosticLogger: input.diagnosticLogger,
      details: { raw: preflightOutput },
      messages: consoleMessages,
      result: "cancelled-after-callback",
      reasonCode: "execution-cancelled"
    });
  }
  const preflightResult = parseCheckPreflightResult(preflightOutput);
  if (preflightResult === undefined) {
    return observeBlockedPreflight({
      check: input.check,
      diagnosticLogger: input.diagnosticLogger,
      details: { raw: preflightOutput },
      messages: consoleMessages,
      result: "malformed",
      reasonCode: "invalid-preflight-result"
    });
  }
  if (preflightResult.status === "failure" && preflightResult.action === "block") {
    return resolveBlockedPreflightResult(input, preflightResult, consoleMessages);
  }
  return resolveReadyPreflightResult(input, preflightOutput, preflightResult, consoleMessages);
}

function resolveBlockedPreflightResult(
  input: PrepareCheckInput,
  preflightResult: Extract<ParsedCheckPreflightResult, { readonly action: "block" }>,
  consoleMessages: readonly CheckMessage[]
): CheckPreflightResolution {
  const resolution = blockedResolution({
    check: input.check,
    messages: combineCheckMessages(consoleMessages, preflightResult.messages),
    reasonCode: preflightResult.reason.code
  });
  observePreflightResolution(
    input.diagnosticLogger,
    input.check.definition.checkId,
    resolution,
    "blocked",
    {
      ...(preflightResult.messages.length === 0 ? {} : { messages: preflightResult.messages }),
      reason: preflightResult.reason
    }
  );
  return resolution;
}

function resolveReadyPreflightResult(
  input: PrepareCheckInput,
  preflightOutput: unknown,
  preflightResult: Exclude<ParsedCheckPreflightResult, { readonly action: "block" }>,
  consoleMessages: readonly CheckMessage[]
): CheckPreflightResolution {
  const checkId = input.check.definition.checkId;
  const result = preflightResult.status === "success" ? "prepared" : "continued";
  const resolution = readyResolution({
    authoredCheck: input.check,
    messages: combineCheckMessages(consoleMessages, preflightResult.messages),
    preparedOptions:
      preflightResult.status === "success"
        ? preflightResult.preparedOptions
        : preflightResult.fallback
  });
  observeReadyOrMalformedResolution(input.diagnosticLogger, checkId, resolution, result, {
    messages: preflightResult.messages,
    ...(preflightResult.status === "success" ? {} : { reason: preflightResult.reason }),
    raw: preflightOutput
  });
  return resolution;
}

async function invokePreflight(
  check: NormalizedCheck,
  signal: AbortSignal | undefined
): Promise<PreflightInvocation> {
  return invokeWithCapturedConsole(() => check.preflight!(check.options, signal ?? INERT_SIGNAL));
}

function observeBlockedPreflight(
  input: Readonly<{
    readonly check: NormalizedCheck;
    readonly diagnosticLogger: DiagnosticLogger | undefined;
    readonly details: Readonly<Record<string, unknown>>;
    readonly messages?: readonly CheckMessage[];
    readonly result: PreflightResolutionResult;
    readonly reasonCode: string;
  }>
): BlockedCheckPreflightResolution {
  const resolution = blockedResolution({
    check: input.check,
    messages: input.messages ?? EMPTY_MESSAGES,
    reasonCode: input.reasonCode
  });
  observePreflightResolution(
    input.diagnosticLogger,
    input.check.definition.checkId,
    resolution,
    input.result,
    input.details
  );
  return resolution;
}

function observeReadyOrMalformedResolution(
  diagnosticLogger: DiagnosticLogger | undefined,
  checkId: string,
  resolution: CheckPreflightResolution,
  result: "skipped" | "prepared" | "continued",
  details: Readonly<Record<string, unknown>>
): void {
  if (resolution.kind === "blocked") {
    observePreflightResolution(diagnosticLogger, checkId, resolution, "malformed", {
      raw: "raw" in details ? details.raw : summarizeDiagnosticValue(details)
    });
    return;
  }
  const messages = "messages" in details ? details.messages : EMPTY_MESSAGES;
  observePreflightResolution(diagnosticLogger, checkId, resolution, result, {
    ...(Array.isArray(messages) && messages.length > 0 ? { messages } : {}),
    options: summarizeDiagnosticValue(resolution.check.options),
    ...("reason" in details ? { reason: details.reason } : {}),
    ...("source" in details ? { source: details.source } : {})
  });
}

function observePreflightResolution(
  diagnosticLogger: DiagnosticLogger | undefined,
  checkId: string,
  resolution: CheckPreflightResolution,
  result: PreflightResolutionResult,
  details: Readonly<Record<string, unknown>>
): void {
  diagnosticLogger?.observe({
    event: "preflight.resolved",
    tags: diagnosticTags(`CHECK:${checkId}`, "PREFLIGHT", result.toUpperCase()),
    details: {
      ...details,
      ...(resolution.kind === "blocked" ? { outcome: resolution.outcome } : {})
    }
  });
}

function readyResolution(
  input: Readonly<{
    readonly authoredCheck: NormalizedCheck;
    readonly messages: readonly CheckMessage[];
    readonly preparedOptions: unknown;
  }>
): CheckPreflightResolution {
  const preparedOptions = snapshotJsonObject(input.preparedOptions);
  if (preparedOptions === undefined) {
    return blockedResolution({
      check: input.authoredCheck,
      messages: input.messages,
      reasonCode: "invalid-preflight-result"
    });
  }
  const { preflight: _preflight, ...check } = input.authoredCheck;
  return Object.freeze({
    kind: "ready",
    check: Object.freeze({
      ...check,
      options: preparedOptions,
      preflightMessages: input.messages
    })
  });
}

function blockedResolution(
  input: Readonly<{
    readonly check: NormalizedCheck;
    readonly messages: readonly CheckMessage[];
    readonly reasonCode: string;
  }>
): BlockedCheckPreflightResolution {
  return Object.freeze({
    kind: "blocked",
    check: Object.freeze({
      definition: input.check.definition,
      preflightMessages: input.messages,
      visibility: input.check.visibility
    }),
    outcome: Object.freeze({
      status: "unavailable",
      reason: Object.freeze({ code: input.reasonCode })
    })
  });
}

import type { CheckMessage, CheckProjectContext } from "../../check/check.ts";
import type {
  AdmissionPolicy,
  NormalizedCheck,
  SchedulerMeasurementHook
} from "../../project-definition/project-definition.ts";
import { createCoreCheckSession, type CoreCheckSession } from "../../check-settlement/session.ts";
import {
  diagnosticTags,
  summarizeDiagnosticValue,
  type DiagnosticLogger
} from "../diagnostic-logging/logger.ts";
import { prepareTaskGraph } from "../task-scheduler/graph.ts";
import { admissionSelectionPolicyFor } from "../task-scheduler/custom-admission-policy.ts";
import { runTaskGraph } from "../task-scheduler/scheduler.ts";
import type { SchedulerPerformanceDiagnosticsInput } from "../task-scheduler/scheduler-performance-diagnostics.ts";
import { executeCheckCallback } from "./callback.ts";
import { runWithCheckConsoleRouter } from "./console-capture.ts";
import { createCheckDependencies } from "./dependencies.ts";
import {
  CheckExecutionInvariantFailure,
  recordSettledCheck,
  settleCallback,
  type CheckExecutionSettlementState,
  type CheckIdentity,
  type SettledCheckFacts
} from "./execution-settlement.ts";
import {
  checkIdentity,
  closeResolvedChecks,
  settleBlockedDependent,
  trustedFailure
} from "./execution-finalization.ts";
import type { CheckExecutionLifecycle } from "./lifecycle.ts";
import { planStaticCheckGraph } from "./plan.ts";
import { resolveFlagControlSettlements, type FlagControlSettlement } from "./flag-controls.ts";
import {
  prepareCheck,
  type CheckPreflightResolution,
  type ReadyCheckPreflightResolution
} from "./preflight.ts";

const INERT_SIGNAL = new AbortController().signal;
const NO_CHECK_MESSAGES: readonly CheckMessage[] = Object.freeze([]);
const SYSTEM_MONOTONIC_CLOCK: CheckExecutionClock = Object.freeze({
  now: () => performance.now()
});

/** Package-private monotonic clock seam for execution accounting. */
export type CheckExecutionClock = Readonly<{ now(): number }>;

type ResolvedCheckExecutionFacts = Readonly<{
  readonly checkDurations: readonly import("../result.ts").CheckDuration[];
  readonly checkMessages: readonly import("../result.ts").CheckRunMessage[];
  readonly snapshot: import("../../check-settlement/facts.ts").CoreSnapshot;
}>;

export type ResolvedCheckExecution =
  | (Readonly<{ readonly kind: "completed" }> & ResolvedCheckExecutionFacts)
  | (Readonly<{ readonly kind: "cancelled" }> & ResolvedCheckExecutionFacts)
  | (Readonly<{ readonly kind: "admission-policy-failed" }> & ResolvedCheckExecutionFacts);

export interface CheckExecutionState extends CheckExecutionSettlementState {
  readonly session: CoreCheckSession;
}

interface ExecuteCheckInput extends CheckExecutionState {
  readonly check: NormalizedCheck;
  readonly clock: CheckExecutionClock;
  readonly project: CheckProjectContext;
  readonly signal: AbortSignal;
}

type ResolvedCheckExecutionInput = Readonly<{
  readonly admissionPolicy?: AdmissionPolicy;
  readonly checks: readonly NormalizedCheck[];
  readonly maxParallel: number;
  readonly project: CheckProjectContext;
  readonly signal: AbortSignal | undefined;
  readonly clock?: CheckExecutionClock;
  readonly diagnosticLogger?: DiagnosticLogger;
  /** Explicit enabled-only diagnostics handoff from the invocation output owner. */
  readonly schedulerPerformanceDiagnostics?: SchedulerPerformanceDiagnosticsInput;
  readonly schedulerMeasurementHooks?: readonly SchedulerMeasurementHook[];
  readonly onSchedulerMeasurementHookFailure?: () => void;
  readonly onSchedulerMeasurementHooksSettled?: () => void;
  readonly lifecycle?: CheckExecutionLifecycle;
}>;

/**
 * Runs the already normalized executable Check collection through one generic
 * Task per Check. Graph validation happens before Core scopes or callbacks.
 */
export async function executeResolvedChecks(
  input: ResolvedCheckExecutionInput
): Promise<ResolvedCheckExecution> {
  prepareTaskGraph(planStaticCheckGraph(input.checks), input.maxParallel);
  return runWithCheckConsoleRouter(() => executePreparedResolvedChecks(input));
}

async function executePreparedResolvedChecks(
  input: ResolvedCheckExecutionInput
): Promise<ResolvedCheckExecution> {
  const state = createExecutionState({
    checks: input.checks,
    diagnosticLogger: input.diagnosticLogger,
    lifecycle: input.lifecycle
  });
  const flagControlSettlements = resolveFlagControlSettlements({
    checks: input.checks,
    diagnosticLogger: input.diagnosticLogger,
    flags: input.project.flags,
    signal: input.signal
  });
  for (const settlement of flagControlSettlements) {
    settleFlagControlOutcome(state, settlement);
  }
  input.lifecycle?.flagControlCompleted();
  const checksByCheckId = new Map(
    input.checks.map((check) => [check.definition.checkId, check] as const)
  );
  let graphRun: Awaited<ReturnType<typeof runTaskGraph<boolean>>>;
  try {
    graphRun = await runTaskGraph<boolean>({
      graph: planStaticCheckGraph(input.checks),
      admissionPolicy:
        input.admissionPolicy === undefined
          ? undefined
          : admissionSelectionPolicyFor(input.admissionPolicy),
      maxParallel: input.maxParallel,
      diagnosticLogger: input.diagnosticLogger,
      performanceDiagnostics: input.schedulerPerformanceDiagnostics,
      measurementHooks: input.schedulerMeasurementHooks,
      onMeasurementHookFailure: input.onSchedulerMeasurementHookFailure,
      onMeasurementHooksSettled: input.onSchedulerMeasurementHooksSettled,
      preAdmissionTaskResults: Object.freeze(
        flagControlSettlements.map((settlement) =>
          Object.freeze({ taskId: settlement.check.definition.checkId, value: false })
        )
      ),
      signal: input.signal,
      isPrerequisiteSatisfied: (satisfied) => satisfied,
      onTaskBlocked: (task, dependencyIds) => {
        const check = checksByCheckId.get(task.id);
        if (check === undefined) {
          throw new CheckExecutionInvariantFailure("Blocked Task has no normalized Check");
        }
        settleBlockedDependent({ check, dependencyIds, state });
      },
      execute: (task, context) => {
        const check = checksByCheckId.get(task.id);
        if (check === undefined) {
          throw new CheckExecutionInvariantFailure("Task graph has no normalized Check");
        }
        return executeAdmittedCheck({
          ...state,
          check,
          clock: input.clock ?? SYSTEM_MONOTONIC_CLOCK,
          project: input.project,
          signal: context.signal ?? INERT_SIGNAL
        });
      }
    });
  } catch (error) {
    throw trustedFailure(error);
  }

  return closeResolvedChecks({
    allChecks: input.checks,
    graphRun,
    state
  });
}

function createExecutionState(
  input: Readonly<{
    readonly checks: readonly NormalizedCheck[];
    readonly diagnosticLogger: DiagnosticLogger | undefined;
    readonly lifecycle: CheckExecutionLifecycle | undefined;
  }>
): CheckExecutionState {
  return {
    diagnosticLogger: input.diagnosticLogger,
    settledFactsByCheckId: new Map<string, SettledCheckFacts>(),
    lifecycle: input.lifecycle,
    session: createCoreCheckSession(
      input.checks.map(({ definition }) => Object.freeze({ definition }))
    )
  };
}

function settleFlagControlOutcome(
  state: CheckExecutionState,
  settlement: FlagControlSettlement
): void {
  const scope = state.session.openCheckScope(settlement.check.definition.checkId);
  const outcome = scope.settleProduct(settlement.outcome);
  recordSettledCheck({
    check: checkIdentity(settlement.check),
    durationMs: null,
    messages: NO_CHECK_MESSAGES,
    outcome,
    phase: "control",
    state
  });
}

function settleBlockedPreflight(
  state: CheckExecutionState,
  preflight: Extract<CheckPreflightResolution, { readonly kind: "blocked" }>
): void {
  const scope = state.session.openCheckScope(preflight.check.definition.checkId);
  const outcome = scope.settleProduct(preflight.outcome);
  recordSettledCheck({
    check: checkIdentity(preflight.check),
    durationMs: null,
    messages: preflight.check.preflightMessages,
    outcome,
    phase: "preflight",
    state
  });
}

async function executeAdmittedCheck(input: ExecuteCheckInput): Promise<boolean> {
  const preflight = await prepareCheck({
    check: input.check,
    diagnosticLogger: input.diagnosticLogger,
    signal: input.signal
  });
  if (preflight.kind === "blocked") {
    settleBlockedPreflight(input, preflight);
    return false;
  }
  return executeReadyCheck({ ...input, preflight });
}

async function executeReadyCheck(
  input: ExecuteCheckInput & Readonly<{ readonly preflight: ReadyCheckPreflightResolution }>
): Promise<boolean> {
  const check = input.preflight.check;
  const checkId = check.definition.checkId;
  const scope = input.session.openCheckScope(checkId);
  const identity = checkIdentity(check);
  input.diagnosticLogger?.observe({
    event: "check.started",
    tags: diagnosticTags(`CHECK:${checkId}`, "EXECUTION", "STARTED"),
    details: {
      dependencies: check.dependsOn,
      displayName: check.definition.displayName,
      options: summarizeDiagnosticValue(check.options)
    }
  });
  emitStarted(input.lifecycle, identity);
  const startedAt = input.clock.now();
  const callback = await executeCheckCallback({
    check,
    dependencies: createCheckDependencies({
      checkId,
      diagnosticLogger: input.diagnosticLogger,
      directRelationCheckIds: directRelationCheckIds(check),
      session: input.session
    }),
    diagnosticLogger: input.diagnosticLogger,
    project: input.project,
    scope,
    signal: input.signal
  });
  const settled = settleCallback({
    callback,
    checkId,
    diagnosticLogger: input.diagnosticLogger,
    preflightMessages: check.preflightMessages,
    scope
  });
  recordSettledCheck({
    check: identity,
    durationMs: durationSince(startedAt, input.clock),
    messages: settled.messages,
    outcome: settled.outcome,
    phase: "execution",
    state: input
  });
  return settled.outcome.status === "passed";
}

function directRelationCheckIds(
  check: Pick<NormalizedCheck, "dependsOn" | "observes">
): readonly string[] {
  return Object.freeze([...new Set([...check.dependsOn, ...check.observes])].sort());
}

function emitStarted(lifecycle: CheckExecutionLifecycle | undefined, check: CheckIdentity): void {
  lifecycle?.started(Object.freeze({ checkId: check.checkId, displayName: check.displayName }));
}

function durationSince(startedAt: number, clock: CheckExecutionClock): number {
  const elapsed = clock.now() - startedAt;
  return Number.isFinite(elapsed) && elapsed >= 0 ? elapsed : 0;
}

import type { CheckMessage } from "../../check/check.ts";
import {
  hasRequiredAndOptionalRecordKeys,
  snapshotClosedRecord
} from "../../data-boundary/closed-values.ts";
import { parseCheckMessages } from "./messages.ts";

/**
 * A terminal callback result split into the Core-owned four-state result and
 * detached presentation-only messages. The caller must still pass `result` to
 * Core; this adapter never validates outcome data or reasons.
 */
export interface ParsedCheckTerminalResult {
  readonly messages: readonly CheckMessage[];
  readonly result: StrippedTerminalResult;
}

type StrippedTerminalResult =
  | Readonly<{ readonly status: "passed" | "failed"; readonly data: unknown }>
  | Readonly<{ readonly status: "not-applicable"; readonly reason?: unknown }>
  | Readonly<{ readonly status: "unavailable"; readonly reason: unknown }>;

/**
 * Safely removes an optional terminal-message attachment from an otherwise
 * closed author result. Any malformed attachment rejects the whole value so a
 * valid prefix can never escape into lifecycle or Run result state.
 */
export function parseCheckTerminalResult(value: unknown): ParsedCheckTerminalResult | undefined {
  const terminal = snapshotClosedRecord(value);
  if (terminal === undefined || typeof terminal.status !== "string") return undefined;

  const result = strippedTerminalResult(terminal);
  if (result === undefined) return undefined;
  const messages = parseCheckMessages(terminal.messages);
  return messages === undefined ? undefined : Object.freeze({ messages, result });
}

function strippedTerminalResult(
  terminal: Readonly<Record<string, unknown>>
): StrippedTerminalResult | undefined {
  switch (terminal.status) {
    case "passed":
    case "failed":
      return hasRequiredAndOptionalRecordKeys(terminal, {
        required: ["status", "data"],
        optional: ["messages"]
      })
        ? Object.freeze({ status: terminal.status, data: terminal.data })
        : undefined;
    case "not-applicable":
      if (
        !hasRequiredAndOptionalRecordKeys(terminal, {
          required: ["status"],
          optional: ["reason", "messages"]
        })
      ) {
        return undefined;
      }
      return Object.freeze(
        Object.hasOwn(terminal, "reason")
          ? { status: "not-applicable", reason: terminal.reason }
          : { status: "not-applicable" }
      );
    case "unavailable":
      return hasRequiredAndOptionalRecordKeys(terminal, {
        required: ["status", "reason"],
        optional: ["messages"]
      })
        ? Object.freeze({ status: "unavailable", reason: terminal.reason })
        : undefined;
    default:
      return undefined;
  }
}

import { resolve } from "node:path";
import { failedOutput } from "./output-status.ts";
import { publishMachineOutput } from "./machine-publication.ts";
import {
  outputFailure,
  type CheckDuration,
  type CheckRunMessage,
  type NonConfigurationRunResult,
  type RunResultFacts
} from "./result.ts";
import type { CheckAggregate } from "./controls/contract.ts";
import { diagnosticTags } from "./diagnostic-logging/logger.ts";
import type { Invocation } from "./invocation.ts";
import {
  createPublicationModelV4,
  type TrustedPublicationModelV4
} from "../machine-output/v4/publication-model.ts";
import type { CoreCheck, CoreSnapshot } from "../check-settlement/facts.ts";

type OutcomeCounts = {
  readonly failed: number;
  readonly notApplicable: number;
  readonly passed: number;
  readonly unavailable: number;
};

/** Settled Check facts consumed by completion and output publication. */
export type CoreExecution = Readonly<{
  readonly aggregate: CheckAggregate | null;
  readonly checkDurations: readonly CheckDuration[];
  readonly checkMessages: readonly CheckRunMessage[];
  readonly snapshot: CoreSnapshot;
}>;

export function completeInvocation(
  invocation: Invocation,
  core: CoreExecution
): NonConfigurationRunResult {
  const facts = runFacts(core);
  if (invocation.outputConfiguration.machinePublication.enabled) {
    const model = createModel(invocation, core.snapshot);
    if (isExecutionResult(model)) return model;
    const published = publishMachineOutput({
      configuration: invocation.outputConfiguration.machinePublication,
      statuses: invocation.outputs,
      model,
      directory: resolve(
        invocation.projectRoot,
        invocation.outputConfiguration.machinePublication.directory
      )
    });
    if (!published) return failure(invocation, facts);
  }
  const output = failedOutput(invocation.outputs.value());
  return output === undefined
    ? Object.freeze({
        kind: "completed",
        declarativeFingerprint: invocation.declarativeFingerprint,
        definitionWarnings: invocation.definitionWarnings,
        outputs: invocation.outputs.value(),
        ...facts
      })
    : failure(invocation, facts);
}
function failure(invocation: Invocation, facts: RunResultFacts): ReturnType<typeof outputFailure> {
  const output = failedOutput(invocation.outputs.value());
  if (output === undefined) throw new Error("Run output failed without a failed status");
  return outputFailure(
    invocation.declarativeFingerprint,
    invocation.definitionWarnings,
    invocation.outputs.value(),
    output,
    facts
  );
}
function runFacts(core: CoreExecution): RunResultFacts {
  return Object.freeze({
    aggregate: core.aggregate,
    checkDurations: core.checkDurations,
    checkMessages: core.checkMessages,
    snapshot: core.snapshot
  });
}
function createModel(
  invocation: Invocation,
  snapshot: CoreExecution["snapshot"]
): TrustedPublicationModelV4 | Extract<NonConfigurationRunResult, { readonly kind: "execution" }> {
  try {
    if (invocation.startedAtUtc === null)
      throw new Error("Machine publication requires an invocation timestamp");
    return createPublicationModelV4({
      invocation: {
        invocationId: invocation.invocationId,
        projectRoot: ".",
        timestamp: invocation.startedAtUtc
      },
      snapshot
    });
  } catch {
    return Object.freeze({
      kind: "execution",
      declarativeFingerprint: invocation.declarativeFingerprint,
      definitionWarnings: invocation.definitionWarnings,
      diagnostic: Object.freeze({ code: "publication-model-failed" }),
      outputs: invocation.outputs.value()
    });
  }
}
function isExecutionResult(
  value:
    | TrustedPublicationModelV4
    | Extract<NonConfigurationRunResult, { readonly kind: "execution" }>
): value is Extract<NonConfigurationRunResult, { readonly kind: "execution" }> {
  return "kind" in value;
}

/** Closes diagnostic logging and applies final output priority to a non-configuration candidate. */
export function finalizeInvocation(
  invocation: Invocation,
  candidate: NonConfigurationRunResult
): NonConfigurationRunResult {
  const preCloseOutputs = invocation.outputs.value();
  invocation.diagnosticLogger.observe({
    event: "run.terminal-before-log-close",
    tags: diagnosticTags("RUN", "TERMINAL", terminalStatusTag(candidate)),
    details: {
      ...closingFacts(candidate),
      diagnosticLogging: "close-not-yet-confirmed",
      outputs: preCloseOutputDetails(preCloseOutputs)
    }
  });
  const diagnosticLoggingStatus = invocation.diagnosticLogger.close();
  if (diagnosticLoggingStatus === "failed") invocation.outputs.failed("diagnosticLogging");
  if (diagnosticLoggingStatus === "succeeded") invocation.outputs.succeeded("diagnosticLogging");

  const outputs = invocation.outputs.value();
  switch (candidate.kind) {
    case "completed": {
      const output = failedOutput(outputs);
      return output === undefined
        ? Object.freeze({ ...candidate, outputs })
        : outputFailure(
            candidate.declarativeFingerprint,
            candidate.definitionWarnings,
            outputs,
            output,
            finalSnapshotFacts(candidate)
          );
    }
    case "output": {
      const output = failedOutput(outputs);
      if (output === undefined) throw new Error("Run output failed without a failed status");
      return outputFailure(
        candidate.declarativeFingerprint,
        candidate.definitionWarnings,
        outputs,
        output,
        finalSnapshotFacts(candidate)
      );
    }
    case "planning":
    case "cancelled":
    case "execution":
      return Object.freeze({ ...candidate, outputs });
  }
}

function terminalStatusTag(candidate: NonConfigurationRunResult): string {
  if ("aggregate" in candidate && candidate.aggregate !== null)
    return candidate.aggregate.toUpperCase();
  if (candidate.kind === "cancelled") return "CANCELLED";
  return candidate.kind.toUpperCase();
}

function preCloseOutputDetails(outputs: ReturnType<Invocation["outputs"]["value"]>): Readonly<{
  readonly machinePublication: (typeof outputs)["machinePublication"];
  readonly progressRendering: (typeof outputs)["progressRendering"];
}> {
  return Object.freeze({
    machinePublication: outputs.machinePublication,
    progressRendering: outputs.progressRendering
  });
}

function closingFacts(candidate: NonConfigurationRunResult): Readonly<{
  readonly aggregate: CheckAggregate | null;
  readonly candidateKind: NonConfigurationRunResult["kind"];
  readonly counts: Readonly<{
    readonly failed: number;
    readonly notApplicable: number;
    readonly passed: number;
    readonly unavailable: number;
  }> | null;
  readonly nonPassed: readonly Readonly<{
    readonly checkId: string;
    readonly reason: unknown;
    readonly status: string;
  }>[];
}> {
  if (!("snapshot" in candidate)) {
    return Object.freeze({
      aggregate: null,
      candidateKind: candidate.kind,
      counts: null,
      nonPassed: []
    });
  }
  const summary = summarizeSnapshot(candidate.snapshot);
  return Object.freeze({
    aggregate: "aggregate" in candidate ? candidate.aggregate : null,
    candidateKind: candidate.kind,
    ...summary
  });
}

function summarizeSnapshot(snapshot: CoreSnapshot): Readonly<{
  readonly counts: OutcomeCounts;
  readonly nonPassed: readonly Readonly<{
    readonly checkId: string;
    readonly reason: unknown;
    readonly status: string;
  }>[];
}> {
  const counts = { failed: 0, notApplicable: 0, passed: 0, unavailable: 0 };
  const nonPassed: Array<Readonly<{ checkId: string; reason: unknown; status: string }>> = [];
  for (const check of snapshot.checks) {
    counts[statusCountKey(check)] += 1;
    const fact = nonPassedFact(check);
    if (fact !== undefined) nonPassed.push(fact);
  }
  return Object.freeze({
    counts: Object.freeze(counts),
    nonPassed: Object.freeze(nonPassed)
  });
}

function statusCountKey(check: CoreCheck): keyof OutcomeCounts {
  return check.outcome.status === "not-applicable" ? "notApplicable" : check.outcome.status;
}

function nonPassedFact(
  check: CoreCheck
):
  | Readonly<{ readonly checkId: string; readonly reason: unknown; readonly status: string }>
  | undefined {
  if (check.outcome.status === "passed") return undefined;
  return Object.freeze({
    checkId: check.checkId,
    reason: check.outcome.status === "failed" ? null : (check.outcome.reason ?? null),
    status: check.outcome.status
  });
}

function finalSnapshotFacts(
  candidate: Extract<NonConfigurationRunResult, RunResultFacts>
): RunResultFacts {
  return Object.freeze({
    aggregate: candidate.aggregate,
    checkDurations: candidate.checkDurations,
    checkMessages: candidate.checkMessages,
    snapshot: candidate.snapshot
  });
}

import type { ProjectOutputs } from "../../project-definition/project-definition.ts";
/** 单次 run 调用的闭合上下文与 output override；Project Definition 保持为 authored input。 */
export interface RunControls {
  readonly checkAggregation?: CheckAggregation;
  /** 仅为本次调用覆盖 Run-owned outputs。 */
  readonly outputs?: Partial<{
    machinePublication: Partial<ProjectOutputs["machinePublication"]>;
    progressRendering: Partial<ProjectOutputs["progressRendering"]>;
    diagnosticLogging: Partial<ProjectOutputs["diagnosticLogging"]>;
  }>;
  readonly flags?: readonly string[];
  readonly projectRoot?: string;
  readonly signal?: AbortSignal;
}
/** 将选定 Check statuses 折叠为 invocation aggregate 的规则。 */
export interface CheckAggregation {
  readonly checks: "all" | readonly string[];
  readonly mode: "all" | "any";
  readonly unavailable: "propagate" | "fail" | "exclude";
  readonly notApplicable: "exclude" | "pass" | "fail";
  readonly empty: "passed" | "failed" | "not-applicable";
}
/** `CheckAggregation` 计算出的 invocation 级结果。 */
export type CheckAggregate = "passed" | "failed" | "not-applicable" | "unavailable";

import { snapshotClosedRecord } from "../../data-boundary/closed-values.ts";
import { isOutputDirectory } from "../../project-definition/output-validation.ts";
import type { ProjectOutputs } from "../../project-definition/project-definition.ts";
import type { RunControls } from "./contract.ts";

type DirectoryOutputOverride = Readonly<{
  readonly directory?: string;
  readonly enabled?: boolean;
}>;

/** Parses invocation-local outputs without changing Definition defaults. */
export function parseOutputsOverride(value: unknown): RunControls["outputs"] | undefined {
  const data = snapshotClosedRecord(value);
  if (
    data === undefined ||
    Object.keys(data).some(
      (key) =>
        key !== "machinePublication" && key !== "progressRendering" && key !== "diagnosticLogging"
    )
  )
    return undefined;
  const machinePublication = optionalOutput(
    data,
    "machinePublication",
    parseDirectoryOutputOverride
  );
  const progressRendering = optionalOutput(data, "progressRendering", parseProgressOutputOverride);
  const diagnosticLogging = optionalOutput(data, "diagnosticLogging", parseDirectoryOutputOverride);
  if (!machinePublication.ok || !progressRendering.ok || !diagnosticLogging.ok) return undefined;
  return Object.freeze({
    ...(machinePublication.value === undefined
      ? {}
      : { machinePublication: machinePublication.value }),
    ...(progressRendering.value === undefined
      ? {}
      : { progressRendering: progressRendering.value }),
    ...(diagnosticLogging.value === undefined ? {} : { diagnosticLogging: diagnosticLogging.value })
  });
}
function optionalOutput<T>(
  value: Readonly<Record<string, unknown>>,
  key: string,
  parse: (candidate: unknown) => T | undefined
): Readonly<{ readonly ok: boolean; readonly value?: T }> {
  if (value[key] === undefined) return Object.freeze({ ok: true });
  const parsed = parse(value[key]);
  return parsed === undefined
    ? Object.freeze({ ok: false })
    : Object.freeze({ ok: true, value: parsed });
}
function parseDirectoryOutputOverride(value: unknown): DirectoryOutputOverride | undefined {
  const data = snapshotClosedRecord(value);
  if (
    data === undefined ||
    Object.keys(data).some((key) => key !== "directory" && key !== "enabled")
  )
    return undefined;
  if (
    data.directory !== undefined &&
    (typeof data.directory !== "string" || !isOutputDirectory(data.directory))
  )
    return undefined;
  if (data.enabled !== undefined && typeof data.enabled !== "boolean") return undefined;
  return Object.freeze({
    ...(data.directory === undefined ? {} : { directory: data.directory }),
    ...(data.enabled === undefined ? {} : { enabled: data.enabled })
  });
}
function parseProgressOutputOverride(
  value: unknown
): Partial<ProjectOutputs["progressRendering"]> | undefined {
  const data = snapshotClosedRecord(value);
  if (data === undefined || Object.keys(data).some((key) => key !== "enabled")) return undefined;
  if (data.enabled !== undefined && typeof data.enabled !== "boolean") return undefined;
  return Object.freeze(data.enabled === undefined ? {} : { enabled: data.enabled });
}

/** Diagnostic emitted when one invocation control is not a closed supported value. */
export interface RunControlDiagnostic {
  readonly kind: "invalid-run-controls";
  readonly path: string;
  readonly reason: "invalid-value" | "unknown-key";
}

/** Closed validation result for a Run-owned invocation control. */
export type RunControlValidationResult<T> = Readonly<
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: RunControlDiagnostic }
>;

import { snapshotClosedArray } from "../../data-boundary/closed-values.ts";
import { isNonArrayRecord, isUnknownArray } from "../../data-boundary/value-shapes.ts";
import { parseOutputsOverride } from "./outputs-override-validation.ts";
import type { RunControlDiagnostic, RunControlValidationResult } from "./validation-result.ts";
import type { CheckAggregation, RunControls } from "./contract.ts";

const RUN_CONTROL_KEYS = ["checkAggregation", "outputs", "flags", "projectRoot", "signal"] as const;
const CHECK_AGGREGATION_MODES = ["all", "any"] as const;
const UNAVAILABLE_HANDLING = ["propagate", "fail", "exclude"] as const;
const NOT_APPLICABLE_HANDLING = ["exclude", "pass", "fail"] as const;
const EMPTY_AGGREGATION_RESULTS = ["passed", "failed", "not-applicable"] as const;

export function validateRunControls(value: unknown = {}): RunControlValidationResult<RunControls> {
  try {
    return validateRunControlsValue(value);
  } catch {
    return invalidControls("controls");
  }
}

function validateRunControlsValue(value: unknown): RunControlValidationResult<RunControls> {
  const data = exactControlRecord(value);
  if (!data.ok) return data;
  const flags = parseFlags(data.value.flags);
  if (!flags.ok) return flags;
  const checkAggregation = parseOptionalCheckAggregation(data.value.checkAggregation);
  if (!checkAggregation.ok) return checkAggregation;
  const outputs = optionalControl(data.value.outputs, parseOutputsOverride, "controls.outputs");
  if (!outputs.ok) return outputs;
  const projectRoot = optionalControl(data.value.projectRoot, parseString, "controls.projectRoot");
  if (!projectRoot.ok) return projectRoot;
  const signal = optionalControl(data.value.signal, parseAbortSignal, "controls.signal");
  if (!signal.ok) return signal;
  return Object.freeze({
    ok: true,
    value: Object.freeze({
      ...(checkAggregation.value === undefined ? {} : { checkAggregation: checkAggregation.value }),
      ...(outputs.value === undefined ? {} : { outputs: outputs.value }),
      flags: flags.value,
      ...(projectRoot.value === undefined ? {} : { projectRoot: projectRoot.value }),
      ...(signal.value === undefined ? {} : { signal: signal.value })
    })
  });
}

function exactControlRecord(
  value: unknown
): RunControlValidationResult<Readonly<Record<string, unknown>>> {
  if (!isNonArrayRecord(value)) return invalidControls("controls");
  const unknownKey = Object.keys(value).find((key) => !isRunControlKey(key));
  return unknownKey === undefined
    ? Object.freeze({ ok: true, value })
    : invalidRunControl(`controls.${unknownKey}`, "unknown-key");
}

function optionalControl<T>(
  value: unknown,
  parse: (candidate: unknown) => T | undefined,
  path: string
): RunControlValidationResult<T | undefined> {
  if (value === undefined) return Object.freeze({ ok: true, value: undefined });
  const parsed = parse(value);
  return parsed === undefined ? invalidControls(path) : Object.freeze({ ok: true, value: parsed });
}

function parseFlags(value: unknown): RunControlValidationResult<readonly string[]> {
  if (value === undefined) return Object.freeze({ ok: true, value: Object.freeze([]) });
  if (!isUnknownArray(value)) return invalidControls("controls.flags");
  const flags: string[] = [];
  const length = value.length;
  for (let index = 0; index < length; index += 1) {
    if (!Object.hasOwn(value, index)) return invalidControls("controls.flags");
    const flag = value[index];
    if (typeof flag !== "string" || flag.length === 0) {
      return invalidControls("controls.flags");
    }
    flags.push(flag);
  }
  return Object.freeze({
    ok: true,
    value: Object.freeze([...new Set(flags)].sort())
  });
}

function parseOptionalCheckAggregation(
  value: unknown
): RunControlValidationResult<CheckAggregation | undefined> {
  if (value === undefined) return Object.freeze({ ok: true, value: undefined });
  const data = exactKeys(value, ["checks", "mode", "unavailable", "notApplicable", "empty"]);
  if (data === undefined) return invalidControls("controls.checkAggregation");
  const checks = data.checks === "all" ? "all" : parseClosedCheckIds(data.checks);
  if (checks === undefined) return invalidControls("controls.checkAggregation.checks");
  const mode = parseLiteral(data.mode, CHECK_AGGREGATION_MODES);
  const unavailable = parseLiteral(data.unavailable, UNAVAILABLE_HANDLING);
  const notApplicable = parseLiteral(data.notApplicable, NOT_APPLICABLE_HANDLING);
  const empty = parseLiteral(data.empty, EMPTY_AGGREGATION_RESULTS);
  if (
    mode === undefined ||
    unavailable === undefined ||
    notApplicable === undefined ||
    empty === undefined
  )
    return invalidControls("controls.checkAggregation");
  return Object.freeze({
    ok: true,
    value: Object.freeze({
      checks,
      mode,
      unavailable,
      notApplicable,
      empty
    })
  });
}

function parseClosedCheckIds(value: unknown): readonly string[] | undefined {
  const values = snapshotClosedArray(value);
  if (values === undefined) return undefined;
  const checkIds: string[] = [];
  for (const checkId of values) {
    if (typeof checkId !== "string" || checkId.length === 0) return undefined;
    checkIds.push(checkId);
  }
  return Object.freeze(checkIds);
}

function parseLiteral<Value extends string>(
  value: unknown,
  allowed: readonly Value[]
): Value | undefined {
  return typeof value === "string" ? allowed.find((option) => option === value) : undefined;
}

function isRunControlKey(value: string): boolean {
  return RUN_CONTROL_KEYS.some((key) => key === value);
}

function exactKeys(
  value: unknown,
  keys: readonly string[]
): Readonly<Record<string, unknown>> | undefined {
  if (!isNonArrayRecord(value)) return undefined;
  return Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key))
    ? value
    : undefined;
}

function isAbortSignal(value: unknown): value is AbortSignal {
  return (
    isNonArrayRecord(value) &&
    typeof value.aborted === "boolean" &&
    typeof value.addEventListener === "function"
  );
}

function parseAbortSignal(value: unknown): AbortSignal | undefined {
  return isAbortSignal(value) ? value : undefined;
}

function parseString(value: unknown): string | undefined {
  return typeof value === "string" ? value : undefined;
}

function invalidControls(path: string): RunControlValidationResult<never> {
  return invalidRunControl(path, "invalid-value");
}

function invalidRunControl(
  path: string,
  reason: RunControlDiagnostic["reason"]
): RunControlValidationResult<never> {
  return Object.freeze({
    ok: false,
    error: Object.freeze({ kind: "invalid-run-controls", path, reason })
  });
}

import { types } from "node:util";

import type { DiagnosticValueSummary } from "./logger.ts";

export function summarizeDiagnosticValue(value: unknown): DiagnosticValueSummary {
  const rendered = renderSafeDiagnosticDetail(value);
  if (!rendered.ok) return Object.freeze({ availability: "unavailable", reason: rendered.reason });

  const parsed: unknown = JSON.parse(rendered.text);
  return summarizeRenderedDiagnosticValue(parsed, Buffer.byteLength(rendered.text, "utf8"));
}

function summarizeRenderedDiagnosticValue(value: unknown, bytes: number): DiagnosticValueSummary {
  if (value === null) return Object.freeze({ availability: "available", bytes, shape: "null" });
  if (Array.isArray(value)) {
    return Object.freeze({ availability: "available", bytes, items: value.length, shape: "array" });
  }
  return summarizeNonArrayDiagnosticValue(value, bytes);
}

function summarizeNonArrayDiagnosticValue(value: unknown, bytes: number): DiagnosticValueSummary {
  switch (typeof value) {
    case "boolean":
      return Object.freeze({ availability: "available", bytes, shape: "boolean" });
    case "number":
      return Object.freeze({ availability: "available", bytes, shape: "number" });
    case "string":
      return Object.freeze({ availability: "available", bytes, shape: "string" });
    case "object":
      return Object.freeze({
        availability: "available",
        bytes,
        keys: value === null ? 0 : Object.keys(value).length,
        shape: "object"
      });
    case "bigint":
    case "function":
    case "symbol":
    case "undefined":
      throw new Error("safe diagnostic rendering produced a non-JSON value");
    default:
      throw new Error("safe diagnostic rendering produced an unknown value");
  }
}

export function renderSafeDiagnosticDetail(value: unknown): DetailRendering {
  return renderDetailValue(value, {
    ancestors: new Set<object>(),
    remainingCharacters: MAX_DETAIL_CHARACTERS,
    remainingValues: MAX_DETAIL_VALUES
  });
}

// These bounds admit ordinary package handoffs while keeping diagnostic work finite.
const MAX_DETAIL_CHARACTERS = 1_048_576;
const MAX_DETAIL_DEPTH = 16;
const MAX_DETAIL_VALUES = 32_768;
const MAX_DETAIL_WIDTH = 4_096;

type DetailRendering =
  | Readonly<{ readonly ok: true; readonly text: string }>
  | Readonly<{ readonly ok: false; readonly reason: string }>;

interface DetailRenderingContext {
  readonly ancestors: Set<object>;
  remainingCharacters: number;
  remainingValues: number;
}

/** Renders only descriptor-readable JSON values; diagnostics must never invoke author hooks. */
function renderDetailValue(
  value: unknown,
  context: DetailRenderingContext,
  depth = 0
): DetailRendering {
  if (context.remainingValues <= 0) return unavailable("value-limit");
  context.remainingValues -= 1;
  const scalar = renderDetailScalar(value, context);
  if (scalar !== undefined) return scalar;
  return renderDetailCompound(value, context, depth);
}

function renderDetailScalar(
  value: unknown,
  context: DetailRenderingContext
): DetailRendering | undefined {
  if (value === null || typeof value === "boolean" || typeof value === "string") {
    return renderDetailText(JSON.stringify(value), context);
  }
  if (typeof value !== "number") return undefined;
  return Number.isFinite(value)
    ? renderDetailText(JSON.stringify(value), context)
    : unavailable("non-finite-number");
}

function renderDetailCompound(
  value: unknown,
  context: DetailRenderingContext,
  depth: number
): DetailRendering {
  if (value === null || typeof value !== "object")
    return unavailable(`unsupported-${typeof value}`);
  if (types.isProxy(value)) return unavailable("proxy");
  if (context.ancestors.has(value)) return unavailable("cycle");
  if (depth >= MAX_DETAIL_DEPTH) return unavailable("depth-limit");
  return Array.isArray(value)
    ? renderDetailArray(value, context, depth)
    : renderDetailRecord(value, context, depth);
}

function renderDetailArray(
  value: readonly unknown[],
  context: DetailRenderingContext,
  depth: number
): DetailRendering {
  const inspection = inspectDetailArray(value);
  if (!inspection.ok) return inspection;
  context.ancestors.add(value);
  try {
    return renderDetailArrayItems(value, inspection.length, context, depth);
  } finally {
    context.ancestors.delete(value);
  }
}

type DetailArrayInspection =
  | Readonly<{ readonly ok: false; readonly reason: string }>
  | Readonly<{ readonly ok: true; readonly length: number }>;

function inspectDetailArray(value: readonly unknown[]): DetailArrayInspection {
  if (Object.getPrototypeOf(value) !== Array.prototype)
    return unavailableArray("unsupported-prototype");
  const length = readableArrayLength(value);
  if (length === null) return unavailableArray("invalid-array");
  if (length > MAX_DETAIL_WIDTH) return unavailableArray("width-limit");
  return Reflect.ownKeys(value).length === length + 1
    ? Object.freeze({ length, ok: true })
    : unavailableArray("invalid-array");
}

function readableArrayLength(value: readonly unknown[]): number | null {
  const descriptor = Object.getOwnPropertyDescriptor(value, "length");
  const length: unknown = descriptor?.value;
  if (descriptor?.get !== undefined || descriptor?.set !== undefined) return null;
  return typeof length === "number" && Number.isSafeInteger(length) && length >= 0 ? length : null;
}

function renderDetailArrayItems(
  value: readonly unknown[],
  length: number,
  context: DetailRenderingContext,
  depth: number
): DetailRendering {
  const items: string[] = [];
  for (let index = 0; index < length; index += 1) {
    const descriptor = Object.getOwnPropertyDescriptor(value, String(index));
    if (!isEnumerableDataDescriptor(descriptor)) return unavailable("accessor-or-sparse-array");
    const rendered = renderDetailValue(descriptor.value, context, depth + 1);
    if (!rendered.ok) return rendered;
    items.push(rendered.text);
  }
  return renderDetailText(`[${items.join(",")}]`, context);
}

function renderDetailRecord(
  value: object,
  context: DetailRenderingContext,
  depth: number
): DetailRendering {
  const prototype: unknown = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null)
    return unavailable("unsupported-prototype");
  const keys = Reflect.ownKeys(value);
  if (keys.length > MAX_DETAIL_WIDTH) return unavailable("width-limit");
  const textKeys: string[] = [];
  for (let index = 0; index < keys.length; index += 1) {
    const key = keys[index];
    if (typeof key !== "string") return unavailable("symbol-key");
    textKeys.push(key);
  }
  textKeys.sort();
  context.ancestors.add(value);
  try {
    const entries: string[] = [];
    for (const key of textKeys) {
      const descriptor = Object.getOwnPropertyDescriptor(value, key);
      if (!isEnumerableDataDescriptor(descriptor))
        return unavailable("accessor-or-hidden-property");
      const rendered = renderDetailValue(descriptor.value, context, depth + 1);
      if (!rendered.ok) return rendered;
      entries.push(`${JSON.stringify(key)}:${rendered.text}`);
    }
    return renderDetailText(`{${entries.join(",")}}`, context);
  } finally {
    context.ancestors.delete(value);
  }
}

function isEnumerableDataDescriptor(
  descriptor: PropertyDescriptor | undefined
): descriptor is PropertyDescriptor & Readonly<{ readonly value: unknown }> {
  return (
    descriptor !== undefined &&
    descriptor.enumerable === true &&
    descriptor.get === undefined &&
    descriptor.set === undefined &&
    Object.hasOwn(descriptor, "value")
  );
}

function renderDetailText(text: string, context: DetailRenderingContext): DetailRendering {
  if (text.length > context.remainingCharacters) return unavailable("size-limit");
  context.remainingCharacters -= text.length;
  return Object.freeze({ ok: true, text });
}

function unavailable(reason: string): DetailRendering {
  return Object.freeze({ ok: false, reason });
}

function unavailableArray(reason: string): DetailArrayInspection {
  return Object.freeze({ ok: false, reason });
}

import { closeSync, mkdirSync, openSync, writeSync } from "node:fs";
import { dirname } from "node:path";

import type { CheckExecutionClock } from "../check-execution/resolved-checks.ts";
import { renderSafeDiagnosticDetail } from "./diagnostic-detail-rendering.ts";
export { summarizeDiagnosticValue } from "./diagnostic-detail-rendering.ts";

/** Product-private observation written synchronously at the fact owner. */
export interface DiagnosticObservation {
  readonly details?: unknown;
  readonly event: string;
  readonly tags: readonly string[];
}

/** Product-private invocation logger; its failures never escape lifecycle owners. */
export interface DiagnosticLogger {
  close(): "disabled" | "failed" | "succeeded";
  observe(observation: DiagnosticObservation): void;
}

/** A bounded, descriptor-safe description for normal diagnostic payloads. */
export type DiagnosticValueSummary =
  | Readonly<{
      readonly availability: "available";
      readonly bytes: number;
      readonly items?: number;
      readonly keys?: number;
      readonly shape: "array" | "boolean" | "null" | "number" | "object" | "string";
    }>
  | Readonly<{ readonly availability: "unavailable"; readonly reason: string }>;

/** Test-only construction seam; Product invocation owns its lifecycle and output mapping. */
export type DiagnosticLoggerFactory = (
  input: Readonly<{
    readonly clock: CheckExecutionClock;
    readonly enabled: boolean;
    readonly file: string | null;
  }>
) => DiagnosticLogger;

export const createDiagnosticLogger: DiagnosticLoggerFactory = (input) => {
  if (!input.enabled || input.file === null) return disabledLogger();
  return createEnabledLogger({ clock: input.clock, file: input.file });
};

/** Builds one immutable set of human-filterable diagnostic labels. */
export function diagnosticTags(...tags: readonly string[]): readonly string[] {
  return Object.freeze([...tags]);
}

function disabledLogger(): DiagnosticLogger {
  return Object.freeze({
    close: () => "disabled" as const,
    observe: () => undefined
  });
}

function createEnabledLogger(
  input: Readonly<{
    readonly clock: CheckExecutionClock;
    readonly file: string;
  }>
): DiagnosticLogger {
  let descriptor: number | undefined;
  let failed = false;
  let sequence = 0;
  const startedAt = safeNow(input.clock);

  try {
    mkdirSync(dirname(input.file), { recursive: true });
    descriptor = openSync(input.file, "wx");
  } catch {
    failed = true;
  }

  return Object.freeze({
    close: () => {
      if (descriptor !== undefined) {
        try {
          closeSync(descriptor);
        } catch {
          failed = true;
        }
        descriptor = undefined;
      }
      return failed ? "failed" : "succeeded";
    },
    observe: (observation: DiagnosticObservation) => {
      if (failed || descriptor === undefined) return;
      try {
        const buffer = renderObservation({
          elapsedMs: elapsedSince(startedAt, input.clock),
          observation,
          sequence: sequence + 1
        });
        sequence += 1;
        writeBuffer(descriptor, buffer);
      } catch {
        failed = true;
      }
    }
  });
}

function writeBuffer(descriptor: number, buffer: string): void {
  const bytes = Buffer.from(buffer, "utf8");
  let offset = 0;
  while (offset < bytes.length) {
    const written = writeSync(descriptor, bytes, offset, bytes.length - offset, null);
    if (written <= 0) throw new Error("Diagnostic log append made no progress");
    offset += written;
  }
}

function renderObservation(
  input: Readonly<{
    readonly elapsedMs: number;
    readonly observation: DiagnosticObservation;
    readonly sequence: number;
  }>
): string {
  const tags = input.observation.tags.map((tag) => `[${escapeLogHeaderField(tag)}]`).join(" ");
  const header = `#${String(input.sequence).padStart(6, "0")} +${formatElapsed(input.elapsedMs)} ${tags} ${escapeLogHeaderField(input.observation.event)}`;
  return renderFactLines(header, diagnosticFacts(input.observation));
}

/** Keeps author-controlled header fields on one physical header line. */
function escapeLogHeaderField(text: string): string {
  let escaped = "";
  for (const character of text) {
    if (character === "\\") {
      escaped += "\\\\";
      continue;
    }
    const codeUnit = character.charCodeAt(0);
    escaped +=
      codeUnit <= 0x1f ||
      (codeUnit >= 0x7f && codeUnit <= 0x9f) ||
      codeUnit === 0x5b ||
      codeUnit === 0x5d ||
      codeUnit === 0x2028 ||
      codeUnit === 0x2029
        ? `\\u${codeUnit.toString(16).padStart(4, "0")}`
        : character;
  }
  return escaped;
}

function diagnosticFacts(observation: DiagnosticObservation): readonly string[] {
  if (observation.details === undefined) return Object.freeze([]);
  const rendered = renderSafeDiagnosticDetail(observation.details);
  if (!rendered.ok)
    return Object.freeze([`details=unavailable:${escapeLogHeaderField(rendered.reason)}`]);

  const value: unknown = JSON.parse(rendered.text);
  const facts: string[] = [];
  flattenDiagnosticFacts(value, [], facts, observation);
  return Object.freeze(facts);
}

function flattenDiagnosticFacts(
  value: unknown,
  path: readonly string[],
  facts: string[],
  observation: DiagnosticObservation
): void {
  if (Array.isArray(value)) {
    flattenDiagnosticArrayFacts(value, path, facts, observation);
    return;
  }

  if (value !== null && typeof value === "object") {
    flattenDiagnosticRecordFacts(value, path, facts, observation);
    return;
  }

  facts.push(`${factKey(path)}=${factValue(path, value)}`);
}

function flattenDiagnosticArrayFacts(
  value: readonly unknown[],
  path: readonly string[],
  facts: string[],
  observation: DiagnosticObservation
): void {
  const inline = JSON.stringify(value);
  if (inline.length <= MAX_INLINE_DIAGNOSTIC_VALUE_CHARACTERS) {
    facts.push(`${factKey(path)}=${inline}`);
    return;
  }
  const arrayPath = path.length === 0 ? ["details"] : path;
  for (let index = 0; index < value.length; index += 1) {
    flattenDiagnosticFacts(value[index], [...arrayPath, String(index)], facts, observation);
  }
}

function flattenDiagnosticRecordFacts(
  value: object,
  path: readonly string[],
  facts: string[],
  observation: DiagnosticObservation
): void {
  const entries = Object.entries(value);
  if (entries.length === 0) {
    facts.push(`${factKey(path)}={}`);
    return;
  }
  for (const [key, nested] of entries) {
    if (path.length === 0 && isTopLevelFactRepresentedByTag(observation, key, nested)) continue;
    flattenDiagnosticFacts(nested, [...path, key], facts, observation);
  }
}

/** Omits only exact producer facts already visible in the observation's filter tags. */
function isTopLevelFactRepresentedByTag(
  observation: DiagnosticObservation,
  key: string,
  value: unknown
): boolean {
  if (typeof value !== "string") return false;
  if (observation.event === "scheduler.decision") {
    if (key === "kind") return observation.tags.includes(value.toUpperCase());
    return key === "taskId" && observation.tags.includes(`TASK:${value}`);
  }
  return (
    observation.event === "record.reported" &&
    key === "result" &&
    observation.tags.includes(value.toUpperCase())
  );
}

const MAX_INLINE_DIAGNOSTIC_VALUE_CHARACTERS = 120;

function factKey(path: readonly string[]): string {
  if (path.length === 0) return "details";
  const joined = path.join(".");
  return /^[A-Za-z_][A-Za-z0-9_.-]*$/u.test(joined) ? joined : JSON.stringify(joined);
}

function factValue(path: readonly string[], value: unknown): string {
  const key = path.at(-1);
  if (typeof value === "number" && key?.endsWith("Ms")) {
    return String(Math.round(value * 1_000) / 1_000);
  }
  return JSON.stringify(value);
}

const MAX_DIAGNOSTIC_LINE_CHARACTERS = 200;

function renderFactLines(header: string, facts: readonly string[]): string {
  if (facts.length === 0) return `${header}\n`;

  const lines: string[] = [];
  let current = header;
  for (const fact of facts) {
    if (current.length + 1 + fact.length <= MAX_DIAGNOSTIC_LINE_CHARACTERS) {
      current += ` ${fact}`;
      continue;
    }

    lines.push(current);
    const firstCapacity = MAX_DIAGNOSTIC_LINE_CHARACTERS - "│ ".length;
    const continuationCapacity = MAX_DIAGNOSTIC_LINE_CHARACTERS - "│   ".length;
    let offset = 0;
    let prefix = "│ ";
    while (fact.length - offset > (prefix === "│ " ? firstCapacity : continuationCapacity)) {
      const capacity = prefix === "│ " ? firstCapacity : continuationCapacity;
      const end = diagnosticChunkEnd(fact, offset, capacity);
      lines.push(`${prefix}${fact.slice(offset, end)}`);
      offset = end;
      prefix = "│   ";
    }
    current = `${prefix}${fact.slice(offset)}`;
  }
  lines.push(current);
  return `${lines.join("\n")}\n`;
}

function diagnosticChunkEnd(text: string, offset: number, capacity: number): number {
  let end = offset + capacity;
  const preferredMinimum = offset + Math.floor(capacity * 0.6);
  for (let index = end - 1; index >= preferredMinimum; index -= 1) {
    if (text[index] === " ") {
      end = index;
      break;
    }
    if (text[index] === ",") {
      end = index + 1;
      break;
    }
  }
  if (
    end < text.length &&
    text.charCodeAt(end - 1) >= 0xd800 &&
    text.charCodeAt(end - 1) <= 0xdbff &&
    text.charCodeAt(end) >= 0xdc00 &&
    text.charCodeAt(end) <= 0xdfff
  ) {
    end -= 1;
  }
  return end;
}

function formatElapsed(elapsedMs: number): string {
  const totalMilliseconds = Math.round(elapsedMs);
  const hours = Math.floor(totalMilliseconds / 3_600_000);
  const minutes = Math.floor((totalMilliseconds % 3_600_000) / 60_000);
  const seconds = Math.floor((totalMilliseconds % 60_000) / 1_000);
  const milliseconds = totalMilliseconds % 1_000;
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}.${String(milliseconds).padStart(3, "0")}`;
}

function safeNow(clock: CheckExecutionClock): number {
  try {
    const now = clock.now();
    return Number.isFinite(now) ? now : 0;
  } catch {
    return 0;
  }
}

function elapsedSince(startedAt: number, clock: CheckExecutionClock): number {
  const elapsed = safeNow(clock) - startedAt;
  return Number.isFinite(elapsed) && elapsed >= 0 ? elapsed : 0;
}

import { randomUUID } from "node:crypto";
import { relative, resolve } from "node:path";

import {
  createDeclarativeFingerprint,
  type DefinitionWarning,
  type NormalizedProjectDefinition,
  type ProjectDefinition
} from "../project-definition/project-definition.ts";
import type { RunControls } from "./controls/contract.ts";
import {
  createDiagnosticLogger,
  type DiagnosticLogger,
  type DiagnosticLoggerFactory,
  type DiagnosticObservation
} from "./diagnostic-logging/logger.ts";
import type { Invocation, RunInvocationDependencies } from "./invocation.ts";
import { createOutputStatuses } from "./output-status.ts";
import { effectiveOutputs } from "./output-configuration.ts";
import { createProgressRendering } from "./progress-rendering/presentation.ts";

const SYSTEM_MONOTONIC_CLOCK: Invocation["clock"] = Object.freeze({
  now: () => performance.now()
});

export interface InvocationCreationInput {
  readonly controls: RunControls;
  readonly definition: ProjectDefinition;
  readonly definitionWarnings: readonly DefinitionWarning[];
  readonly dependencies: RunInvocationDependencies;
  readonly normalized: NormalizedProjectDefinition;
}

/** Creates immutable invocation-owned output state before any planning or execution work. */
export function createInvocation(input: InvocationCreationInput): Invocation {
  const outputConfiguration = effectiveOutputs(input.definition, input.controls);
  const clock = input.dependencies.clock ?? SYSTEM_MONOTONIC_CLOCK;
  const projectRoot = resolve(input.controls.projectRoot ?? process.cwd());
  const startedAtUtc = captureOutputCreationTimestamp(outputConfiguration, input.dependencies);
  const identity = createInvocationIdentity();
  const diagnosticLoggingFile = resolveDiagnosticLoggingFile({
    identity,
    outputConfiguration,
    projectRoot,
    startedAtUtc
  });
  const outputs = createOutputStatuses(
    outputConfiguration,
    diagnosticLoggingFile,
    input.normalized.scheduler.measurementHooks.length > 0
  );
  const diagnosticLogger = createDiagnosticLoggerSafely(
    input.dependencies.diagnosticLoggerFactory ?? createDiagnosticLogger,
    {
      clock,
      enabled: outputConfiguration.diagnosticLogging.enabled,
      file: diagnosticLoggingFile === null ? null : resolve(projectRoot, diagnosticLoggingFile)
    }
  );

  return Object.freeze({
    clock,
    controls: input.controls,
    declarativeFingerprint: createDeclarativeFingerprint(input.normalized.declarative),
    definition: input.definition,
    definitionWarnings: Object.freeze([...input.definitionWarnings]),
    diagnosticLogger,
    diagnosticLoggingEnabled: outputConfiguration.diagnosticLogging.enabled,
    outputConfiguration,
    outputs,
    invocationId: identity.id,
    normalized: input.normalized,
    progressRendering: createProgressRendering(outputConfiguration.progressRendering, outputs, {
      clock,
      refreshScheduler: input.dependencies.progressRefreshScheduler,
      writerFactory: input.dependencies.progressWriterFactory
    }),
    projectRoot,
    startedAtUtc
  });
}

function captureOutputCreationTimestamp(
  outputConfiguration: ProjectDefinition["outputs"],
  dependencies: RunInvocationDependencies
): string | null {
  if (
    !outputConfiguration.diagnosticLogging.enabled &&
    !outputConfiguration.machinePublication.enabled
  )
    return null;
  return (dependencies.wallClock?.now() ?? new Date()).toISOString();
}

function createInvocationIdentity(): Readonly<{
  readonly id: string;
  readonly uuid: string;
}> {
  const uuid = randomUUID();
  return Object.freeze({ id: `invocation/v1:${uuid}`, uuid });
}

function resolveDiagnosticLoggingFile(
  input: Readonly<{
    readonly identity: Readonly<{ readonly uuid: string }>;
    readonly outputConfiguration: ProjectDefinition["outputs"];
    readonly projectRoot: string;
    readonly startedAtUtc: string | null;
  }>
): string | null {
  if (!input.outputConfiguration.diagnosticLogging.enabled) return null;
  return relative(
    input.projectRoot,
    resolve(
      input.projectRoot,
      input.outputConfiguration.diagnosticLogging.directory,
      diagnosticLogFileName(requireStartedAtUtc(input.startedAtUtc), input.identity.uuid)
    )
  );
}

function createDiagnosticLoggerSafely(
  factory: DiagnosticLoggerFactory,
  input: Parameters<DiagnosticLoggerFactory>[0]
): DiagnosticLogger {
  let delegate: DiagnosticLogger;
  try {
    delegate = factory(input);
  } catch {
    return failedDiagnosticLogger();
  }
  let failed = false;
  return Object.freeze({
    close: () => {
      try {
        const status = delegate.close();
        return failed ? "failed" : status;
      } catch {
        return "failed";
      }
    },
    observe: (observation: DiagnosticObservation) => {
      if (failed) return;
      try {
        delegate.observe(observation);
      } catch {
        failed = true;
      }
    }
  });
}

function failedDiagnosticLogger(): DiagnosticLogger {
  return Object.freeze({
    close: () => "failed" as const,
    observe: () => undefined
  });
}

function diagnosticLogFileName(startedAtUtc: string, invocationUuid: string): string {
  const compactUtc = startedAtUtc.replaceAll("-", "").replaceAll(":", "");
  return `run-${compactUtc}-${invocationUuid}.log`;
}

function requireStartedAtUtc(startedAtUtc: string | null): string {
  if (startedAtUtc === null) throw new Error("Enabled output requires an invocation timestamp");
  return startedAtUtc;
}

import type { CoreSnapshot } from "../check-settlement/facts.ts";
import type { CheckExecutionClock } from "./check-execution/resolved-checks.ts";

/** Forms the terminal progress counters without changing Core Check facts. */
export function outcomeCounts(snapshot: CoreSnapshot): Readonly<{
  readonly failed: number;
  readonly notApplicable: number;
  readonly passed: number;
  readonly unavailable: number;
}> {
  let failed = 0;
  let notApplicable = 0;
  let passed = 0;
  let unavailable = 0;
  for (const check of snapshot.checks) {
    switch (check.outcome.status) {
      case "passed":
        passed += 1;
        break;
      case "failed":
        failed += 1;
        break;
      case "not-applicable":
        notApplicable += 1;
        break;
      case "unavailable":
        unavailable += 1;
        break;
    }
  }
  return Object.freeze({ failed, notApplicable, passed, unavailable });
}

/** Converts the invocation monotonic clock into a safe progress duration. */
export function elapsedSince(startedAt: number, clock: CheckExecutionClock): number {
  const elapsed = clock.now() - startedAt;
  return Number.isFinite(elapsed) && elapsed >= 0 ? elapsed : 0;
}

import type { CheckProjectContext } from "../check/check.ts";
import {
  normalizeProjectDefinition,
  type DefinitionWarning,
  type NormalizedProjectDefinition,
  type ProjectDefinition
} from "../project-definition/project-definition.ts";
import type { CheckAggregation, RunControls } from "./controls/contract.ts";
import { prepareTaskGraph } from "./task-scheduler/graph.ts";
import { aggregateCheckOutcomes, validateCheckAggregationSelection } from "./aggregation.ts";
import {
  executeResolvedChecks,
  type CheckExecutionClock,
  type ResolvedCheckExecution
} from "./check-execution/resolved-checks.ts";
import { planStaticCheckGraph } from "./check-execution/plan.ts";
import {
  type ProgressRefreshScheduler,
  type ProgressRendering,
  type ProgressWriterFactory
} from "./progress-rendering/presentation.ts";
import { completeInvocation, finalizeInvocation, type CoreExecution } from "./completion.ts";
import { createProjectContext } from "./project-context.ts";
import {
  executionCancellation,
  isCancelled,
  planning,
  preExecutionCancellation,
  type NonConfigurationRunResult,
  type RunDiagnostic,
  type RunResult
} from "./result.ts";
import {
  diagnosticTags,
  type DiagnosticLogger,
  type DiagnosticLoggerFactory
} from "./diagnostic-logging/logger.ts";
import { createInvocation } from "./invocation-creation.ts";
import { elapsedSince, outcomeCounts } from "./invocation-progress.ts";
import type { OutputStatuses } from "./output-status.ts";
export type Invocation = Readonly<{
  readonly clock: CheckExecutionClock;
  readonly controls: RunControls;
  readonly declarativeFingerprint: string;
  readonly definition: ProjectDefinition;
  readonly definitionWarnings: readonly DefinitionWarning[];
  readonly diagnosticLogger: DiagnosticLogger;
  /** Effective output selection, retained privately for enabled-only Scheduler diagnostics. */
  readonly diagnosticLoggingEnabled: boolean;
  readonly outputConfiguration: ProjectDefinition["outputs"];
  readonly outputs: OutputStatuses;
  readonly invocationId: string;
  readonly normalized: NormalizedProjectDefinition;
  readonly progressRendering: ProgressRendering;
  readonly projectRoot: string;
  /** Immutable UTC instant captured for enabled diagnostic or machine output, otherwise `null`. */
  readonly startedAtUtc: string | null;
}>;
export interface RunInvocationDependencies {
  readonly clock?: CheckExecutionClock;
  readonly progressRefreshScheduler?: ProgressRefreshScheduler;
  readonly progressWriterFactory?: ProgressWriterFactory;
  readonly diagnosticLoggerFactory?: DiagnosticLoggerFactory;
  /** Test seam for the invocation's machine-readable wall-clock timestamp. */
  readonly wallClock?: Readonly<{ now(): Date }>;
}
export async function executeValidatedRun(
  definition: ProjectDefinition,
  controls: RunControls,
  definitionWarnings: readonly DefinitionWarning[],
  dependencies: RunInvocationDependencies = {}
): Promise<RunResult> {
  const normalized = normalizeProjectDefinition(definition);
  const aggregation = validateCheckAggregationSelection(
    controls.checkAggregation,
    normalized.checks.map((check) => check.definition.checkId)
  );
  if (!aggregation.ok)
    return Object.freeze({
      kind: "configuration",
      definitionWarnings: Object.freeze([...definitionWarnings]),
      diagnostic: aggregation.error
    });

  const invocation = createInvocation({
    controls,
    definition,
    definitionWarnings,
    dependencies,
    normalized
  });
  let candidate: NonConfigurationRunResult;
  try {
    observeInvocationStarted(invocation, aggregation.value);
    if (isCancelled(controls)) {
      candidate = cancelledBeforeExecution(invocation, "pre-work");
    } else if (!validateTaskGraph(invocation)) {
      candidate = planningResult(invocation, "task-graph-invalid");
    } else {
      candidate = await executePlannedInvocation(invocation, aggregation.value);
    }
  } catch {
    candidate = executionResult(invocation, "task-engine-failed");
  }
  return finalizeInvocation(invocation, candidate);
}

function observeInvocationStarted(
  invocation: Invocation,
  aggregation: CheckAggregation | undefined
): void {
  invocation.diagnosticLogger.observe({
    event: "run.started",
    tags: diagnosticTags("RUN", "STARTED"),
    details: {
      aggregation: aggregation ?? null,
      checkCount: invocation.normalized.checks.length,
      flags: invocation.controls.flags ?? [],
      invocationId: invocation.invocationId,
      outputs: invocation.outputConfiguration,
      scheduler: invocation.normalized.declarative.scheduler
    }
  });
}

function validateTaskGraph(invocation: Invocation): boolean {
  try {
    prepareTaskGraph(
      planStaticCheckGraph(invocation.normalized.checks),
      invocation.normalized.declarative.scheduler.maxParallel
    );
    invocation.diagnosticLogger.observe({
      event: "run.planning.succeeded",
      tags: diagnosticTags("RUN", "PLANNING", "SUCCEEDED"),
      details: {
        checkCount: invocation.normalized.checks.length,
        maxParallel: invocation.normalized.declarative.scheduler.maxParallel
      }
    });
    return true;
  } catch {
    invocation.diagnosticLogger.observe({
      event: "run.planning.failed",
      tags: diagnosticTags("RUN", "PLANNING", "FAILED"),
      details: {
        checkCount: invocation.normalized.checks.length,
        maxParallel: invocation.normalized.declarative.scheduler.maxParallel
      }
    });
    return false;
  }
}
async function executePlannedInvocation(
  invocation: Invocation,
  aggregation: CheckAggregation | undefined
): Promise<NonConfigurationRunResult> {
  if (isCancelled(invocation.controls)) return cancelledBeforeExecution(invocation, "pre-work");
  return executePreparedInvocation(
    invocation,
    aggregation,
    createProjectContext({
      controls: invocation.controls,
      root: invocation.projectRoot
    })
  );
}
async function executePreparedInvocation(
  invocation: Invocation,
  aggregation: CheckAggregation | undefined,
  project: CheckProjectContext
): Promise<NonConfigurationRunResult> {
  if (isCancelled(invocation.controls)) return cancelledBeforeExecution(invocation, "planning");
  invocation.progressRendering.prepared(invocation.normalized.checks.length);
  const executionStartedAt = invocation.clock.now();
  const executed = await executeChecks(invocation, project, invocation.clock);
  if (isExecutionRunResult(executed)) return executed;
  if (executed.kind === "admission-policy-failed") {
    return executionResult(invocation, "admission-policy-failed");
  }
  invocation.progressRendering.final({
    counts: outcomeCounts(executed.snapshot),
    elapsedMs: elapsedSince(executionStartedAt, invocation.clock),
    execution: executed.kind
  });
  if (executed.kind === "cancelled") {
    invocation.diagnosticLogger.observe({
      event: "run.execution.cancelled",
      tags: diagnosticTags("RUN", "EXECUTION", "CANCELLED"),
      details: { checkCount: executed.snapshot.checks.length }
    });
    return executionCancellation({
      checkDurations: executed.checkDurations,
      checkMessages: executed.checkMessages,
      declarativeFingerprint: invocation.declarativeFingerprint,
      definitionWarnings: invocation.definitionWarnings,
      outputs: invocation.outputs.value(),
      snapshot: executed.snapshot
    });
  }
  const aggregate =
    aggregation === undefined ? null : aggregateCheckOutcomes(executed.snapshot, aggregation);
  invocation.diagnosticLogger.observe({
    event: "run.aggregation.completed",
    tags: diagnosticTags("RUN", "AGGREGATION", "COMPLETED"),
    details: { aggregate, selection: aggregation ?? null }
  });
  const core: CoreExecution = Object.freeze({
    aggregate,
    checkDurations: executed.checkDurations,
    checkMessages: executed.checkMessages,
    snapshot: executed.snapshot
  });
  return completeInvocation(invocation, core);
}

function cancelledBeforeExecution(
  invocation: Invocation,
  phase: "pre-work" | "planning"
): NonConfigurationRunResult {
  invocation.diagnosticLogger.observe({
    event: "run.cancelled",
    tags: diagnosticTags("RUN", "CANCELLED"),
    details: { phase }
  });
  return preExecutionCancellation(
    invocation.declarativeFingerprint,
    invocation.definitionWarnings,
    invocation.outputs.value(),
    phase
  );
}

async function executeChecks(
  invocation: Invocation,
  project: CheckProjectContext,
  clock: CheckExecutionClock
): Promise<ResolvedCheckExecution | NonConfigurationRunResult> {
  try {
    return await executeResolvedChecks({
      admissionPolicy: invocation.normalized.scheduler.admissionPolicy,
      checks: invocation.normalized.checks,
      clock,
      diagnosticLogger: invocation.diagnosticLogger,
      schedulerPerformanceDiagnostics:
        invocation.diagnosticLoggingEnabled ||
        invocation.normalized.scheduler.measurementHooks.length > 0 ||
        invocation.normalized.scheduler.admissionPolicy.kind === "custom"
          ? Object.freeze({
              clock,
              declarativeFingerprint: invocation.declarativeFingerprint,
              ...(invocation.diagnosticLoggingEnabled
                ? { logger: invocation.diagnosticLogger }
                : {})
            })
          : undefined,
      schedulerMeasurementHooks: invocation.normalized.scheduler.measurementHooks,
      onSchedulerMeasurementHookFailure: () => invocation.outputs.failed("measurementHooks"),
      onSchedulerMeasurementHooksSettled: () => invocation.outputs.succeeded("measurementHooks"),
      maxParallel: invocation.normalized.declarative.scheduler.maxParallel,
      lifecycle: invocation.progressRendering.lifecycle,
      project,
      signal: invocation.controls.signal
    });
  } catch {
    return executionResult(invocation, "task-engine-failed");
  }
}
function planningResult(
  invocation: Invocation,
  code: Extract<RunDiagnostic["code"], "task-graph-invalid">
): NonConfigurationRunResult {
  return planning(
    invocation.declarativeFingerprint,
    invocation.definitionWarnings,
    invocation.outputs.value(),
    code
  );
}
function executionResult(
  invocation: Invocation,
  code: Extract<
    RunDiagnostic["code"],
    "admission-policy-failed" | "publication-model-failed" | "task-engine-failed"
  >
): NonConfigurationRunResult {
  return Object.freeze({
    kind: "execution",
    declarativeFingerprint: invocation.declarativeFingerprint,
    definitionWarnings: invocation.definitionWarnings,
    diagnostic: Object.freeze({ code }),
    outputs: invocation.outputs.value()
  });
}
function isExecutionRunResult(
  value: ResolvedCheckExecution | NonConfigurationRunResult
): value is NonConfigurationRunResult {
  return "declarativeFingerprint" in value;
}

import type { ProjectOutputs } from "../project-definition/project-definition.ts";
