import type { ProjectOutputs } from "../project-definition/project-definition.ts";

export interface RunOutputStatus {
  readonly enabled: boolean;
  readonly status: "disabled" | "failed" | "not-run" | "succeeded";
}

export interface RunDiagnosticLoggingOutputStatus extends RunOutputStatus {
  /** `path.relative(projectRoot, resolvedFile)` when enabled, otherwise `null`. */
  readonly file: string | null;
}

export interface RunOutputStatuses {
  readonly machinePublication: RunOutputStatus;
  readonly progressRendering: RunOutputStatus;
  readonly diagnosticLogging: RunDiagnosticLoggingOutputStatus;
  /** Scheduler measurement hooks are terminal side effects configured by the Definition. */
  readonly measurementHooks: RunOutputStatus;
}

export interface OutputStatuses {
  readonly failed: (output: keyof RunOutputStatuses) => void;
  readonly succeeded: (output: keyof RunOutputStatuses) => void;
  readonly value: () => RunOutputStatuses;
}

export function createOutputStatuses(
  configuration: ProjectOutputs,
  diagnosticLoggingFile: string | null,
  measurementHooksEnabled: boolean
): OutputStatuses {
  const statuses: Record<keyof RunOutputStatuses, RunOutputStatus["status"]> = {
    machinePublication: initialStatus(configuration.machinePublication.enabled),
    progressRendering: initialStatus(configuration.progressRendering.enabled),
    diagnosticLogging: initialStatus(configuration.diagnosticLogging.enabled),
    measurementHooks: initialStatus(measurementHooksEnabled)
  };
  const enabled = (output: keyof RunOutputStatuses): boolean =>
    output === "measurementHooks" ? measurementHooksEnabled : configuration[output].enabled;
  return Object.freeze({
    failed: (output: keyof RunOutputStatuses) => {
      if (enabled(output)) statuses[output] = "failed";
    },
    succeeded: (output: keyof RunOutputStatuses) => {
      if (enabled(output)) statuses[output] = "succeeded";
    },
    value: () =>
      Object.freeze({
        machinePublication: Object.freeze({
          enabled: configuration.machinePublication.enabled,
          status: statuses.machinePublication
        }),
        progressRendering: Object.freeze({
          enabled: configuration.progressRendering.enabled,
          status: statuses.progressRendering
        }),
        diagnosticLogging: Object.freeze({
          enabled: configuration.diagnosticLogging.enabled,
          file: diagnosticLoggingFile,
          status: statuses.diagnosticLogging
        }),
        measurementHooks: Object.freeze({
          enabled: measurementHooksEnabled,
          status: statuses.measurementHooks
        })
      })
  });
}

export function failedOutput(statuses: RunOutputStatuses): keyof RunOutputStatuses | undefined {
  for (const output of [
    "progressRendering",
    "machinePublication",
    "diagnosticLogging",
    "measurementHooks"
  ] as const)
    if (statuses[output].status === "failed") return output;
  return undefined;
}

function initialStatus(enabled: boolean): RunOutputStatus["status"] {
  return enabled ? "not-run" : "disabled";
}

import type {
  CheckExecutionLifecycle,
  CheckSettledFact,
  CheckStartedFact
} from "../check-execution/lifecycle.ts";
import {
  createProgressRenderer,
  type ProgressClock,
  type ProgressFeedback,
  type ProgressOutcomeCounts,
  type ProgressWriter
} from "./renderer.ts";
import type { ProjectOutputs } from "../../project-definition/project-definition.ts";
import type { OutputStatuses } from "../output-status.ts";
export interface ProgressRendering {
  readonly final: (input: ProgressFinalFeedback) => void;
  readonly lifecycle: CheckExecutionLifecycle;
  readonly prepared: (totalChecks: number) => void;
}
export interface ProgressFinalFeedback {
  readonly counts: ProgressOutcomeCounts;
  readonly elapsedMs: number;
  readonly execution: "cancelled" | "completed";
}
export type ProgressWriterFactory = () => ProgressWriter;

export interface ProgressRefreshSchedule {
  cancel(): void;
}

export interface ProgressRefreshScheduler {
  schedule(refresh: () => void, intervalMs: number): ProgressRefreshSchedule;
}

export interface ProgressRenderingDependencies {
  readonly clock?: ProgressClock;
  readonly refreshScheduler?: ProgressRefreshScheduler;
  readonly writerFactory?: ProgressWriterFactory;
}

const PROGRESS_REFRESH_INTERVAL_MS = 5_000;

const defaultProgressRefreshScheduler: ProgressRefreshScheduler = Object.freeze({
  schedule: (refresh: () => void, intervalMs: number) => {
    const interval = setInterval(refresh, intervalMs);
    interval.unref();
    return Object.freeze({ cancel: () => clearInterval(interval) });
  }
});

/** Owns progress writer lifecycle and rendering; failed writers are permanently muted. */
export function createProgressRendering(
  configuration: ProjectOutputs["progressRendering"],
  statuses: OutputStatuses,
  dependencies: ProgressRenderingDependencies = {}
): ProgressRendering {
  if (!configuration.enabled) return inertProgressRendering();
  let failed = false;
  const runningCheckIds = new Set<string>();
  let renderer: ReturnType<typeof createProgressRenderer> | undefined;
  let refreshSchedule: ProgressRefreshSchedule | undefined;

  const failRendering = (): void => {
    if (failed) return;
    failed = true;
    const activeSchedule = refreshSchedule;
    refreshSchedule = undefined;
    try {
      activeSchedule?.cancel();
    } catch {
      // The output is already failed; a scheduler cleanup fault must not reach Check execution.
    }
    statuses.failed("progressRendering");
  };

  const stopRefresh = (): void => {
    const activeSchedule = refreshSchedule;
    refreshSchedule = undefined;
    try {
      activeSchedule?.cancel();
    } catch {
      failRendering();
    }
  };

  const render = (feedback: ProgressFeedback): void => {
    if (failed) return;
    try {
      renderer ??= createProgressRenderer(
        (dependencies.writerFactory ?? defaultProgressWriter)(),
        dependencies.clock
      );
      renderer.render(feedback);
      if (feedback.kind === "final") {
        statuses.succeeded("progressRendering");
      }
    } catch {
      failRendering();
    }
  };

  const refresh = (): void => {
    if (failed) return;
    try {
      renderer?.refresh();
    } catch {
      failRendering();
    }
  };

  const startRefresh = (): void => {
    if (
      failed ||
      refreshSchedule !== undefined ||
      runningCheckIds.size === 0 ||
      renderer?.refreshesRunningRegion !== true
    ) {
      return;
    }
    try {
      refreshSchedule = (dependencies.refreshScheduler ?? defaultProgressRefreshScheduler).schedule(
        refresh,
        PROGRESS_REFRESH_INTERVAL_MS
      );
    } catch {
      failRendering();
    }
  };

  return Object.freeze({
    prepared: (totalChecks: number) => render(Object.freeze({ kind: "prepared", totalChecks })),
    lifecycle: Object.freeze({
      flagControlCompleted: () => render(Object.freeze({ kind: "flag-control-completed" })),
      settled: (fact: CheckSettledFact) => {
        render(
          Object.freeze({
            kind: "settled",
            checkId: fact.checkId,
            displayName: fact.displayName,
            durationMs: fact.durationMs,
            messages: fact.messages,
            outcome: fact.outcome,
            visibility: fact.visibility
          })
        );
        runningCheckIds.delete(fact.checkId);
        if (runningCheckIds.size === 0) stopRefresh();
      },
      started: (fact: CheckStartedFact) => {
        runningCheckIds.add(fact.checkId);
        render(
          Object.freeze({ kind: "started", checkId: fact.checkId, displayName: fact.displayName })
        );
        startRefresh();
      }
    }),
    final: (input: ProgressFinalFeedback) => {
      stopRefresh();
      render(
        Object.freeze({
          kind: "final",
          counts: input.counts,
          elapsedMs: input.elapsedMs,
          execution: input.execution
        })
      );
    }
  });
}
function inertProgressRendering(): ProgressRendering {
  const lifecycle = Object.freeze({
    flagControlCompleted: (): void => undefined,
    settled: (_fact: CheckSettledFact): void => undefined,
    started: (_fact: CheckStartedFact): void => undefined
  });
  return Object.freeze({
    prepared: (_totalChecks: number): void => undefined,
    lifecycle,
    final: (_input: ProgressFinalFeedback): void => undefined
  });
}
function defaultProgressWriter(): ProgressWriter {
  return Object.freeze({
    color: process.stdout.isTTY === true && process.env.NO_COLOR === undefined,
    isTTY: process.stdout.isTTY === true,
    term: process.env.TERM,
    write: (content: string) => {
      process.stdout.write(content);
    }
  });
}

import type { CheckMessage, CheckOutcome } from "../../check/check.ts";
import { FLAG_CONDITION_NOT_MATCHED_CODE } from "../check-execution/flag-controls.ts";
import type { ProgressFeedback, ProgressOutcomeCounts } from "./renderer.ts";

const COLOR = Object.freeze({
  error: "\u001B[31m",
  info: "\u001B[36m",
  reset: "\u001B[0m",
  warning: "\u001B[33m"
});

const NAMED_CONTROL_ESCAPES: Readonly<Partial<Record<string, string>>> = Object.freeze({
  "\n": "\\n",
  "\r": "\\r",
  "\t": "\\t"
});

export function formatRunningRow(
  input: Readonly<{
    readonly displayIndex: number;
    readonly displayName: string;
    readonly elapsedMs: number | null;
    readonly totalChecks: number;
  }>
): string {
  const elapsed = input.elapsedMs === null ? "" : ` | ${formatDuration(input.elapsedMs)}`;
  return `  [${input.displayIndex}/${input.totalChecks}] ${escapeTerminalText(input.displayName)} | running${elapsed}\n`;
}

export function shouldPresentSettledFeedback(
  feedback: Extract<ProgressFeedback, { readonly kind: "settled" }>
): boolean {
  return (
    feedback.visibility !== "attention" ||
    feedback.outcome.status !== "passed" ||
    feedback.messages.length > 0
  );
}

export function isFlagConditionNotMatchedFeedback(
  feedback: Extract<ProgressFeedback, { readonly kind: "settled" }>
): boolean {
  return (
    feedback.durationMs === null &&
    feedback.messages.length === 0 &&
    feedback.outcome.status === "not-applicable" &&
    feedback.outcome.reason?.code === FLAG_CONDITION_NOT_MATCHED_CODE
  );
}

export function formatFlagConditionNotMatchedBlock(
  displayNames: readonly [string, ...string[]]
): string {
  const subject =
    displayNames.length === 1
      ? "The following check did not run because the run flags did not match its condition:"
      : `The following ${displayNames.length} checks did not run because the run flags did not match their conditions:`;
  return `  ${subject}\n${displayNames
    .map((displayName) => `    - ${escapeTerminalText(displayName)}\n`)
    .join("")}`;
}

export function formatSettledBlock(
  input: Readonly<{
    readonly completionOrdinal: number;
    readonly displayName: string;
    readonly durationMs: number | null;
    readonly messages: readonly CheckMessage[];
    readonly outcome: CheckOutcome;
    readonly totalChecks: number;
    readonly usesColor: boolean;
  }>
): string {
  const status = statusForOutcome(input.outcome);
  const reason = reasonForOutcome(input.outcome);
  const duration = input.durationMs === null ? "not run" : formatDuration(input.durationMs);
  const reasonSuffix = reason === undefined ? "" : ` | ${escapeTerminalText(reason)}`;
  const row = `  [${input.completionOrdinal}/${input.totalChecks}] ${escapeTerminalText(input.displayName)} | ${status} | ${duration}${reasonSuffix}\n`;
  return `${row}${input.messages.map((message) => formatMessage(message, input.usesColor)).join("")}`;
}

export function formatFinalSummary(
  input: Extract<ProgressFeedback, { readonly kind: "final" }>
): string {
  return [
    "",
    "Execution summary:",
    `  execution: ${input.execution}`,
    `  total checks: ${totalChecks(input.counts)}`,
    `  passed: ${input.counts.passed}`,
    `  failed: ${input.counts.failed}`,
    `  not applicable: ${input.counts.notApplicable}`,
    `  unavailable: ${input.counts.unavailable}`,
    `  elapsed: ${formatDuration(input.elapsedMs)}`,
    ""
  ].join("\n");
}

function formatMessage(message: CheckMessage, usesColor: boolean): string {
  const label = colorMessageLevel(message.level, usesColor);
  return `    [${label}] ${escapeTerminalText(message.message)}\n`;
}

function totalChecks(counts: ProgressOutcomeCounts): number {
  return counts.passed + counts.failed + counts.notApplicable + counts.unavailable;
}

function statusForOutcome(outcome: CheckOutcome): ProgressStatus {
  switch (outcome.status) {
    case "passed":
    case "failed":
      return outcome.status;
    case "not-applicable":
      return "not-applicable";
    case "unavailable":
      return "unavailable";
  }
}

function reasonForOutcome(outcome: CheckOutcome): string | undefined {
  return outcome.status === "passed" || outcome.status === "failed"
    ? undefined
    : outcome.reason?.code;
}

/** Human-only fields must not control the terminal that presents them. */
function escapeTerminalText(value: string): string {
  let escaped = "";
  for (const character of value) {
    const codePoint = character.codePointAt(0) ?? 0;
    const namedEscape = NAMED_CONTROL_ESCAPES[character];
    if (namedEscape !== undefined) {
      escaped += namedEscape;
      continue;
    }
    escaped += isTerminalControl(codePoint)
      ? `\\u${codePoint.toString(16).padStart(4, "0").toUpperCase()}`
      : character;
  }
  return escaped;
}

function isTerminalControl(codePoint: number): boolean {
  return (
    codePoint <= 0x1f ||
    (codePoint >= 0x7f && codePoint <= 0x9f) ||
    codePoint === 0x2028 ||
    codePoint === 0x2029
  );
}

function colorMessageLevel(level: CheckMessage["level"], usesColor: boolean): string {
  if (!usesColor) return level;
  return `${COLOR[level]}${level}${COLOR.reset}`;
}

type ProgressStatus = CheckOutcome["status"];

function formatDuration(durationMs: number): string {
  if (durationMs < 1_000) {
    return `${Number.isInteger(durationMs) ? durationMs : Number(durationMs.toFixed(1))}ms`;
  }
  const seconds = durationMs / 1_000;
  return `${Number.isInteger(seconds) ? seconds : Number(seconds.toFixed(1))}s`;
}

import type {
  ProgressClock,
  ProgressFeedback,
  ProgressRenderer,
  ProgressWriter
} from "./renderer.ts";
import {
  formatFlagConditionNotMatchedBlock,
  formatFinalSummary,
  formatRunningRow,
  formatSettledBlock,
  isFlagConditionNotMatchedFeedback,
  shouldPresentSettledFeedback
} from "./renderer-formatting.ts";

interface RunningCheck {
  readonly checkId: string;
  readonly displayName: string;
  readonly startedAtMs: number;
  elapsedMs: number | null;
}

/** Maintains the mutable lifecycle state and the TTY-only running terminal region. */
export class ProgressRendererController implements ProgressRenderer {
  readonly refreshesRunningRegion: boolean;

  private readonly clock: ProgressClock;
  private readonly writer: ProgressWriter;
  private completedCount = 0;
  private readonly flagConditionNotMatchedDisplayNames: string[] = [];
  private preparedTotal: number | undefined;
  private renderedRunningRows = 0;
  private readonly running: RunningCheck[] = [];
  private readonly usesColor: boolean;

  constructor(writer: ProgressWriter, clock: ProgressClock) {
    this.writer = writer;
    this.clock = clock;
    this.refreshesRunningRegion = writer.isTTY && writer.term?.toLowerCase() !== "dumb";
    this.usesColor = this.refreshesRunningRegion && writer.color;
  }

  refresh(): void {
    if (!this.refreshesRunningRegion || this.running.length === 0) return;
    this.requirePrepared();
    this.eraseRunningRegion();
    this.updateRunningDurations(this.clock.now());
    this.redrawRunningRegion();
  }

  render(feedback: ProgressFeedback): void {
    switch (feedback.kind) {
      case "prepared":
        this.prepare(feedback.totalChecks);
        return;
      case "flag-control-completed":
        this.completeFlagControl();
        return;
      case "started":
        this.start(feedback);
        return;
      case "settled":
        this.settle(feedback);
        return;
      case "final":
        this.finish(feedback);
    }
  }

  private prepare(totalChecks: number): void {
    if (this.preparedTotal !== undefined) throw new Error("Progress feedback was prepared twice");
    this.preparedTotal = totalChecks;
    this.writer.write(`Vibe Check\ntotal ${totalChecks} checks\n\nChecks:\n`);
  }

  private start(feedback: Extract<ProgressFeedback, { readonly kind: "started" }>): void {
    if (!this.refreshesRunningRegion) return;
    this.requirePrepared();
    this.eraseRunningRegion();
    this.running.push({
      checkId: feedback.checkId,
      displayName: feedback.displayName,
      elapsedMs: null,
      startedAtMs: this.clock.now()
    });
    this.redrawRunningRegion();
  }

  private settle(feedback: Extract<ProgressFeedback, { readonly kind: "settled" }>): void {
    const totalChecks = this.requirePrepared();
    if (this.refreshesRunningRegion) this.eraseRunningRegion();
    this.completedCount += 1;
    this.removeRunningCheck(feedback.checkId);
    if (isFlagConditionNotMatchedFeedback(feedback)) {
      this.flagConditionNotMatchedDisplayNames.push(feedback.displayName);
    } else if (shouldPresentSettledFeedback(feedback)) {
      this.writer.write(
        formatSettledBlock({
          completionOrdinal: this.completedCount,
          displayName: feedback.displayName,
          durationMs: feedback.durationMs,
          messages: feedback.messages,
          outcome: feedback.outcome,
          totalChecks,
          usesColor: this.usesColor
        })
      );
    }
    if (this.refreshesRunningRegion) this.redrawRunningRegion();
  }

  private finish(feedback: Extract<ProgressFeedback, { readonly kind: "final" }>): void {
    this.requirePrepared();
    if (this.running.length > 0) {
      throw new Error("Progress feedback finalized while Checks are still running");
    }
    this.flushFlagConditionNotMatchedChecks();
    this.writer.write(formatFinalSummary(feedback));
  }

  private completeFlagControl(): void {
    this.requirePrepared();
    this.flushFlagConditionNotMatchedChecks();
  }

  private flushFlagConditionNotMatchedChecks(): void {
    const firstDisplayName = this.flagConditionNotMatchedDisplayNames[0];
    if (firstDisplayName === undefined) return;
    this.writer.write(
      formatFlagConditionNotMatchedBlock([
        firstDisplayName,
        ...this.flagConditionNotMatchedDisplayNames.slice(1)
      ])
    );
    this.flagConditionNotMatchedDisplayNames.length = 0;
  }

  private eraseRunningRegion(): void {
    for (let index = 0; index < this.renderedRunningRows; index += 1) {
      this.writer.write("\u001B[1A\u001B[2K");
    }
    this.renderedRunningRows = 0;
  }

  private redrawRunningRegion(): void {
    const totalChecks = this.requirePrepared();
    for (const [index, check] of this.running.entries()) {
      this.writer.write(
        formatRunningRow({
          displayIndex: this.completedCount + index + 1,
          displayName: check.displayName,
          elapsedMs: check.elapsedMs,
          totalChecks
        })
      );
    }
    this.renderedRunningRows = this.running.length;
  }

  private removeRunningCheck(checkId: string): void {
    const index = this.running.findIndex((check) => check.checkId === checkId);
    if (index >= 0) this.running.splice(index, 1);
  }

  private updateRunningDurations(refreshedAtMs: number): void {
    for (const check of this.running) {
      const elapsedMs = refreshedAtMs - check.startedAtMs;
      check.elapsedMs = Number.isFinite(elapsedMs) && elapsedMs >= 0 ? elapsedMs : 0;
    }
  }

  private requirePrepared(): number {
    if (this.preparedTotal === undefined) {
      throw new Error("Progress feedback arrived before preparation");
    }
    return this.preparedTotal;
  }
}

import type { CheckMessage, CheckOutcome, CheckVisibility } from "../../check/check.ts";
import { ProgressRendererController } from "./renderer-lifecycle.ts";

export interface ProgressWriter {
  readonly color: boolean;
  readonly isTTY: boolean;
  readonly term: string | undefined;
  write(content: string): void;
}

export type ProgressFeedback = Readonly<
  | {
      readonly kind: "prepared";
      readonly totalChecks: number;
    }
  | {
      readonly kind: "flag-control-completed";
    }
  | {
      readonly kind: "started";
      readonly checkId: string;
      readonly displayName: string;
    }
  | {
      readonly kind: "settled";
      readonly checkId: string;
      readonly displayName: string;
      readonly outcome: CheckOutcome;
      readonly durationMs: number | null;
      readonly visibility: CheckVisibility;
      readonly messages: readonly CheckMessage[];
    }
  | {
      readonly kind: "final";
      readonly execution: "cancelled" | "completed";
      readonly counts: ProgressOutcomeCounts;
      readonly elapsedMs: number;
    }
>;

export interface ProgressOutcomeCounts {
  readonly failed: number;
  readonly notApplicable: number;
  readonly passed: number;
  readonly unavailable: number;
}

export interface ProgressRenderer {
  refresh(): void;
  readonly refreshesRunningRegion: boolean;
  render(feedback: ProgressFeedback): void;
}

export interface ProgressClock {
  now(): number;
}

const SYSTEM_PROGRESS_CLOCK: ProgressClock = Object.freeze({ now: () => performance.now() });

/** Product-private lifecycle presentation with one owner for feedback and its writer. */
export function createProgressRenderer(
  writer: ProgressWriter,
  clock: ProgressClock = SYSTEM_PROGRESS_CLOCK
): ProgressRenderer {
  const controller = new ProgressRendererController(writer, clock);
  return Object.freeze({
    refreshesRunningRegion: controller.refreshesRunningRegion,
    refresh: (): void => controller.refresh(),
    render: (feedback: ProgressFeedback): void => controller.render(feedback)
  });
}

