import type {
  DefinitionWarning,
  ProjectDefinitionDiagnostic
} from "../project-definition/project-definition.ts";
import type { RunControlDiagnostic } from "./controls/validation-result.ts";
import type { CheckAggregate, RunControls } from "./controls/contract.ts";
import type { CheckMessageLevel } from "../check/check.ts";
import type { CoreSnapshot } from "../check-settlement/facts.ts";
import type { RunOutputStatuses } from "./output-status.ts";
export type RunDiagnostic = Readonly<{
  readonly code:
    | "admission-policy-failed"
    | "task-graph-invalid"
    | "task-engine-failed"
    | "publication-model-failed";
}>;
export type CheckDuration = Readonly<{
  readonly checkId: string;
  readonly durationMs: number | null;
}>;
export interface CheckRunMessage {
  readonly checkId: string;
  readonly level: CheckMessageLevel;
  readonly code: string;
  readonly message: string;
}
export interface RunResultFacts {
  readonly aggregate: CheckAggregate | null;
  readonly checkDurations: readonly CheckDuration[];
  readonly checkMessages: readonly CheckRunMessage[];
  readonly snapshot: CoreSnapshot;
}
/** 一次 Project Run 的可判别结果；output failure 保留已结算 facts。 */
export type RunResult = Readonly<
  | {
      readonly kind: "configuration";
      readonly definitionWarnings: readonly DefinitionWarning[];
      readonly diagnostic: ProjectDefinitionDiagnostic | RunControlDiagnostic;
    }
  | {
      readonly kind: "planning";
      readonly declarativeFingerprint: string;
      readonly definitionWarnings: readonly DefinitionWarning[];
      readonly diagnostic: RunDiagnostic;
      readonly outputs: RunOutputStatuses;
    }
  | {
      readonly kind: "cancelled";
      readonly declarativeFingerprint: string;
      readonly definitionWarnings: readonly DefinitionWarning[];
      readonly outputs: RunOutputStatuses;
      readonly phase: "pre-work" | "planning";
    }
  | {
      readonly kind: "cancelled";
      readonly declarativeFingerprint: string;
      readonly definitionWarnings: readonly DefinitionWarning[];
      readonly outputs: RunOutputStatuses;
      readonly phase: "execution";
      readonly checkDurations: readonly CheckDuration[];
      readonly checkMessages: readonly CheckRunMessage[];
      readonly snapshot: CoreSnapshot;
    }
  | ({
      readonly kind: "completed";
      readonly declarativeFingerprint: string;
      readonly definitionWarnings: readonly DefinitionWarning[];
      readonly outputs: RunOutputStatuses;
    } & RunResultFacts)
  | {
      readonly kind: "execution";
      readonly declarativeFingerprint: string;
      readonly definitionWarnings: readonly DefinitionWarning[];
      readonly diagnostic: RunDiagnostic;
      readonly outputs: RunOutputStatuses;
    }
  | ({
      readonly kind: "output";
      readonly declarativeFingerprint: string;
      readonly definitionWarnings: readonly DefinitionWarning[];
      readonly diagnostic: Readonly<{
        readonly code:
          | "machine-publication-failed"
          | "progress-rendering-failed"
          | "diagnostic-logging-failed"
          | "scheduler-measurement-hooks-failed";
      }>;
      readonly outputs: RunOutputStatuses;
    } & RunResultFacts)
>;

/** Any Run result produced after controls and Definition validation have completed. */
export type NonConfigurationRunResult = Exclude<RunResult, { readonly kind: "configuration" }>;

type OutputRunResult = Extract<RunResult, { readonly kind: "output" }>;

export function outputFailure(
  declarativeFingerprint: string,
  definitionWarnings: readonly DefinitionWarning[],
  outputs: RunOutputStatuses,
  output: keyof RunOutputStatuses,
  facts: RunResultFacts
): OutputRunResult {
  return Object.freeze({
    kind: "output",
    declarativeFingerprint,
    definitionWarnings,
    diagnostic: Object.freeze({ code: outputDiagnosticCode(output) }),
    outputs,
    ...facts
  });
}
function outputDiagnosticCode(
  output: keyof RunOutputStatuses
): Extract<RunResult, { readonly kind: "output" }>["diagnostic"]["code"] {
  switch (output) {
    case "machinePublication":
      return "machine-publication-failed";
    case "progressRendering":
      return "progress-rendering-failed";
    case "diagnosticLogging":
      return "diagnostic-logging-failed";
    case "measurementHooks":
      return "scheduler-measurement-hooks-failed";
  }
}

export function isCancelled(controls: RunControls): boolean {
  return controls.signal?.aborted === true;
}
export function planning(
  declarativeFingerprint: string,
  definitionWarnings: readonly DefinitionWarning[],
  outputs: RunOutputStatuses,
  code: Extract<RunDiagnostic["code"], "task-graph-invalid">
): Extract<NonConfigurationRunResult, { readonly kind: "planning" }> {
  return Object.freeze({
    kind: "planning",
    declarativeFingerprint,
    definitionWarnings,
    diagnostic: Object.freeze({ code }),
    outputs
  });
}
export function preExecutionCancellation(
  declarativeFingerprint: string,
  definitionWarnings: readonly DefinitionWarning[],
  outputs: RunOutputStatuses,
  phase: "pre-work" | "planning"
): Extract<
  NonConfigurationRunResult,
  { readonly kind: "cancelled"; readonly phase: "pre-work" | "planning" }
> {
  return Object.freeze({
    kind: "cancelled",
    declarativeFingerprint,
    definitionWarnings,
    outputs,
    phase
  });
}
export function executionCancellation(
  input: Readonly<{
    readonly checkDurations: readonly CheckDuration[];
    readonly checkMessages: readonly CheckRunMessage[];
    readonly declarativeFingerprint: string;
    readonly definitionWarnings: readonly DefinitionWarning[];
    readonly outputs: RunOutputStatuses;
    readonly snapshot: CoreSnapshot;
  }>
): Extract<NonConfigurationRunResult, { readonly kind: "cancelled"; readonly phase: "execution" }> {
  return Object.freeze({
    kind: "cancelled",
    declarativeFingerprint: input.declarativeFingerprint,
    definitionWarnings: input.definitionWarnings,
    outputs: input.outputs,
    phase: "execution",
    checkDurations: input.checkDurations,
    checkMessages: input.checkMessages,
    snapshot: input.snapshot
  });
}

import type { ProjectDefinition } from "../project-definition/project-definition.ts";
import type { RunControls } from "./controls/contract.ts";
import { validateProjectDefinition } from "../project-definition/project-definition-validation.ts";
import { validateRunControls } from "./controls/validation.ts";
import { executeValidatedRun } from "./invocation.ts";
import type { RunResult } from "./result.ts";

export type { RunOutputStatus, RunOutputStatuses } from "./output-status.ts";
export type { RunDiagnostic, RunResult } from "./result.ts";

/**
 * 在调用方的 Bun runtime 中执行一个由项目拥有的 Project Definition。
 *
 * @param definition - Project Definition input；{@link defineConfig} 补齐 defaults，run 在 invocation 前验证。
 * @param controls - 本次 invocation context 与 outputs 使用的闭合控制值。
 * @returns ordinary configuration、planning、execution、cancellation 与 output failures 通过 `RunResult`
 * 返回；调用方先按 `kind` narrow。
 * @remarks Definition validation 关闭 authoring grammar；可选 Check preflight 在其 Task 通过直接 relation
 * readiness 后被 Scheduler admission 时运行，并先于该 Check 自己的 execution callback。它受该 Task 的
 * mutex、capacity、priority 与 cancellation 约束，而不是 invocation-wide barrier。`output` branch 同时提供
 * 完整 final snapshot 与 output failure diagnostic。
 */
export async function run(
  definition: ProjectDefinition,
  controls?: RunControls
): Promise<RunResult>;
export async function run(definition: unknown, controls?: unknown): Promise<RunResult>;
export async function run(definition: unknown, controls: unknown = {}): Promise<RunResult> {
  const validatedDefinition = validateProjectDefinition(definition);
  if (!validatedDefinition.ok) {
    return Object.freeze({
      kind: "configuration",
      definitionWarnings: Object.freeze([]),
      diagnostic: validatedDefinition.error
    });
  }
  const validatedControls = validateRunControls(controls);
  if (!validatedControls.ok) {
    return Object.freeze({
      kind: "configuration",
      definitionWarnings: Object.freeze([]),
      diagnostic: validatedControls.error
    });
  }

  return executeValidatedRun(
    validatedDefinition.value,
    validatedControls.value,
    validatedDefinition.warnings
  );
}

import type { PlannedTask, PlannedTaskGraph, PlannedTaskScope } from "./graph.ts";
import type { SchedulerInspection } from "./scheduler-decision-inspection.ts";
import type {
  AdmissionPolicyContext,
  SchedulerGraphSnapshot
} from "../../project-definition/project-definition.ts";

export interface AdmissionCandidate {
  readonly canAdmit: boolean;
  readonly task: PlannedTask;
}

export interface AdmissionPolicyInput {
  /** Scheduler-owned decision-boundary measurement, present only for custom policy. */
  readonly measurement?: AdmissionPolicyContext["measurement"];
  readonly candidates: readonly AdmissionCandidate[];
  readonly graph: PlannedTaskGraph;
  readonly graphSnapshot: SchedulerGraphSnapshot;
  readonly inspection: SchedulerInspection;
}

export type AdmissionPolicyDecision =
  | Readonly<{ readonly kind: "select"; readonly taskId: string }>
  | Readonly<{ readonly kind: "wait" }>;

/** A Product-private pure admission policy; it receives no executor or mutable scheduler state. */
export interface AdmissionSelectionPolicy {
  /** Only custom policies require Scheduler sampling before every callback. */
  readonly requiresMeasurement?: true;
  readonly decide: (input: AdmissionPolicyInput) => AdmissionPolicyDecision;
}

export const staticAdmissionSelectionPolicy: AdmissionSelectionPolicy = Object.freeze({
  decide: decideStaticAdmission
});

function decideStaticAdmission(input: AdmissionPolicyInput): AdmissionPolicyDecision {
  const tightening = selectTighteningCandidate(input);
  if (tightening !== undefined) return proposalFor(tightening);

  const continuation = selectConstrainedContinuation(input);
  if (continuation !== undefined) return proposalFor(continuation);

  return proposalFor(selectOrdinaryReadyCandidate(input.candidates));
}

function proposalFor(candidate: AdmissionCandidate): AdmissionPolicyDecision {
  return candidate.canAdmit
    ? Object.freeze({ kind: "select", taskId: candidate.task.id })
    : Object.freeze({ kind: "wait" });
}

function selectTighteningCandidate(input: AdmissionPolicyInput): AdmissionCandidate | undefined {
  return input.candidates
    .filter((candidate) => activatesTighteningScope(input, candidate.task))
    .sort((left, right) => compareConstrainedCandidates(input, left, right))[0];
}

function selectConstrainedContinuation(
  input: AdmissionPolicyInput
): AdmissionCandidate | undefined {
  return input.candidates
    .filter((candidate) => isConstrainedContinuation(input, candidate.task))
    .sort((left, right) => compareConstrainedCandidates(input, left, right))[0];
}

function selectOrdinaryReadyCandidate(
  candidates: readonly AdmissionCandidate[]
): AdmissionCandidate {
  const [first, ...remaining] = candidates;
  if (first === undefined) throw new Error("static scheduler selection requires a candidate");
  return remaining.reduce(
    (selected, candidate) =>
      candidate.task.admissionPriority > selected.task.admissionPriority ? candidate : selected,
    first
  );
}

function activatesTighteningScope(input: AdmissionPolicyInput, task: PlannedTask): boolean {
  const scope = activationScopeFor(input, task);
  return scope !== undefined && scope.maxParallel < input.inspection.maxParallel;
}

function isConstrainedContinuation(input: AdmissionPolicyInput, task: PlannedTask): boolean {
  const scope = scopeForTask(input.graph, task);
  return (
    scope !== undefined &&
    input.inspection.activeScopeIds.includes(scope.id) &&
    scope.maxParallel < input.inspection.maxParallel
  );
}

function compareConstrainedCandidates(
  input: AdmissionPolicyInput,
  left: AdmissionCandidate,
  right: AdmissionCandidate
): number {
  const leftScope = scopeForTask(input.graph, left.task);
  const rightScope = scopeForTask(input.graph, right.task);
  if (leftScope === undefined || rightScope === undefined) {
    throw new Error("constrained task is missing a scope");
  }
  return (
    leftScope.maxParallel - rightScope.maxParallel ||
    right.task.admissionPriority - left.task.admissionPriority ||
    compareText(leftScope.id, rightScope.id) ||
    compareText(left.task.id, right.task.id)
  );
}

function activationScopeFor(
  input: AdmissionPolicyInput,
  task: PlannedTask
): PlannedTaskScope | undefined {
  const scope = scopeForTask(input.graph, task);
  return scope?.activationTaskIds.includes(task.id) === true &&
    !input.inspection.activeScopeIds.includes(scope.id)
    ? scope
    : undefined;
}

function scopeForTask(graph: PlannedTaskGraph, task: PlannedTask): PlannedTaskScope | undefined {
  return task.scopeId === undefined
    ? undefined
    : graph.scopes.find((scope) => scope.id === task.scopeId);
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import type {
  AdmissionPolicy,
  AdmissionPolicyContext,
  AdmissionProposal
} from "../../project-definition/project-definition.ts";
import type {
  AdmissionPolicyInput,
  AdmissionSelectionPolicy
} from "./admission-selection-policy.ts";
import {
  AdmissionPolicyFault,
  type AdmissionPolicyFaultCategory
} from "./scheduler-admission-decision.ts";
import { capacityFor } from "./scheduler-decision-inspection.ts";

/** Adapts the public, trusted callback to the Scheduler's private pure policy seam. */
export function admissionSelectionPolicyFor(
  policy: AdmissionPolicy
): AdmissionSelectionPolicy | undefined {
  if (policy.kind === "static") return undefined;
  const customPolicy: AdmissionSelectionPolicy = Object.freeze({
    requiresMeasurement: true,
    decide: (input: AdmissionPolicyInput) => invokeCustomPolicy(policy.proposeAdmission, input)
  });
  return customPolicy;
}

function invokeCustomPolicy(
  proposeAdmission: Extract<AdmissionPolicy, { readonly kind: "custom" }>["proposeAdmission"],
  input: AdmissionPolicyInput
): AdmissionProposal {
  let proposal: unknown;
  try {
    proposal = proposeAdmission(admissionPolicyContext(input));
  } catch {
    throw new AdmissionPolicyFault("callback-threw");
  }
  if (isThenable(proposal)) throw new AdmissionPolicyFault("thenable-proposal");
  return validateProposal(proposal);
}

function admissionPolicyContext(input: AdmissionPolicyInput): AdmissionPolicyContext {
  if (input.measurement === undefined)
    throw new Error("custom admission policy requires measurement");
  return deepFreeze({
    activeScopeIds: [...input.inspection.activeScopeIds],
    candidates: input.candidates.map((candidate) => ({
      canAdmit: candidate.canAdmit,
      taskId: candidate.task.id
    })),
    capacity: capacityFor(input.inspection),
    measurement: input.measurement,
    graph: input.graphSnapshot,
    runningTaskIds: [...input.inspection.runningTaskIds],
    runtime: {
      abortRequested: input.inspection.isAbortRequested,
      cancelled: input.inspection.isCancelled
    },
    settledTaskIds: input.inspection.settledTasks.map((task) => task.taskId)
  });
}

function validateProposal(value: unknown): AdmissionProposal {
  if (!isPlainRecord(value)) throw new AdmissionPolicyFault("malformed-proposal");
  try {
    return parseProposalRecord(value);
  } catch (error) {
    if (error instanceof AdmissionPolicyFault) throw error;
    throw new AdmissionPolicyFault("malformed-proposal");
  }
}

function parseProposalRecord(value: Record<string, unknown>): AdmissionProposal {
  switch (value.kind) {
    case "select":
      return parseSelectProposal(value);
    case "wait":
      return parseWaitProposal(value);
  }
  throw new AdmissionPolicyFault("malformed-proposal");
}

function parseSelectProposal(value: Record<string, unknown>): AdmissionProposal {
  const keys = Reflect.ownKeys(value);
  if (
    keys.length !== 2 ||
    !keys.includes("kind") ||
    !keys.includes("taskId") ||
    typeof value.taskId !== "string"
  ) {
    throw new AdmissionPolicyFault("malformed-proposal");
  }
  return Object.freeze({ kind: "select", taskId: value.taskId });
}

function parseWaitProposal(value: Record<string, unknown>): AdmissionProposal {
  const keys = Reflect.ownKeys(value);
  if (keys.length !== 1 || keys[0] !== "kind") {
    throw new AdmissionPolicyFault("malformed-proposal");
  }
  return Object.freeze({ kind: "wait" });
}

function isPlainRecord(value: unknown): value is Record<string, unknown> {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  try {
    const prototype = Reflect.getPrototypeOf(value);
    return prototype === Object.prototype || prototype === null;
  } catch {
    return false;
  }
}

function isThenable(value: unknown): boolean {
  if (value === null || (typeof value !== "object" && typeof value !== "function")) return false;
  try {
    return typeof Reflect.get(value, "then") === "function";
  } catch {
    return true;
  }
}

function deepFreeze<T>(value: T): T {
  if (value === null || typeof value !== "object" || Object.isFrozen(value)) return value;
  for (const item of Object.values(value)) deepFreeze(item);
  return Object.freeze(value);
}

export type { AdmissionPolicyFaultCategory };

import type { SchedulerMeasurementHook } from "../../project-definition/project-definition.ts";
import type { PlannedTask, PlannedTaskGraph, PlannedTaskScope, TaskGraph } from "./graph.ts";
import {
  staticAdmissionSelectionPolicy,
  type AdmissionSelectionPolicy
} from "./admission-selection-policy.ts";
import type { DiagnosticLogger } from "../diagnostic-logging/logger.ts";
import type { SchedulerSnapshot } from "./scheduler-decision.ts";
import type { AdmissionPolicyFaultCategory } from "./scheduler-admission-decision.ts";
import type { SchedulerPerformanceDiagnosticsInput } from "./scheduler-performance-diagnostics.ts";

export type TaskSettlement<TResult> = Readonly<
  | { readonly kind: "completed"; readonly value: TResult }
  | { readonly kind: "prerequisite-unsatisfied"; readonly value: TResult }
  | { readonly kind: "failed"; readonly error: unknown }
  | { readonly kind: "blocked"; readonly dependencyIds: readonly string[] }
  | { readonly kind: "cancelled-before-start" }
>;

export interface SettledTask<TResult> {
  readonly task: PlannedTask;
  readonly settlement: TaskSettlement<TResult>;
}

export interface TaskExecutionContext {
  readonly signal: AbortSignal | undefined;
}

export interface PreAdmissionTaskResult<TResult> {
  readonly taskId: string;
  readonly value: TResult;
}

export interface TaskGraphRun<TResult> {
  readonly admissionPolicyFault: AdmissionPolicyFaultCategory | undefined;
  readonly cancelled: boolean;
  /** One entry per static graph Task, in static graph order. */
  readonly settlements: readonly SettledTask<TResult>[];
}

export interface RunTaskGraphOptions<TResult> {
  /** Product-private policy handoff; package consumers cannot author this through the public API. */
  readonly admissionPolicy?: AdmissionSelectionPolicy;
  readonly diagnosticLogger?: DiagnosticLogger;
  /** Explicit enabled-only handoff; no Scheduler behavior is inferred from a logger shape. */
  readonly performanceDiagnostics?: SchedulerPerformanceDiagnosticsInput;
  /** Runtime-only terminal consumers; their context is formed after Scheduler drain. */
  readonly measurementHooks?: readonly SchedulerMeasurementHook[];
  readonly onMeasurementHookFailure?: () => void;
  readonly onMeasurementHooksSettled?: () => void;
  readonly graph: TaskGraph;
  /** Product-private Task results formed without Scheduler admission in the current Run. */
  readonly preAdmissionTaskResults?: readonly PreAdmissionTaskResult<TResult>[];
  readonly maxParallel: number;
  readonly signal?: AbortSignal;
  readonly execute: (
    task: PlannedTask,
    context: TaskExecutionContext
  ) => TResult | Promise<TResult>;
  /** Maps a completed Task's opaque product value to prerequisite satisfaction. */
  readonly isPrerequisiteSatisfied?: (value: TResult) => boolean;
  /** Lets a product close a blocked Task before any terminal observer can be admitted. */
  readonly onTaskBlocked?: (task: PlannedTask, dependencyIds: readonly string[]) => void;
}

export type RunningTaskCompletion<TResult> = Readonly<{
  readonly taskId: string;
  readonly settlement: TaskSettlement<TResult>;
}>;

export interface RunningTask<TResult> {
  readonly task: PlannedTask;
  readonly completion: Promise<RunningTaskCompletion<TResult>>;
}

export interface RuntimeScope {
  readonly scope: PlannedTaskScope;
  readonly activationTaskIds: ReadonlySet<string>;
  isActive: boolean;
}

export interface SchedulerState<TResult> {
  readonly admissionPolicy: AdmissionSelectionPolicy;
  readonly diagnosticLogger: DiagnosticLogger | undefined;
  readonly graph: PlannedTaskGraph;
  readonly isPrerequisiteSatisfied: RunTaskGraphOptions<TResult>["isPrerequisiteSatisfied"];
  readonly maxParallel: number;
  readonly signal: AbortSignal | undefined;
  readonly execute: RunTaskGraphOptions<TResult>["execute"];
  readonly onTaskBlocked: RunTaskGraphOptions<TResult>["onTaskBlocked"];
  readonly pending: PlannedTask[];
  readonly runningById: Map<string, RunningTask<TResult>>;
  readonly runningMutexes: Set<string>;
  readonly settlementsByTaskId: Map<string, TaskSettlement<TResult>>;
  readonly scopesById: ReadonlyMap<string, RuntimeScope>;
  isCancelled: boolean;
  admissionPolicyFault: AdmissionPolicyFaultCategory | undefined;
}

export function createSchedulerState<TResult>(
  graph: PlannedTaskGraph,
  options: RunTaskGraphOptions<TResult>
): SchedulerState<TResult> {
  const admissionPolicy = options.admissionPolicy ?? staticAdmissionSelectionPolicy;
  if (!Object.isFrozen(admissionPolicy) || typeof admissionPolicy.decide !== "function") {
    throw new TypeError("task engine admission policy must be a frozen policy value");
  }
  const scopesById = new Map<string, RuntimeScope>();
  for (const scope of graph.scopes) {
    scopesById.set(scope.id, {
      scope,
      activationTaskIds: new Set(scope.activationTaskIds),
      isActive: false
    });
  }
  const state: SchedulerState<TResult> = {
    admissionPolicy,
    diagnosticLogger: options.diagnosticLogger,
    graph,
    isPrerequisiteSatisfied: options.isPrerequisiteSatisfied,
    maxParallel: options.maxParallel,
    onTaskBlocked: options.onTaskBlocked,
    signal: options.signal,
    execute: options.execute,
    pending: [...graph.tasks],
    runningById: new Map(),
    runningMutexes: new Set(),
    settlementsByTaskId: new Map(),
    scopesById,
    isCancelled: false,
    admissionPolicyFault: undefined
  };
  recordPreAdmissionTaskResults(state, options.preAdmissionTaskResults ?? []);
  return state;
}

function recordPreAdmissionTaskResults<TResult>(
  state: SchedulerState<TResult>,
  preAdmissionTaskResults: readonly PreAdmissionTaskResult<TResult>[]
): void {
  for (const result of preAdmissionTaskResults) {
    const pendingIndex = state.pending.findIndex((task) => task.id === result.taskId);
    if (pendingIndex < 0) {
      throw new TypeError(
        `pre-admission task result references unknown or duplicate task ${result.taskId}`
      );
    }
    const [task] = state.pending.splice(pendingIndex, 1);
    if (task === undefined) {
      throw new Error(`pre-admission task ${result.taskId} disappeared before settlement`);
    }
    const settlement: TaskSettlement<TResult> =
      state.isPrerequisiteSatisfied?.(result.value) === false
        ? { kind: "prerequisite-unsatisfied", value: result.value }
        : { kind: "completed", value: result.value };
    recordSettlement(state, task, Object.freeze(settlement));
  }
}

/** Projects mutable execution state into the pure scheduler-decision input. */
export function snapshotSchedulerState<TResult>(state: SchedulerState<TResult>): SchedulerSnapshot {
  return Object.freeze({
    activeScopeIds: Object.freeze(
      [...state.scopesById.values()]
        .filter((scope) => scope.isActive)
        .map((scope) => scope.scope.id)
    ),
    graph: state.graph,
    isAbortRequested: state.signal?.aborted === true,
    isCancelled: state.isCancelled,
    maxParallel: state.maxParallel,
    pendingTaskIds: Object.freeze(state.pending.map((task) => task.id)),
    runningMutexes: Object.freeze([...state.runningMutexes]),
    runningTaskIds: Object.freeze([...state.runningById.keys()]),
    settledTasks: Object.freeze(
      [...state.settlementsByTaskId].map(([taskId, settlement]) =>
        Object.freeze({ kind: settlement.kind, taskId })
      )
    )
  });
}

export function scopeForTask<TResult>(
  task: PlannedTask,
  state: SchedulerState<TResult>
): RuntimeScope | undefined {
  return task.scopeId === undefined ? undefined : state.scopesById.get(task.scopeId);
}

export function cancelPendingTasks<TResult>(state: SchedulerState<TResult>): void {
  state.isCancelled = true;
  while (state.pending.length > 0) {
    const task = state.pending.shift();
    if (task === undefined) {
      throw new Error("task graph pending queue changed unexpectedly");
    }
    recordSettlement(state, task, Object.freeze({ kind: "cancelled-before-start" }));
  }
}

export function recordSettlement<TResult>(
  state: SchedulerState<TResult>,
  task: PlannedTask,
  settlement: TaskSettlement<TResult>
): void {
  if (state.settlementsByTaskId.has(task.id)) {
    throw new Error(`task ${task.id} settled more than once`);
  }
  state.settlementsByTaskId.set(task.id, settlement);
  const scope = scopeForTask(task, state);
  if (scope?.scope.terminalTaskId === task.id) {
    scope.isActive = false;
  }
}

import type { PlannedTask, PlannedTaskScope } from "./graph.ts";

interface PreparedTaskGraphValidationInput {
  readonly rootMaxParallel: number | undefined;
  readonly scopeById: ReadonlyMap<string, PlannedTaskScope>;
  readonly scopes: readonly PlannedTaskScope[];
  readonly taskById: ReadonlyMap<string, PlannedTask>;
  readonly tasks: readonly PlannedTask[];
}

type TaskRelationField = "dependsOn" | "observes";

interface TaskRelationPathQuery {
  readonly requiredRelatedTaskId: string;
  readonly taskById: ReadonlyMap<string, PlannedTask>;
  readonly taskId: string;
}

interface TaskRelationTraversal {
  readonly pending: string[];
  readonly query: TaskRelationPathQuery;
  readonly visited: Set<string>;
}

/** Validates direct relations and scope structure after graph-shaped input is normalized. */
export function validatePreparedTaskGraph(input: PreparedTaskGraphValidationInput): void {
  validateTaskRelations(input.tasks, input.taskById);
  validateTaskRelationCycles(input.tasks, input.taskById);
  validateScopes(input);
}

function validateTaskRelations(
  tasks: readonly PlannedTask[],
  taskById: ReadonlyMap<string, PlannedTask>
): void {
  for (const task of tasks) {
    validateRelatedTaskIds(task, "dependsOn", task.dependsOn, taskById);
    validateRelatedTaskIds(task, "observes", task.observes, taskById);
    for (const dependencyId of task.dependsOn) {
      if (task.observes.includes(dependencyId)) {
        throw new Error(`task ${task.id} cannot both depend on and observe task ${dependencyId}`);
      }
    }
  }
}

function validateRelatedTaskIds(
  task: PlannedTask,
  relation: TaskRelationField,
  relationTargetIds: readonly string[],
  taskById: ReadonlyMap<string, PlannedTask>
): void {
  const action = relation === "dependsOn" ? "depends on" : "observes";
  for (const relatedTaskId of relationTargetIds) {
    if (!taskById.has(relatedTaskId)) {
      throw new Error(`task ${task.id} ${action} unknown task ${relatedTaskId}`);
    }
  }
}

function validateTaskRelationCycles(
  tasks: readonly PlannedTask[],
  taskById: ReadonlyMap<string, PlannedTask>
): void {
  const visiting = new Set<string>();
  const visited = new Set<string>();

  const visit = (task: PlannedTask): void => {
    if (visiting.has(task.id)) {
      throw new Error(`task dependency cycle includes ${task.id}`);
    }
    if (visited.has(task.id)) return;

    visiting.add(task.id);
    for (const relatedTaskId of relatedTaskIds(task)) {
      const relatedTask = taskById.get(relatedTaskId);
      if (relatedTask === undefined) {
        throw new Error(`task ${task.id} relates to unknown task ${relatedTaskId}`);
      }
      visit(relatedTask);
    }
    visiting.delete(task.id);
    visited.add(task.id);
  };

  for (const task of tasks) {
    visit(task);
  }
}

function validateScopes(input: PreparedTaskGraphValidationInput): void {
  validateRootMaxParallel(input.rootMaxParallel);
  validateTaskScopeMembership(input.tasks, input.scopeById);
  for (const scope of input.scopes) {
    validateScopeCap(scope, input.rootMaxParallel);
    validateScopeTerminal(scope, input.taskById);
    validateScopeActivation(scope, input.taskById);
    validateScopeTerminalReachability(scope, input.tasks, input.taskById);
  }
}

function validateRootMaxParallel(rootMaxParallel: number | undefined): void {
  if (
    rootMaxParallel !== undefined &&
    (!Number.isSafeInteger(rootMaxParallel) || rootMaxParallel <= 0)
  ) {
    throw new TypeError("task engine maxParallel must be a positive safe integer");
  }
}

function validateTaskScopeMembership(
  tasks: readonly PlannedTask[],
  scopeById: ReadonlyMap<string, PlannedTaskScope>
): void {
  for (const task of tasks) {
    if (task.scopeId !== undefined && !scopeById.has(task.scopeId)) {
      throw new Error(`task ${task.id} references unknown scope ${task.scopeId}`);
    }
  }
}

function validateScopeCap(scope: PlannedTaskScope, rootMaxParallel: number | undefined): void {
  if (rootMaxParallel !== undefined && scope.maxParallel > rootMaxParallel) {
    throw new Error(`task scope ${scope.id} maxParallel exceeds task engine maxParallel`);
  }
}

function validateScopeTerminal(
  scope: PlannedTaskScope,
  taskById: ReadonlyMap<string, PlannedTask>
): void {
  const terminal = taskById.get(scope.terminalTaskId);
  if (terminal?.scopeId !== scope.id) {
    throw new Error(`task scope ${scope.id} terminal task must belong to the scope`);
  }
}

function validateScopeActivation(
  scope: PlannedTaskScope,
  taskById: ReadonlyMap<string, PlannedTask>
): void {
  const activationIds = new Set<string>();
  for (const taskId of scope.activationTaskIds) {
    if (activationIds.has(taskId)) {
      throw new Error(`task scope ${scope.id} repeats activation task ${taskId}`);
    }
    activationIds.add(taskId);
    const task = taskById.get(taskId);
    if (task?.scopeId !== scope.id) {
      throw new Error(`task scope ${scope.id} activation task must belong to the scope: ${taskId}`);
    }
  }
}

function validateScopeTerminalReachability(
  scope: PlannedTaskScope,
  tasks: readonly PlannedTask[],
  taskById: ReadonlyMap<string, PlannedTask>
): void {
  for (const task of tasks) {
    if (task.scopeId !== scope.id || task.id === scope.terminalTaskId) continue;
    if (
      !isRelatedToTask({ requiredRelatedTaskId: task.id, taskById, taskId: scope.terminalTaskId })
    ) {
      throw new Error(`task scope ${scope.id} terminal task must relate to scoped task ${task.id}`);
    }
  }
}

function isRelatedToTask(query: TaskRelationPathQuery): boolean {
  return traverseTaskRelations({
    pending: [...relatedTaskIdsFor(query.taskById, query.taskId)],
    query,
    visited: new Set()
  });
}

function traverseTaskRelations(traversal: TaskRelationTraversal): boolean {
  while (traversal.pending.length > 0) {
    const relatedTaskId = traversal.pending.pop();
    if (relatedTaskId === undefined || traversal.visited.has(relatedTaskId)) continue;
    if (relatedTaskId === traversal.query.requiredRelatedTaskId) return true;

    traversal.visited.add(relatedTaskId);
    traversal.pending.push(...relatedTaskIdsFor(traversal.query.taskById, relatedTaskId));
  }
  return false;
}

function relatedTaskIdsFor(
  taskById: ReadonlyMap<string, PlannedTask>,
  taskId: string
): readonly string[] {
  const task = taskById.get(taskId);
  return task === undefined ? [] : relatedTaskIds(task);
}

function relatedTaskIds(task: PlannedTask): readonly string[] {
  return [...task.dependsOn, ...task.observes];
}

import { validatePreparedTaskGraph } from "./graph-validation.ts";
import type { SchedulerGraphSnapshot } from "../../project-definition/project-definition.ts";

export interface TaskNode {
  readonly admissionPriority?: number;
  readonly id: string;
  readonly dependsOn?: readonly string[];
  readonly mutex?: readonly string[];
  readonly observes?: readonly string[];
  readonly scopeId?: string;
}

/**
 * A scheduling scope is intentionally product-agnostic. Product adapters may
 * use its opaque id to bind local Check semantics, but the engine only uses
 * membership, a cap, activation candidates, and the terminal relation.
 */
export interface TaskScope {
  readonly id: string;
  readonly maxParallel: number;
  readonly activationTaskIds: readonly string[];
  readonly terminalTaskId: string;
}

export interface TaskGraph {
  readonly tasks: readonly TaskNode[];
  readonly scopes?: readonly TaskScope[];
}

export interface PlannedTask {
  readonly admissionPriority: number;
  readonly id: string;
  readonly dependsOn: readonly string[];
  readonly mutex: readonly string[];
  readonly observes: readonly string[];
  readonly scopeId: string | undefined;
}

export interface PlannedTaskScope {
  readonly id: string;
  readonly maxParallel: number;
  readonly activationTaskIds: readonly string[];
  readonly terminalTaskId: string;
}

export interface PlannedTaskGraph {
  /** Immutable public projection shared by every decision and terminal measurement in one run. */
  readonly schedulerGraphSnapshot: SchedulerGraphSnapshot;
  readonly tasks: readonly PlannedTask[];
  readonly scopes: readonly PlannedTaskScope[];
}

const TASK_GRAPH_KEYS = ["tasks", "scopes"] as const;
const TASK_NODE_KEYS = [
  "admissionPriority",
  "id",
  "dependsOn",
  "mutex",
  "observes",
  "scopeId"
] as const;
const TASK_SCOPE_KEYS = ["id", "maxParallel", "activationTaskIds", "terminalTaskId"] as const;

/** Validates untrusted graph-shaped input without admitting it to scheduler execution. */
export function validateTaskGraph(graph: unknown): void {
  prepareTaskGraph(graph);
}

export function prepareTaskGraph(graph: unknown, rootMaxParallel?: number): PlannedTaskGraph {
  const data = record(graph, "task graph", TASK_GRAPH_KEYS);
  const tasks = normalizeTasks(data.tasks);
  const scopes = normalizeScopes(data.scopes);
  const taskById = new Map(tasks.map((task) => [task.id, task] as const));
  const scopeById = new Map(scopes.map((scope) => [scope.id, scope] as const));

  validatePreparedTaskGraph({ rootMaxParallel, scopeById, scopes, taskById, tasks });

  return Object.freeze({
    schedulerGraphSnapshot: schedulerGraphSnapshot(tasks, scopes),
    tasks: Object.freeze(tasks),
    scopes: Object.freeze(scopes)
  });
}

function schedulerGraphSnapshot(
  tasks: readonly PlannedTask[],
  scopes: readonly PlannedTaskScope[]
): SchedulerGraphSnapshot {
  return Object.freeze({
    scopes: Object.freeze(
      scopes.map((scope) =>
        Object.freeze({
          activationTaskIds: Object.freeze([...scope.activationTaskIds]),
          id: scope.id,
          maxParallel: scope.maxParallel,
          terminalTaskId: scope.terminalTaskId
        })
      )
    ),
    tasks: Object.freeze(
      tasks.map((task) =>
        Object.freeze({
          admissionPriority: task.admissionPriority,
          dependsOn: Object.freeze([...task.dependsOn]),
          mutex: Object.freeze([...task.mutex]),
          observes: Object.freeze([...task.observes]),
          scopeId: task.scopeId ?? null,
          taskId: task.id
        })
      )
    )
  });
}

function normalizeTasks(value: unknown): PlannedTask[] {
  if (!Array.isArray(value)) {
    throw new TypeError("task graph tasks must be an array");
  }

  const ids = new Set<string>();
  const tasks: PlannedTask[] = [];
  for (const [index, candidate] of value.entries()) {
    const data = record(candidate, `task graph tasks[${index}]`, TASK_NODE_KEYS);
    const id = nonEmptyString(data.id, `task graph tasks[${index}].id`);
    if (ids.has(id)) {
      throw new TypeError(`duplicate task id: ${id}`);
    }
    ids.add(id);
    const admissionPriority = admissionPriorityOrDefault(data.admissionPriority, id);
    const scopeId = optionalNonEmptyString(data.scopeId, `task ${id}.scopeId`);
    tasks.push(
      Object.freeze({
        admissionPriority,
        id,
        dependsOn: Object.freeze(stringList(data.dependsOn, `task ${id}.dependsOn`)),
        mutex: Object.freeze(stringList(data.mutex, `task ${id}.mutex`)),
        observes: Object.freeze(stringList(data.observes, `task ${id}.observes`)),
        scopeId
      })
    );
  }
  return tasks;
}

function normalizeScopes(value: unknown): PlannedTaskScope[] {
  if (value === undefined) {
    return [];
  }
  if (!Array.isArray(value)) {
    throw new TypeError("task graph scopes must be an array");
  }

  const ids = new Set<string>();
  const scopes: PlannedTaskScope[] = [];
  for (const [index, candidate] of value.entries()) {
    const data = record(candidate, `task graph scopes[${index}]`, TASK_SCOPE_KEYS);
    const id = nonEmptyString(data.id, `task graph scopes[${index}].id`);
    if (ids.has(id)) {
      throw new TypeError(`duplicate task scope id: ${id}`);
    }
    ids.add(id);
    const maxParallel = positiveSafeInteger(data.maxParallel, `task scope ${id}.maxParallel`);
    const activationTaskIds = requiredStringList(
      data.activationTaskIds,
      `task scope ${id}.activationTaskIds`
    );
    const terminalTaskId = nonEmptyString(data.terminalTaskId, `task scope ${id}.terminalTaskId`);
    scopes.push(
      Object.freeze({
        id,
        maxParallel,
        activationTaskIds: Object.freeze(activationTaskIds),
        terminalTaskId
      })
    );
  }
  return scopes;
}

function record(
  value: unknown,
  fieldName: string,
  allowedKeys: readonly string[]
): Readonly<Record<string, unknown>> {
  if (!isTaskGraphRecord(value)) {
    throw new TypeError(`${fieldName} must be an object`);
  }
  for (const key of Object.keys(value)) {
    if (!allowedKeys.includes(key)) {
      throw new TypeError(`${fieldName} has unknown property: ${key}`);
    }
  }
  return value;
}

function isTaskGraphRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function nonEmptyString(value: unknown, fieldName: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${fieldName} must be a non-empty string`);
  }
  return value;
}

function optionalNonEmptyString(value: unknown, fieldName: string): string | undefined {
  return value === undefined ? undefined : nonEmptyString(value, fieldName);
}

function stringList(value: unknown, fieldName: string): string[] {
  if (value === undefined) {
    return [];
  }
  if (!Array.isArray(value)) {
    throw new TypeError(`${fieldName} must be an array of non-empty strings`);
  }
  return value.map((item, index) => nonEmptyString(item, `${fieldName}[${index}]`));
}

function requiredStringList(value: unknown, fieldName: string): string[] {
  if (value === undefined) {
    throw new TypeError(`${fieldName} must be an array of non-empty strings`);
  }
  return stringList(value, fieldName);
}

function positiveSafeInteger(value: unknown, fieldName: string): number {
  if (typeof value !== "number" || !Number.isSafeInteger(value) || value <= 0) {
    throw new TypeError(`${fieldName} must be a positive safe integer`);
  }
  return value;
}

function admissionPriorityOrDefault(value: unknown, taskId: string): number {
  if (value === undefined) return 0;
  if (typeof value !== "number" || !Number.isSafeInteger(value)) {
    throw new TypeError(`task ${taskId}.admissionPriority must be a safe integer`);
  }
  return value;
}

import type { AdmissionPolicyContext } from "../../project-definition/project-definition.ts";
import type {
  AdmissionCandidate,
  AdmissionPolicyDecision,
  AdmissionSelectionPolicy
} from "./admission-selection-policy.ts";
import {
  activationScopeFor,
  canAdmit,
  isRelationMutexEligible
} from "./scheduler-decision-inspection.ts";
import {
  freezeDecision,
  type SchedulerAdmissionCandidateFact,
  type SchedulerAdmissionHardGuard,
  type SchedulerDecision,
  type SchedulerDecisionContext,
  type SchedulerTrigger
} from "./scheduler-decision-model.ts";
import type { SchedulerInspection } from "./scheduler-decision-inspection.ts";

export interface SchedulerDecisionCycle {
  readonly context: SchedulerDecisionContext;
  readonly policy: AdmissionSelectionPolicy;
  /** Invoked immediately before the private policy seam enters a custom callback. */
  readonly measurement?: () => AdmissionPolicyContext["measurement"];
  readonly state: SchedulerInspection;
  readonly trigger: SchedulerTrigger;
}

export function decideAdmission(cycle: SchedulerDecisionCycle): SchedulerDecision {
  const candidates = Object.freeze(
    cycle.state.pendingTasks
      .filter((task) => isRelationMutexEligible(task, cycle.state))
      .map((task) => Object.freeze({ canAdmit: canAdmit(cycle.state, task), task }))
  );
  if (candidates.length === 0) return awaitDecision(cycle, candidates);

  const measurement = cycle.measurement?.();
  const result = validatePolicyDecision(
    cycle.policy.decide(
      Object.freeze({
        candidates,
        graph: cycle.state.graph,
        graphSnapshot: cycle.context.graphIdentity,
        inspection: cycle.state,
        ...(measurement === undefined ? {} : { measurement })
      })
    )
  );
  return result.kind === "select"
    ? admitDecision(cycle, candidates, result)
    : awaitDecision(cycle, candidates, result);
}

function admitDecision(
  cycle: SchedulerDecisionCycle,
  candidates: readonly AdmissionCandidate[],
  result: Extract<AdmissionPolicyDecision, { readonly kind: "select" }>
): SchedulerDecision {
  const candidate = candidateFor(result.taskId, candidates);
  if (candidate === undefined) {
    throw new AdmissionPolicyFault("non-candidate-select");
  }
  if (!candidate.canAdmit) {
    throw new AdmissionPolicyFault("capacity-invalid-select");
  }
  return freezeDecision({
    ...cycle.context,
    admissionPriority: candidate.task.admissionPriority,
    candidates: candidateFacts(candidates),
    eligibleCount: candidates.length,
    hardGuard: selectHardGuard(candidate.task.id),
    kind: "admit",
    proposal: result,
    scopeToActivate: activationScopeFor(cycle.state, candidate.task)?.id ?? null,
    taskId: candidate.task.id,
    trigger: cycle.trigger
  });
}

function awaitDecision(
  cycle: SchedulerDecisionCycle,
  candidates: readonly AdmissionCandidate[],
  proposal: AdmissionPolicyDecision | null = null
): SchedulerDecision {
  if (cycle.state.runningTaskIds.length === 0) {
    throw new AdmissionPolicyFault("undrainable-wait");
  }
  return freezeDecision({
    ...cycle.context,
    candidates: candidateFacts(candidates),
    eligibleCount: candidates.length,
    hardGuard: waitHardGuard(),
    kind: "await-running",
    proposal,
    trigger: cycle.trigger
  });
}

function candidateFacts(
  candidates: readonly AdmissionCandidate[]
): readonly SchedulerAdmissionCandidateFact[] {
  return Object.freeze(
    candidates.map((candidate) =>
      Object.freeze({ canAdmit: candidate.canAdmit, taskId: candidate.task.id })
    )
  );
}

function selectHardGuard(
  taskId: string
): Extract<SchedulerAdmissionHardGuard, { readonly kind: "select" }> {
  return Object.freeze({
    canAdmit: true,
    isCandidate: true,
    kind: "select",
    lifecycleOpen: true,
    taskId
  });
}

function waitHardGuard(): Extract<SchedulerAdmissionHardGuard, { readonly kind: "wait" }> {
  return Object.freeze({ kind: "wait", runningCanDrain: true });
}

function validatePolicyDecision(value: unknown): AdmissionPolicyDecision {
  if (!isRecord(value)) throw new AdmissionPolicyFault("malformed-proposal");
  if (value["kind"] === "select") {
    requireExactKeys(value, ["kind", "taskId"]);
    if (typeof value["taskId"] !== "string") {
      throw new AdmissionPolicyFault("malformed-proposal");
    }
    return Object.freeze({ kind: "select", taskId: value["taskId"] });
  }
  if (value["kind"] === "wait") {
    requireExactKeys(value, ["kind"]);
    return Object.freeze({ kind: "wait" });
  }
  throw new AdmissionPolicyFault("malformed-proposal");
}

function candidateFor(
  taskId: string,
  candidates: readonly AdmissionCandidate[]
): AdmissionCandidate | undefined {
  return candidates.find((candidate) => candidate.task.id === taskId);
}

function requireExactKeys(value: Readonly<Record<string, unknown>>, keys: readonly string[]): void {
  const prototype = Reflect.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new AdmissionPolicyFault("malformed-proposal");
  }
  const actualKeys = Reflect.ownKeys(value);
  if (
    actualKeys.length !== keys.length ||
    actualKeys.some((key) => typeof key !== "string" || !keys.includes(key))
  ) {
    throw new AdmissionPolicyFault("malformed-proposal");
  }
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

export type AdmissionPolicyFaultCategory =
  | "callback-threw"
  | "thenable-proposal"
  | "malformed-proposal"
  | "non-candidate-select"
  | "capacity-invalid-select"
  | "lifecycle-invalid-select"
  | "undrainable-wait";

export class AdmissionPolicyFault extends Error {
  public readonly category: AdmissionPolicyFaultCategory;

  public constructor(category: AdmissionPolicyFaultCategory) {
    super("admission policy fault");
    this.category = category;
  }
}

import type { SchedulerInspection } from "./scheduler-decision-inspection.ts";
import type { SchedulerBlockerSummary, SchedulerCapacity } from "./scheduler-decision-model.ts";

/** Summarizes why pending Tasks cannot currently advance. */
export function summarizeSchedulerBlockers(
  state: SchedulerInspection,
  capacity: SchedulerCapacity
): SchedulerBlockerSummary {
  let dependency = 0;
  let mutex = 0;
  for (const task of state.pendingTasks) {
    if (hasUnsatisfiedRelation(task, state.settledTasks)) {
      dependency += 1;
      continue;
    }
    if (hasRunningMutex(task.mutex, state.runningMutexes)) mutex += 1;
  }
  return Object.freeze({
    dependency,
    mutex,
    rootCapacity: state.runningTaskIds.length >= state.maxParallel,
    scopeCapacity:
      capacity.effectiveMaxParallel < state.maxParallel &&
      state.runningTaskIds.length >= capacity.effectiveMaxParallel
  });
}

function hasUnsatisfiedRelation(
  task: SchedulerInspection["pendingTasks"][number],
  settledTasks: SchedulerInspection["settledTasks"]
): boolean {
  return (
    task.dependsOn.some(
      (dependencyId) => settlementKindFor(settledTasks, dependencyId) !== "completed"
    ) ||
    task.observes.some(
      (observationId) => settlementKindFor(settledTasks, observationId) === undefined
    )
  );
}

function hasRunningMutex(
  mutexNames: readonly string[],
  runningMutexes: SchedulerInspection["runningMutexes"]
): boolean {
  return mutexNames.some((mutexName) => runningMutexes.includes(mutexName));
}

function settlementKindFor(
  settledTasks: SchedulerInspection["settledTasks"],
  taskId: string
): SchedulerInspection["settledTasks"][number]["kind"] | undefined {
  return settledTasks.find((task) => task.taskId === taskId)?.kind;
}

import type { PlannedTask, PlannedTaskGraph, PlannedTaskScope } from "./graph.ts";
import type { SchedulerGraphSnapshot } from "../../project-definition/project-definition.ts";
import { summarizeSchedulerBlockers } from "./scheduler-blocker-summary.ts";
import type {
  SchedulerCapacity,
  SchedulerDecisionContext,
  SchedulerSettlementKind,
  SchedulerSnapshot
} from "./scheduler-decision-model.ts";

export interface SchedulerInspection {
  readonly activeScopeIds: readonly string[];
  readonly graph: PlannedTaskGraph;
  readonly isAbortRequested: boolean;
  readonly isCancelled: boolean;
  readonly maxParallel: number;
  readonly pendingTasks: readonly PlannedTask[];
  readonly runningMutexes: readonly string[];
  readonly runningTaskIds: readonly string[];
  readonly settledTasks: readonly Readonly<{
    readonly kind: SchedulerSettlementKind;
    readonly taskId: string;
  }>[];
}

export function inspectSnapshot(snapshot: SchedulerSnapshot): SchedulerInspection {
  const tasksById = new Map(snapshot.graph.tasks.map((task) => [task.id, task] as const));
  const pendingTasks = snapshot.pendingTaskIds.map((taskId) => pendingTaskFor(taskId, tasksById));
  return Object.freeze({
    activeScopeIds: Object.freeze([...snapshot.activeScopeIds]),
    graph: snapshot.graph,
    isAbortRequested: snapshot.isAbortRequested,
    isCancelled: snapshot.isCancelled,
    maxParallel: snapshot.maxParallel,
    pendingTasks: Object.freeze(pendingTasks),
    runningMutexes: Object.freeze([...snapshot.runningMutexes]),
    runningTaskIds: Object.freeze([...snapshot.runningTaskIds]),
    settledTasks: Object.freeze(
      snapshot.settledTasks.map(({ taskId, kind }) => Object.freeze({ kind, taskId }))
    )
  });
}

export function decisionContext(
  state: SchedulerInspection,
  graphIdentity: SchedulerGraphSnapshot
): SchedulerDecisionContext {
  const capacity = capacityFor(state);
  return Object.freeze({
    blockers: summarizeSchedulerBlockers(state, capacity),
    capacity,
    graphIdentity
  });
}

export function selectBlockedTask(
  state: SchedulerInspection
): Readonly<{ readonly dependencyIds: readonly string[]; readonly task: PlannedTask }> | undefined {
  for (let index = state.pendingTasks.length - 1; index >= 0; index -= 1) {
    const task = state.pendingTasks[index];
    const dependencyIds = blockingDependencyIds(task, state.settledTasks);
    if (dependencyIds !== undefined)
      return Object.freeze({ dependencyIds: Object.freeze(dependencyIds), task });
  }
  return undefined;
}

export function isRelationMutexEligible(task: PlannedTask, state: SchedulerInspection): boolean {
  return (
    isRelationEligible(task, state) &&
    task.mutex.every((mutex) => !state.runningMutexes.includes(mutex))
  );
}

export function isRelationEligible(task: PlannedTask, state: SchedulerInspection): boolean {
  return (
    task.dependsOn.every(
      (dependencyId) => settlementKindFor(state.settledTasks, dependencyId) === "completed"
    ) &&
    task.observes.every(
      (observationId) => settlementKindFor(state.settledTasks, observationId) !== undefined
    )
  );
}

export function canAdmit(state: SchedulerInspection, task: PlannedTask): boolean {
  return state.runningTaskIds.length < prospectiveMaxParallel(state, task);
}

export function activationScopeFor(
  state: SchedulerInspection,
  task: PlannedTask
): PlannedTaskScope | undefined {
  const scope = scopeForTask(state, task);
  return scope?.activationTaskIds.includes(task.id) === true &&
    !state.activeScopeIds.includes(scope.id)
    ? scope
    : undefined;
}

function pendingTaskFor(taskId: string, tasksById: ReadonlyMap<string, PlannedTask>): PlannedTask {
  const task = tasksById.get(taskId);
  if (task === undefined) throw new Error(`scheduler snapshot has unknown pending task ${taskId}`);
  return task;
}

function blockingDependencyIds(
  task: PlannedTask,
  settledTasks: SchedulerInspection["settledTasks"]
): string[] | undefined {
  const settlementKinds = task.dependsOn.map(
    (dependencyId) => [dependencyId, settlementKindFor(settledTasks, dependencyId)] as const
  );
  if (settlementKinds.some(([, kind]) => kind === undefined)) return undefined;
  const dependencyIds = settlementKinds.flatMap(([dependencyId, kind]) =>
    kind === "completed" ? [] : [dependencyId]
  );
  return dependencyIds.length === 0 ? undefined : dependencyIds;
}

export function capacityFor(state: SchedulerInspection): SchedulerCapacity {
  return Object.freeze({
    effectiveMaxParallel: effectiveMaxParallelFor(state),
    maxParallel: state.maxParallel,
    running: state.runningTaskIds.length
  });
}

function effectiveMaxParallelFor(state: SchedulerInspection): number {
  let effective = state.maxParallel;
  for (const scope of state.graph.scopes) {
    if (state.activeScopeIds.includes(scope.id)) effective = Math.min(effective, scope.maxParallel);
  }
  return effective;
}

function prospectiveMaxParallel(state: SchedulerInspection, task: PlannedTask): number {
  const scope = activationScopeFor(state, task);
  return scope === undefined
    ? effectiveMaxParallelFor(state)
    : Math.min(effectiveMaxParallelFor(state), scope.maxParallel);
}

function scopeForTask(state: SchedulerInspection, task: PlannedTask): PlannedTaskScope | undefined {
  return task.scopeId === undefined
    ? undefined
    : state.graph.scopes.find((scope) => scope.id === task.scopeId);
}

function settlementKindFor(
  settledTasks: SchedulerInspection["settledTasks"],
  taskId: string
): SchedulerSettlementKind | undefined {
  return settledTasks.find((task) => task.taskId === taskId)?.kind;
}

import type { PlannedTaskGraph } from "./graph.ts";
import type { SchedulerGraphSnapshot } from "../../project-definition/project-definition.ts";

export type SchedulerSettlementKind =
  | "completed"
  | "prerequisite-unsatisfied"
  | "failed"
  | "blocked"
  | "cancelled-before-start";

export type SchedulerTrigger =
  | Readonly<{ readonly kind: "execution-started" }>
  | Readonly<{ readonly kind: "admission-continued" }>
  | Readonly<{ readonly kind: "blocked-settled"; readonly taskId: string }>
  | Readonly<{
      readonly kind: "task-settled";
      readonly settlementKind: SchedulerSettlementKind;
      readonly taskId: string;
    }>
  | Readonly<{ readonly kind: "cancellation-observed" }>
  | Readonly<{ readonly kind: "cancellation-applied" }>;

export interface SchedulerSnapshot {
  readonly graph: PlannedTaskGraph;
  readonly isAbortRequested: boolean;
  readonly isCancelled: boolean;
  readonly pendingTaskIds: readonly string[];
  readonly runningMutexes: readonly string[];
  readonly runningTaskIds: readonly string[];
  readonly settledTasks: readonly Readonly<{
    readonly kind: SchedulerSettlementKind;
    readonly taskId: string;
  }>[];
  readonly activeScopeIds: readonly string[];
  readonly maxParallel: number;
}

export interface SchedulerCapacity {
  readonly effectiveMaxParallel: number;
  readonly maxParallel: number;
  readonly running: number;
}

export interface SchedulerBlockerSummary {
  readonly dependency: number;
  readonly mutex: number;
  readonly rootCapacity: boolean;
  readonly scopeCapacity: boolean;
}

/** The sole public Scheduler graph DTO; task identity is always `taskId`. */
export type { SchedulerGraphSnapshot } from "../../project-definition/project-definition.ts";

export interface SchedulerAdmissionCandidateFact {
  readonly canAdmit: boolean;
  readonly taskId: string;
}

export type SchedulerAdmissionProposal =
  | Readonly<{ readonly kind: "select"; readonly taskId: string }>
  | Readonly<{ readonly kind: "wait" }>;

export type SchedulerAdmissionHardGuard =
  | Readonly<{
      readonly canAdmit: true;
      readonly isCandidate: true;
      readonly kind: "select";
      readonly lifecycleOpen: true;
      readonly taskId: string;
    }>
  | Readonly<{ readonly kind: "wait"; readonly runningCanDrain: true }>;

export interface SchedulerDecisionContext {
  readonly blockers: SchedulerBlockerSummary;
  readonly capacity: SchedulerCapacity;
  readonly graphIdentity: SchedulerGraphSnapshot;
}

export type SchedulerDecision = SchedulerDecisionContext &
  (
    | Readonly<{
        readonly admissionPriority: number;
        readonly candidates: readonly SchedulerAdmissionCandidateFact[];
        readonly eligibleCount: number;
        readonly hardGuard: Extract<SchedulerAdmissionHardGuard, { readonly kind: "select" }>;
        readonly kind: "admit";
        readonly proposal: Extract<SchedulerAdmissionProposal, { readonly kind: "select" }>;
        readonly scopeToActivate: string | null;
        readonly taskId: string;
        readonly trigger: SchedulerTrigger;
      }>
    | Readonly<{
        readonly dependencyIds: readonly string[];
        readonly kind: "settle-blocked";
        readonly taskId: string;
        readonly trigger: SchedulerTrigger;
      }>
    | Readonly<{
        readonly candidates: readonly SchedulerAdmissionCandidateFact[];
        readonly eligibleCount: number;
        readonly hardGuard: Extract<SchedulerAdmissionHardGuard, { readonly kind: "wait" }>;
        readonly kind: "await-running";
        readonly proposal: SchedulerAdmissionProposal | null;
        readonly trigger: SchedulerTrigger;
      }>
    | Readonly<{
        readonly kind: "cancel-pending";
        readonly taskIds: readonly string[];
        readonly trigger: SchedulerTrigger;
      }>
    | Readonly<{
        readonly cancelled: boolean;
        readonly kind: "complete";
        readonly trigger: SchedulerTrigger;
      }>
  );

export function freezeDecision(decision: SchedulerDecision): SchedulerDecision {
  const trigger = freezeTrigger(decision.trigger);
  switch (decision.kind) {
    case "admit":
    case "await-running":
      return Object.freeze({ ...decision, trigger });
    case "settle-blocked":
      return Object.freeze({
        ...decision,
        dependencyIds: Object.freeze([...decision.dependencyIds]),
        trigger
      });
    case "cancel-pending":
      return Object.freeze({ ...decision, taskIds: Object.freeze([...decision.taskIds]), trigger });
    case "complete":
      return Object.freeze({ ...decision, trigger });
  }
}

function freezeTrigger(trigger: SchedulerTrigger): SchedulerTrigger {
  switch (trigger.kind) {
    case "execution-started":
    case "admission-continued":
    case "cancellation-observed":
    case "cancellation-applied":
      return Object.freeze({ kind: trigger.kind });
    case "blocked-settled":
      return Object.freeze({ kind: trigger.kind, taskId: trigger.taskId });
    case "task-settled":
      return Object.freeze({
        kind: trigger.kind,
        settlementKind: trigger.settlementKind,
        taskId: trigger.taskId
      });
  }
}

import type { AdmissionSelectionPolicy } from "./admission-selection-policy.ts";
import type { AdmissionPolicyContext } from "../../project-definition/project-definition.ts";
import { staticAdmissionSelectionPolicy } from "./admission-selection-policy.ts";
import { decideAdmission, type SchedulerDecisionCycle } from "./scheduler-admission-decision.ts";
import {
  decisionContext,
  inspectSnapshot,
  selectBlockedTask
} from "./scheduler-decision-inspection.ts";
import { freezeDecision } from "./scheduler-decision-model.ts";
import type {
  SchedulerDecision,
  SchedulerSnapshot,
  SchedulerTrigger
} from "./scheduler-decision-model.ts";

export type {
  SchedulerDecision,
  SchedulerSettlementKind,
  SchedulerSnapshot,
  SchedulerTrigger
} from "./scheduler-decision-model.ts";

/**
 * Computes the next generic task-engine action from an immutable state projection.
 * Starting work, awaiting promises, cancellation, and diagnostic output remain in
 * the imperative scheduler shell.
 */
export function decideScheduler(
  snapshot: SchedulerSnapshot,
  trigger: SchedulerTrigger,
  policy: AdmissionSelectionPolicy = staticAdmissionSelectionPolicy,
  measurement?: () => AdmissionPolicyContext["measurement"]
): SchedulerDecision {
  const state = inspectSnapshot(snapshot);
  const cycle: SchedulerDecisionCycle = Object.freeze({
    context: decisionContext(state, state.graph.schedulerGraphSnapshot),
    policy,
    state,
    ...(measurement === undefined ? {} : { measurement }),
    trigger
  });
  const terminalDecision = decideTerminalSchedulerAction(cycle, snapshot);
  if (terminalDecision !== undefined) return terminalDecision;

  const blocked = selectBlockedTask(state);
  if (blocked !== undefined) {
    return freezeDecision({
      ...cycle.context,
      dependencyIds: blocked.dependencyIds,
      kind: "settle-blocked",
      taskId: blocked.task.id,
      trigger
    });
  }

  return decideAdmission(cycle);
}

function decideTerminalSchedulerAction(
  cycle: SchedulerDecisionCycle,
  snapshot: SchedulerSnapshot
): SchedulerDecision | undefined {
  if (snapshot.isAbortRequested && !snapshot.isCancelled) {
    return freezeDecision({
      ...cycle.context,
      kind: "cancel-pending",
      taskIds: snapshot.pendingTaskIds,
      trigger: Object.freeze({ kind: "cancellation-observed" })
    });
  }
  if (cycle.state.pendingTasks.length === 0 && cycle.state.runningTaskIds.length === 0) {
    return freezeDecision({
      ...cycle.context,
      cancelled: snapshot.isCancelled,
      kind: "complete",
      trigger: cycle.trigger
    });
  }
  if (snapshot.isCancelled) {
    if (cycle.state.pendingTasks.length > 0) {
      throw new Error("cancelled scheduler state retains pending tasks");
    }
    return cancellationDrainDecision(cycle);
  }
  if (cycle.state.pendingTasks.length === 0) return runningDrainDecision(cycle);
  return undefined;
}

function cancellationDrainDecision(cycle: SchedulerDecisionCycle): SchedulerDecision {
  return awaitDrainDecision(cycle);
}

function runningDrainDecision(cycle: SchedulerDecisionCycle): SchedulerDecision {
  return awaitDrainDecision(cycle);
}

function awaitDrainDecision(cycle: SchedulerDecisionCycle): SchedulerDecision {
  return freezeDecision({
    ...cycle.context,
    candidates: Object.freeze([]),
    eligibleCount: 0,
    hardGuard: Object.freeze({ kind: "wait", runningCanDrain: true }),
    kind: "await-running",
    proposal: null,
    trigger: cycle.trigger
  });
}

import type { PlannedTask } from "./graph.ts";
import { diagnosticTags, type DiagnosticObservation } from "../diagnostic-logging/logger.ts";
import type { SchedulerDecision } from "./scheduler-decision.ts";
import { snapshotSchedulerState, type SchedulerState } from "./execution-state.ts";
import {
  canAdmit,
  capacityFor,
  inspectSnapshot,
  isRelationEligible,
  isRelationMutexEligible,
  type SchedulerInspection
} from "./scheduler-decision-inspection.ts";
import type {
  AdmissionViablePendingTask,
  SchedulerPerformanceDiagnostics,
  SchedulerPerformanceState
} from "./scheduler-performance-diagnostics.ts";
import type { AdmissionPolicyFault } from "./scheduler-admission-decision.ts";

/** Fault logging is observational and therefore excluded from Scheduler control-path timing. */
export function observeAdmissionPolicyFault<TResult>(
  state: SchedulerState<TResult>,
  fault: AdmissionPolicyFault
): void {
  observeSchedulerDiagnostic(state, {
    event: "scheduler.admission-policy-failed",
    tags: diagnosticTags("SCHEDULER", "ADMISSION_POLICY_FAILED", fault.category.toUpperCase()),
    details: Object.freeze({ category: fault.category })
  });
}

export function observeSchedulerDecision<TResult>(
  state: SchedulerState<TResult>,
  decision: SchedulerDecision,
  diagnostics: SchedulerPerformanceDiagnostics | undefined
): void {
  const observation: DiagnosticObservation = {
    event: "scheduler.decision",
    tags: schedulerDecisionTags(decision),
    details: decision
  };
  const observe = () => observeSchedulerDiagnostic(state, observation);
  if (diagnostics === undefined) observe();
  else diagnostics.observeDecision(observe);
}

/** Logger failures are observational and must not revise Scheduler lifecycle state. */
export function observeSchedulerDiagnostic<TResult>(
  state: SchedulerState<TResult>,
  observation: DiagnosticObservation
): void {
  try {
    state.diagnosticLogger?.observe(observation);
  } catch {
    // Invocation logging has its own containment; retain it for direct Scheduler seams as well.
  }
}

export function performanceState<TResult>(
  state: SchedulerState<TResult>
): SchedulerPerformanceState {
  const inspection = inspectSnapshot(snapshotSchedulerState(state));
  const admissionViablePendingTasks: AdmissionViablePendingTask[] = [];
  for (const task of inspection.pendingTasks) {
    if (!isRelationEligible(task, inspection)) continue;
    admissionViablePendingTasks.push(
      Object.freeze({
        kind: admissionViablePendingKind(task, inspection),
        taskId: task.id
      })
    );
  }
  const capacity = capacityFor(inspection);
  return Object.freeze({
    admissionViablePendingTasks: Object.freeze(admissionViablePendingTasks),
    effectiveMaxParallel: capacity.effectiveMaxParallel,
    rootMaxParallel: capacity.maxParallel,
    running: capacity.running
  });
}

function admissionViablePendingKind(
  task: PlannedTask,
  inspection: SchedulerInspection
): AdmissionViablePendingTask["kind"] {
  if (!isRelationMutexEligible(task, inspection)) return "mutex-blocked";
  return canAdmit(inspection, task) ? "admissible-pending" : "capacity-blocked";
}

function schedulerDecisionTags(decision: SchedulerDecision): readonly string[] {
  return diagnosticTags(
    "SCHEDULER",
    decision.kind.toUpperCase(),
    ...("taskId" in decision ? [`TASK:${decision.taskId}`] : [])
  );
}

import type {
  AdmissionPolicyMeasurement,
  SchedulerDecisionMeasurementCumulative,
  SchedulerMeasurementAdmission,
  SchedulerMeasurementEffect,
  SchedulerMeasurementHook,
  SchedulerRawMeasurement
} from "../../project-definition/project-definition.ts";
import { diagnosticTags, type DiagnosticLogger } from "../diagnostic-logging/logger.ts";
import type { AdmissionDelayBreakdown } from "./scheduler-performance-integrals.ts";
import { summaryFromSchedulerMeasurement } from "./scheduler-performance-summary.ts";
import { SchedulerPerformanceTiming } from "./scheduler-performance-timing.ts";
import { SchedulerPolicyMeasurement } from "./scheduler-policy-measurement.ts";

/** Explicit, enabled-only private handoff; the Scheduler never infers this from logger behavior. */
export type SchedulerPerformanceDiagnosticsInput = Readonly<{
  readonly clock: Readonly<{ now(): number }>;
  readonly declarativeFingerprint: string;
  readonly logger?: DiagnosticLogger;
}>;

type AdmissionChronology = {
  readonly admissionDelay: AdmissionDelayBreakdown;
  readonly admittedAt: number;
  settledAt: number | undefined;
};

export type AdmissionViablePendingTask = Readonly<{
  readonly kind: "admissible-pending" | "capacity-blocked" | "mutex-blocked";
  readonly taskId: string;
}>;

export type SchedulerPerformanceState = Readonly<{
  readonly admissionViablePendingTasks: readonly AdmissionViablePendingTask[];
  readonly effectiveMaxParallel: number;
  readonly rootMaxParallel: number;
  readonly running: number;
}>;

/**
 * Scheduler-owned, invocation-local lifecycle projection. Clock boundaries and
 * numeric interval accumulation remain private collaborators of this owner.
 */
export class SchedulerPerformanceDiagnostics {
  readonly #declarativeFingerprint: string;
  readonly #logger: DiagnosticLogger | undefined;
  readonly #timing: SchedulerPerformanceTiming;
  #lastSettledTaskId: string | undefined;
  #completionTailActiveTaskIds: readonly string[] = Object.freeze([]);
  readonly #admittedTaskIds = new Set<string>();
  readonly #chronologyByTaskId = new Map<string, AdmissionChronology>();
  readonly #policyMeasurement = new SchedulerPolicyMeasurement();

  public constructor(
    input: SchedulerPerformanceDiagnosticsInput,
    initial: SchedulerPerformanceState
  ) {
    this.#declarativeFingerprint = input.declarativeFingerprint;
    this.#logger = input.logger;
    this.#timing = new SchedulerPerformanceTiming(input.clock, initial);
  }

  public measureControlPath<T>(operation: () => T): T {
    return this.#timing.measureControlPath(operation);
  }

  public observeDecision(observation: () => void): void {
    this.#timing.observeDecision(observation);
  }

  /** Flushes the old state before admission changes the real Scheduler state. */
  public beforeAdmission(taskId: string, runningTaskIds: readonly string[]): void {
    this.#admittedTaskIds.add(taskId);
    this.#completionTailActiveTaskIds = Object.freeze([...runningTaskIds, taskId]);
    const boundary = this.#timing.boundary();
    if (boundary === undefined) return;
    const admissionDelay = this.#timing.takeAdmissionDelay(taskId);
    if (admissionDelay === undefined) return this.#timing.invalidate("integral-invalid");
    this.#chronologyByTaskId.set(taskId, {
      admissionDelay,
      admittedAt: boundary,
      settledAt: undefined
    });
  }

  /** Flushes the old state before blocked/cancelled changes the real Scheduler state. */
  public beforePendingSettlement(taskIds: readonly string[] = []): void {
    const lastTaskId = taskIds.at(-1);
    if (lastTaskId !== undefined) this.#lastSettledTaskId = lastTaskId;
    this.#timing.boundary();
  }

  /** Flushes the old running interval before removing the actual running Task. */
  public beforeRunningSettlement(taskId: string): void {
    this.#lastSettledTaskId = taskId;
    const boundary = this.#timing.boundary();
    if (boundary === undefined) return;
    this.#timing.closeAcceptedWait(boundary);
    const chronology = this.#chronologyByTaskId.get(taskId);
    if (chronology === undefined) return this.#timing.invalidate("integral-invalid");
    chronology.settledAt = boundary;
  }

  public beforeAcceptedWait(): void {
    this.#timing.beginAcceptedWait();
  }

  public captureState(state: SchedulerPerformanceState): void {
    this.#timing.captureState(state);
  }

  public rawMeasurement(): SchedulerRawMeasurement {
    return this.#measurement(true);
  }

  public beginSelectedPolicyAction(taskId: string): void {
    this.#policyMeasurement.beginSelected(taskId, this.#timing.snapshot().totals);
  }

  public beginWaitPolicyAction(): void {
    this.#policyMeasurement.beginWait(this.#timing.snapshot().totals);
  }

  public recordEffect(effect: SchedulerMeasurementEffect): void {
    this.#policyMeasurement.recordEffect(effect);
  }

  public policyMeasurement(): AdmissionPolicyMeasurement {
    this.#timing.boundary();
    this.#completePolicyAction();
    return this.#policyMeasurement.snapshot(this.#cumulativeMeasurement());
  }

  public completePendingActionObservation(): void {
    this.#timing.boundary();
    this.#completePolicyAction();
  }

  public admittedTaskIds(): readonly string[] {
    return Object.freeze([...this.#admittedTaskIds]);
  }

  /** Internal default terminal hook; it contains writer failure without runner special-casing. */
  public defaultSummaryHook(): SchedulerMeasurementHook | undefined {
    if (this.#logger === undefined) return undefined;
    const logger = this.#logger;
    return (context) => {
      try {
        logger.observe({
          event: "scheduler.summary",
          tags: diagnosticTags("SCHEDULER", "SUMMARY"),
          details: summaryFromSchedulerMeasurement(context.rawMeasurement)
        });
      } catch {
        // Summary writer failure is contained by this hook, not the shared runner.
      }
    };
  }

  #completePolicyAction(): void {
    const timing = this.#timing.snapshot();
    this.#policyMeasurement.complete(timing.totals, timing.timing);
  }

  #cumulativeMeasurement(): SchedulerDecisionMeasurementCumulative {
    const snapshot = this.#timing.snapshot();
    const facts = Object.freeze({
      declarativeFingerprint: this.#declarativeFingerprint,
      discrete: Object.freeze({
        acceptedWaitCount: snapshot.acceptedWaitCount,
        admittedCount: this.#admittedTaskIds.size,
        maxRunning: snapshot.maxRunning
      }),
      peaks: snapshot.peaks
    });
    if (snapshot.timing.availability === "unavailable") {
      return Object.freeze({ ...facts, timing: snapshot.timing });
    }
    return Object.freeze({
      ...facts,
      timing: snapshot.timing,
      timingFacts: Object.freeze({
        acceptedWaitMs: snapshot.acceptedWaitMs,
        effectiveCapacitySlotMs: snapshot.totals.effectiveCapacitySlotMs,
        rootCapacitySlotMs: snapshot.totals.rootCapacitySlotMs,
        taskSlotMs: snapshot.totals.taskSlotMs
      })
    });
  }

  #measurement(terminal: boolean): SchedulerRawMeasurement {
    const endedAt = this.#timing.boundary();
    if (terminal && endedAt !== undefined) this.#timing.closeAcceptedWait(endedAt);
    const snapshot = this.#timing.snapshot();
    const facts = Object.freeze({
      declarativeFingerprint: this.#declarativeFingerprint,
      discrete: Object.freeze({
        acceptedWaitCount: snapshot.acceptedWaitCount,
        admittedCount: this.#admittedTaskIds.size,
        completionTailActiveTaskIds: Object.freeze([...this.#completionTailActiveTaskIds]),
        lastSettledTaskId: this.#lastSettledTaskId ?? null,
        maxRunning: snapshot.maxRunning
      }),
      peaks: snapshot.peaks
    });
    if (snapshot.timing.availability === "unavailable") {
      return Object.freeze({ ...facts, timing: snapshot.timing });
    }
    if (endedAt === undefined)
      throw new Error("available Scheduler timing has no terminal boundary");
    return Object.freeze({
      ...facts,
      timing: snapshot.timing,
      timingFacts: Object.freeze({
        acceptedWaitMs: snapshot.acceptedWaitMs,
        admissions: Object.freeze(this.#admissionMeasurements()),
        effectiveCapacitySlotMs: snapshot.totals.effectiveCapacitySlotMs,
        endedAtMonotonicMs: endedAt,
        rootCapacitySlotMs: snapshot.totals.rootCapacitySlotMs,
        schedulerControlPathMs: snapshot.schedulerControlPathMs,
        schedulerDecisionObservationMs: snapshot.decisionObservationMs,
        startedAtMonotonicMs: snapshot.startedAtMonotonicMs ?? endedAt,
        taskSlotMs: snapshot.totals.taskSlotMs
      })
    });
  }

  #admissionMeasurements(): SchedulerMeasurementAdmission[] {
    const pendingByTaskId = new Map(
      this.#timing
        .pendingAdmissionDelays()
        .map(({ admissionDelay, taskId }) => [taskId, admissionDelay])
    );
    const taskIds = new Set([...pendingByTaskId.keys(), ...this.#chronologyByTaskId.keys()]);
    return [...taskIds]
      .map((taskId) => this.#admissionMeasurement(taskId, pendingByTaskId))
      .sort((left, right) => compareText(left.taskId, right.taskId));
  }

  #admissionMeasurement(
    taskId: string,
    pendingByTaskId: ReadonlyMap<string, AdmissionDelayBreakdown>
  ): SchedulerMeasurementAdmission {
    const chronology = this.#chronologyByTaskId.get(taskId);
    const admissionDelay = chronology?.admissionDelay ?? pendingByTaskId.get(taskId);
    if (admissionDelay === undefined)
      throw new Error(`missing admission measurement for ${taskId}`);
    return Object.freeze({
      admissionDelay,
      admittedAtMonotonicMs: chronology?.admittedAt ?? null,
      settledAtMonotonicMs: chronology?.settledAt ?? null,
      taskId
    });
  }
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import type { SchedulerMeasurementIntervalContribution } from "../../project-definition/project-definition.ts";
import type {
  AdmissionViablePendingTask,
  SchedulerPerformanceState
} from "./scheduler-performance-diagnostics.ts";

export type AdmissionDelayBreakdown = Readonly<{
  readonly admissiblePendingMs: number;
  readonly capacityBlockedMs: number;
  readonly mutexBlockedMs: number;
}>;

type MutableAdmissionDelayBreakdown = {
  admissiblePendingMs: number;
  capacityBlockedMs: number;
  mutexBlockedMs: number;
};

export type SchedulerPerformancePeaks = Readonly<{
  readonly admissionViablePendingTaskCount: number;
  readonly admissiblePendingTaskCount: number;
  readonly capacityBlockedTaskCount: number;
  readonly mutexBlockedTaskCount: number;
}>;

/** Accumulates interval-weighted capacity and admission-delay measurements. */
export class SchedulerPerformanceIntegrals {
  #taskSlotMs = 0;
  #rootCapacitySlotMs = 0;
  #effectiveCapacitySlotMs = 0;
  #mutexBlockedTaskMs = 0;
  #capacityBlockedTaskMs = 0;
  #admissiblePendingTaskMs = 0;
  #peakAdmissionViablePendingTaskCount = 0;
  #peakMutexBlockedTaskCount = 0;
  #peakCapacityBlockedTaskCount = 0;
  #peakAdmissiblePendingTaskCount = 0;
  readonly #admissionDelayByTaskId = new Map<string, MutableAdmissionDelayBreakdown>();

  public installPendingProjection(
    pendingTasks: readonly AdmissionViablePendingTask[],
    timingAvailable: boolean
  ): void {
    this.#peakAdmissionViablePendingTaskCount = Math.max(
      this.#peakAdmissionViablePendingTaskCount,
      pendingTasks.length
    );
    this.#peakMutexBlockedTaskCount = Math.max(
      this.#peakMutexBlockedTaskCount,
      pendingCount(pendingTasks, "mutex-blocked")
    );
    this.#peakCapacityBlockedTaskCount = Math.max(
      this.#peakCapacityBlockedTaskCount,
      pendingCount(pendingTasks, "capacity-blocked")
    );
    this.#peakAdmissiblePendingTaskCount = Math.max(
      this.#peakAdmissiblePendingTaskCount,
      pendingCount(pendingTasks, "admissible-pending")
    );
    if (!timingAvailable) return;
    for (const pendingTask of pendingTasks) {
      if (this.#admissionDelayByTaskId.has(pendingTask.taskId)) continue;
      this.#admissionDelayByTaskId.set(pendingTask.taskId, {
        admissiblePendingMs: 0,
        capacityBlockedMs: 0,
        mutexBlockedMs: 0
      });
    }
  }

  /** Returns false when an interval cannot be represented as finite non-negative totals. */
  public addInterval(elapsedMs: number, state: SchedulerPerformanceState): boolean {
    const contribution = intervalContribution(elapsedMs, state);
    if (contribution === undefined) return false;
    this.#taskSlotMs += contribution.taskSlotMs;
    this.#rootCapacitySlotMs += contribution.rootCapacitySlotMs;
    this.#effectiveCapacitySlotMs += contribution.effectiveCapacitySlotMs;
    this.#mutexBlockedTaskMs += contribution.mutexBlockedTaskMs;
    this.#capacityBlockedTaskMs += contribution.capacityBlockedTaskMs;
    this.#admissiblePendingTaskMs += contribution.admissiblePendingTaskMs;
    if (!finiteContribution(this.totals())) return false;
    return this.#addAdmissionDelay(elapsedMs, state.admissionViablePendingTasks);
  }

  public takeAdmissionDelay(taskId: string): AdmissionDelayBreakdown | undefined {
    const delay = this.#admissionDelayByTaskId.get(taskId);
    if (delay === undefined) return undefined;
    this.#admissionDelayByTaskId.delete(taskId);
    return Object.freeze({ ...delay });
  }

  public pendingAdmissionDelays(): readonly Readonly<{
    readonly admissionDelay: AdmissionDelayBreakdown;
    readonly taskId: string;
  }>[] {
    return Object.freeze(
      [...this.#admissionDelayByTaskId].map(([taskId, admissionDelay]) =>
        Object.freeze({ admissionDelay: Object.freeze({ ...admissionDelay }), taskId })
      )
    );
  }

  public peaks(): SchedulerPerformancePeaks {
    return Object.freeze({
      admissionViablePendingTaskCount: this.#peakAdmissionViablePendingTaskCount,
      admissiblePendingTaskCount: this.#peakAdmissiblePendingTaskCount,
      capacityBlockedTaskCount: this.#peakCapacityBlockedTaskCount,
      mutexBlockedTaskCount: this.#peakMutexBlockedTaskCount
    });
  }

  public totals(): SchedulerMeasurementIntervalContribution {
    return Object.freeze({
      admissiblePendingTaskMs: this.#admissiblePendingTaskMs,
      acceptedWaitMs: 0,
      capacityBlockedTaskMs: this.#capacityBlockedTaskMs,
      effectiveCapacitySlotMs: this.#effectiveCapacitySlotMs,
      mutexBlockedTaskMs: this.#mutexBlockedTaskMs,
      rootCapacitySlotMs: this.#rootCapacitySlotMs,
      taskSlotMs: this.#taskSlotMs
    });
  }

  #addAdmissionDelay(
    elapsedMs: number,
    pendingTasks: readonly AdmissionViablePendingTask[]
  ): boolean {
    for (const pendingTask of pendingTasks) {
      const delay = this.#admissionDelayByTaskId.get(pendingTask.taskId);
      if (delay === undefined) continue;
      addDelay(delay, pendingTask.kind, elapsedMs);
      if (!finiteAdmissionDelay(delay)) return false;
    }
    return true;
  }
}

function intervalContribution(
  elapsedMs: number,
  state: SchedulerPerformanceState
): SchedulerMeasurementIntervalContribution | undefined {
  const contribution = Object.freeze({
    admissiblePendingTaskMs:
      elapsedMs * pendingCount(state.admissionViablePendingTasks, "admissible-pending"),
    acceptedWaitMs: 0,
    capacityBlockedTaskMs:
      elapsedMs * pendingCount(state.admissionViablePendingTasks, "capacity-blocked"),
    effectiveCapacitySlotMs: elapsedMs * state.effectiveMaxParallel,
    mutexBlockedTaskMs:
      elapsedMs * pendingCount(state.admissionViablePendingTasks, "mutex-blocked"),
    rootCapacitySlotMs: elapsedMs * state.rootMaxParallel,
    taskSlotMs: elapsedMs * state.running
  });
  return finiteContribution(contribution) ? contribution : undefined;
}

function finiteContribution(contribution: SchedulerMeasurementIntervalContribution): boolean {
  return Object.values(contribution).every((value) => Number.isFinite(value) && value >= 0);
}

function addDelay(
  delay: MutableAdmissionDelayBreakdown,
  kind: AdmissionViablePendingTask["kind"],
  elapsedMs: number
): void {
  if (kind === "mutex-blocked") delay.mutexBlockedMs += elapsedMs;
  if (kind === "capacity-blocked") delay.capacityBlockedMs += elapsedMs;
  if (kind === "admissible-pending") delay.admissiblePendingMs += elapsedMs;
}

function finiteAdmissionDelay(delay: MutableAdmissionDelayBreakdown): boolean {
  return Object.values(delay).every((value) => Number.isFinite(value) && value >= 0);
}

function pendingCount(
  pendingTasks: readonly AdmissionViablePendingTask[],
  kind: AdmissionViablePendingTask["kind"]
): number {
  return pendingTasks.filter((task) => task.kind === kind).length;
}

import type {
  SchedulerMeasurementAdmission,
  SchedulerMeasurementTimingFacts,
  SchedulerRawMeasurement
} from "../../project-definition/project-definition.ts";

const TOP_TASK_LIMIT = 3;

type AdmissionDelaySummary = Readonly<{
  readonly admissiblePendingMs: number;
  readonly admissionDelayMs: number;
  readonly capacityBlockedMs: number;
  readonly mutexBlockedMs: number;
  readonly taskActiveMs: number;
  readonly taskId: string;
}>;

/** Projects raw Scheduler measurement into the bounded diagnostic summary. */
export function summaryFromSchedulerMeasurement(
  raw: SchedulerRawMeasurement
): Readonly<Record<string, unknown>> {
  const alwaysAvailable = alwaysAvailableSummary(raw);
  if (!hasTimingFacts(raw)) return Object.freeze({ ...alwaysAvailable, timing: raw.timing });

  const timingFacts = raw.timingFacts;
  const delayTotals = admissionDelayTotals(timingFacts.admissions);
  const lastAdmissionAt = latestAdmissionAt(timingFacts.admissions);
  return Object.freeze({
    ...alwaysAvailable,
    timing: raw.timing,
    schedulerControlPathMs: timingFacts.schedulerControlPathMs,
    schedulerDecisionObservationMs: timingFacts.schedulerDecisionObservationMs,
    schedulerSpanMs: timingFacts.endedAtMonotonicMs - timingFacts.startedAtMonotonicMs,
    taskSlotMs: timingFacts.taskSlotMs,
    rootCapacitySlotMs: timingFacts.rootCapacitySlotMs,
    effectiveCapacitySlotMs: timingFacts.effectiveCapacitySlotMs,
    rootSlotUtilization: ratio(timingFacts.taskSlotMs, timingFacts.rootCapacitySlotMs),
    effectiveSlotUtilization: ratio(timingFacts.taskSlotMs, timingFacts.effectiveCapacitySlotMs),
    acceptedWaitMs: timingFacts.acceptedWaitMs,
    ...delayTotals,
    topAdmissionDelays: topAdmissionDelays(timingFacts.admissions),
    completionTailMs:
      lastAdmissionAt === null ? null : timingFacts.endedAtMonotonicMs - lastAdmissionAt,
    topCompletionTailContributors: topCompletionTailContributors(
      raw.discrete.completionTailActiveTaskIds,
      timingFacts.admissions,
      lastAdmissionAt
    )
  });
}

function alwaysAvailableSummary(raw: SchedulerRawMeasurement): Readonly<Record<string, unknown>> {
  return Object.freeze({
    declarativeFingerprint: raw.declarativeFingerprint,
    discrete: Object.freeze({
      acceptedWaitCount: raw.discrete.acceptedWaitCount,
      admittedCount: raw.discrete.admittedCount,
      completionTailActiveTaskCount: raw.discrete.completionTailActiveTaskIds.length,
      lastSettledTaskId: raw.discrete.lastSettledTaskId,
      maxRunning: raw.discrete.maxRunning
    }),
    peakAdmissionViablePendingTaskCount: raw.peaks.admissionViablePendingTaskCount,
    peakMutexBlockedTaskCount: raw.peaks.mutexBlockedTaskCount,
    peakCapacityBlockedTaskCount: raw.peaks.capacityBlockedTaskCount,
    peakAdmissiblePendingTaskCount: raw.peaks.admissiblePendingTaskCount
  });
}

function admissionDelayTotals(admissions: readonly SchedulerMeasurementAdmission[]): Readonly<{
  readonly admissiblePendingTaskMs: number;
  readonly admissionViablePendingTaskMs: number;
  readonly capacityBlockedTaskMs: number;
  readonly mutexBlockedTaskMs: number;
}> {
  let admissiblePendingTaskMs = 0;
  let capacityBlockedTaskMs = 0;
  let mutexBlockedTaskMs = 0;
  for (const admission of admissions) {
    admissiblePendingTaskMs += admission.admissionDelay.admissiblePendingMs;
    capacityBlockedTaskMs += admission.admissionDelay.capacityBlockedMs;
    mutexBlockedTaskMs += admission.admissionDelay.mutexBlockedMs;
  }
  return Object.freeze({
    admissiblePendingTaskMs,
    admissionViablePendingTaskMs:
      admissiblePendingTaskMs + capacityBlockedTaskMs + mutexBlockedTaskMs,
    capacityBlockedTaskMs,
    mutexBlockedTaskMs
  });
}

function topAdmissionDelays(
  admissions: readonly SchedulerMeasurementAdmission[]
): readonly AdmissionDelaySummary[] {
  return Object.freeze(
    admissions
      .flatMap((admission) => {
        if (admission.admittedAtMonotonicMs === null || admission.settledAtMonotonicMs === null) {
          return [];
        }
        return [
          Object.freeze({
            admissiblePendingMs: admission.admissionDelay.admissiblePendingMs,
            admissionDelayMs: admissionDelayMsFor(admission.admissionDelay),
            capacityBlockedMs: admission.admissionDelay.capacityBlockedMs,
            mutexBlockedMs: admission.admissionDelay.mutexBlockedMs,
            taskActiveMs: admission.settledAtMonotonicMs - admission.admittedAtMonotonicMs,
            taskId: admission.taskId
          })
        ];
      })
      .sort(
        (left, right) =>
          right.admissionDelayMs - left.admissionDelayMs || compareText(left.taskId, right.taskId)
      )
      .slice(0, TOP_TASK_LIMIT)
  );
}

function latestAdmissionAt(admissions: readonly SchedulerMeasurementAdmission[]): number | null {
  let latest: number | null = null;
  for (const admission of admissions) {
    if (admission.admittedAtMonotonicMs === null) continue;
    latest = Math.max(latest ?? admission.admittedAtMonotonicMs, admission.admittedAtMonotonicMs);
  }
  return latest;
}

function topCompletionTailContributors(
  activeTaskIds: readonly string[],
  admissions: readonly SchedulerMeasurementAdmission[],
  lastAdmissionAt: number | null
): readonly Readonly<{ readonly settledAfterLastAdmissionMs: number; readonly taskId: string }>[] {
  if (lastAdmissionAt === null) return Object.freeze([]);
  const admittedByTaskId = new Map(admissions.map((admission) => [admission.taskId, admission]));
  return Object.freeze(
    activeTaskIds
      .flatMap((taskId) => {
        const settledAt = admittedByTaskId.get(taskId)?.settledAtMonotonicMs;
        return settledAt === undefined || settledAt === null
          ? []
          : [Object.freeze({ settledAfterLastAdmissionMs: settledAt - lastAdmissionAt, taskId })];
      })
      .sort(
        (left, right) =>
          right.settledAfterLastAdmissionMs - left.settledAfterLastAdmissionMs ||
          compareText(left.taskId, right.taskId)
      )
      .slice(0, TOP_TASK_LIMIT)
  );
}

function hasTimingFacts(raw: SchedulerRawMeasurement): raw is SchedulerRawMeasurement &
  Readonly<{
    readonly timing: Readonly<{ readonly availability: "available" }>;
    readonly timingFacts: SchedulerMeasurementTimingFacts;
  }> {
  return raw.timing.availability === "available";
}

function ratio(numerator: number, denominator: number): number | null {
  if (denominator === 0) return null;
  const value = numerator / denominator;
  return Number.isFinite(value) && value >= 0 && value <= 1 ? value : null;
}

function admissionDelayMsFor(breakdown: SchedulerMeasurementAdmission["admissionDelay"]): number {
  return breakdown.mutexBlockedMs + breakdown.capacityBlockedMs + breakdown.admissiblePendingMs;
}

function compareText(left: string, right: string): number {
  if (left < right) return -1;
  if (left > right) return 1;
  return 0;
}

import type {
  SchedulerMeasurementIntervalContribution,
  SchedulerMeasurementTiming,
  SchedulerMeasurementTimingUnavailableReason
} from "../../project-definition/project-definition.ts";
import type { SchedulerPerformanceState } from "./scheduler-performance-diagnostics.ts";
import {
  SchedulerPerformanceIntegrals,
  type AdmissionDelayBreakdown,
  type SchedulerPerformancePeaks
} from "./scheduler-performance-integrals.ts";

export type SchedulerPerformanceTimingSnapshot = Readonly<{
  readonly acceptedWaitCount: number;
  readonly acceptedWaitMs: number;
  readonly decisionObservationMs: number;
  readonly maxRunning: number;
  readonly peaks: SchedulerPerformancePeaks;
  readonly schedulerControlPathMs: number;
  readonly startedAtMonotonicMs: number | undefined;
  readonly timing: SchedulerMeasurementTiming;
  readonly totals: SchedulerMeasurementIntervalContribution;
}>;

/** Owns monotonic clock boundaries and delegates numeric interval accumulation. */
export class SchedulerPerformanceTiming {
  readonly #clock: Readonly<{ now(): number }>;
  readonly #integrals = new SchedulerPerformanceIntegrals();
  #lastBoundaryAt: number | undefined;
  #startedAt: number | undefined;
  #lastState: SchedulerPerformanceState;
  #timing: SchedulerMeasurementTiming = Object.freeze({ availability: "available" });
  #controlPathMs = 0;
  #decisionObservationMs = 0;
  #maxRunning: number;
  #acceptedWaitStartedAt: number | undefined;
  #acceptedWaitMs = 0;
  #acceptedWaitCount = 0;

  public constructor(clock: Readonly<{ now(): number }>, initial: SchedulerPerformanceState) {
    this.#clock = clock;
    this.#lastState = initial;
    this.#maxRunning = initial.running;
    this.#integrals.installPendingProjection(initial.admissionViablePendingTasks, true);
    const boundary = this.#sample();
    if (boundary !== undefined) {
      this.#lastBoundaryAt = boundary;
      this.#startedAt = boundary;
    }
  }

  /** Accounts a synchronous shell operation, never an await or author callback. */
  public measureControlPath<T>(operation: () => T): T {
    const startedAt = this.#sample();
    try {
      return operation();
    } finally {
      this.#addTiming("control", startedAt, this.#sample());
    }
  }

  /** Keeps decision writer work separate from the shell control-path projection. */
  public observeDecision(observation: () => void): void {
    const startedAt = this.#sample();
    try {
      observation();
    } catch {
      // Diagnostic writers are observational; a direct test seam must preserve that containment too.
    }
    this.#addTiming("decision-observation", startedAt, this.#sample());
  }

  public boundary(): number | undefined {
    const now = this.#sample();
    if (now === undefined) return undefined;
    if (this.#lastBoundaryAt !== undefined) this.#addElapsed(now - this.#lastBoundaryAt);
    this.#lastBoundaryAt = now;
    return this.#timing.availability === "available" ? now : undefined;
  }

  public beginAcceptedWait(): void {
    this.#acceptedWaitCount += 1;
    const boundary = this.boundary();
    if (boundary !== undefined && this.#acceptedWaitStartedAt === undefined) {
      this.#acceptedWaitStartedAt = boundary;
    }
  }

  public closeAcceptedWait(boundary: number): void {
    if (this.#acceptedWaitStartedAt === undefined) return;
    const elapsedMs = boundary - this.#acceptedWaitStartedAt;
    if (!validElapsed(elapsedMs)) this.#markUnavailable("interval-invalid");
    else this.#acceptedWaitMs += elapsedMs;
    if (!Number.isFinite(this.#acceptedWaitMs)) this.#markUnavailable("integral-invalid");
    this.#acceptedWaitStartedAt = undefined;
  }

  public captureState(state: SchedulerPerformanceState): void {
    this.#lastState = state;
    this.#maxRunning = Math.max(this.#maxRunning, state.running);
    this.#integrals.installPendingProjection(
      state.admissionViablePendingTasks,
      this.#timing.availability === "available"
    );
  }

  public takeAdmissionDelay(taskId: string): AdmissionDelayBreakdown | undefined {
    return this.#integrals.takeAdmissionDelay(taskId);
  }

  public pendingAdmissionDelays(): ReturnType<
    SchedulerPerformanceIntegrals["pendingAdmissionDelays"]
  > {
    return this.#integrals.pendingAdmissionDelays();
  }

  public snapshot(): SchedulerPerformanceTimingSnapshot {
    const integralTotals = this.#integrals.totals();
    return Object.freeze({
      acceptedWaitCount: this.#acceptedWaitCount,
      acceptedWaitMs: this.#acceptedWaitMs,
      decisionObservationMs: this.#decisionObservationMs,
      maxRunning: this.#maxRunning,
      peaks: this.#integrals.peaks(),
      schedulerControlPathMs: this.#controlPathMs,
      startedAtMonotonicMs: this.#startedAt,
      timing: this.#timing,
      totals: Object.freeze({ ...integralTotals, acceptedWaitMs: this.#acceptedWaitMs })
    });
  }

  public invalidate(reason: SchedulerMeasurementTimingUnavailableReason): void {
    this.#markUnavailable(reason);
  }

  #sample(): number | undefined {
    if (this.#timing.availability === "unavailable") return undefined;
    try {
      const now = this.#clock.now();
      if (!Number.isFinite(now)) return this.#unavailable("clock-non-finite");
      if (this.#lastBoundaryAt !== undefined && now < this.#lastBoundaryAt) {
        return this.#unavailable("clock-backward");
      }
      return now;
    } catch {
      return this.#unavailable("clock-threw");
    }
  }

  #addTiming(
    kind: "control" | "decision-observation",
    startedAt: number | undefined,
    endedAt: number | undefined
  ): void {
    if (startedAt === undefined || endedAt === undefined) return;
    const elapsedMs = endedAt - startedAt;
    if (!validElapsed(elapsedMs)) return this.#markUnavailable("interval-invalid");
    if (kind === "control") this.#controlPathMs += elapsedMs;
    else this.#decisionObservationMs += elapsedMs;
    if (!Number.isFinite(this.#controlPathMs) || !Number.isFinite(this.#decisionObservationMs)) {
      this.#markUnavailable("integral-invalid");
    }
  }

  #addElapsed(elapsedMs: number): void {
    if (!validElapsed(elapsedMs)) {
      this.#markUnavailable(elapsedMs < 0 ? "clock-backward" : "interval-invalid");
      return;
    }
    if (this.#timing.availability !== "available") return;
    if (!this.#integrals.addInterval(elapsedMs, this.#lastState)) {
      this.#markUnavailable("integral-invalid");
    }
  }

  #unavailable(reason: SchedulerMeasurementTimingUnavailableReason): undefined {
    this.#markUnavailable(reason);
    return undefined;
  }

  #markUnavailable(reason: SchedulerMeasurementTimingUnavailableReason): void {
    if (this.#timing.availability === "available") {
      this.#timing = Object.freeze({ availability: "unavailable", reason });
    }
  }
}

function validElapsed(elapsedMs: number): boolean {
  return Number.isFinite(elapsedMs) && elapsedMs >= 0;
}

import type {
  AdmissionPolicyMeasurement,
  SchedulerDecisionMeasurementCumulative,
  SchedulerMeasurementActionObservation,
  SchedulerMeasurementEffect,
  SchedulerMeasurementIntervalContribution,
  SchedulerMeasurementTiming
} from "../../project-definition/project-definition.ts";

type AcceptedPolicyAction =
  | Readonly<{ readonly kind: "select"; readonly taskId: string }>
  | Readonly<{ readonly kind: "wait"; readonly taskId: null }>;

type PendingPolicyAction = AcceptedPolicyAction & {
  readonly baseline: SchedulerMeasurementIntervalContribution;
  readonly effects: SchedulerMeasurementEffect[];
  readonly sequence: number;
};

/** Owns the immutable prefix of observations formed after accepted custom-policy actions. */
export class SchedulerPolicyMeasurement {
  #pendingAction: PendingPolicyAction | undefined;
  #actionSequence = 0;
  readonly #actionObservations: SchedulerMeasurementActionObservation[] = [];

  public beginSelected(taskId: string, baseline: SchedulerMeasurementIntervalContribution): void {
    this.#begin(Object.freeze({ kind: "select", taskId }), baseline);
  }

  public beginWait(baseline: SchedulerMeasurementIntervalContribution): void {
    this.#begin(Object.freeze({ kind: "wait", taskId: null }), baseline);
  }

  public recordEffect(effect: SchedulerMeasurementEffect): void {
    this.#pendingAction?.effects.push(Object.freeze({ ...effect }));
  }

  public complete(
    totals: SchedulerMeasurementIntervalContribution,
    timing: SchedulerMeasurementTiming
  ): void {
    const action = this.#pendingAction;
    if (action === undefined) return;
    this.#pendingAction = undefined;
    const interval =
      timing.availability === "available"
        ? Object.freeze({
            availability: "available" as const,
            contribution: subtractIntervalContribution(totals, action.baseline)
          })
        : Object.freeze({ availability: "unavailable" as const, reason: timing.reason });
    this.#actionObservations.push(completedObservation(action, interval));
  }

  public snapshot(cumulative: SchedulerDecisionMeasurementCumulative): AdmissionPolicyMeasurement {
    const endCount = this.#actionObservations.length;
    const measurementAt = Object.freeze((index: number) => this.#measurementAt(index, endCount));
    return Object.freeze({ cumulative, measurementAt, measurementCount: endCount });
  }

  #begin(action: AcceptedPolicyAction, baseline: SchedulerMeasurementIntervalContribution): void {
    if (this.#pendingAction !== undefined) {
      throw new Error("previous policy action was not observed before the next action");
    }
    const sequence = ++this.#actionSequence;
    this.#pendingAction = Object.assign({ baseline, effects: [], sequence }, action);
  }

  #measurementAt(
    index: number,
    endCount: number
  ): SchedulerMeasurementActionObservation | undefined {
    if (!Number.isSafeInteger(index) || index < 0 || index >= endCount) return undefined;
    return this.#actionObservations[index];
  }
}

function completedObservation(
  action: PendingPolicyAction,
  interval: SchedulerMeasurementActionObservation["interval"]
): SchedulerMeasurementActionObservation {
  const facts = {
    effects: Object.freeze([...action.effects]),
    interval,
    sequence: action.sequence
  };
  return action.kind === "select"
    ? Object.freeze({ ...facts, kind: "select", taskId: action.taskId })
    : Object.freeze({ ...facts, kind: "wait", taskId: null });
}

function subtractIntervalContribution(
  current: SchedulerMeasurementIntervalContribution,
  prior: SchedulerMeasurementIntervalContribution
): SchedulerMeasurementIntervalContribution {
  return Object.freeze({
    admissiblePendingTaskMs: current.admissiblePendingTaskMs - prior.admissiblePendingTaskMs,
    acceptedWaitMs: current.acceptedWaitMs - prior.acceptedWaitMs,
    capacityBlockedTaskMs: current.capacityBlockedTaskMs - prior.capacityBlockedTaskMs,
    effectiveCapacitySlotMs: current.effectiveCapacitySlotMs - prior.effectiveCapacitySlotMs,
    mutexBlockedTaskMs: current.mutexBlockedTaskMs - prior.mutexBlockedTaskMs,
    rootCapacitySlotMs: current.rootCapacitySlotMs - prior.rootCapacitySlotMs,
    taskSlotMs: current.taskSlotMs - prior.taskSlotMs
  });
}

import type { PlannedTask } from "./graph.ts";
import {
  cancelPendingTasks,
  recordSettlement,
  type RunningTaskCompletion,
  type RunTaskGraphOptions,
  type SchedulerState,
  type TaskGraphRun,
  type TaskSettlement
} from "./execution-state.ts";
import type { SchedulerDecision } from "./scheduler-decision.ts";
import type { AdmissionPolicyFault } from "./scheduler-admission-decision.ts";

export function applyAdmissionPolicyFault<TResult>(
  state: SchedulerState<TResult>,
  fault: AdmissionPolicyFault
): void {
  if (state.admissionPolicyFault !== undefined) {
    throw new Error("scheduler received more than one admission policy fault");
  }
  state.admissionPolicyFault = fault.category;
  cancelPendingTasks(state);
}

export function applyAdmission<TResult>(
  state: SchedulerState<TResult>,
  decision: Extract<SchedulerDecision, { readonly kind: "admit" }>
): void {
  const task = takePendingTask(state, decision.taskId, "admission");
  for (const mutex of task.mutex) state.runningMutexes.add(mutex);
  activateScope(state, decision.scopeToActivate);

  const completion = Promise.resolve()
    .then(() => state.execute(task, Object.freeze({ signal: state.signal })))
    .then((value) => completedTaskCompletion(task.id, value, state.isPrerequisiteSatisfied))
    .catch((error: unknown) => failedTaskCompletion<TResult>(task.id, error));
  state.runningById.set(task.id, { task, completion });
}

export function applyBlockedSettlement<TResult>(
  state: SchedulerState<TResult>,
  decision: Extract<SchedulerDecision, { readonly kind: "settle-blocked" }>
): void {
  const task = takePendingTask(state, decision.taskId, "blocked settlement");
  recordSettlement(
    state,
    task,
    Object.freeze({ kind: "blocked", dependencyIds: decision.dependencyIds })
  );
  state.onTaskBlocked?.(task, decision.dependencyIds);
}

export function applyCancellation<TResult>(
  state: SchedulerState<TResult>,
  decision: Extract<SchedulerDecision, { readonly kind: "cancel-pending" }>
): void {
  const pendingTaskIds = state.pending.map((task) => task.id);
  if (!sameTaskIds(pendingTaskIds, decision.taskIds)) {
    throw new Error("scheduler cancellation decision no longer matches pending tasks");
  }
  cancelPendingTasks(state);
}

export async function nextRunningSettlement<TResult>(
  state: SchedulerState<TResult>
): Promise<RunningTaskCompletion<TResult>> {
  if (state.runningById.size === 0) {
    throw new Error("scheduler cannot await a task when no task is running");
  }
  return Promise.race([...state.runningById.values()].map((running) => running.completion));
}

export function settleRunningTask<TResult>(
  state: SchedulerState<TResult>,
  result: RunningTaskCompletion<TResult>
): void {
  const running = state.runningById.get(result.taskId);
  if (running === undefined) throw new Error(`task ${result.taskId} settled without admission`);
  state.runningById.delete(result.taskId);
  for (const mutex of running.task.mutex) state.runningMutexes.delete(mutex);
  recordSettlement(state, running.task, result.settlement);
}

export function buildTaskGraphRun<TResult>(state: SchedulerState<TResult>): TaskGraphRun<TResult> {
  return Object.freeze({
    admissionPolicyFault: state.admissionPolicyFault,
    cancelled: state.isCancelled,
    settlements: Object.freeze(
      state.graph.tasks.map((task) => {
        const settlement = state.settlementsByTaskId.get(task.id);
        if (settlement === undefined) throw new Error(`task ${task.id} was not settled`);
        return Object.freeze({ task, settlement });
      })
    )
  });
}

function activateScope<TResult>(state: SchedulerState<TResult>, scopeId: string | null): void {
  if (scopeId === null) return;
  const scope = state.scopesById.get(scopeId);
  if (scope === undefined) {
    throw new Error(`scheduler admission references unknown scope ${scopeId}`);
  }
  scope.isActive = true;
}

function takePendingTask<TResult>(
  state: SchedulerState<TResult>,
  taskId: string,
  action: string
): PlannedTask {
  const index = state.pending.findIndex((task) => task.id === taskId);
  if (index < 0) throw new Error(`task ${taskId} is not pending for ${action}`);
  const [task] = state.pending.splice(index, 1);
  if (task === undefined) throw new Error(`task ${taskId} disappeared during ${action}`);
  return task;
}

function completedTaskCompletion<TResult>(
  taskId: string,
  value: TResult,
  isPrerequisiteSatisfied: RunTaskGraphOptions<TResult>["isPrerequisiteSatisfied"]
): RunningTaskCompletion<TResult> {
  const settlement: TaskSettlement<TResult> =
    isPrerequisiteSatisfied?.(value) === false
      ? { kind: "prerequisite-unsatisfied", value }
      : { kind: "completed", value };
  return Object.freeze({ taskId, settlement: Object.freeze(settlement) });
}

function failedTaskCompletion<TResult>(
  taskId: string,
  error: unknown
): RunningTaskCompletion<TResult> {
  const settlement: TaskSettlement<TResult> = { kind: "failed", error };
  return Object.freeze({ taskId, settlement: Object.freeze(settlement) });
}

function sameTaskIds(left: readonly string[], right: readonly string[]): boolean {
  return left.length === right.length && left.every((taskId, index) => taskId === right[index]);
}

import type {
  SchedulerMeasurementContext,
  SchedulerMeasurementHook,
  SchedulerRawMeasurement
} from "../../project-definition/project-definition.ts";
import { diagnosticTags } from "../diagnostic-logging/logger.ts";
import type { RunTaskGraphOptions, SchedulerState } from "./execution-state.ts";
import type { SchedulerPerformanceDiagnostics } from "./scheduler-performance-diagnostics.ts";
import { observeSchedulerDiagnostic } from "./scheduler-observation.ts";

/** Delivers the terminal measurement to the internal summary and caller hooks exactly once. */
export async function observeTerminalMeasurement<TResult>(
  input: Readonly<{
    readonly diagnostics: SchedulerPerformanceDiagnostics;
    readonly options: RunTaskGraphOptions<TResult>;
    readonly state: SchedulerState<TResult>;
  }>
): Promise<void> {
  input.diagnostics.completePendingActionObservation();
  const context = measurementContext(
    input.state,
    input.diagnostics.admittedTaskIds(),
    input.diagnostics.rawMeasurement()
  );
  const callerHooks = input.options.measurementHooks ?? [];
  let callerHookFailed = false;
  const callerFailure = () => {
    callerHookFailed = true;
    observeSchedulerDiagnostic(input.state, {
      event: "scheduler.measurement-hook-failed",
      tags: diagnosticTags("SCHEDULER", "MEASUREMENT_HOOK_FAILED"),
      details: Object.freeze({})
    });
    try {
      input.options.onMeasurementHookFailure?.();
    } catch {
      // A failure-reporting seam cannot revise terminal Scheduler facts either.
    }
  };
  const defaultHook = input.diagnostics.defaultSummaryHook();
  const deliveries: readonly TerminalMeasurementDelivery[] = Object.freeze([
    ...(defaultHook === undefined
      ? []
      : [Object.freeze({ hook: defaultHook, onFailure: () => undefined })]),
    ...callerHooks.map((hook) => Object.freeze({ hook, onFailure: callerFailure }))
  ]);
  await deliverTerminalMeasurementHooks(deliveries, context);
  if (callerHooks.length > 0 && !callerHookFailed) {
    try {
      input.options.onMeasurementHooksSettled?.();
    } catch {
      // A success-reporting seam cannot revise terminal Scheduler facts either.
    }
  }
}

type TerminalMeasurementDelivery = Readonly<{
  readonly hook: SchedulerMeasurementHook;
  readonly onFailure: () => void;
}>;

async function deliverTerminalMeasurementHooks(
  deliveries: readonly TerminalMeasurementDelivery[],
  context: SchedulerMeasurementContext
): Promise<void> {
  for (const delivery of deliveries) {
    try {
      await delivery.hook(context);
    } catch {
      delivery.onFailure();
    }
  }
}

function measurementContext<TResult>(
  state: SchedulerState<TResult>,
  admittedTaskIds: readonly string[],
  rawMeasurement: SchedulerRawMeasurement
): SchedulerMeasurementContext {
  return Object.freeze({
    graph: state.graph.schedulerGraphSnapshot,
    execution: Object.freeze({
      admittedTaskIds: Object.freeze([...admittedTaskIds]),
      settledTasks: Object.freeze(
        state.graph.tasks.map((task) => {
          const settlement = state.settlementsByTaskId.get(task.id);
          if (settlement === undefined) throw new Error(`task ${task.id} was not settled`);
          return Object.freeze({ kind: settlement.kind, taskId: task.id });
        })
      )
    }),
    rawMeasurement
  });
}

import type { AdmissionPolicyContext } from "../../project-definition/project-definition.ts";
import { prepareTaskGraph } from "./graph.ts";
import {
  decideScheduler,
  type SchedulerDecision,
  type SchedulerTrigger
} from "./scheduler-decision.ts";
import {
  createSchedulerState,
  snapshotSchedulerState,
  type RunTaskGraphOptions,
  type TaskGraphRun
} from "./execution-state.ts";
export type {
  RunTaskGraphOptions,
  SettledTask,
  TaskExecutionContext,
  TaskGraphRun,
  TaskSettlement
} from "./execution-state.ts";
import { AdmissionPolicyFault } from "./scheduler-admission-decision.ts";
import { SchedulerPerformanceDiagnostics } from "./scheduler-performance-diagnostics.ts";
import {
  observeAdmissionPolicyFault,
  observeSchedulerDecision,
  performanceState
} from "./scheduler-observation.ts";
import { observeTerminalMeasurement } from "./scheduler-terminal-measurement.ts";
import {
  applyAdmission,
  applyAdmissionPolicyFault,
  applyBlockedSettlement,
  applyCancellation,
  buildTaskGraphRun,
  nextRunningSettlement,
  settleRunningTask
} from "./scheduler-task-lifecycle.ts";

export async function runTaskGraph<TResult>(
  options: RunTaskGraphOptions<TResult>
): Promise<TaskGraphRun<TResult>> {
  const graph = prepareTaskGraph(options.graph, options.maxParallel);
  const state = createSchedulerState(graph, options);
  const measurementInput =
    options.performanceDiagnostics ??
    (state.admissionPolicy.requiresMeasurement === true
      ? Object.freeze({
          clock: Object.freeze({ now: () => performance.now() }),
          declarativeFingerprint: ""
        })
      : undefined);
  const diagnostics =
    measurementInput === undefined
      ? undefined
      : new SchedulerPerformanceDiagnostics(measurementInput, performanceState(state));
  let trigger: SchedulerTrigger = Object.freeze({ kind: "execution-started" });

  while (true) {
    let decision: SchedulerDecision;
    try {
      const snapshot = snapshotSchedulerState(state);
      const measurement =
        state.admissionPolicy.requiresMeasurement === true
          ? () => decisionBoundaryMeasurement(diagnostics)
          : undefined;
      decision =
        diagnostics?.measureControlPath(() =>
          decideScheduler(snapshot, trigger, state.admissionPolicy, measurement)
        ) ?? decideScheduler(snapshot, trigger, state.admissionPolicy, measurement);
    } catch (error) {
      if (!(error instanceof AdmissionPolicyFault)) throw error;
      diagnostics?.beforePendingSettlement(state.pending.map((task) => task.id));
      if (diagnostics === undefined) applyAdmissionPolicyFault(state, error);
      else diagnostics.measureControlPath(() => applyAdmissionPolicyFault(state, error));
      diagnostics?.captureState(performanceState(state));
      observeAdmissionPolicyFault(state, error);
      trigger = Object.freeze({ kind: "cancellation-applied" });
      continue;
    }
    observeSchedulerDecision(state, decision, diagnostics);

    switch (decision.kind) {
      case "admit":
        if (state.signal?.aborted === true) {
          diagnostics?.beforePendingSettlement(state.pending.map((task) => task.id));
          const lifecycleFault = new AdmissionPolicyFault("lifecycle-invalid-select");
          if (diagnostics === undefined) applyAdmissionPolicyFault(state, lifecycleFault);
          else
            diagnostics.measureControlPath(() => applyAdmissionPolicyFault(state, lifecycleFault));
          diagnostics?.captureState(performanceState(state));
          observeAdmissionPolicyFault(state, lifecycleFault);
          trigger = Object.freeze({ kind: "cancellation-applied" });
          continue;
        }
        diagnostics?.beforeAdmission(decision.taskId, [...state.runningById.keys()]);
        if (diagnostics === undefined) applyAdmission(state, decision);
        else diagnostics.measureControlPath(() => applyAdmission(state, decision));
        diagnostics?.captureState(performanceState(state));
        if (state.admissionPolicy.requiresMeasurement === true) {
          diagnostics?.beginSelectedPolicyAction(decision.taskId);
          diagnostics?.recordEffect(Object.freeze({ kind: "admitted", taskId: decision.taskId }));
        }
        trigger = Object.freeze({ kind: "admission-continued" });
        continue;
      case "settle-blocked":
        diagnostics?.beforePendingSettlement([decision.taskId]);
        if (diagnostics === undefined) applyBlockedSettlement(state, decision);
        else diagnostics.measureControlPath(() => applyBlockedSettlement(state, decision));
        diagnostics?.captureState(performanceState(state));
        diagnostics?.recordEffect(
          Object.freeze({ kind: "settled", settlementKind: "blocked", taskId: decision.taskId })
        );
        trigger = Object.freeze({
          kind: "blocked-settled",
          taskId: decision.taskId
        });
        continue;
      case "cancel-pending":
        diagnostics?.beforePendingSettlement(decision.taskIds);
        if (diagnostics === undefined) applyCancellation(state, decision);
        else diagnostics.measureControlPath(() => applyCancellation(state, decision));
        diagnostics?.captureState(performanceState(state));
        for (const taskId of decision.taskIds) {
          diagnostics?.recordEffect(
            Object.freeze({ kind: "settled", settlementKind: "cancelled-before-start", taskId })
          );
        }
        trigger = Object.freeze({ kind: "cancellation-applied" });
        continue;
      case "await-running": {
        if (decision.proposal?.kind === "wait") {
          diagnostics?.beforeAcceptedWait();
          if (state.admissionPolicy.requiresMeasurement === true) {
            diagnostics?.beginWaitPolicyAction();
          }
        }
        const completion = await nextRunningSettlement(state);
        diagnostics?.beforeRunningSettlement(completion.taskId);
        if (diagnostics === undefined) settleRunningTask(state, completion);
        else diagnostics.measureControlPath(() => settleRunningTask(state, completion));
        diagnostics?.captureState(performanceState(state));
        diagnostics?.recordEffect(
          Object.freeze({
            kind: "settled",
            settlementKind: completion.settlement.kind,
            taskId: completion.taskId
          })
        );
        trigger = Object.freeze({
          kind: "task-settled",
          settlementKind: completion.settlement.kind,
          taskId: completion.taskId
        });
        continue;
      }
      case "complete": {
        if (diagnostics === undefined) return buildTaskGraphRun(state);
        const run = diagnostics.measureControlPath(() => buildTaskGraphRun(state));
        await observeTerminalMeasurement({ diagnostics, options, state });
        return run;
      }
    }
  }
}

function decisionBoundaryMeasurement(
  diagnostics: SchedulerPerformanceDiagnostics | undefined
): AdmissionPolicyContext["measurement"] {
  if (diagnostics === undefined) {
    throw new Error("custom policy measurement collector is unavailable");
  }
  return diagnostics.policyMeasurement();
}
